-- RaidMaster – Raids: 한국어 (koKR)
-- Automatisch erzeugt (Raidnamen, Taktiken, Raidchat-Zeilen, Markierungsvorlagen).
-- Fehlende Einträge erscheinen auf Deutsch.

local _, RM = ...
if RM.LOCALE ~= "koKR" then return end
local L = RM.L

L["Ruinen von Ahn'Qiraj"] = "안퀴라즈 폐허"
L["Kurinnaxx"] = "쿠린낙스"
L["- Tödliche Wunde: stapelnder Debuff auf dem Tank, reduziert erhaltene Heilung -> Tankwechsel bei hohen Stapeln."] = "- 죽음의 상처: 탱커에게 중첩되는 디버프, 받는 치유량 감소 -> 중첩이 높으면 탱 교대."
L["- Sandfalle: erscheint unter einem Spieler und lässt ihn bei Auslösen verfehlen -> sofort herauslaufen."] = "- 모래 덫: 플레이어 발밑에 생기며 발동 시 공격이 빗나가게 함 -> 즉시 밖으로 이동."
L["- Raserei bei ca. 30 %: deutlich mehr Schaden -> Heiler auf die Tanks, Schaden hochfahren."] = "- 약 30 %에 광란: 피해량 대폭 증가 -> 힐러는 탱커 집중, 딜 끌어올리기."
L["Taktik: Zwei Tanks wechseln sich ab, Raid verteilt hinter dem Boss, Sandfallen sofort verlassen."] = "공략: 탱커 두 명이 번갈아 탱, 공격대는 보스 뒤에 산개, 모래 덫은 즉시 벗어나기."
L["KURINNAXX: Tankwechsel bei Tödlicher Wunde! Raus aus der Sandfalle!"] = "쿠린낙스: 죽음의 상처 시 탱 교대! 모래 덫에서 나오세요!"
L["Ab 30 % Raserei: Heiler auf die Tanks, alles auf den Boss."] = "30 %부터 광란: 힐러는 탱커, 전원 보스 점사."
L["General Rajaxx + Wellen der Qiraji (mit Generalleutnant Andorov)"] = "장군 라작스 + 퀴라지 웨이브 (중장 안도로프 동행)"
L["- Wellen: mehrere Wellen Qiraji-Krieger mit je einem Hauptmann greifen nacheinander an -> Hauptmann und Adds sauber abarbeiten."] = "- 웨이브: 대장 한 명씩을 포함한 퀴라지 전사 웨이브가 차례로 공격 -> 대장과 쫄을 깔끔하게 정리."
L["- Andorov: NPC-Verbündeter mit Aura und Händler -> am Leben halten, er hilft bei den Wellen."] = "- 안도로프: 오라와 상점 기능이 있는 NPC 아군 -> 살려두기, 웨이브 처리를 도와줌."
L["- Donnerkrachen (Rajaxx): halbiert das aktuelle Leben aller Spieler in der Nähe -> Raid hoch halten, Abstand für Fernkampf."] = "- 천둥의 일격 (라작스): 근처 모든 플레이어의 현재 생명력을 절반으로 -> 공격대 피 유지, 원딜은 거리 유지."
L["- Entwaffnen/Ansturm-Fähigkeiten der Hauptleute: Tankschaden schwankt -> Heiler aufmerksam."] = "- 대장들의 무장 해제/돌진 기술: 탱커 피해량 변동 -> 힐러 주의."
L["Taktik: Wellen am Startpunkt tanken und mit Flächenschaden töten, zwischen den Wellen regenerieren. Zum Schluss Rajaxx tanken und mit allem töten."] = "공략: 웨이브는 시작 지점에서 탱하고 광역으로 처치, 웨이브 사이에 회복. 마지막에 라작스를 탱하고 전원 점사."
L["RAJAXX: Wellen sauber abarbeiten, Andorov am Leben halten!"] = "라작스: 웨이브 깔끔하게 정리, 안도로프 살려두세요!"
L["Donnerkrachen halbiert Leben: Raid immer voll heilen."] = "천둥의 일격은 생명력 절반: 공격대 항상 풀피 유지."
L["Moam + Manadämonen"] = "모암 + 마나 정령"
L["- Mana entziehen: Moam saugt Mana der Spieler; bei vollem Mana Arkanausbruch auf den ganzen Raid -> sein Mana leer halten (Mana verbrennen, Vipernbiss, Mana entziehen)."] = "- 마나 흡수: 모암이 플레이어 마나를 흡수; 마나가 가득 차면 공격대 전체에 비전 폭발 -> 모암 마나를 비워두기 (마나 연소, 독사 쐐기, 마나 흡수)."
L["- Versteinern: Moam wird zu Stein und ruft Manadämonen -> Dämonen verbannen bzw. tanken und töten."] = "- 석화: 모암이 돌로 변하며 마나 정령 소환 -> 정령 추방 또는 탱 후 처치."
L["- Manadämonen: Arkanschaden und Spalten -> nicht frei laufen lassen."] = "- 마나 정령: 비전 피해와 회전베기 -> 풀어두지 말 것."
L["Taktik: Schnell Schaden machen, Jäger/Priester/Hexer halten sein Mana unten. Bei Versteinerung Hexer auf die Manadämonen einteilen."] = "공략: 빠르게 딜, 사냥꾼/사제/흑마법사가 마나를 낮게 유지. 석화 시 흑마법사를 마나 정령에 배정."
L["MOAM: Sein Mana leer halten! Bei Stein: Manadämonen verbannen!"] = "모암: 마나 비워두세요! 석화 시: 마나 정령 추방!"
L["Jäger Vipernbiss, Priester Mana verbrennen, Hexer Mana entziehen."] = "사냥꾼 독사 쐐기, 사제 마나 연소, 흑마 마나 흡수."
L["Moam (Dämonen)"] = "모암 (정령)"
L["Jeder Manadämon ein Symbol, je ein Hexer verbannt sein zugewiesenes Symbol."] = "마나 정령마다 징표 하나, 흑마법사 한 명씩 배정된 징표를 추방."
L["Buru der Verschlinger + Eier"] = "먹보 부루 + 알"
L["- Fixieren: Buru verfolgt einen zufälligen Spieler -> diesen Spieler Buru in ein Ei ziehen lassen."] = "- 시선 고정: 부루가 무작위 플레이어를 추격 -> 해당 플레이어가 부루를 알 쪽으로 유인."
L["- Eier: zerstörte Eier explodieren und verletzen Buru (und Spieler in der Nähe), es schlüpfen Brutlinge -> Eier nur zerschlagen, wenn Buru danebensteht, Abstand halten."] = "- 알: 알을 부수면 폭발해 부루 (및 근처 플레이어)에게 피해, 새끼가 부화 -> 부루가 옆에 있을 때만 알 깨기, 거리 유지."
L["- Phase 2 (ca. 20 %): Buru verliert Panzer, kriechende Seuche verursacht steigenden Raidschaden -> alles auf den Boss."] = "- 2단계 (약 20 %): 부루의 껍질이 벗겨지고 기어가는 역병으로 공격대 피해 증가 -> 전원 보스 점사."
L["Taktik: Raid zerschlägt Eier gezielt, wenn Buru den fixierten Spieler durch ein Ei verfolgt; Brutlinge schnell töten. Ab 20 % voller Schaden."] = "공략: 시선 고정된 플레이어를 쫓는 부루가 알을 지날 때 공격대가 알을 노려서 깨기; 새끼는 빠르게 처치. 20 %부터 풀딜."
L["BURU: Fixierten Spieler -> Buru durch die Eier ziehen! Abstand zur Explosion!"] = "부루: 시선 고정 대상 -> 부루를 알 위로 유인! 폭발 거리 유지!"
L["Bei 20 % alles auf Buru, Heiler Raid hoch halten."] = "20 %에 전원 부루 점사, 힐러는 공격대 피 유지."
L["Ayamiss der Jäger + Larven/Wespen"] = "사냥꾼 아야미스 + 유충/말벌"
L["- Phase 1 in der Luft: nur Fernkampf erreicht sie -> Fernkampf auf den Boss, Nahkampf auf Adds."] = "- 공중 1단계: 원딜만 닿음 -> 원딜은 보스, 근딜은 쫄."
L["- Lähmen: ein Spieler wird auf den Altar gebracht, eine Larve läuft hin -> Larve sofort töten, sonst stirbt der Spieler."] = "- 마비: 한 명이 제단으로 옮겨지고 유충이 다가감 -> 유충 즉시 처치, 아니면 플레이어 사망."
L["- Giftstachelsalve: Naturschaden auf viele Spieler -> Gift entfernen, Naturwiderstand hilft."] = "- 독침 일제 사격: 다수에게 자연 피해 -> 독 해제, 자연 저항 도움."
L["- Phase 2 (ca. 70 %): landet und wird getankt, ruft weiter Wespen -> Tank übernimmt, Adds mit Flächenschaden töten."] = "- 2단계 (약 70 %): 착지해 탱 가능, 계속 말벌 소환 -> 탱커가 인계, 쫄은 광역으로 처치."
L["Taktik: Fernkampf schießt den Boss herunter, Nahkampf kümmert sich um Larven und Wespen. Nach der Landung normal tanken."] = "공략: 원딜이 보스를 끌어내리고 근딜은 유충과 말벌 담당. 착지 후 일반 탱."
L["AYAMISS: Larve zum Altar sofort töten! Fernkampf auf den Boss!"] = "아야미스: 제단으로 가는 유충 즉시 처치! 원딜은 보스!"
L["Gift entfernen. Ab 70 % landet sie: Tank bereit."] = "독 해제. 70 %부터 착지: 탱커 대기."
L["Ossirian der Narbenlose"] = "무적의 오시리안"
L["- Stärke des Ossirian: ohne Schwäche fast unverwundbar und tödlich -> immer zu einem Kristall ziehen."] = "- 오시리안의 힘: 약점 없이는 거의 무적이며 치명적 -> 항상 수정으로 끌고 가기."
L["- Kristalle: Aktivieren gibt ihm eine Zauberschwäche für ca. 45 Sek. -> rechtzeitig nächsten Kristall aktivieren und Boss dorthin tanken."] = "- 수정: 활성화하면 약 45초간 주문 약점 부여 -> 제때 다음 수정을 활성화하고 보스를 그쪽으로 탱."
L["- Wirbelstürme: wandern durch den Raum -> ausweichen."] = "- 회오리바람: 방 안을 돌아다님 -> 피하기."
L["- Fluch der Sprachen/Umhüllende Winde/Kriegsdonner: Raidkontrolle -> entfluchen, Abstand halten."] = "- 언어의 저주/휘감는 바람/전쟁발구르기: 공격대 제어 -> 저주 해제, 거리 유지."
L["Taktik: Tank kitet Ossirian von Kristall zu Kristall, ein Spieler aktiviert den nächsten vor Ablauf der Schwäche. Schaden passend zur Schwäche-Schule."] = "공략: 탱커가 오시리안을 수정에서 수정으로 카이팅, 한 명이 약점이 끝나기 전에 다음 수정 활성화. 약점 계열에 맞춰 딜."
L["OSSIRIAN: Nächsten Kristall rechtzeitig aktivieren! Schwäche nie ablaufen lassen!"] = "오시리안: 다음 수정 제때 활성화! 약점 절대 끊기지 않게!"
L["Wirbelstürmen ausweichen, Flüche entfernen."] = "회오리바람 피하기, 저주 해제."
L["Tempel von Ahn'Qiraj"] = "안퀴라즈 사원"
L["Der Prophet Skeram + 2 Abbilder"] = "예언자 스케람 + 분신 2"
L["- Arkane Explosion: hoher Flächenschaden -> unterbrechen, Nahkampf vorsichtig."] = "- 신비한 폭발: 강력한 광역 피해 -> 차단, 근딜 주의."
L["- Wahre Erfüllung: Gedankenkontrolle -> Spieler kontrollieren (Verwandlung, Furcht), nicht töten."] = "- 진정한 충족: 정신 지배 -> 플레이어 제어 (변이, 공포), 죽이지 말 것."
L["- Teleport: Skeram springt auf eine andere Plattform und setzt die Bedrohung zurück -> auf jeder Plattform ein Tank."] = "- 순간이동: 스케람이 다른 단상으로 이동하며 위협 수준 초기화 -> 단상마다 탱커 한 명."
L["- Abbilder bei 75/50/25 %: zwei Kopien erscheinen -> Kopien tanken, echten Skeram finden und töten."] = "- 75/50/25 %에 분신: 복제 두 개 등장 -> 복제는 탱, 진짜 스케람을 찾아 처치."
L["Taktik: Drei Tanks auf drei Positionen verteilen, Unterbrecher fest einteilen. Bei Abbildern echten Skeram markieren und zuerst töten."] = "공략: 탱커 세 명을 세 위치에 배치, 차단 담당 고정. 분신 시 진짜 스케람에 징표 후 먼저 처치."
L["SKERAM: Arkane Explosion unterbrechen! Gedankenkontrolle kontrollieren, nicht töten!"] = "스케람: 신비한 폭발 차단! 정신 지배는 제어, 죽이지 마세요!"
L["Bei Abbildern nur auf den echten Skeram (Totenkopf)."] = "분신 시 진짜 스케람(해골)만 공격."
L["Skeram"] = "스케람"
L["Totenkopf auf den echten Skeram, Kreuz und Viereck auf die Abbilder."] = "진짜 스케람에 해골, 분신에 가위표와 네모."
L["Adel der Silithiden: Lord Kri, Prinzessin Yauj, Vem"] = "실리시드 왕실: 군주 크리, 공주 야우즈, 벰"
L["- Lord Kri: Giftwolke und bei Tod eine Giftwolke -> nicht darin stehen, Gift entfernen."] = "- 군주 크리: 독구름, 사망 시에도 독구름 -> 그 안에 서지 말 것, 독 해제."
L["- Prinzessin Yauj: Große Heilung und Furcht -> Heilung unterbrechen, Furcht beachten; bei Tod erscheinen Käfer -> Flächenschaden."] = "- 공주 야우즈: 상급 치유와 공포 -> 치유 차단, 공포 주의; 사망 시 딱정벌레 등장 -> 광역."
L["- Vem: Ansturm und Rückstoß, wird stärker, wenn die anderen sterben -> stabil tanken."] = "- 벰: 돌진과 밀쳐내기, 다른 둘이 죽으면 강해짐 -> 안정적으로 탱."
L["- Wer zuletzt stirbt, bestimmt die Beute -> Reihenfolge vorher absprechen."] = "- 마지막으로 죽는 보스가 전리품을 결정 -> 순서를 미리 정하기."
L["Taktik: Alle drei getrennt tanken, Unterbrecher auf Yauj, Kill-Reihenfolge nach Absprache (der letzte Boss bestimmt die Beute)."] = "공략: 셋을 따로 탱, 차단은 야우즈, 처치 순서는 사전 합의 (마지막 보스가 전리품 결정)."
L["SILITHIDEN: Kill-Reihenfolge laut Symbolen! Yauj-Heilung unterbrechen!"] = "실리시드: 징표 순서대로 처치! 야우즈 치유 차단!"
L["Giftwolken meiden. Käfer nach Yauj mit Flächenschaden töten."] = "독구름 피하기. 야우즈 이후 딱정벌레 광역 처치."
L["Adel der Silithiden"] = "실리시드 왕실"
L["Totenkopf zuerst, dann Kreuz, Viereck zuletzt (bestimmt die Beute)."] = "해골 먼저, 다음 가위표, 네모 마지막 (전리품 결정)."
L["Schlachtwache Sartura + 3 Königliche Wachen"] = "전투감시병 살투라 + 왕실 경비병 3"
L["- Wirbelwind: Sartura und Wachen wirbeln und laufen durch den Raid -> Abstand halten, Nahkampf raus."] = "- 소용돌이: 살투라와 경비병이 회전하며 공격대를 휩쓸고 다님 -> 거리 유지, 근딜 빠지기."
L["- Wachen: verursachen viel Schaden -> mit Betäubungsrotation kontrollieren und zuerst töten."] = "- 경비병: 큰 피해 -> 기절 로테이션으로 제어 후 먼저 처치."
L["- Wutanfall bei ca. 20 % und hartes Zeitlimit -> zügig Schaden machen."] = "- 약 20 %에 격노 및 엄격한 시간 제한 -> 빠르게 딜."
L["Taktik: Wachen einzeln tanken und nacheinander töten, Betäubungen fest einteilen. Danach Sartura, Raid verteilt."] = "공략: 경비병을 하나씩 탱하고 차례로 처치, 기절 담당 고정. 이후 살투라, 공격대 산개."
L["SARTURA: Wachen zuerst! Betäubungen rotieren, bei Wirbelwind weg!"] = "살투라: 경비병 먼저! 기절 로테이션, 소용돌이 시 빠지세요!"
L["Raid verteilt stehen. Ab 20 % Wutanfall: Heiler auf Tank."] = "공격대 산개. 20 %부터 격노: 힐러는 탱커."
L["Sartura"] = "살투라"
L["Totenkopf, Kreuz, Viereck auf die drei Wachen in Tötungsreihenfolge."] = "세 경비병에 처치 순서대로 해골, 가위표, 네모."
L["Fankriss der Unnachgiebige + Brut/Jungtiere"] = "불굴의 판크리스 + 새끼/유충"
L["- Tödliche Wunde: stapelnder Heilungsreduktions-Debuff -> Tankwechsel."] = "- 죽음의 상처: 중첩되는 치유 감소 디버프 -> 탱 교대."
L["- Brut des Fankriss: wird nach kurzer Zeit wütend -> sofort töten."] = "- 판크리스의 새끼: 잠시 후 격노 -> 즉시 처치."
L["- Vekniss-Jungtiere: kommen aus den Tunneln -> Offtank sammelt sie, Flächenschaden."] = "- 베크니스 유충: 터널에서 나옴 -> 보조 탱커가 모으고 광역."
L["- Umschlingen: Spieler werden in die Tunnel versetzt -> zurücklaufen, Adds dort nicht ignorieren."] = "- 휘감기: 플레이어가 터널로 이동됨 -> 돌아오기, 그곳의 쫄 무시 금지."
L["Taktik: Zwei bis drei Tanks wechseln auf dem Boss, Fernkampf tötet Brut sofort. Schnell Schaden machen, bevor Adds überhandnehmen."] = "공략: 탱커 2~3명이 보스를 교대, 원딜은 새끼 즉시 처치. 쫄이 쌓이기 전에 빠르게 딜."
L["FANKRISS: Brut sofort töten! Tankwechsel bei Tödlicher Wunde!"] = "판크리스: 새끼 즉시 처치! 죽음의 상처 시 탱 교대!"
L["Jungtiere zum Offtank, Flächenschaden."] = "유충은 보조 탱커에게, 광역."
L["Viscidus"] = "비시디우스"
L["- Gefrieren: Viscidus muss mit Frostschaden eingefroren werden (Frostblitz, Frost-Zauberstäbe, Frostöl) -> alle Frostschaden."] = "- 빙결: 냉기 피해로 얼려야 함 (얼음화살, 냉기 마법봉, 냉기 오일) -> 전원 냉기 피해."
L["- Zerschlagen: eingefroren mit Nahkampf zerschlagen -> er zerfällt in Kugeln."] = "- 산산조각: 얼면 근접 공격으로 부숨 -> 작은 덩어리로 분열."
L["- Kugeln: laufen zur Mitte zurück und heilen ihn -> alle Kugeln töten."] = "- 덩어리: 중앙으로 돌아가 보스를 치유 -> 덩어리 전부 처치."
L["- Giftblitzsalve und Giftwolken: Naturschaden -> Naturwiderstand, Gift entfernen."] = "- 독화살 일제 사격과 독구름: 자연 피해 -> 자연 저항, 독 해제."
L["Taktik: Frost-Phase mit allem Fernkampf, Zerschlagen mit Nahkampf, danach Kugeln mit Flächenschaden. Wiederholen bis er tot ist."] = "공략: 냉기 단계는 원딜 전원, 산산조각은 근딜, 이후 덩어리 광역. 죽을 때까지 반복."
L["VISCIDUS: Alles Frostschaden! Gefroren -> Nahkampf zerschlagen!"] = "비시디우스: 전원 냉기 피해! 얼면 -> 근딜이 부수기!"
L["Alle Kugeln töten, bevor sie die Mitte erreichen."] = "덩어리가 중앙에 닿기 전에 전부 처치."
L["Prinzessin Huhuran"] = "공주 후후란"
L["- Raserei: deutlich mehr Schaden -> Jäger mit Einlullender Schuss sofort entfernen."] = "- 광란: 피해량 대폭 증가 -> 사냥꾼이 평정의 사격으로 즉시 해제."
L["- Wyverngift: Schlaf auf Spielern, beim Bannen Schaden -> gezielt bannen."] = "- 비룡 독: 플레이어 수면, 해제 시 피해 -> 골라서 해제."
L["- Giftblitzsalve: trifft die nächsten Spieler -> Naturwiderstand-Gruppe nahe am Boss."] = "- 독화살 일제 사격: 가장 가까운 플레이어 적중 -> 자연 저항 파티가 보스 가까이."
L["- Säurespucke: Stapel-Debuff auf Tank; ab 30 % Berserker -> Burn-Phase, Heiler voll."] = "- 산성 침: 탱커에게 중첩 디버프; 30 %부터 광폭 -> 극딜 단계, 힐러 풀가동."
L["Taktik: Naturwiderstand bei Nahkampf und Tank, Jäger-Rotation für Einlullender Schuss. Ab 30 % alles zünden und Raid hoch halten."] = "공략: 근딜과 탱커는 자연 저항, 평정의 사격은 사냥꾼 로테이션. 30 %부터 쿨기 전부 쓰고 공격대 피 유지."
L["HUHURAN: Raserei sofort einlullen! Ab 30 % Burn!"] = "후후란: 광란 즉시 평정! 30 %부터 극딜!"
L["Naturwiderstand nahe am Boss, Wyverngift gezielt bannen."] = "자연 저항은 보스 가까이, 비룡 독은 골라서 해제."
L["Zwillingsimperatoren: Vek'lor + Vek'nilash"] = "쌍둥이 황제: 베클로어 + 베크닐라시"
L["- Vek'lor: immun gegen körperlichen Schaden, Schattenblitz, Blizzard, Arkane Explosion -> von einem Hexer (Schattenschutz) getankt."] = "- 베클로어: 물리 피해 면역, 어둠의 화살, 눈보라, 신비한 폭발 -> 흑마법사(암흑 보호)가 탱."
L["- Vek'nilash: immun gegen Magie, Aufwärtshaken -> von Kriegern getankt, nur Nahkampf."] = "- 베크닐라시: 마법 면역, 어퍼컷 -> 전사가 탱, 근딜만."
L["- Bruder heilen: sind sie nah beieinander, heilen sie sich -> immer weit auseinander halten."] = "- 형제 치유: 가까이 있으면 서로 치유 -> 항상 멀리 떨어뜨리기."
L["- Teleport: tauschen regelmäßig die Plätze -> Tanks an beiden Seiten bereit, Bedrohung neu aufbauen; Käfer explodieren/mutieren -> töten."] = "- 순간이동: 주기적으로 위치 교환 -> 양쪽에 탱커 대기, 위협 수준 재확보; 딱정벌레 폭발/변이 -> 처치."
L["Taktik: Zwei Tankgruppen an beiden Enden, Hexer auf Vek'lor, Krieger auf Vek'nilash. Nach jedem Teleport sofort übernehmen."] = "공략: 양 끝에 탱 조 두 개, 흑마는 베클로어, 전사는 베크닐라시. 순간이동마다 즉시 인계."
L["ZWILLINGE: Brüder auseinander halten! Nach Teleport Tanks sofort übernehmen!"] = "쌍둥이: 형제 떨어뜨리기! 순간이동 후 탱커 즉시 인계!"
L["Nahkampf nur Vek'nilash, Magie nur Vek'lor. Käfer töten."] = "근딜은 베크닐라시만, 마법은 베클로어만. 딱정벌레 처치."
L["Ouro + Skarabäen"] = "아우로 + 스카라베"
L["- Fegen: Rückstoß und Betäubung im Umkreis -> Tanks rotieren."] = "- 휩쓸기: 주변 밀쳐내기와 기절 -> 탱커 로테이션."
L["- Sandstoß: großer Frontalkegel -> nur Tanks vor Ouro."] = "- 모래 폭발: 큰 전방 부채꼴 -> 아우로 앞에는 탱커만."
L["- Untertauchen: Erdhügel verfolgen Spieler, Skarabäen erscheinen -> weglaufen, Skarabäen töten."] = "- 잠복: 흙더미가 플레이어를 쫓고 스카라베 등장 -> 도망가고 스카라베 처치."
L["- Ist niemand in Nahkampfreichweite, wirft er Felsbrocken; ab 20 % Berserker -> Burn."] = "- 근접 사거리에 아무도 없으면 바위를 던짐; 20 %부터 광폭 -> 극딜."
L["Taktik: Mehrere Tanks halten Ouro im Nahkampf, Raid seitlich. Beim Untertauchen verteilen und Skarabäen töten."] = "공략: 여러 탱커가 아우로를 근접 유지, 공격대는 측면. 잠복 시 산개하고 스카라베 처치."
L["OURO: Nicht vor den Boss! Untertauchen: verteilen, Skarabäen töten!"] = "아우로: 보스 앞 금지! 잠복: 산개, 스카라베 처치!"
L["Immer ein Tank im Nahkampf, sonst Felsbrocken."] = "항상 탱커 한 명은 근접, 아니면 바위 날아옴."
L["C'Thun + Tentakel"] = "쑨 + 촉수"
L["- Augenstrahl: springt auf Spieler in der Nähe -> Raid im Kreis mit Abstand verteilen."] = "- 눈 광선: 근처 플레이어로 튐 -> 공격대는 원형으로 거리 두고 산개."
L["- Dunkles Starren: rotierender Todesstrahl -> sofort zur Seite."] = "- 어둠의 시선: 회전하는 죽음의 광선 -> 즉시 옆으로."
L["- Tentakel: Augen- und Klauententakel erscheinen -> schnell töten."] = "- 촉수: 눈 촉수와 발톱 촉수 등장 -> 빠르게 처치."
L["- Phase 2: Spieler werden verschlungen; im Magen Fleischtentakel töten, um C'Thun zu schwächen -> nur in der Schwächephase Schaden."] = "- 2단계: 플레이어가 삼켜짐; 위장 안에서 살덩이 촉수를 잡아 쑨을 약화 -> 약화 단계에만 딜."
L["Taktik: Feste Kreisaufstellung mit Abstand, Tentakel sofort weg. In Phase 2 Magen-Team tötet die Fleischtentakel, Raid zündet in der Schwächephase."] = "공략: 거리 둔 원형 고정 배치, 촉수는 즉시 제거. 2단계에 위장 조가 살덩이 촉수 처치, 공격대는 약화 단계에 극딜."
L["C'THUN: Abstand halten! Dunkles Starren ausweichen, Tentakel sofort töten!"] = "쑨: 거리 유지! 어둠의 시선 피하기, 촉수 즉시 처치!"
L["Phase 2: Magen-Team auf Fleischtentakel, Schaden in Schwäche."] = "2단계: 위장 조는 살덩이 촉수, 약화 때 딜."
L["Pechschwingenhort"] = "검은날개 둥지"
L["Razorgore der Ungezähmte + Adds der Schwarzen Drachenbrut"] = "폭군 서슬송곳니 + 검은용군단 쫄"
L["- Phase 1: Ein Spieler kontrolliert Razorgore über die Kugel und zerstört mit ihm die Eier."] = "- 1단계: 한 명이 구슬로 서슬송곳니를 조종해 알을 파괴."
L["- Adds: Drachenbrut, Drachkin und Magier strömen aus den Eingängen -> an den Eingängen tanken und töten."] = "- 쫄: 용족, 용기병, 마법사가 입구에서 몰려옴 -> 입구에서 탱하고 처치."
L["- Kugel-Kontrolle: Kontrolleur nicht unterbrechen, Bedrohung für Phase 2 beachten."] = "- 구슬 조종: 조종자 방해 금지, 2단계를 위한 위협 수준 주의."
L["- Phase 2: Razorgore wird frei, Feuerballsalve und Eroberung -> Tank bereit, Raid verteilt."] = "- 2단계: 서슬송곳니 풀려남, 화염구 일제 사격과 정복 -> 탱커 대기, 공격대 산개."
L["Taktik: Gruppen an den Eingängen halten die Adds, der Kontrolleur zerstört alle Eier. Phase 2: Tank übernimmt Razorgore sofort."] = "공략: 입구별 조가 쫄을 막고 조종자가 알을 전부 파괴. 2단계: 탱커가 서슬송곳니 즉시 인계."
L["RAZORGORE: Eier zerstören, Adds an den Eingängen halten!"] = "서슬송곳니: 알 파괴, 쫄은 입구에서 막기!"
L["Kugel-Kontrolleur nicht unterbrechen. Phase 2: Tank bereit."] = "구슬 조종자 방해 금지. 2단계: 탱커 대기."
L["Vaelastrasz der Verdorbene"] = "타락한 밸라스트라즈"
L["- Essenz des Roten: alle Spieler haben unbegrenzt Mana/Wut/Energie -> durchgehend Vollgas."] = "- 붉은용의 정수: 모든 플레이어 마나/분노/기력 무한 -> 끝까지 풀딜."
L["- Brennendes Adrenalin: Spieler explodiert nach kurzer Zeit und stirbt -> sofort aus dem Raid laufen; auf dem Tank -> Tankwechsel."] = "- 불타는 아드레날린: 잠시 후 폭발해 사망 -> 즉시 공격대 밖으로; 탱커에게 걸리면 -> 탱 교대."
L["- Flammenatem/Schwanzfeger: vorne und hinten gefährlich -> nur Tank vorne, Raid seitlich."] = "- 화염 숨결/꼬리 휘둘러치기: 앞뒤 위험 -> 앞에는 탱커만, 공격대는 측면."
L["Taktik: Tank-Reihenfolge festlegen, Raid seitlich am Boss. Vael startet bei 30 % Leben: schnell töten, bevor zu viele Spieler sterben."] = "공략: 탱커 순서 정하기, 공격대는 보스 측면. 밸은 생명력 30 %로 시작: 너무 많이 죽기 전에 빠르게 처치."
L["VAELASTRASZ: Brennendes Adrenalin -> sofort raus aus dem Raid!"] = "밸라스트라즈: 불타는 아드레날린 -> 즉시 공격대 밖으로!"
L["Nur seitlich stehen. Tank-Reihenfolge einhalten, Vollgas!"] = "측면에만 서기. 탱 순서 지키고 풀딜!"
L["Brutwächter Dreschbringer"] = "용기대장 래쉬레이어"
L["- Tödlicher Stoß: senkt die Heilung auf dem Tank -> Heiler aufmerksam, Tank mit Abklingzeiten."] = "- 죽음의 일격: 탱커 치유량 감소 -> 힐러 주의, 탱커는 생존기."
L["- Druckwelle: Feuerschaden im Umkreis -> Nahkampf heilen, Fernkampf auf Abstand."] = "- 충격파: 주변 화염 피해 -> 근딜 치유, 원딜 거리 유지."
L["- Wegschlagen: senkt Bedrohung und wirft den Tank weg -> Tank mit dem Rücken zur Wand, Zweittank hoch in der Bedrohung."] = "- 후려치기: 위협 수준 감소, 탱커를 날림 -> 탱커는 벽을 등지고, 보조 탱커 위협 수준 높게."
L["Taktik: Vorher den Unterdrückungsraum säubern. Boss mit dem Rücken des Tanks zur Wand tanken, Zweittank als Ersatz bereit."] = "공략: 미리 억압의 방 정리. 탱커가 벽을 등지고 탱, 보조 탱커 대기."
L["BRUTWÄCHTER: Tank an die Wand! Zweittank Bedrohung hoch halten!"] = "래쉬레이어: 탱커 벽으로! 보조 탱커 위협 수준 유지!"
L["Tödlicher Stoß: Tank stark heilen. Fernkampf auf Abstand."] = "죽음의 일격: 탱커 집중 치유. 원딜 거리 유지."
L["Feuerschwinge"] = "화염아귀"
L["- Flammenpuffer: stapelnder Feuer-Debuff auf allen in Sichtlinie -> hinter Säulen Stapel abbauen."] = "- 화염 버프: 시야 내 전원에게 중첩되는 화염 디버프 -> 기둥 뒤에서 중첩 해소."
L["- Flügelstoß: senkt Bedrohung, wirft zurück -> Tankwechsel einplanen."] = "- 날개 강타: 위협 수준 감소, 뒤로 밀침 -> 탱 교대 계획."
L["- Schattenflamme: Frontalkegel -> Onyxiaschuppenumhang tragen, nur Tank vorne."] = "- 암흑의 불길: 전방 부채꼴 -> 오닉시아 비늘 망토 착용, 앞에는 탱커만."
L["Taktik: Zwei Tanks wechseln bei Flügelstoß, Fernkampf und Heiler pendeln zwischen Sichtlinie und Säule, um Stapel abzubauen."] = "공략: 날개 강타 시 탱커 둘이 교대, 원딜과 힐러는 시야와 기둥 사이를 오가며 중첩 해소."
L["FEUERSCHWINGE: Stapel hinter der Säule abbauen! Umhang an!"] = "화염아귀: 기둥 뒤에서 중첩 해소! 망토 착용!"
L["Tankwechsel bei Flügelstoß. Nur Tank vorne."] = "날개 강타 시 탱 교대. 앞에는 탱커만."
L["Schattenschwinge"] = "에본로크"
L["- Schatten von Schattenschwinge: Debuff auf dem Tank, jeder Treffer heilt den Boss -> sofort Tankwechsel."] = "- 에본로크의 그림자: 탱커 디버프, 적중마다 보스 회복 -> 즉시 탱 교대."
L["- Flügelstoß: senkt Bedrohung -> Zweittank bereit."] = "- 날개 강타: 위협 수준 감소 -> 보조 탱커 대기."
L["Taktik: Zwei Tanks wechseln bei jedem Schatten-Debuff, Raid seitlich. Mit Umhängen ist der Kampf ruhig."] = "공략: 그림자 디버프마다 탱커 둘이 교대, 공격대는 측면. 망토만 있으면 무난한 전투."
L["SCHATTENSCHWINGE: Tankwechsel bei Schatten-Debuff! Umhang an!"] = "에본로크: 그림자 디버프 시 탱 교대! 망토 착용!"
L["Nur Tank vorne, Raid seitlich am Boss."] = "앞에는 탱커만, 공격대는 보스 측면."
L["Flammenmaul"] = "플레임고르"
L["- Raserei: mehr Schaden auf den Tank -> Jäger mit Einlullender Schuss sofort entfernen."] = "- 광란: 탱커 피해 증가 -> 사냥꾼이 평정의 사격으로 즉시 해제."
L["- Feuernova: Feuerschaden auf den ganzen Raid -> Heiler aufmerksam, Feuerwiderstand hilft."] = "- 화염 회오리: 공격대 전체 화염 피해 -> 힐러 주의, 화염 저항 도움."
L["- Flügelstoß und Schattenflamme: Bedrohungsverlust und Frontalkegel -> Tankwechsel, Umhang, nur Tank vorne."] = "- 날개 강타와 암흑의 불길: 위협 손실과 전방 부채꼴 -> 탱 교대, 망토, 앞에는 탱커만."
L["Taktik: Zwei Tanks, Jäger-Rotation für Einlullender Schuss, Raid seitlich und verteilt."] = "공략: 탱커 둘, 평정의 사격은 사냥꾼 로테이션, 공격대는 측면 산개."
L["FLAMMENMAUL: Raserei sofort einlullen! Umhang an!"] = "플레임고르: 광란 즉시 평정! 망토 착용!"
L["Tankwechsel bei Flügelstoß, Feuernova gegenheilen."] = "날개 강타 시 탱 교대, 화염 회오리는 힐로 버티기."
L["Schattenschwinge und Flammenmaul (gemeinsame Begegnung)"] = "에본로크와 플레임고르 (동시 전투)"
L["- Gemeinsamer Kampf: beide Drachen gleichzeitig -> getrennt tanken, Fernkampf zwischen beiden aufteilen."] = "- 동시 전투: 두 용을 동시에 -> 따로 탱, 원딜은 둘로 나누기."
L["- Schatten von Schattenschwinge: Treffer auf dem betroffenen Tank heilen den Drachen -> sofort Tankwechsel."] = "- 에본로크의 그림자: 걸린 탱커를 때리면 용이 회복 -> 즉시 탱 교대."
L["- Raserei (Flammenmaul): sofort mit Einlullender Schuss entfernen."] = "- 광란 (플레임고르): 평정의 사격으로 즉시 해제."
L["- Schattenflamme und Flügelstoß: Frontalkegel und Bedrohungsverlust -> Umhang, nur Tanks vorne."] = "- 암흑의 불길과 날개 강타: 전방 부채꼴과 위협 손실 -> 망토, 앞에는 탱커만."
L["Taktik: Je zwei Tanks pro Drache, Drachen voneinander weg und seitlich zum Raid ausrichten. Ein Drache nach dem anderen fokussieren."] = "공략: 용마다 탱커 두 명, 두 용을 서로 떨어뜨리고 공격대 쪽으로 측면을 향하게. 한 마리씩 점사."
L["Nur in Classic-Versionen, in denen beide Drachen gemeinsam bekämpft werden."] = "두 용을 함께 상대하는 클래식 버전에서만 해당."
L["DRACHEN: Getrennt tanken! Tankwechsel bei Schatten, Raserei einlullen!"] = "용: 따로 탱! 그림자 시 탱 교대, 광란 평정!"
L["Umhang an, nur Tanks vorne. Fokus laut Symbol."] = "망토 착용, 앞에는 탱커만. 징표대로 점사."
L["Schattenschwinge/Flammenmaul"] = "에본로크/플레임고르"
L["Totenkopf auf den Drachen, der zuerst stirbt, Kreuz auf den zweiten."] = "먼저 죽일 용에 해골, 두 번째에 가위표."
L["Chromaggus"] = "크로마구스"
L["- Atem: zwei von fünf Atemarten pro ID (z. B. Verbrennen, Ätzende Säure, Frostbrand, Zeitraffer, Fleisch entzünden) -> hinter die Wand in Deckung gehen."] = "- 숨결: 귀속마다 다섯 숨결 중 두 가지 (예: 소각, 부식성 산, 서리 화상, 시간 경과, 살점 점화) -> 벽 뒤로 숨기."
L["- Brutgebrechen: fünf farbige Debuffs; Bronze nur mit Sand des Stundenglases entfernbar -> bannen, entfluchen, Gift/Krankheit heilen."] = "- 혈족의 고통: 다섯 색 디버프; 청동은 모래시계 모래로만 해제 -> 마법 해제, 저주 해제, 독/질병 치료."
L["- Raserei: Jäger mit Einlullender Schuss; ab 20 % Wutanfall -> Burn."] = "- 광란: 사냥꾼 평정의 사격; 20 %부터 격노 -> 극딜."
L["- Wechselnde Verwundbarkeit: Chromaggus wird gegen eine Schule anfällig -> passende Zauber nutzen."] = "- 약점 변화: 크로마구스가 특정 계열에 취약해짐 -> 맞는 주문 사용."
L["Taktik: Tank zieht Chromaggus an den Eingang, Raid steht für die Atemangriffe hinter der Mauer in Deckung. Debuffs sofort entfernen."] = "공략: 탱커가 크로마구스를 입구로 끌고, 공격대는 숨결 때 벽 뒤에 숨기. 디버프 즉시 해제."
L["CHROMAGGUS: Bei Atem hinter die Wand! Brutgebrechen sofort entfernen!"] = "크로마구스: 숨결 때 벽 뒤로! 혈족의 고통 즉시 해제!"
L["Raserei einlullen, Sand für Bronze bereithalten. Ab 20 % Burn."] = "광란 평정, 청동용 모래 준비. 20 %부터 극딜."
L["Nefarian + Drakoniden"] = "네파리안 + 드라코니드"
L["- Phase 1: Drakoniden zweier Farben aus beiden Seiten -> an beiden Seiten tanken und töten, bis Nefarian landet."] = "- 1단계: 양쪽에서 두 색의 드라코니드 -> 네파리안 착지까지 양쪽에서 탱하고 처치."
L["- Dröhnendes Gebrüll: Furcht auf alle -> Furchtschutz, Tremorstotem, Tanks mit Berserkerwut."] = "- 우레같은 포효: 전원 공포 -> 공포의 수호물, 진동의 토템, 탱커는 광전사의 격노."
L["- Klassenrufe: Klassen erhalten negative Effekte -> je nach Ruf reagieren (z. B. Krieger Haltung, Priester nicht heilen)."] = "- 직업 호출: 직업별 해로운 효과 -> 호출에 맞게 대응 (예: 전사 태세, 사제 치유 금지)."
L["- Schleier der Schatten/Schattenflamme: Heilungsreduktion und Frontalkegel -> entfluchen, Umhang, nur Tank vorne."] = "- 어둠의 장막/암흑의 불길: 치유 감소와 전방 부채꼴 -> 저주 해제, 망토, 앞에는 탱커만."
L["- Phase 3 bei 20 %: tote Drakoniden erstehen als Skelette -> Offtanks sammeln, Fokus Nefarian."] = "- 20 %에 3단계: 죽은 드라코니드가 해골로 부활 -> 보조 탱커가 모으고, 네파리안 점사."
L["Taktik: Zwei Gruppen halten in Phase 1 die Drakoniden. Phase 2 Nefarian mit Rücken zur Wand tanken, Raid seitlich, auf Klassenrufe achten."] = "공략: 1단계에 두 조가 드라코니드 처리. 2단계 네파리안은 벽을 등지고 탱, 공격대 측면, 직업 호출 주의."
L["NEFARIAN: Furchtschutz bereit! Auf Klassenrufe reagieren!"] = "네파리안: 공포의 수호물 준비! 직업 호출에 대응!"
L["Nur Tank vorne, Umhang an. Phase 3: Skelette sammeln, Fokus Nef."] = "앞에는 탱커만, 망토 착용. 3단계: 해골 모으고 네파 점사."
L["Naxxramas"] = "낙스라마스"
L["Anub'Rekhan + Gruftwächter"] = "아눕레칸 + 지하실 경비병"
L["- Heuschreckenschwarm: Anub'Rekhan wird schneller und verursacht viel Schaden -> Tank kitet ihn durch den Raum."] = "- 메뚜기 떼: 아눕레칸이 빨라지고 큰 피해 -> 탱커가 방 안을 카이팅."
L["- Aufspießen: Linie mit Hochschleudern -> nicht in einer Linie mit dem Boss stehen."] = "- 꿰뚫기: 직선 띄우기 -> 보스와 일직선에 서지 말 것."
L["- Gruftwächter: kommen zu Beginn und während des Kampfes -> Offtank übernimmt, zuerst töten."] = "- 지하실 경비병: 시작과 전투 중 등장 -> 보조 탱커가 인계, 먼저 처치."
L["- Leichenskarabäen: aus getöteten Spielern/Adds -> mit Flächenschaden töten."] = "- 시체 스카라베: 죽은 플레이어/쫄에서 나옴 -> 광역 처치."
L["Taktik: Wächter zuerst töten, Raid verteilt seitlich. Beim Heuschreckenschwarm kitet der Tank Anub'Rekhan im großen Kreis durch den Raum."] = "공략: 경비병 먼저 처치, 공격대 측면 산개. 메뚜기 떼 때 탱커가 아눕레칸을 크게 원을 그리며 카이팅."
L["ANUB'REKHAN: Heuschreckenschwarm -> Tank kitet, Raid ausweichen!"] = "아눕레칸: 메뚜기 떼 -> 탱커 카이팅, 공격대 회피!"
L["Gruftwächter zuerst. Nicht in Linie für Aufspießen."] = "지하실 경비병 먼저. 꿰뚫기 일직선 금지."
L["Großwitwe Faerlina + Anhänger und Verehrer"] = "귀부인 팰리나 + 추종자와 숭배자"
L["- Raserei: hoher Tankschaden -> Verehrer in ihrer Nähe sterben lassen (Umarmung der Witwe), Raserei endet."] = "- 광란: 큰 탱커 피해 -> 근처에서 숭배자 처치 (과부의 포옹), 광란 종료."
L["- Feuerregen: Feuerzone -> sofort verlassen."] = "- 불비: 화염 지대 -> 즉시 벗어나기."
L["- Giftblitzsalve: Naturschaden auf Gruppen -> Gift entfernen, Naturwiderstand hilft."] = "- 독화살 일제 사격: 파티 단위 자연 피해 -> 독 해제, 자연 저항 도움."
L["- Anhänger: Ansturm und Stille -> zuerst töten."] = "- 추종자: 돌진과 침묵 -> 먼저 처치."
L["Taktik: Anhänger zuerst töten, Verehrer per Gedankenkontrolle der Priester aufsparen und bei Raserei neben Faerlina opfern."] = "공략: 추종자 먼저 처치, 숭배자는 사제 정신 지배로 남겨뒀다가 광란 때 팰리나 옆에서 희생."
L["FAERLINA: Anhänger zuerst! Verehrer für Raserei aufheben!"] = "팰리나: 추종자 먼저! 숭배자는 광란용으로 남기기!"
L["Raus aus dem Feuerregen, Gift entfernen."] = "불비에서 나오고 독 해제."
L["Faerlina"] = "팰리나"
L["Totenkopf/Kreuz auf die Anhänger (zuerst töten), Stern bis Dreieck auf die Verehrer für die Priester."] = "추종자에 해골/가위표 (먼저 처치), 숭배자에 별~세모 (사제용)."
L["Maexxna + Spinnenjunge"] = "맥스나 + 새끼 거미"
L["- Netzspray: betäubt den ganzen Raid ca. 8 Sek. -> vorher Tank voll heilen, HoTs drauf."] = "- 거미줄 분사: 공격대 전체 약 8초 기절 -> 미리 탱커 풀피, 지속 치유 걸기."
L["- Netzwirbel: Spieler werden an die Wand gesponnen -> Fernkampf befreit sie sofort."] = "- 거미줄 감싸기: 플레이어가 벽에 감김 -> 원딜이 즉시 풀어주기."
L["- Nekrotisches Gift: senkt Heilung auf dem Tank -> Gift sofort entfernen."] = "- 괴저 독: 탱커 치유량 감소 -> 즉시 독 해제."
L["- Spinnenjunge: werden regelmäßig ausgespuckt -> Flächenschaden; ab 30 % Raserei -> Burn."] = "- 새끼 거미: 주기적으로 뱉어냄 -> 광역; 30 %부터 광란 -> 극딜."
L["Taktik: Tank in der Mitte, Fernkampf befreit Eingesponnene, Heiler bereiten jedes Netzspray mit Vorheilung vor."] = "공략: 탱커는 중앙, 원딜이 감긴 사람 구출, 힐러는 거미줄 분사마다 선힐 준비."
L["MAEXXNA: Vor Netzspray Tank voll heilen! Eingesponnene sofort befreien!"] = "맥스나: 거미줄 분사 전 탱커 풀피! 감긴 사람 즉시 구출!"
L["Nekrotisches Gift entfernen, Spinnenjunge per Flächenschaden."] = "괴저 독 해제, 새끼 거미는 광역."
L["Noth der Seuchenfürst + Seuchenkrieger"] = "역병술사 노스 + 역병 전사"
L["- Fluch des Seuchenfürsten: bei Ablauf Schaden auf Spieler und Umgebung -> sofort entfluchen."] = "- 역병술사의 저주: 만료 시 대상과 주변에 피해 -> 즉시 저주 해제."
L["- Blinzeln: Noth teleportiert und setzt Bedrohung zurück -> Tanks schnell übernehmen."] = "- 점멸: 노스가 순간이동하며 위협 수준 초기화 -> 탱커 빠르게 인계."
L["- Balkon-Phase: Noth teleportiert sich weg, Wellen von Skeletten -> Offtanks sammeln, Flächenschaden."] = "- 발코니 단계: 노스가 사라지고 해골 웨이브 -> 보조 탱커가 모으고 광역."
L["Taktik: Entfluchen fest einteilen, Tanks in den Ecken bereit. Adds in den Balkon-Phasen sammeln und schnell töten."] = "공략: 저주 해제 담당 고정, 구석마다 탱커 대기. 발코니 단계 쫄은 모아서 빠르게 처치."
L["NOTH: Flüche sofort entfernen! Nach Blinzeln Tank übernehmen!"] = "노스: 저주 즉시 해제! 점멸 후 탱커 인계!"
L["Balkon-Phase: Adds sammeln und mit Flächenschaden töten."] = "발코니 단계: 쫄 모아서 광역 처치."
L["Heigan der Unreine"] = "부정의 헤이건"
L["- Ausbruch: der Boden bricht in Zonen nacheinander aus -> im Takt die Zonen wechseln (Tanzen)."] = "- 분출: 바닥이 구역별로 차례로 분출 -> 박자에 맞춰 구역 이동 (춤추기)."
L["- Zauberunterbrechung/Manabrand: in der Nähe Zauberverlangsamung -> Fernkampf auf der Plattform weg."] = "- 주문 방해/마나 연소: 근처 시전 속도 감소 -> 원딜은 단상 위로 빠지기."
L["- Fieberhafte Krankheit: Krankheits-Debuff, senkt Leben -> Krankheit heilen."] = "- 열병 질병: 질병 디버프, 생명력 감소 -> 질병 치료."
L["- Tanz-Phase: Heigan teleportiert auf die Plattform, schnellere Ausbrüche -> alle tanzen mit."] = "- 춤 단계: 헤이건이 단상으로 순간이동, 분출이 빨라짐 -> 전원 함께 춤."
L["Taktik: Tank führt Heigan im Takt durch die Zonen, Fernkampf auf der Plattform. In der Tanz-Phase alle zusammen der Zonenreihenfolge folgen."] = "공략: 탱커가 박자에 맞춰 헤이건을 구역 사이로 이동, 원딜은 단상. 춤 단계에는 전원 구역 순서를 따라 이동."
L["HEIGAN: Im Takt die Zonen wechseln! Nicht im Ausbruch stehen!"] = "헤이건: 박자 맞춰 구역 이동! 분출 위에 서지 마세요!"
L["Krankheit heilen. Tanz-Phase: alle zusammen dem Tank folgen."] = "질병 치료. 춤 단계: 전원 탱커 따라가기."
L["Loatheb + Sporen"] = "로데브 + 포자"
L["- Verderbter Geist: Heiler können nur ca. einmal pro Minute heilen -> feste Heilrotation."] = "- 타락한 정신: 힐러는 약 1분에 한 번만 치유 가능 -> 고정 힐 로테이션."
L["- Unausweichliches Schicksal: hoher Schattenschaden nach kurzer Zeit -> Schattenschutz-Tränke, rechtzeitig heilen."] = "- 피할 수 없는 운명: 잠시 후 큰 암흑 피해 -> 암흑 보호 물약, 제때 치유."
L["- Sporen: getötete Spore gibt nahen Spielern kritische Treffer -> Gruppen nacheinander in die Spore."] = "- 포자: 포자를 잡으면 근처 플레이어 치명타 증가 -> 파티별로 차례로 포자에."
L["Taktik: Strikte Heilrotation, Schattenschutz-Tränke vorher. Sporen gruppenweise für Kritbonus nutzen und Schaden maximieren."] = "공략: 엄격한 힐 로테이션, 암흑 보호 물약 미리 사용. 포자는 파티별로 치명타 버프로 활용해 딜 극대화."
L["LOATHEB: Heilrotation einhalten! Schattenschutz-Trank nutzen!"] = "로데브: 힐 로테이션 지키기! 암흑 보호 물약 사용!"
L["Sporen gruppenweise nutzen für kritische Treffer."] = "포자는 파티별로 치명타 버프 활용."
L["Instrukteur Razuvious + 4 Todesritter-Reservisten"] = "훈련교관 라주비어스 + 죽음의 기사 예비병 4"
L["- Schwere Nahkampfschläge: töten normale Tanks fast sofort -> nur gedankenkontrollierte Reservisten tanken ihn."] = "- 강력한 근접 공격: 일반 탱커는 거의 즉사 -> 정신 지배한 예비병만 탱."
L["- Störender Schrei: Manabrand und Schaden im Umkreis -> Abstand halten."] = "- 방해의 외침: 주변 마나 연소와 피해 -> 거리 유지."
L["- Gedankenkontrolle: Priester steuern die Reservisten (Schildwall, Spott) -> Kontrolle rechtzeitig wechseln."] = "- 정신 지배: 사제가 예비병 조종 (방패의 벽, 도발) -> 제때 지배 교체."
L["Taktik: Priester übernehmen je einen Reservisten und wechseln die Rolle als Tank, Fernkampf auf Distanz, Nahkampf am Boss."] = "공략: 사제가 예비병을 하나씩 맡아 탱 역할을 교대, 원딜은 거리 유지, 근딜은 보스."
L["RAZUVIOUS: Nur Reservisten tanken! Priester Kontrolle rechtzeitig wechseln!"] = "라주비어스: 예비병만 탱! 사제는 제때 지배 교체!"
L["Abstand wegen Störender Schrei."] = "방해의 외침 때문에 거리 유지."
L["Razuvious (Reservisten)"] = "라주비어스 (예비병)"
L["Jeder Reservist ein Symbol, jeder Priester übernimmt sein zugewiesenes Symbol."] = "예비병마다 징표 하나, 사제마다 배정된 징표를 맡음."
L["Gothik der Seelenjäger + Lebende und Untote"] = "영혼착취자 고딕 + 산 자와 죽은 자"
L["- Zwei Seiten: Raid aufgeteilt in lebende und tote Seite -> beide Seiten gleich stark besetzen."] = "- 양쪽 진영: 공격대를 산 자 쪽과 죽은 자 쪽으로 분할 -> 양쪽 전력을 균등하게."
L["- Lebende Adds: sterben sie, erscheinen sie als Geister auf der toten Seite -> tote Seite muss mithalten."] = "- 산 자 쫄: 죽으면 죽은 자 쪽에 망령으로 등장 -> 죽은 자 쪽도 버텨야 함."
L["- Tor: öffnet nach einiger Zeit, dann kommt Gothik herunter -> Adds vorher unter Kontrolle haben."] = "- 문: 일정 시간 후 열리고 고딕이 내려옴 -> 그 전에 쫄 정리."
L["- Seele ernten: stapelnder Debuff -> zügig töten."] = "- 영혼 수확: 중첩 디버프 -> 빠르게 처치."
L["Taktik: Raid in zwei Hälften, jede Seite tötet ihre Wellen. Nach Öffnen des Tores Gothik tanken und schnell töten."] = "공략: 공격대를 반으로 나눠 각자 웨이브 처치. 문이 열리면 고딕을 탱하고 빠르게 처치."
L["GOTHIK: Beide Seiten halten! Tote Seite auf Geister vorbereiten!"] = "고딕: 양쪽 다 버티기! 죽은 자 쪽은 망령 대비!"
L["Nach dem Tor: Gothik schnell töten."] = "문이 열리면: 고딕 빠르게 처치."
L["Die Vier Reiter: Thane Korth'azz, Lady Blaumeux, Hochlord Mograine, Sir Zeliek"] = "4인의 기병대: 영주 코스아즈, 여군주 블라미우스, 대영주 모그레인, 젤리에크 경"
L["- Male: jeder Reiter stapelt sein Mal, hohe Stapel töten -> Tanks rotieren zwischen den Reitern."] = "- 징표: 기병마다 자신의 징표 중첩, 중첩이 높으면 사망 -> 탱커가 기병 사이를 로테이션."
L["- Meteor (Korth'azz): Schaden geteilt auf getroffene Spieler -> bei ihm zusammenstehen."] = "- 유성 (코스아즈): 맞은 플레이어끼리 피해 분배 -> 그 앞에 뭉치기."
L["- Leerezone (Blaumeux): Schattenfläche -> herauslaufen."] = "- 공허의 지대 (블라미우스): 암흑 장판 -> 밖으로 나가기."
L["- Heiliger Zorn (Zeliek): springt zwischen Spielern -> verteilt stehen."] = "- 신의 격노 (젤리에크): 플레이어 사이로 튐 -> 산개."
L["Taktik: Reiter in die vier Ecken ziehen, Tanks und Heiler rotieren nach festem Plan, um Mal-Stapel abzubauen. Zwei Reiter nacheinander fokussieren."] = "공략: 기병을 네 구석으로 끌고, 탱커와 힐러가 고정 계획대로 로테이션해 징표 중첩 해소. 기병 둘을 차례로 점사."
L["VIER REITER: Rotation einhalten! Male nicht zu hoch stapeln!"] = "4인의 기병대: 로테이션 지키기! 징표 너무 쌓지 마세요!"
L["Meteor: zusammen. Zeliek: verteilt. Leerezone verlassen."] = "유성: 뭉치기. 젤리에크: 산개. 공허의 지대 벗어나기."
L["Flickwerk"] = "패치워크"
L["- Hasserfüllter Schlag: trifft den Nahkampf-Spieler mit dem meisten Leben (nicht den Haupttank) -> drei Offtanks mit voller Gesundheit soaken."] = "- 증오의 일격: 근접 중 생명력이 가장 높은 대상 적중 (메인 탱 제외) -> 풀피 보조 탱커 셋이 받아내기."
L["- Berserker nach ca. 7 Minuten: Raid stirbt -> Schaden maximieren."] = "- 약 7분 후 광폭: 공격대 전멸 -> 딜 극대화."
L["- Raserei ab 5 %: mehr Schaden -> Heiler voll auf die Tanks."] = "- 5 %부터 광란: 피해 증가 -> 힐러는 탱커에 집중."
L["Taktik: Haupttank plus drei Offtanks mit hohem Leben im Nahkampf, Heiler fest auf die Tanks eingeteilt, alle anderen maximaler Schaden."] = "공략: 메인 탱과 생명력 높은 보조 탱커 셋이 근접, 힐러는 탱커 고정 배정, 나머지는 최대 딜."
L["FLICKWERK: Offtanks mit vollem Leben im Nahkampf! Volles DPS!"] = "패치워크: 보조 탱커 풀피로 근접! 풀딜!"
L["Heiler nur auf die Tanks. Berserker-Timer beachten."] = "힐러는 탱커만. 광폭 타이머 주의."
L["Grobbulus + Brühschleime"] = "그라불루스 + 오물 수액괴물"
L["- Mutierende Injektion: Spieler explodiert nach Ablauf mit Giftwolke -> an den Rand laufen, erst dort bannen/ablaufen lassen."] = "- 돌연변이 주입: 만료 시 독구름과 함께 폭발 -> 가장자리로 가서 해제/만료."
L["- Schleimspray: Kegel vor dem Boss, ruft Brühschleime -> Raid nicht vorne, Schleime töten."] = "- 수액 분사: 보스 앞 부채꼴, 오물 수액괴물 소환 -> 공격대는 앞 금지, 수액괴물 처치."
L["- Giftwolken: bleiben liegen -> Tank zieht Grobbulus langsam am Rand entlang."] = "- 독구름: 바닥에 남음 -> 탱커가 가장자리를 따라 천천히 이동."
L["Taktik: Tank kitet Grobbulus langsam um den Raum, Raid hinten/seitlich, betroffene Spieler laufen mit Injektion an die Seite."] = "공략: 탱커가 그라불루스를 방 둘레로 천천히 카이팅, 공격대는 뒤/측면, 주입 대상은 옆으로 이동."
L["GROBBULUS: Injektion -> an den Rand laufen! Nicht vor den Boss!"] = "그라불루스: 주입 -> 가장자리로! 보스 앞 금지!"
L["Schleime töten, Giftwolken meiden, Tank kitet am Rand."] = "수액괴물 처치, 독구름 피하기, 탱커는 가장자리 카이팅."
L["Gluth + Zombies"] = "글루스 + 좀비"
L["- Tödliche Wunde: Heilungsreduktions-Stapel -> Tankwechsel."] = "- 죽음의 상처: 치유 감소 중첩 -> 탱 교대."
L["- Dezimieren: bringt alle auf ca. 5 % Leben, Zombies laufen zu Gluth und heilen ihn -> Zombies kiten und mit Flächenschaden töten."] = "- 척살: 전원 생명력 약 5 %로, 좀비가 글루스에게 가서 치유 -> 좀비 카이팅 후 광역 처치."
L["- Raserei: Jäger mit Einlullender Schuss."] = "- 광란: 사냥꾼 평정의 사격."
L["- Schreckliches Gebrüll: Furcht -> Furchtschutz für Tanks."] = "- 공포의 포효: 공포 -> 탱커에게 공포의 수호물."
L["Taktik: Zwei Tanks wechseln, ein Kiter mit Fallen hält die Zombies vom Boss weg. Nach Dezimieren Zombies sofort mit Flächenschaden töten."] = "공략: 탱커 둘 교대, 덫을 쓰는 카이터가 좀비를 보스에게서 떼어놓기. 척살 후 좀비 즉시 광역 처치."
L["GLUTH: Zombies kiten und töten! Raserei einlullen!"] = "글루스: 좀비 카이팅 후 처치! 광란 평정!"
L["Tankwechsel bei Tödlicher Wunde. Nach Dezimieren hochheilen."] = "죽음의 상처 시 탱 교대. 척살 후 풀힐."
L["Thaddius + Stalagg und Feugen"] = "타디우스 + 스탈라그와 퓨진"
L["- Phase 1: Stalagg und Feugen auf zwei Plattformen -> beide gleichzeitig töten (kurzes Zeitfenster), sonst erwacht der andere wieder."] = "- 1단계: 두 단상의 스탈라그와 퓨진 -> 동시에 처치 (짧은 시간 내), 아니면 다른 쪽 부활."
L["- Magnetzug: tauscht die Tanks zwischen den Plattformen -> Tanks bereit halten."] = "- 자력 끌기: 단상 사이 탱커 교환 -> 탱커 대기."
L["- Polaritätsverschiebung: Plus- oder Minus-Ladung -> zur Gruppe mit gleicher Ladung laufen."] = "- 극성 변환: 양전하 또는 음전하 -> 같은 전하 그룹으로 이동."
L["- Kettenblitz und Berserker nach ca. 5 Minuten -> verteilt und schnell."] = "- 연쇄 번개와 약 5분 후 광폭 -> 산개, 빠르게."
L["Taktik: Phase 1 beide Adds gleichzeitig herunterbringen. Phase 2 feste Plus- und Minus-Seite, bei Polaritätswechsel sofort Seite wechseln."] = "공략: 1단계 두 쫄을 동시에 처치. 2단계 양/음 진영 고정, 극성 변환 시 즉시 진영 이동."
L["THADDIUS: Plus links, Minus rechts! Bei Polaritätswechsel Seite wechseln!"] = "타디우스: 양전하 왼쪽, 음전하 오른쪽! 극성 변환 시 이동!"
L["Phase 1: Stalagg und Feugen gleichzeitig töten."] = "1단계: 스탈라그와 퓨진 동시 처치."
L["Saphiron"] = "사피론"
L["- Frostaura: dauerhafter Frostschaden -> Frostwiderstand für alle."] = "- 서리 오라: 지속 냉기 피해 -> 전원 냉기 저항."
L["- Lebensentzug: Fluch auf Spielern -> sofort entfluchen."] = "- 생명력 흡수: 플레이어 저주 -> 즉시 저주 해제."
L["- Flugphase: Eisblitz friert Spieler zu Eisblöcken -> danach hinter einem Eisblock vor Frostatem verstecken."] = "- 비행 단계: 얼음 화살이 플레이어를 얼음덩이로 -> 이후 얼음덩이 뒤에 숨어 서리 숨결 피하기."
L["- Blizzard: wandernde Frostzonen -> ausweichen."] = "- 눈보라: 움직이는 냉기 지대 -> 피하기."
L["Taktik: Frostwiderstand-Ausrüstung pflicht. Tank hält Saphiron mit Kopf weg vom Raid, in der Flugphase alle verteilt und dann hinter Eisblock."] = "공략: 냉기 저항 장비 필수. 탱커는 사피론 머리를 공격대 반대로, 비행 단계에 전원 산개 후 얼음덩이 뒤로."
L["SAPHIRON: Hinter Eisblock bei Frostatem! Flüche sofort entfernen!"] = "사피론: 서리 숨결 때 얼음덩이 뒤로! 저주 즉시 해제!"
L["Frostwiderstand an. Blizzard ausweichen."] = "냉기 저항 착용. 눈보라 피하기."
L["Kel'Thuzad + Adds"] = "켈투자드 + 쫄"
L["- Phase 1: Skelette, Abscheulichkeiten und Seelenweber -> am Rand der Nischen töten."] = "- 1단계: 해골, 누더기골렘, 영혼 착취자 -> 구역 가장자리에서 처치."
L["- Frostblitz: sehr hoher Schaden -> unterbrechen."] = "- 얼음화살: 매우 큰 피해 -> 차단."
L["- Frostschlag/Detonieren von Mana/Schattenspalt: Frost-Wurzeln, Manaexplosion und Bodenflächen -> heilen, Manaspieler raus, Spalt verlassen."] = "- 냉기 작렬/마나 폭발/암흑 균열: 냉기 뿌리묶기, 마나 폭발, 바닥 장판 -> 치유, 마나 직업 빠지기, 균열 벗어나기."
L["- Ketten von Kel'Thuzad: Gedankenkontrolle -> Spieler kontrollieren."] = "- 켈투자드의 사슬: 정신 지배 -> 플레이어 제어."
L["- Phase 3 (45 %): Wächter von Eiskrone -> Priester fesseln die Untoten."] = "- 3단계 (45 %): 얼음왕관 수호자 -> 사제가 언데드 속박."
L["Taktik: Raid verteilt in den Nischen, Unterbrecher-Rotation auf Frostblitz. Phase 3: Wächter per Untote fesseln binden."] = "공략: 공격대는 구역별 산개, 얼음화살에 차단 로테이션. 3단계: 수호자는 언데드 속박으로 묶기."
L["KEL'THUZAD: Frostblitz unterbrechen! Schattenspalt sofort verlassen!"] = "켈투자드: 얼음화살 차단! 암흑 균열 즉시 벗어나기!"
L["Gedankenkontrollierte kontrollieren. Phase 3: Wächter fesseln."] = "정신 지배된 사람 제어. 3단계: 수호자 속박."
L["Kel'Thuzad (Wächter)"] = "켈투자드 (수호자)"
L["Jeder Wächter von Eiskrone ein Symbol, Priester fesseln ihr zugewiesenes Symbol (Stern zuerst)."] = "얼음왕관 수호자마다 징표 하나, 사제는 배정된 징표 속박 (별 먼저)."
L["Onyxias Hort"] = "오닉시아의 둥지"
L["Onyxia + Welpen und Wachen"] = "오닉시아 + 새끼용과 경비병"
L["- Phase 2 (65 %): fliegt, Feuerbälle und Tiefer Atem -> aus der Atemlinie laufen, Welpen aus den Höhlen töten."] = "- 2단계 (65 %): 비행, 화염구와 깊은 숨결 -> 숨결 경로에서 벗어나기, 동굴에서 나오는 새끼용 처치."
L["- Phase 3 (40 %): landet, Furcht (Gebrüll) und Bodenausbrüche -> Furchtschutz, Tremorstotem."] = "- 3단계 (40 %): 착지, 공포 (포효)와 바닥 분출 -> 공포의 수호물, 진동의 토템."
L["- Flügelstoß: senkt Bedrohung -> Tank behält vorsichtig Aggro."] = "- 날개 강타: 위협 수준 감소 -> 탱커는 신중하게 어그로 유지."
L["Taktik: Phase 1 Onyxia mit Kopf zur Wand, Raid seitlich. Phase 2 verteilt, Welpen mit Flächenschaden. Phase 3 Tank übernimmt, Furcht beachten."] = "공략: 1단계 오닉시아 머리를 벽으로, 공격대 측면. 2단계 산개, 새끼용 광역. 3단계 탱커 인계, 공포 주의."
L["ONYXIA: Nicht vor oder hinter den Drachen! Tiefer Atem: aus der Linie!"] = "오닉시아: 용 앞뒤 금지! 깊은 숨결: 경로에서 벗어나기!"
L["Welpen sofort töten. Phase 3: Furchtschutz bereit."] = "새끼용 즉시 처치. 3단계: 공포의 수호물 준비."
L["Zul'Gurub"] = "줄구룹"
L["Hohepriesterin Jeklik + Fledermäuse"] = "대여사제 제클릭 + 박쥐"
L["- Phase 1 (Fledermausform): Ansturm, Schallexplosion (Stille), Fledermausschwärme -> Fernkampf verteilt, Fledermäuse töten."] = "- 1단계 (박쥐 변신): 돌진, 음파 폭발 (침묵), 박쥐 떼 -> 원딜 산개, 박쥐 처치."
L["- Phase 2 (50 %): Trollform, Große Heilung -> unterbrechen!"] = "- 2단계 (50 %): 트롤 변신, 상급 치유 -> 차단!"
L["- Gedankenschinden/Schattenwort: Schmerz: Schattenschaden -> bannen, heilen."] = "- 정신의 채찍/어둠의 권능: 고통: 암흑 피해 -> 해제, 치유."
L["- Feuer-Fledermäuse: werfen Feuerbomben -> aus den Flammen laufen."] = "- 화염 박쥐: 화염 폭탄 투하 -> 불에서 나오기."
L["Taktik: Tank hält Jeklik, Nahkampf auf Schallexplosion achten. Phase 2: Unterbrecher fest einteilen, aus dem Feuer bleiben."] = "공략: 탱커가 제클릭 유지, 근딜은 음파 폭발 주의. 2단계: 차단 담당 고정, 불 피하기."
L["JEKLIK: Große Heilung unterbrechen! Raus aus dem Feuer!"] = "제클릭: 상급 치유 차단! 불에서 나오세요!"
L["Fledermäuse töten, Fernkampf verteilt gegen Ansturm."] = "박쥐 처치, 돌진 대비 원딜 산개."
L["Hohepriester Venoxis + 4 Schlangen"] = "대사제 베녹시스 + 뱀 4"
L["- Schlangen: vier Adds -> zuerst töten."] = "- 뱀: 쫄 넷 -> 먼저 처치."
L["- Heiliges Feuer/Erneuerung: Priesterform heilt und verursacht Schaden -> unterbrechen und bannen."] = "- 신성한 불꽃/소생: 사제 형태로 치유와 피해 -> 차단 및 해제."
L["- Heiliger Zorn: springt zwischen Spielern -> Abstand halten."] = "- 신의 격노: 플레이어 사이로 튐 -> 거리 유지."
L["- Schlangenform (50 %): Giftwolken und Gift -> aus Wolken laufen, Gift entfernen."] = "- 뱀 변신 (50 %): 독구름과 독 -> 구름에서 나오기, 독 해제."
L["Taktik: Schlangen zuerst, dann Venoxis mit Unterbrechern. In Schlangenform Giftwolken meiden und Gift entfernen."] = "공략: 뱀 먼저, 이후 차단하며 베녹시스. 뱀 변신 시 독구름 피하고 독 해제."
L["VENOXIS: Schlangen zuerst! Heilige Zauber unterbrechen!"] = "베녹시스: 뱀 먼저! 신성 주문 차단!"
L["Abstand für Heiliger Zorn. Giftwolken meiden."] = "신의 격노 대비 거리 유지. 독구름 피하기."
L["Venoxis"] = "베녹시스"
L["Totenkopf, Kreuz, Viereck, Mond auf die Schlangen in Tötungsreihenfolge."] = "뱀에 처치 순서대로 해골, 가위표, 네모, 달."
L["Hohepriesterin Mar'li + Spinnenjunge"] = "대여사제 말리 + 새끼 거미"
L["- Spinnenjunge: wachsen mit der Zeit -> sofort töten."] = "- 새끼 거미: 시간이 지나면 성장 -> 즉시 처치."
L["- Giftblitzsalve: Naturschaden im Umkreis -> Gift entfernen."] = "- 독화살 일제 사격: 주변 자연 피해 -> 독 해제."
L["- Spinnenform: umhüllende Netze und Bedrohungsverlust -> zweiter Tank bereit."] = "- 거미 변신: 감싸는 거미줄과 위협 손실 -> 보조 탱커 대기."
L["- Leben entziehen: heilt Mar'li -> bannen bzw. unterbrechen."] = "- 생명력 흡수: 말리 치유 -> 해제 또는 차단."
L["Taktik: Spinnenjunge sofort töten, Gift entfernen. Zwei Tanks wegen Bedrohungsverlust in Spinnenform."] = "공략: 새끼 거미 즉시 처치, 독 해제. 거미 변신 시 위협 손실 대비 탱커 둘."
L["MAR'LI: Spinnenjunge sofort töten! Gift entfernen!"] = "말리: 새끼 거미 즉시 처치! 독 해제!"
L["Zweittank bereit bei Spinnenform."] = "거미 변신 때 보조 탱커 대기."
L["Blutfürst Mandokir + Ohgan"] = "혈군주 만도키르 + 오간"
L["- Bedrohlicher Blick: Mandokir starrt einen Spieler an -> dieser macht nichts (kein Angriff, Zauber, Bewegung), sonst Ansturm und Tod."] = "- 위협의 응시: 만도키르가 한 명을 노려봄 -> 그 사람은 아무것도 하지 말 것 (공격, 시전, 이동 금지), 아니면 돌진 후 사망."
L["- Wirbelwind: hoher Schaden im Umkreis -> Nahkampf kurz raus."] = "- 소용돌이: 주변 큰 피해 -> 근딜 잠시 빠지기."
L["- Geister: tote Spieler können wiederbelebt werden; Mandokir steigt bei Kills im Level -> Tode vermeiden."] = "- 영혼: 죽은 플레이어 부활 가능; 만도키르는 처치 시 레벨 상승 -> 사망 방지."
L["- Ohgan: Raptor -> von einem zweiten Tank halten."] = "- 오간: 랩터 -> 보조 탱커가 유지."
L["Taktik: Ohgan separat tanken, Mandokir mit Rücken zum Raid. Angestarrte Spieler hören sofort auf zu handeln."] = "공략: 오간은 따로 탱, 만도키르는 공격대 반대 방향. 응시 대상은 즉시 모든 행동 중지."
L["MANDOKIR: Angestarrt? NICHTS tun! Wirbelwind -> Nahkampf raus!"] = "만도키르: 응시 대상? 아무것도 하지 마세요! 소용돌이 -> 근딜 빠지기!"
L["Ohgan separat tanken, Tode vermeiden."] = "오간 따로 탱, 사망 방지."
L["Rand des Wahnsinns: Gri'lek, Hazza'rah, Renataki oder Wushoolay"] = "광기의 가장자리: 그리렉, 하자라, 레나타키 또는 우슐레이"
L["- Wechselnder Boss: einer von vier Bossen, je nach Rotation -> vorher klären, welcher aktiv ist."] = "- 교체 보스: 로테이션에 따라 네 보스 중 하나 -> 누가 나오는지 미리 확인."
L["- Gri'lek: verfolgt Spieler -> Weglaufen; Hazza'rah: Illusionen -> töten; Renataki: Verschwinden/Bedrohungsreset -> Tank bereit."] = "- 그리렉: 플레이어 추격 -> 도망; 하자라: 환영 -> 처치; 레나타키: 사라짐/위협 초기화 -> 탱커 대기."
L["- Wushoolay: Kettenblitz -> verteilt stehen."] = "- 우슐레이: 연쇄 번개 -> 산개."
L["Taktik: Je nach Boss Raid verteilen oder Illusionen schnell töten, ansonsten einfacher Tank-und-Schaden-Kampf."] = "공략: 보스에 따라 산개하거나 환영을 빠르게 처치, 그 외엔 단순한 탱딜 전투."
L["Optionaler Boss, wird über die Gurubashi-Wahnsinnsmechanik beschworen."] = "선택 보스, 구루바시 광기 메커니즘으로 소환."
L["RAND DES WAHNSINNS: Boss-Mechanik beachten! Verteilt stehen!"] = "광기의 가장자리: 보스 기믹 주의! 산개!"
L["Illusionen/Adds schnell töten, Tank bei Bedrohungsreset bereit."] = "환영/쫄 빠르게 처치, 위협 초기화 대비 탱커 대기."
L["Gahz'ranka"] = "가즈란카"
L["- Frostatem: Frontalkegel mit Manaentzug -> nur Tank vorne."] = "- 서리 숨결: 마나 흡수 전방 부채꼴 -> 앞에는 탱커만."
L["- Gewaltiger Geysir: schleudert Spieler hoch -> Fallschaden, Heiler aufmerksam."] = "- 거대한 간헐천: 플레이어를 띄움 -> 낙하 피해, 힐러 주의."
L["- Zerschmettern: Rückstoß auf den Tank -> Tank stabil positionieren."] = "- 강타: 탱커 밀쳐내기 -> 탱커 위치 안정적으로."
L["Taktik: Tank hält Gahz'ranka mit Kopf weg vom Raid, Raid seitlich. Einfacher Kampf, Fallschaden gegenheilen."] = "공략: 탱커가 가즈란카 머리를 공격대 반대로, 공격대 측면. 쉬운 전투, 낙하 피해는 치유로."
L["Optionaler Boss, wird mit einem Schlammstinkerköder am Teich geangelt."] = "선택 보스, 연못에서 진흙투성이 미끼로 낚아 올림."
L["GAHZ'RANKA: Nur Tank vorne! Geysir-Fallschaden gegenheilen!"] = "가즈란카: 앞에는 탱커만! 간헐천 낙하 피해 치유!"
L["Raid seitlich, Heiler auf Rückstoß achten."] = "공격대 측면, 힐러는 밀쳐내기 주의."
L["Hohepriester Thekal + Zelot Lor'Khan und Zelot Zath"] = "대사제 데칼 + 광신자 로르칸과 광신자 자스"
L["- Phase 1: Thekal, Lor'Khan und Zath -> alle drei fast gleichzeitig töten, sonst stehen sie wieder auf."] = "- 1단계: 데칼, 로르칸, 자스 -> 셋을 거의 동시에 처치, 아니면 부활."
L["- Lor'Khan: heilt -> unterbrechen; Zath: Blenden/Verschwinden -> Tank bereit."] = "- 로르칸: 치유 -> 차단; 자스: 실명/사라짐 -> 탱커 대기."
L["- Phase 2 (Tigerform): Kraftschlag mit Rückstoß, Tiger-Adds, Raserei -> Tank an die Wand, Adds töten, Raserei einlullen."] = "- 2단계 (호랑이 변신): 밀쳐내는 강력한 일격, 호랑이 쫄, 광란 -> 탱커 벽으로, 쫄 처치, 광란 평정."
L["Taktik: Drei Tanks, alle drei Ziele gleichmäßig herunterbringen und im Zeitfenster töten. Phase 2: Tank mit Rücken zur Wand."] = "공략: 탱커 셋, 세 대상을 고르게 깎아 제한 시간 안에 처치. 2단계: 탱커는 벽을 등지고."
L["THEKAL: Alle drei gleichzeitig töten! Lor'Khan unterbrechen!"] = "데칼: 셋 동시에 처치! 로르칸 차단!"
L["Phase 2: Tiger töten, Raserei einlullen."] = "2단계: 호랑이 처치, 광란 평정."
L["Thekal"] = "데칼"
L["Totenkopf Thekal, Kreuz Lor'Khan, Viereck Zath – gleichmäßig herunterbringen."] = "해골 데칼, 가위표 로르칸, 네모 자스 – 고르게 깎기."
L["Hohepriesterin Arlokk + Panther"] = "대여사제 알로크 + 표범"
L["- Mal der Arlokk: Panther greifen den markierten Spieler an -> Spieler zum Tank laufen, Panther abfangen."] = "- 알로크의 징표: 표범이 징표 대상 공격 -> 대상은 탱커에게 이동, 표범 가로채기."
L["- Verschwinden: Arlokk wird unsichtbar, viele Panther kommen -> Offtanks sammeln, Flächenschaden."] = "- 사라짐: 알로크가 투명해지고 표범 다수 등장 -> 보조 탱커가 모으고 광역."
L["- Solarplexus/Wirbelwind: Tank wird betäubt -> Zweittank bereit."] = "- 명치 치기/소용돌이: 탱커 기절 -> 보조 탱커 대기."
L["Taktik: Raid in der Mitte zusammen, Offtanks fangen Panther ab, Flächenschaden auf Panther. Arlokk nach Erscheinen sofort übernehmen."] = "공략: 공격대는 중앙에 뭉치고, 보조 탱커가 표범을 잡고 광역. 알로크가 나타나면 즉시 인계."
L["ARLOKK: Markierter Spieler -> zu den Tanks laufen! Panther sammeln!"] = "알로크: 징표 대상 -> 탱커에게 이동! 표범 모으기!"
L["Bei Verschwinden: Flächenschaden auf Panther, Tank bereit."] = "사라짐 시: 표범 광역, 탱커 대기."
L["Jin'do der Verhexer + Totems und Skelette"] = "주술사 진도 + 토템과 해골"
L["- Mächtiger Heilungszauberschutz: heilt Jin'do -> sofort zerstören."] = "- 강력한 치유의 수호물: 진도 치유 -> 즉시 파괴."
L["- Gehirnwäsche-Totem: Gedankenkontrolle -> sofort zerstören."] = "- 세뇌의 토템: 정신 지배 -> 즉시 파괴."
L["- Verhexung: Tank verwandelt -> magisch bannen."] = "- 주술: 탱커 변이 -> 마법 해제."
L["- Wahnvorstellungen: Fluch, Schatten sehen -> entfluchen, Schatten töten; Teleport in die Grube -> Skelette töten und herauskommen."] = "- 망상: 저주, 망령이 보임 -> 저주 해제, 망령 처치; 구덩이로 순간이동 -> 해골 처치 후 탈출."
L["Taktik: Fernkampf zerstört sofort alle Totems, Banner/Entflucher fest einteilen. Spieler in der Grube kämpfen sich frei."] = "공략: 원딜이 토템 즉시 파괴, 해제/저주 해제 담당 고정. 구덩이에 빠진 사람은 싸워서 탈출."
L["JIN'DO: Totems sofort zerstören! Verhexung bannen!"] = "진도: 토템 즉시 파괴! 주술 해제!"
L["Wahnvorstellungen entfluchen, Schatten töten."] = "망상 저주 해제, 망령 처치."
L["Hakkar der Seelenschinder + Söhne des Hakkar"] = "영혼약탈자 학카르 + 학카르의 아들"
L["- Blutsauger: regelmäßig Lebensentzug auf den Raid -> vorher Gift (Giftiges Blut) von Söhnen des Hakkar holen, dann schadet er sich selbst."] = "- 피의 흡수: 주기적으로 공격대 생명력 흡수 -> 미리 학카르의 아들에게서 독 (독성 혈액) 받기, 그러면 자해."
L["- Verderbtes Blut: springt zwischen Spielern -> verteilt stehen."] = "- 오염된 피: 플레이어 사이로 튐 -> 산개."
L["- Wahnsinn verursachen: Gedankenkontrolle des Tanks -> Zweittank übernimmt."] = "- 광기 유발: 탱커 정신 지배 -> 보조 탱커 인계."
L["- Aspekte: lebende Hohepriester geben Hakkar zusätzliche Fähigkeiten -> vorher alle Priester töten."] = "- 위상: 살아있는 대사제가 학카르에게 추가 능력 부여 -> 미리 모든 사제 처치."
L["Taktik: Alle Priester vor Hakkar töten. Vor jedem Blutsauger Söhne töten, damit der Raid vergiftet ist, ansonsten verteilt stehen."] = "공략: 학카르 전에 사제 전부 처치. 피의 흡수마다 그 전에 아들을 잡아 공격대에 독 묻히기, 그 외엔 산개."
L["HAKKAR: Vor Blutsauger ins Gift von Sohn des Hakkar!"] = "학카르: 피의 흡수 전 학카르의 아들 독 묻히기!"
L["Verteilt stehen, Zweittank bei Gedankenkontrolle bereit."] = "산개, 정신 지배 대비 보조 탱커 대기."
L["Der Schwarze Tempel"] = "검은 사원"
L["Oberster Kriegsfürst Naj'entus"] = "대장군 나젠투스"
L["- Nadelstachel: Schaden auf zufällige Spieler und Umstehende -> Fernkampf und Heiler verteilt stehen."] = "- 바늘 가시: 무작위 대상과 주변에 피해 -> 원딜과 힐러 산개."
L["- Aufspießender Stachel: Spieler wird aufgespießt und erleidet Schaden -> ein anderer Spieler zieht den Stachel per Klick heraus und behält ihn."] = "- 꿰뚫는 가시: 플레이어가 꿰뚫려 피해 -> 다른 플레이어가 클릭해 가시를 뽑아 보관."
L["- Gezeitenschild: Boss wird unverwundbar -> mit dem gesammelten Stachel auf den Boss werfen, um den Schild zu brechen."] = "- 해일의 보호막: 보스 무적 -> 모은 가시를 보스에게 던져 보호막 파괴."
L["- Gezeitenschlag beim Brechen des Schilds: Schaden am ganzen Raid -> Raid vorher voll heilen."] = "- 보호막 파괴 시 해일 폭발: 공격대 전체 피해 -> 미리 공격대 풀피."
L["- Hartes Enrage nach ca. 8 Min. -> konstanter Schaden nötig."] = "- 약 8분 후 광폭 -> 꾸준한 딜 필요."
L["Taktik: Boss in der Mitte tanken, alle anderen verteilt; feste Spieler zum Ziehen der Stacheln und zum Brechen des Schilds einteilen."] = "공략: 보스는 중앙에서 탱, 나머지는 산개; 가시 뽑기와 보호막 파괴 담당 고정."
L["NAJ'ENTUS: Verteilt stehen! Stacheln sofort ziehen und für den Schild aufheben!"] = "나젠투스: 산개! 가시 즉시 뽑고 보호막용으로 보관!"
L["Schild brechen nur mit vollem Leben im Raid."] = "보호막은 공격대 풀피일 때만 파괴."
L["Supremus"] = "궁극의 심연"
L["- Hasserfüllter Stoß (Tankphase): trifft den Nahkämpfer mit der höchsten Bedrohung neben dem Haupttank -> 2-3 Tanks/Spieler mit viel Leben im Nahkampf, Bedrohung aufbauen."] = "- 증오의 일격 (탱 단계): 메인 탱 다음으로 위협 수준 높은 근접 적중 -> 근접에 탱커/생명력 높은 2~3명, 위협 수준 쌓기."
L["- Geschmolzene Flammen/Feuerspur am Boden -> sofort aus dem Feuer gehen."] = "- 녹아내린 불길/바닥의 불길 자국 -> 즉시 불에서 나오기."
L["- Vulkanausbrüche: Geysire auf dem Boden -> umgehen."] = "- 화산 분출: 바닥 간헐천 -> 피해 다니기."
L["- Jagdphase (wechselt jede Minute): Supremus fixiert einen zufälligen Spieler und wird schneller -> Ziel läuft weg, Raid weicht aus."] = "- 추격 단계 (1분마다 전환): 궁극의 심연이 무작위 대상을 고정하고 빨라짐 -> 대상은 도망, 공격대 회피."
L["- Hartes Enrage nach 15 Min."] = "- 15분 후 광폭."
L["Taktik: In der Tankphase Haupttank plus Hasserfüllter-Stoß-Abfänger heilen; in der Jagdphase laufen, Feuer meiden und weiter Schaden machen."] = "공략: 탱 단계엔 메인 탱과 증오의 일격 담당 치유; 추격 단계엔 이동하며 불 피하고 계속 딜."
L["SUPREMUS: Jagdphase - Ziel rennt! Aus Feuer und Vulkanen raus!"] = "궁극의 심연: 추격 단계 - 대상 도망! 불과 화산에서 나오세요!"
L["Tankphase: Stoß-Abfänger im Nahkampf voll heilen."] = "탱 단계: 일격 담당 근접 풀힐."
L["Akamas Schemen"] = "아카마의 망령"
L["Akamas Schemen + Kanalisierer und Adds der Aschenzungen"] = "아카마의 망령 + 잿빛혓바닥 정신집중자와 쫄"
L["- Kanalisierer der Aschenzungen: 6 Adds halten den Schemen gebannt -> alle Kanalisierer töten, dann wird der Schemen angreifbar."] = "- 잿빛혓바닥 정신집중자: 쫄 6명이 망령을 묶어둠 -> 정신집중자 전부 처치하면 망령 공격 가능."
L["- Zauberer der Aschenzungen: kommen aus den Seitentüren und kanalisieren ebenfalls -> sofort töten."] = "- 잿빛혓바닥 마술사: 옆문에서 나와 같이 정신집중 -> 즉시 처치."
L["- Weitere Adds (Verteidiger, Elementaristen, Geistbinder) aus den Seitentüren -> an den Türen abfangen und tanken."] = "- 기타 쫄 (수호병, 정령술사, 영혼술사)이 옆문에서 -> 문에서 막고 탱."
L["- Akama darf nicht sterben -> Schemen nach dem Freikommen schnell übernehmen und töten."] = "- 아카마가 죽으면 안 됨 -> 망령이 풀려나면 빠르게 인계 후 처치."
L["Taktik: Zwei Gruppen an den Seitentüren fangen Adds ab, der Rest tötet die Kanalisierer; danach alles auf den Schemen, Akama hilft mit."] = "공략: 두 조가 옆문에서 쫄을 막고 나머지는 정신집중자 처치; 이후 전원 망령, 아카마도 함께 공격."
L["SCHEMEN: Kanalisierer und Zauberer zuerst! Türgruppen Adds abfangen!"] = "망령: 정신집중자와 마술사 먼저! 문 조는 쫄 막기!"
L["Akama am Leben halten. Danach alles auf den Schemen."] = "아카마 살려두기. 이후 전원 망령 점사."
L["Teron Blutschatten"] = "테론 고어핀드"
L["Teron Blutschatten + Schattenhafte Konstrukte"] = "테론 고어핀드 + 그림자 구조물"
L["- Schatten des Todes: Spieler stirbt nach kurzer Zeit und wird zum Geist -> als Geist mit den Geisterfähigkeiten die Konstrukte verlangsamen und töten."] = "- 죽음의 그림자: 잠시 후 사망해 유령이 됨 -> 유령 능력으로 구조물 감속 및 처치."
L["- Schattenhafte Konstrukte: greifen den Raid an -> von Geistern binden, verlangsamen und töten lassen, nicht zum Raid laufen lassen."] = "- 그림자 구조물: 공격대 공격 -> 유령이 묶고 감속해 처치, 공격대로 오지 못하게."
L["- Verbrennen: Magie-Debuff mit Feuerschaden -> bannen."] = "- 소각: 화염 피해 마법 디버프 -> 해제."
L["- Zermalmende Schatten: Schattenschaden auf mehrere Spieler -> Heiler reagieren schnell."] = "- 분쇄의 그림자: 여러 명에게 암흑 피해 -> 힐러 빠르게 대응."
L["- Schicksalsblüten: schießen Schattenblitze -> Schaden heilen."] = "- 운명의 꽃: 어둠의 화살 발사 -> 피해 치유."
L["Taktik: Teron am Rand tanken; Spieler mit Schatten des Todes stellen sich vor dem Tod an die Konstrukt-Position und erledigen die Adds als Geist."] = "공략: 테론은 가장자리에서 탱; 죽음의 그림자 대상은 죽기 전에 구조물 위치로 가서 유령으로 쫄 처리."
L["TERON: Schatten des Todes - zu den Konstrukten gehen! Als Geist Adds töten!"] = "테론: 죽음의 그림자 - 구조물 쪽으로! 유령으로 쫄 처치!"
L["Verbrennen bannen. Konstrukte vom Raid fernhalten."] = "소각 해제. 구조물이 공격대에 오지 않게."
L["Gurtogg Siedeblut"] = "구르토그 블러드보일"
L["- Blutsieden: trifft die 5 entferntesten Spieler, Debuff stapelt -> 3 Fernkampfgruppen im Wechsel hinten stehen."] = "- 피의 끓음: 가장 먼 5명 적중, 디버프 중첩 -> 원딜 3개 조가 교대로 뒤에 서기."
L["- Teufelssäure / Säurewunde: stapelnde Rüstungsreduktion am Tank -> Tankwechsel."] = "- 지옥 산성 / 산성 상처: 탱커 방어도 감소 중첩 -> 탱 교대."
L["- Rauswerfen: Rückstoß mit Bedrohungsverlust -> zweiter Tank sofort übernehmen."] = "- 내팽개치기: 위협 손실 밀쳐내기 -> 보조 탱커 즉시 인계."
L["- Teufelswut (Phase 2): fixiert einen zufälligen Spieler, der viel Leben und Rüstung bekommt -> diesen Spieler stark heilen, Raid weiter auf Boss."] = "- 지옥의 분노 (2단계): 무작위 대상을 고정, 대상은 생명력과 방어도 대폭 증가 -> 대상 집중 치유, 공격대는 계속 보스."
L["- Teufelsgeysir: Schaden um den Fixierten -> nicht zu nah stehen."] = "- 지옥 간헐천: 고정 대상 주변 피해 -> 너무 가까이 서지 말 것."
L["Taktik: Zwei Tanks wechseln wegen der Säure, Fernkampf in Gruppen für Blutsieden rotieren; in Teufelswut den Fixierten hochheilen."] = "공략: 산성 때문에 탱커 둘 교대, 원딜은 피의 끓음 조 로테이션; 지옥의 분노 때 고정 대상 풀힐."
L["GURTOGG: Blutsieden-Gruppen rotieren! Tankwechsel bei Säurestapeln!"] = "구르토그: 피의 끓음 조 로테이션! 산성 중첩 시 탱 교대!"
L["Teufelswut: Fixiertes Ziel voll heilen, nicht wegrennen."] = "지옥의 분노: 고정 대상 풀힐, 도망가지 마세요."
L["Reliquiar der Seelen"] = "영혼의 성물함"
L["Reliquiar der Seelen (Essenz des Leidens, der Begierde, des Zorns)"] = "영혼의 성물함 (고뇌의 정수, 욕망의 정수, 분노의 정수)"
L["- Essenz des Leidens: Aura senkt Heilung massiv, fixiert den nächsten Spieler -> Nahkämpfer mit hohem Leben vorne, schnell töten."] = "- 고뇌의 정수: 오라로 치유 대폭 감소, 가장 가까운 대상 고정 -> 생명력 높은 근딜이 앞, 빠르게 처치."
L["- Gefangene Seelen zwischen den Phasen: Adds -> schnell töten."] = "- 단계 사이 갇힌 영혼: 쫄 -> 빠르게 처치."
L["- Essenz der Begierde: Aura reflektiert Schaden auf den Angreifer und senkt Mana -> Schaden dosieren; Runenschild bannen, Abstumpfen und Geistschock unterbrechen."] = "- 욕망의 정수: 오라로 공격자에게 피해 반사, 마나 감소 -> 딜 조절; 룬 보호막 해제, 둔화와 영혼 충격 차단."
L["- Essenz des Zorns: Bosheit auf mehrere Spieler -> heilen; Seelenschrei entzieht Mana -> Mana sparen."] = "- 분노의 정수: 다수에게 원한 -> 치유; 영혼의 비명이 마나 흡수 -> 마나 아끼기."
L["- Zorn steigert sich bei Tankwechsel -> nur einen Tank verwenden."] = "- 탱 교대 시 분노 증가 -> 탱커 한 명만."
L["Taktik: Drei Phasen nacheinander: Leiden schnell töten, Begierde kontrolliert mit Unterbrechern, Zorn mit vollem Raid-Schaden."] = "공략: 세 단계 차례로: 고뇌는 빠르게, 욕망은 차단하며 조절, 분노는 공격대 풀딜."
L["RELIQUIAR: Phase 2 Reflexion beachten! Unterbrecher bereit!"] = "성물함: 2단계 반사 주의! 차단 대기!"
L["Phase 1: Wenig Heilung, schnell töten. Adds zwischen den Phasen weg."] = "1단계: 치유 적음, 빠르게 처치. 단계 사이 쫄 정리."
L["Mutter Shahraz"] = "대모 샤라즈"
L["- Unheilvoller, Übler, Gemeiner, Sündiger Strahl: Schattenschaden und Debuffs -> Raid mit Schattenwiderstand."] = "- 사악한/불경한/비열한/죄악의 광선: 암흑 피해와 디버프 -> 공격대 암흑 저항."
L["- Tödliche Anziehung: 3 Spieler werden zusammen teleportiert und schaden sich gegenseitig -> sofort auseinander laufen."] = "- 치명적인 매력: 3명이 함께 순간이동되어 서로 피해 -> 즉시 흩어지기."
L["- Säbelpeitsche: Schaden wird auf Umstehende aufgeteilt -> Nahkampf und Tanks zusammen am Boss."] = "- 톱니 채찍: 주변 인원에게 피해 분배 -> 근딜과 탱커 보스에 뭉치기."
L["- Prismatische Aura: wechselnde Widerstände -> keine Gegenmaßnahme nötig."] = "- 오색 오라: 저항 변화 -> 대응 불필요."
L["- Raserei bei ca. 10% -> Cooldowns aufheben."] = "- 약 10%에 광란 -> 쿨기 아껴두기."
L["Taktik: Boss mittig tanken, Nahkampf zum Teilen der Säbelpeitsche stapeln, Raid mit Schattenwiderstand-Ausrüstung verteilt."] = "공략: 보스는 중앙에서 탱, 근딜은 톱니 채찍 분담 위해 뭉치기, 공격대는 암흑 저항 장비로 산개."
L["SHAHRAZ: Bei Anziehung SOFORT auseinander laufen!"] = "샤라즈: 매력 걸리면 즉시 흩어지세요!"
L["Nahkampf am Boss für Säbelpeitsche. Schattenwiderstand an."] = "근딜은 톱니 채찍 분담. 암흑 저항 착용."
L["Rat der Illidari"] = "일리다리 의회"
L["Rat der Illidari (Gathios, Malande, Zerevor, Veras)"] = "일리다리 의회 (가디오스, 말란데, 제레보르, 베라스)"
L["- Gemeinsamer Lebenspool: alle vier teilen sich das Leben -> Schaden verteilen ist egal, alle sterben zusammen."] = "- 생명력 공유: 넷이 생명력 공유 -> 딜 분배 무관, 함께 사망."
L["- Gathios der Zerschmetterer: Weihe und Segen/Auren -> Segen und Schutz stehlen/reinigen, von Weihe weg tanken."] = "- 파괴자 가디오스: 신성화와 축복/오라 -> 축복과 보호 훔치기/정화, 신성화에서 떨어져 탱."
L["- Lady Malande: Gebet der Heilung, Göttlicher Zorn, Reflexionsschild -> Heilzauber unterbrechen, Schild beachten."] = "- 여군주 말란데: 치유의 기원, 신의 격노, 반사 보호막 -> 치유 주문 차단, 보호막 주의."
L["- Hochnethermant Zerevor: Arkane Explosion, Blizzard, Flammenstoß -> auf Distanz halten (Magier/Hexer-Tank), aus Flächenschaden raus."] = "- 고위 황천술사 제레보르: 신비한 폭발, 눈보라, 불기둥 -> 거리 유지 (법사/흑마 탱), 장판에서 나오기."
L["- Veras Dunkelschatten: Verschwinden und tödliches Gift -> Gift entfernen, Ziel heilen."] = "- 베라스 다크섀도우: 사라짐과 치명적인 독 -> 독 해제, 대상 치유."
L["Taktik: Jedes Ratsmitglied eigener Tank an eigener Position, Zerevor auf Distanz; Malandes Heilungen konsequent unterbrechen."] = "공략: 의회원마다 전담 탱커와 위치, 제레보르는 원거리; 말란데 치유는 철저히 차단."
L["RAT: Malande unterbrechen! Zerevor-AoE meiden!"] = "의회: 말란데 차단! 제레보르 광역 피하기!"
L["Gift von Veras entfernen. Segen von Gathios stehlen/reinigen."] = "베라스 독 해제. 가디오스 축복 훔치기/정화."
L["Rat (Tanks)"] = "의회 (탱커)"
L["Ein Symbol pro Ratsmitglied für die Tankzuteilung: Totenkopf Gathios, Kreuz Malande, Viereck Zerevor, Mond Veras."] = "탱커 배정용 의회원별 징표: 해골 가디오스, 가위표 말란데, 네모 제레보르, 달 베라스."
L["Illidan Sturmgrimm"] = "일리단 스톰레이지"
L["Illidan Sturmgrimm + Flammen von Azzinoth und Schattendämonen"] = "일리단 스톰레이지 + 아지노스의 불꽃과 그림자 악마"
L["- Scheren: senkt das max. Leben des Tanks stark -> Tank nutzt Verteidigungs-CDs, Heiler bereit."] = "- 칼날 베기: 탱커 최대 생명력 대폭 감소 -> 탱커 생존기, 힐러 대기."
L["- Parasitärer Schattenteufel: Spieler bekommt Debuff, Adds schlüpfen -> Adds sofort töten."] = "- 기생 그림자마: 디버프 대상에서 쫄 부화 -> 쫄 즉시 처치."
L["- Phase 2 (Flammen von Azzinoth): zwei Elementare -> mit Feuerwiderstand-Tanks getrennt tanken, nicht zu nah an die Gleven ziehen."] = "- 2단계 (아지노스의 불꽃): 정령 둘 -> 화염 저항 탱커가 따로 탱, 글레이브 가까이 끌지 말 것."
L["- Augenstrahl / Feuerbälle: Linie aus Feuer am Boden -> ausweichen."] = "- 눈 광선 / 화염구: 바닥에 불길 -> 피하기."
L["- Dämonenform: Schattendämonen fixieren Spieler -> sofort töten; Fernkampf verteilt (Flammenexplosion)."] = "- 악마 변신: 그림자 악마가 플레이어 고정 -> 즉시 처치; 원딜 산개 (화염 폭발)."
L["- Maiev (ab ca. 30%): legt Käfigfallen -> Illidan in die Falle ziehen."] = "- 마이에브 (약 30%부터): 감옥 덫 설치 -> 일리단을 덫으로 유인."
L["Taktik: Phasen 1-5: Tankphase, Flammenphase mit Feuerwiderstands-Tanks, wieder Tank, Dämonenform mit Hexer-Tank, Maiev-Phase mit Fallen."] = "공략: 1~5단계: 탱 단계, 화염 저항 탱커의 불꽃 단계, 다시 탱 단계, 흑마 탱 악마 변신, 덫을 쓰는 마이에브 단계."
L["ILLIDAN: Scheren - Tank-CDs! Schattenteufel und Dämonen sofort töten!"] = "일리단: 칼날 베기 - 탱커 생존기! 그림자마와 악마 즉시 처치!"
L["Flammen getrennt tanken, Augenstrahl ausweichen. Maiev: Falle nutzen."] = "불꽃 따로 탱, 눈 광선 피하기. 마이에브: 덫 활용."
L["Illidan"] = "일리단"
L["Totenkopf und Kreuz auf die beiden Flammen von Azzinoth (je ein Tank)."] = "아지노스의 불꽃 둘에 해골과 가위표 (탱커 하나씩)."
L["Gruuls Unterschlupf"] = "그룰의 둥지"
L["Hochkönig Maulgar"] = "왕중왕 마울가르"
L["Hochkönig Maulgar + Krosh, Olm, Kiggler, Blindauge"] = "왕중왕 마울가르 + 크로쉬, 올름, 키글러, 블라인드아이"
L["- Blindauge der Seher (Priester): Heilung und Schild -> unterbrechen, als Erstes töten."] = "- 현자 블라인드아이 (사제): 치유와 보호막 -> 차단, 가장 먼저 처치."
L["- Olm der Beschwörer: beschwört Teufelsjäger -> Hexer tanken/binden, als Zweites töten."] = "- 소환사 올름: 지옥사냥개 소환 -> 흑마가 탱/묶기, 두 번째로 처치."
L["- Kiggler der Verrückte: Verwandlung und Rückstoß -> auf Distanz von Jägern/Druiden tanken."] = "- 광기의 키글러: 변이와 밀쳐내기 -> 사냥꾼/드루이드가 원거리 탱."
L["- Krosh Feuerhand: starke Feuerzauber -> Magier tankt mit Zauberraub auf Kroshs Zauberschild."] = "- 크로쉬 파이어핸드: 강력한 화염 주문 -> 마법사가 크로쉬 주문 보호막을 주문 훔치기로 가져가며 탱."
L["- Maulgar: Wirbelwind und Ansturm, ab 50% Raserei -> Nahkampf bei Wirbelwind raus."] = "- 마울가르: 소용돌이와 돌진, 50%부터 광란 -> 소용돌이 시 근딜 빠지기."
L["Taktik: Jedes Add eigener Tank an eigener Stelle; Reihenfolge Blindauge, Olm, Kiggler, Krosh, zuletzt Maulgar."] = "공략: 쫄마다 전담 탱커와 위치; 순서는 블라인드아이, 올름, 키글러, 크로쉬, 마지막 마울가르."
L["MAULGAR: Blindauge zuerst und unterbrechen! Dann Olm, Kiggler, Krosh!"] = "마울가르: 블라인드아이 먼저, 차단! 이후 올름, 키글러, 크로쉬!"
L["Krosh nur der Magier-Tank. Wirbelwind: Nahkampf raus."] = "크로쉬는 법사 탱만. 소용돌이: 근딜 빠지기."
L["Maulgar"] = "마울가르"
L["Totenkopf Blindauge, Kreuz Olm, Viereck Kiggler, Mond Krosh, Dreieck Maulgar."] = "해골 블라인드아이, 가위표 올름, 네모 키글러, 달 크로쉬, 세모 마울가르."
L["Gruul der Drachenschlächter"] = "용 학살자 그룰"
L["- Wachstum: Gruul wird alle 30 Sek. größer und stärker -> weiches Enrage, schnell töten."] = "- 성장: 그룰이 30초마다 커지고 강해짐 -> 소프트 광폭, 빠르게 처치."
L["- Verletzender Schlag: trifft den Nahkämpfer mit zweithöchster Bedrohung -> zweiter Tank/Plattenträger direkt hinter dem Haupttank."] = "- 상처의 일격: 위협 수준 두 번째로 높은 근접 대상 적중 -> 보조 탱커/판금 착용자가 메인 탱 바로 뒤에."
L["- Bodenschlag + Zerschmettern: Raid wird herangezogen und versteinert, danach Schaden je nach Nähe -> sofort auseinanderlaufen."] = "- 대지 강타 + 산산조각: 공격대를 끌어당겨 석화, 이후 거리에 비례한 피해 -> 즉시 흩어지기."
L["- Höhleneinsturz: Steinschlag am Boden -> sofort raus."] = "- 동굴 붕괴: 바닥에 낙석 -> 즉시 나오기."
L["- Widerhall: Stille in der Nähe -> Heiler auf Abstand."] = "- 반향: 근처 침묵 -> 힐러 거리 유지."
L["Taktik: Fernkampf und Heiler verteilt mit genug Abstand, nach jedem Bodenschlag sofort auseinander; volle Schadensphase gegen das Wachstum."] = "공략: 원딜과 힐러는 충분히 거리 두고 산개, 대지 강타 후 즉시 흩어지기; 성장에 맞서 풀딜."
L["GRUUL: Nach Bodenschlag SOFORT verteilen! Raus aus dem Einsturz!"] = "그룰: 대지 강타 후 즉시 산개! 붕괴에서 나오세요!"
L["Zweiter Tank für Verletzenden Schlag bereit. Volle DPS gegen Wachstum."] = "상처의 일격용 보조 탱커 대기. 성장 대비 풀딜."
L["Hyjalgipfel"] = "하이잘 정상"
L["Furor Winterfrost"] = "격노한 윈터칠"
L["Furor Winterfrost (nach 8 Trash-Wellen)"] = "격노한 윈터칠 (쫄 웨이브 8회 후)"
L["- Tod und Verfall: Schaden in einem Bereich -> sofort herausgehen."] = "- 죽음과 부패: 범위 피해 -> 즉시 나오기."
L["- Eisblitz: Frostschaden und Betäubung auf zufälligen Spieler -> heilen."] = "- 얼음 화살: 무작위 대상 냉기 피해와 기절 -> 치유."
L["- Frostnova: friert Spieler in der Nähe fest -> nicht zu viele Spieler eng stehen."] = "- 얼음 회오리: 근처 플레이어 빙결 -> 너무 많이 뭉치지 말 것."
L["- Frostrüstung: verlangsamt Angreifer -> Nahkampf kurz aushalten."] = "- 냉기 갑옷: 공격자 감속 -> 근딜은 잠시 버티기."
L["Taktik: Vorher die Trash-Wellen im Lager abfangen; Boss an Ort und Stelle tanken, Raid aus Tod und Verfall raus."] = "공략: 먼저 진지에서 쫄 웨이브 처리; 보스는 제자리 탱, 공격대는 죽음과 부패에서 나오기."
L["FUROR: Raus aus Tod und Verfall!"] = "윈터칠: 죽음과 부패에서 나오세요!"
L["Eisblitz-Ziele heilen. Trash-Wellen vorher sauber abfangen."] = "얼음 화살 대상 치유. 쫄 웨이브 먼저 깔끔하게 처리."
L["Anetheron"] = "아네테론"
L["Anetheron + Höllenbestien"] = "아네테론 + 지옥불정령"
L["- Aasschwarm: Schaden im Kegel und Heilung reduziert -> Boss vom Raid weggedreht tanken."] = "- 썩은고기 떼: 부채꼴 피해와 치유 감소 -> 보스를 공격대 반대로 돌려 탱."
L["- Schlaf: mehrere Spieler schlafen -> Magie bannen."] = "- 수면: 여러 명 수면 -> 마법 해제."
L["- Vampiraura: Boss heilt sich bei Treffern -> Tank gut ausgerüstet halten."] = "- 흡혈의 오라: 공격 적중 시 보스 회복 -> 탱커 장비 충실하게."
L["- Inferno: Höllenbestie auf zufälligem Spieler -> von Offtank/Hexer wegtanken, Raid raus aus dem Feuer."] = "- 지옥불: 무작위 대상에 지옥불정령 -> 보조 탱커/흑마가 떼어서 탱, 공격대는 불에서 나오기."
L["Taktik: Anetheron vom Raid weg drehen, Höllenbestien von einem Offtank aufnehmen und abseits halten."] = "공략: 아네테론을 공격대 반대로 돌리고, 지옥불정령은 보조 탱커가 받아 멀리 유지."
L["ANETHERON: Höllenbestien sofort abholen! Schlaf bannen!"] = "아네테론: 지옥불정령 즉시 잡기! 수면 해제!"
L["Nicht vor den Boss stellen (Aasschwarm)."] = "보스 앞에 서지 마세요 (썩은고기 떼)."
L["Kaz'rogal"] = "카즈로갈"
L["- Mal von Kaz'rogal: entzieht allen Manaklassen Mana, bei 0 Mana Explosion mit hohem Schaden -> Mana tränken, bei leerem Mana raus aus dem Raid."] = "- 카즈로갈의 징표: 마나 직업 전원 마나 흡수, 마나 0이면 큰 피해 폭발 -> 마나 물약, 마나가 바닥나면 공격대 밖으로."
L["- Intervall des Mals wird immer kürzer -> schnell töten."] = "- 징표 간격이 점점 짧아짐 -> 빠르게 처치."
L["- Kriegsdonner: Betäubung im Nahkampf -> Nahkampf kurz raus wenn möglich."] = "- 전쟁발구르기: 근접 기절 -> 가능하면 근딜 잠시 빠지기."
L["- Spalten: Frontalschaden -> Boss weg vom Raid drehen."] = "- 회전베기: 전방 피해 -> 보스를 공격대 반대로."
L["Taktik: Boss weg vom Raid tanken; Manaklassen achten auf ihr Mana und laufen bei fast leerem Mana vom Raid weg."] = "공략: 보스는 공격대 반대로 탱; 마나 직업은 마나를 확인하고 거의 바닥나면 공격대에서 떨어지기."
L["KAZ'ROGAL: Mana im Blick! Fast leer = weg vom Raid laufen!"] = "카즈로갈: 마나 확인! 거의 바닥 = 공격대 밖으로!"
L["Mana-Tränke nutzen. Boss weg vom Raid gedreht."] = "마나 물약 사용. 보스는 공격대 반대로."
L["Azgalor"] = "아즈갈로"
L["Azgalor + Geringe Verdammniswachen"] = "아즈갈로 + 하급 파멸수호병"
L["- Feuerregen: Flächenschaden -> sofort raus."] = "- 불비: 광역 피해 -> 즉시 나오기."
L["- Verdammnis: Spieler stirbt nach Ablauf und erzeugt eine Verdammniswache -> zum Offtank laufen, Wache abseits tanken/töten."] = "- 파멸: 만료 시 사망하며 파멸수호병 생성 -> 보조 탱커에게 이동, 수호병은 떨어진 곳에서 탱/처치."
L["- Heulen von Azgalor: Stille im Umkreis -> Heiler auf Abstand."] = "- 아즈갈로의 울부짖음: 주변 침묵 -> 힐러 거리 유지."
L["Taktik: Boss weg vom Raid tanken, Verdammniswachen von Offtank abseits halten und töten; nie im Feuer stehen."] = "공략: 보스는 공격대 반대로 탱, 파멸수호병은 보조 탱커가 떨어진 곳에서 처치; 불 위에 절대 서지 말 것."
L["AZGALOR: Raus aus dem Feuerregen! Verdammnis-Ziele zum Offtank!"] = "아즈갈로: 불비에서 나오세요! 파멸 대상은 보조 탱커에게!"
L["Verdammniswachen abseits tanken. Heiler auf Abstand (Stille)."] = "파멸수호병은 떨어져서 탱. 힐러 거리 유지 (침묵)."
L["Archimonde"] = "아키몬드"
L["- Luftstoß: schleudert Spieler hoch -> Tränen der Göttin nutzen, um nicht am Sturz zu sterben."] = "- 공기 폭발: 플레이어를 띄움 -> 여신의 눈물로 낙사 방지."
L["- Verdammnisfeuer: Feuerspur folgt Spielern -> wegziehen, nicht durch das Feuer laufen."] = "- 파멸의 불길: 불길 자국이 플레이어를 따라옴 -> 끌고 가기, 불 위로 지나가지 말 것."
L["- Furcht: ganzer Raid -> Furchtschutz auf Tank, Totem des Erdstoßes."] = "- 공포: 공격대 전체 -> 탱커에게 공포의 수호물, 진동의 토템."
L["- Griff der Legion: Fluch -> entfluchen."] = "- 군단의 손아귀: 저주 -> 저주 해제."
L["- Seelenladung bei Spielertoden -> niemand sterben lassen."] = "- 플레이어 사망 시 영혼 충전 -> 아무도 죽지 않게."
L["Taktik: Raid locker verteilt um den Boss, jeder hat Tränen der Göttin in der Leiste; Feuer sofort wegziehen."] = "공략: 공격대는 보스 주변에 느슨하게 산개, 전원 단축바에 여신의 눈물; 불은 즉시 끌고 나가기."
L["ARCHIMONDE: Tränen der Göttin bei Luftstoß nutzen!"] = "아키몬드: 공기 폭발 때 여신의 눈물 사용!"
L["Verdammnisfeuer wegziehen. Flüche entfernen, Furchtschutz auf Tank."] = "파멸의 불길 끌고 가기. 저주 해제, 탱커에게 공포의 수호물."
L["Karazhan"] = "카라잔"
L["Attumen der Jäger"] = "사냥꾼 어튜멘"
L["Attumen der Jäger + Mittnacht"] = "사냥꾼 어튜멘 + 천둥이"
L["- Mittnacht: zuerst Pferd tanken, Attumen erscheint dazu -> zweiter Tank übernimmt Attumen."] = "- 천둥이: 먼저 말을 탱, 어튜멘이 합류 -> 보조 탱커가 어튜멘 인계."
L["- Schattenspalten: Frontalschaden -> nur Tank vorne."] = "- 그림자 회전베기: 전방 피해 -> 앞에는 탱커만."
L["- Unkörperliche Präsenz: Fluch -> entfluchen."] = "- 무형의 존재: 저주 -> 저주 해제."
L["- Beritten (ab 25%): Ansturm auf entfernte Spieler -> Fernkampf verteilt in mittlerer Distanz."] = "- 기마 (25%부터): 먼 대상에게 돌진 -> 원딜은 중거리에 산개."
L["Taktik: Zwei Tanks: einer auf Mittnacht, einer auf Attumen; nach dem Aufsitzen Ansturm-Schaden heilen und durchziehen."] = "공략: 탱커 둘: 하나는 천둥이, 하나는 어튜멘; 탑승 후 돌진 피해 치유하며 마무리."
L["ATTUMEN: Nicht vor den Boss! Flüche entfernen!"] = "어튜멘: 보스 앞 금지! 저주 해제!"
L["Ab Aufsitzen: Fernkampf verteilt für Ansturm."] = "탑승 후: 돌진 대비 원딜 산개."
L["Moroes"] = "모로스"
L["Moroes + 4 Gäste"] = "모로스 + 손님 4"
L["- Solarplexus: betäubt den Tank -> zweiter Tank mit hoher Bedrohung übernimmt."] = "- 명치 치기: 탱커 기절 -> 위협 수준 높은 보조 탱커가 인계."
L["- Verschwinden + Erdrosseln: stapelnde Blutung auf zufälligem Spieler -> heilen (Eisblock/Gottesschild entfernen)."] = "- 사라짐 + 목조르기: 무작위 대상에 중첩 출혈 -> 치유 (얼음 방패/천상의 보호막으로 해제)."
L["- Gäste: Heiler-Adds (Priester/Paladine) zuerst töten, gefährliche Adds kontrollieren."] = "- 손님: 힐러 쫄 (사제/성기사) 먼저 처치, 위험한 쫄은 제어."
L["- Raserei bei 30% -> Gäste vorher töten oder sicher kontrollieren."] = "- 30%에 광란 -> 그 전에 손님 처치 또는 확실히 제어."
L["Taktik: CC auf zwei Gäste (Kopfnuss, Fesseln, Verwandlung), zwei Gäste nacheinander töten, dann Moroes; Erdrosseln heilen."] = "공략: 손님 둘 CC (혼절시키기, 속박, 변이), 둘은 차례로 처치 후 모로스; 목조르기 치유."
L["MOROES: Heiler-Gäste zuerst! CC halten!"] = "모로스: 힐러 손님 먼저! CC 유지!"
L["Solarplexus: Zweiter Tank übernimmt. Erdrosseln-Ziele heilen."] = "명치 치기: 보조 탱커 인계. 목조르기 대상 치유."
L["Totenkopf und Kreuz töten, Viereck und Mond CC, Stern auf Moroes."] = "해골과 가위표 처치, 네모와 달 CC, 별은 모로스."
L["Tugendhafte Maid"] = "고결의 여신"
L["- Buße: lähmt alle Spieler, löst sich bei Schaden -> vorher alle hochheilen."] = "- 참회: 전원 행동 불가, 피해 받으면 풀림 -> 미리 전원 풀피."
L["- Heiliges Feuer: Magie-DoT -> bannen."] = "- 신성한 불꽃: 마법 도트 -> 해제."
L["- Heiliger Zorn: springt zwischen Spielern -> verteilt stehen."] = "- 신의 격노: 플레이어 사이로 튐 -> 산개."
L["- Geheiligter Boden: Stille um die Maid -> Heiler und Fernkampf außerhalb."] = "- 신성한 땅: 여신 주변 침묵 -> 힐러와 원딜은 범위 밖."
L["Taktik: Fernkampf und Heiler verteilt am Rand des Raums außerhalb des geheiligten Bodens, Nahkampf am Boss."] = "공략: 원딜과 힐러는 신성한 땅 밖 방 가장자리에 산개, 근딜은 보스."
L["MAID: Verteilt am Rand! Vor Buße hochheilen!"] = "여신: 가장자리에 산개! 참회 전 풀피!"
L["Heiliges Feuer bannen. Heiler nicht in den Geheiligten Boden."] = "신성한 불꽃 해제. 힐러는 신성한 땅에 들어가지 마세요."
L["Der große böse Wolf"] = "커다란 나쁜 늑대"
L["Oper: Der große böse Wolf"] = "오페라: 커다란 나쁜 늑대"
L["- Rotkäppchen: Spieler wird verwandelt, verliert Rüstung und Widerstände -> im Kreis vom Wolf weglaufen."] = "- 빨간 망토: 플레이어 변신, 방어도와 저항 상실 -> 늑대를 피해 원을 그리며 도망."
L["- Schreckliches Heulen: Furcht -> Furchtschutz/Erdstoßtotem."] = "- 공포의 울부짖음: 공포 -> 공포의 수호물/진동의 토템."
L["- Weiter Prankenhieb: Schaden vorne -> nur Tank vor dem Wolf."] = "- 광역 할퀴기: 전방 피해 -> 늑대 앞에는 탱커만."
L["Taktik: Wolf mittig tanken; Rotkäppchen läuft im Kreis außen herum, Raid bleibt ruhig und macht weiter Schaden."] = "공략: 늑대는 중앙에서 탱; 빨간 망토는 바깥쪽으로 원을 그리며 달리고, 공격대는 침착하게 계속 딜."
L["WOLF: Rotkäppchen im Kreis laufen!"] = "늑대: 빨간 망토는 원을 그리며 달리기!"
L["Nicht vor den Wolf stellen. Furchtschutz auf den Tank."] = "늑대 앞에 서지 마세요. 탱커에게 공포의 수호물."
L["Romulo und Julianne"] = "로밀로와 줄리엔"
L["Oper: Romulo und Julianne"] = "오페라: 로밀로와 줄리엔"
L["- Julianne: Ewige Zuneigung (Heilung) -> unterbrechen; Hingabe-Buff -> reinigen/stehlen."] = "- 줄리엔: 영원한 사랑 (치유) -> 차단; 헌신 버프 -> 정화/훔치기."
L["- Romulo: Wagemut-Buff -> reinigen/stehlen; Gift -> entfernen."] = "- 로밀로: 대담함 버프 -> 정화/훔치기; 독 -> 해제."
L["- Mächtige Anziehung: Betäubung -> heilen."] = "- 강력한 매력: 기절 -> 치유."
L["- Phase 3: beide stehen wieder auf und müssen innerhalb von 10 Sek. sterben -> Schaden gleichmäßig verteilen."] = "- 3단계: 둘 다 부활, 10초 안에 함께 죽여야 함 -> 딜 고르게 분배."
L["Taktik: Erst Julianne, dann Romulo, in Phase 3 beide getrennt tanken und gleichzeitig runterbringen."] = "공략: 먼저 줄리엔, 다음 로밀로, 3단계엔 따로 탱하고 동시에 깎기."
L["ROMULO & JULIANNE: Heilung unterbrechen! Phase 3 gleichzeitig töten!"] = "로밀로와 줄리엔: 치유 차단! 3단계 동시 처치!"
L["Buffs reinigen/stehlen. Gift entfernen."] = "버프 정화/훔치기. 독 해제."
L["Totenkopf Julianne, Kreuz Romulo."] = "해골 줄리엔, 가위표 로밀로."
L["Der Zauberer von Oz"] = "오즈의 마법사"
L["Oper: Der Zauberer von Oz (Dorothee, Tito, Brüller, Strohmann, Blechkopf, Hexe)"] = "오페라: 오즈의 마법사 (도로시, 티토, 어흥이, 허수아비, 양철나무꾼, 마녀)"
L["- Dorothee: nicht tankbar, Wasserblitze und Furcht, ruft Tito -> Fernkampf zuerst töten."] = "- 도로시: 탱 불가, 물 화살과 공포, 티토 소환 -> 원딜이 먼저 처치."
L["- Brüller: Furcht -> schnell töten."] = "- 어흥이: 공포 -> 빠르게 처치."
L["- Strohmann: anfällig für Feuer -> Feuerzauber betäuben ihn, Magier/Hexer übernehmen."] = "- 허수아비: 화염에 취약 -> 화염 주문으로 기절, 법사/흑마 담당."
L["- Blechkopf: wird mit der Zeit rostig/langsam -> tanken oder kiten."] = "- 양철나무꾼: 시간이 지나면 녹슬어 느려짐 -> 탱 또는 카이팅."
L["- Hexe (am Ende): Wirbelstürme und Kettenblitz -> Wirbelstürmen ausweichen."] = "- 마녀 (마지막): 회오리바람과 연쇄 번개 -> 회오리바람 피하기."
L["Taktik: Adds zügig nacheinander töten, Strohmann mit Feuer kontrollieren; danach die Hexe, Wirbelstürme meiden."] = "공략: 쫄을 빠르게 차례로 처치, 허수아비는 화염으로 제어; 이후 마녀, 회오리바람 피하기."
L["OZ: Dorothee zuerst! Strohmann mit Feuer!"] = "오즈: 도로시 먼저! 허수아비는 화염으로!"
L["Hexe: Wirbelstürmen ausweichen."] = "마녀: 회오리바람 피하기."
L["Oz"] = "오즈"
L["Totenkopf Dorothee, Kreuz Brüller, Viereck Strohmann, Mond Blechkopf."] = "해골 도로시, 가위표 어흥이, 네모 허수아비, 달 양철나무꾼."
L["Der Kurator"] = "전시 관리인"
L["Der Kurator + Astrale Blitze"] = "전시 관리인 + 비전 섬광"
L["- Astrale Blitze: alle 10 Sek. ein Add mit Arkanschaden -> sofort töten (Nahkampf)."] = "- 비전 섬광: 10초마다 비전 피해 쫄 -> 즉시 처치 (근딜)."
L["- Hasserfüllter Blitz: trifft den Spieler mit dem meisten Leben (außer Tank) -> Spieler mit viel Leben voll heilen."] = "- 증오의 화살: 생명력이 가장 높은 대상 적중 (탱커 제외) -> 생명력 높은 대상 풀힐."
L["- Hervorrufung: bei 0 Mana erleidet der Kurator +200% Schaden -> alles auf den Boss, Cooldowns nutzen."] = "- 환기: 마나 0이 되면 관리인 받는 피해 +200% -> 전원 보스, 쿨기 사용."
L["- Enrage bei 15%: keine Blitze mehr, Hasserfüllter Blitz öfter -> durchheilen und schnell töten."] = "- 15%에 광폭: 섬광 중단, 증오의 화살 빈도 증가 -> 버티며 빠르게 처치."
L["Taktik: Fernkampf am Boss, Nahkampf auf die Blitze; in der Hervorrufung volle Cooldowns."] = "공략: 원딜은 보스, 근딜은 섬광; 환기 때 쿨기 전부."
L["KURATOR: Astrale Blitze sofort töten!"] = "관리인: 비전 섬광 즉시 처치!"
L["Hervorrufung = alle CDs auf den Boss. Ab 15% durchheilen."] = "환기 = 쿨기 전부 보스에. 15%부터 버티기 힐."
L["Terestian Siechhuf"] = "테레스티안 일후프"
L["Terestian Siechhuf + Kil'rek"] = "테레스티안 일후프 + 킬렉"
L["- Opferung: Spieler in dämonische Ketten gelegt -> Ketten sofort töten."] = "- 희생: 플레이어가 악마의 사슬에 묶임 -> 사슬 즉시 처치."
L["- Kil'rek (Wichtel): beim Tod erleidet Terestian mehr Schaden -> Kil'rek töten, dann Boss."] = "- 킬렉 (임프): 죽으면 테레스티안 받는 피해 증가 -> 킬렉 처치 후 보스."
L["- Dämonische Portale: Wichtel strömen -> per AoE töten."] = "- 악마 차원문: 임프가 몰려옴 -> 광역 처치."
L["- Schattenblitz auf den Tank -> heilen."] = "- 탱커에게 어둠의 화살 -> 치유."
L["Taktik: Kil'rek zuerst töten, dann auf Terestian; Ketten haben höchste Priorität, Wichtel per AoE."] = "공략: 킬렉 먼저, 그다음 테레스티안; 사슬 최우선, 임프는 광역."
L["TERESTIAN: Ketten sofort töten! Kil'rek zuerst!"] = "테레스티안: 사슬 즉시 처치! 킬렉 먼저!"
L["Wichtel mit AoE wegräumen."] = "임프는 광역으로 정리."
L["Terestian"] = "테레스티안"
L["Totenkopf Ketten der Opferung, Kreuz Kil'rek."] = "해골 희생의 사슬, 가위표 킬렉."
L["Arans Schemen"] = "아란의 망령"
L["- Flammenkranz: Feuerkreise um Spieler -> nicht bewegen, sonst explodiert der Kreis."] = "- 화염의 고리: 플레이어 주변 불의 원 -> 움직이지 말 것, 움직이면 원 폭발."
L["- Arkane Explosion: zieht Spieler in die Mitte -> sofort an den Rand laufen."] = "- 신비한 폭발: 플레이어를 중앙으로 끌어당김 -> 즉시 가장자리로."
L["- Blizzard: wandert durch den Raum -> rausgehen."] = "- 눈보라: 방 안을 이동 -> 나오기."
L["- Arkane/Feuer/Frost-Geschosse -> unterbrechen."] = "- 비전/화염/냉기 화살 -> 차단."
L["- Wasserelementare bei 40%, Massenverwandlung + Trinken bei 0 Mana -> Elementare verbannen/furchten, beim Trinken volle DPS."] = "- 40%에 물의 정령, 마나 0이면 광역 변이 + 마나 회복 -> 정령 추방/공포, 마나 회복 중 풀딜."
L["Taktik: Raid verteilt am Rand, Unterbrecher fest einteilen; bei Flammenkranz stehenbleiben, bei Arkaner Explosion raus."] = "공략: 공격대는 가장자리 산개, 차단 담당 고정; 화염의 고리 땐 정지, 신비한 폭발 땐 밖으로."
L["ARAN: Flammenkranz - NICHT BEWEGEN!"] = "아란: 화염의 고리 - 움직이지 마세요!"
L["Arkane Explosion: an den Rand laufen. Zauber unterbrechen."] = "신비한 폭발: 가장자리로. 주문 차단."
L["Nethergroll"] = "황천의 원령"
L["- Roter Strahl (Beharrlichkeit): Tank stellt sich hinein -> Bedrohung und Leben, Boss greift diesen Spieler an."] = "- 붉은 광선 (인내): 탱커가 막음 -> 위협과 생명력, 보스가 그 대상을 공격."
L["- Grüner Strahl (Gelassenheit): Heiler stellt sich hinein -> mehr Heilung, weniger Mana."] = "- 초록 광선 (평정): 힐러가 막음 -> 치유량 증가, 마나 감소."
L["- Blauer Strahl (Dominanz): DPS stellt sich hinein -> mehr Schaden."] = "- 파란 광선 (지배): 딜러가 막음 -> 피해 증가."
L["- Erschöpfungs-Debuff -> in den Strahlen rotieren."] = "- 탈진 디버프 -> 광선 로테이션."
L["- Verbannphase: Netheratem und Leerezonen -> verteilt stehen, Leerezonen meiden."] = "- 추방 단계: 황천 숨결과 공허의 지대 -> 산개, 공허의 지대 피하기."
L["Taktik: Feste Spieler pro Strahl einteilen und rotieren; in der Verbannphase Abstand halten und Zonen meiden."] = "공략: 광선마다 고정 인원 배정 후 로테이션; 추방 단계엔 거리 유지, 장판 피하기."
L["NETHERGROLL: Strahlen blocken und rotieren!"] = "황천의 원령: 광선 막고 로테이션!"
L["Verbannphase: Verteilen, aus Leerezonen raus."] = "추방 단계: 산개, 공허의 지대에서 나오세요."
L["Schachspiel"] = "체스 이벤트"
L["Schachspiel (Medivhs Spiel)"] = "체스 이벤트 (메디브의 체스판)"
L["- Spieler steuern Figuren -> den gegnerischen König angreifen."] = "- 플레이어가 말을 조종 -> 상대 왕 공격."
L["- Medivh schummelt: Feuer auf dem Brett und Buffs für Gegner -> Figuren aus dem Feuer ziehen."] = "- 메디브의 반칙: 체스판의 불과 상대 버프 -> 말을 불에서 빼기."
L["- Fähigkeiten der Figuren aktiv nutzen -> König schützen."] = "- 말 능력 적극 활용 -> 왕 보호."
L["Taktik: Ein Spieler pro Figur, Fokus auf den gegnerischen König, eigene Figuren aus dem Feuer."] = "공략: 말 하나당 한 명, 상대 왕 집중, 아군 말은 불에서 빼기."
L["SCHACH: Fokus auf den König! Aus dem Feuer ziehen!"] = "체스: 왕 집중! 불에서 빼세요!"
L["Eigenen König schützen."] = "아군 왕 보호."
L["Prinz Malchezaar"] = "공작 말체자르"
L["Prinz Malchezaar + Höllenbestien"] = "공작 말체자르 + 지옥불정령"
L["- Entkräften: setzt 5 Spieler auf 1 Leben -> sofort vor der Schattennova weglaufen."] = "- 쇠약: 5명의 생명력을 1로 -> 즉시 암흑 회오리에서 도망."
L["- Schattennova: Schaden um den Prinzen -> Raid in Abstand halten."] = "- 암흑 회오리: 공작 주변 피해 -> 공격대 거리 유지."
L["- Höllenbestien: fallen vom Himmel und machen Feuerschaden -> ausweichen."] = "- 지옥불정령: 하늘에서 떨어져 화염 피해 -> 피하기."
L["- Phase 2 (60%): Äxte, starke Nahkampftreffer -> Tank-CDs."] = "- 2단계 (60%): 도끼, 강력한 근접 공격 -> 탱커 생존기."
L["- Phase 3 (30%): fliegende Äxte und Schadensverstärkung -> Heiler aufmerksam."] = "- 3단계 (30%): 날아다니는 도끼와 피해 증폭 -> 힐러 주의."
L["Taktik: Boss in eine Ecke ohne Höllenbestien tanken; Entkräftete laufen sofort raus, ab 30% alles in Schaden."] = "공략: 지옥불정령 없는 구석에서 보스 탱; 쇠약 대상은 즉시 빠지기, 30%부터 전원 딜."
L["PRINZ: Entkräftet = sofort raus! Höllenbestien meiden!"] = "공작: 쇠약 = 즉시 빠지기! 지옥불정령 피하기!"
L["Phase 2: Tank-CDs. Phase 3: Volle DPS."] = "2단계: 탱커 생존기. 3단계: 풀딜."
L["Schrecken der Nacht"] = "파멸의 어둠"
L["Schrecken der Nacht + Skelette"] = "파멸의 어둠 + 해골"
L["- Dröhnendes Gebrüll: Furcht -> Furchtschutz/Erdstoßtotem."] = "- 우레같은 포효: 공포 -> 공포의 수호물/진동의 토템."
L["- Schwanzfeger/Spalten -> seitlich stehen."] = "- 꼬리 휘둘러치기/회전베기 -> 측면에 서기."
L["- Verkohlte Erde: Feuer am Boden -> raus."] = "- 그을린 대지: 바닥에 불 -> 나오기."
L["- Luftphase (75/50/25%): Knochenregen ruft Skelette -> sofort töten; Rauchende Explosion auf Tank."] = "- 공중 단계 (75/50/25%): 뼈의 비가 해골 소환 -> 즉시 처치; 탱커에게 연기 폭발."
L["Taktik: Boss seitlich tanken, Raid seitlich und verteilt; in der Luftphase Skelette per AoE töten."] = "공략: 보스는 측면으로 탱, 공격대는 측면 산개; 공중 단계엔 해골 광역 처치."
L["SCHRECKEN DER NACHT: Nicht vorne/hinten stehen! Feuer meiden!"] = "파멸의 어둠: 앞/뒤에 서지 마세요! 불 피하기!"
L["Luftphase: Skelette sofort töten."] = "공중 단계: 해골 즉시 처치."
L["Magtheridons Kammer"] = "마그테리돈의 둥지"
L["Magtheridon"] = "마그테리돈"
L["Magtheridon + 5 Kanalisierer des Höllenfeuers"] = "마그테리돈 + 지옥불 정신집중자 5"
L["- Kanalisierer: Schattenblitzsalve, Dunkle Heilung -> unterbrechen, einzeln tanken und töten (sie stärken die anderen beim Tod)."] = "- 정신집중자: 어둠의 화살 일제 사격, 어둠의 치유 -> 차단, 하나씩 탱하고 처치 (죽으면 나머지 강화)."
L["- Höllenbestien: fallen auf Spieler -> ausweichen."] = "- 지옥불정령: 플레이어 위로 떨어짐 -> 피하기."
L["- Druckwellennova: Raidweiter Schaden -> 5 Spieler klicken gleichzeitig die Manticronwürfel, um sie zu unterbrechen."] = "- 폭발의 파동: 공격대 전체 피해 -> 5명이 동시에 마나티크론 정육면체를 클릭해 차단."
L["- Debris-Einsturz (ab 30%): Steine fallen -> aus dem Bereich laufen."] = "- 잔해 붕괴 (30%부터): 돌이 떨어짐 -> 범위에서 나오기."
L["Taktik: Kanalisierer schnell töten; 2 Gruppen à 5 Spieler für die Würfel einteilen und abwechseln (Debuff)."] = "공략: 정신집중자 빠르게 처치; 정육면체용 5인 2개 조를 배정해 교대 (디버프)."
L["MAGTHERIDON: Würfel gleichzeitig klicken bei Druckwellennova!"] = "마그테리돈: 폭발의 파동 때 정육면체 동시 클릭!"
L["Phase 1: Kanalisierer unterbrechen und töten. Ab 30%: Debris meiden."] = "1단계: 정신집중자 차단 후 처치. 30%부터: 잔해 피하기."
L["Jeder Kanalisierer ein Symbol in Tötungsreihenfolge, Totenkopf zuerst."] = "정신집중자마다 처치 순서대로 징표, 해골 먼저."
L["Höhle des Schlangenschreins"] = "불뱀 제단"
L["Hydross der Unstete"] = "불안정한 히드로스"
L["Hydross der Unstete + Elementare"] = "불안정한 히드로스 + 정령"
L["- Frost- und Naturform: wechselt beim Überschreiten der Linie -> Frost- und Naturwiderstand-Tank im Wechsel."] = "- 냉기 형상과 자연 형상: 선을 넘으면 전환 -> 냉기 저항 탱커와 자연 저항 탱커 교대."
L["- Mal des Hydross / Mal der Verderbnis: stapelnde Schadenserhöhung -> Boss rechtzeitig über die Linie ziehen."] = "- 히드로스의 징표 / 타락의 징표: 중첩되는 피해 증가 -> 제때 보스를 선 너머로 끌기."
L["- Elementare beim Formwechsel -> per AoE töten."] = "- 형상 전환 시 정령 -> 광역 처치."
L["- Wassergrab / Schlamm-Effekte -> Betroffene heilen."] = "- 물의 무덤 / 진흙 효과 -> 대상 치유."
L["Taktik: Zwei Tanks mit Widerstand, Formwechsel bei ca. 3-4 Stapeln; Fernkampf AoE auf die Elementare."] = "공략: 저항 장비 탱커 둘, 약 3~4 중첩에 형상 전환; 원딜은 정령 광역."
L["HYDROSS: Formwechsel = Tankwechsel! Elementare mit AoE!"] = "히드로스: 형상 전환 = 탱 교대! 정령은 광역!"
L["Nicht zu viele Mal-Stapel aufbauen."] = "징표 중첩 너무 쌓지 마세요."
L["Das Grauen aus der Tiefe"] = "심연의 잠복꾼"
L["Das Grauen aus der Tiefe + Adds"] = "심연의 잠복꾼 + 쫄"
L["- Speien: rotierender Wasserstrahl -> ins Wasser springen."] = "- 분출: 회전하는 물줄기 -> 물에 뛰어들기."
L["- Wirbeln: Rückstoß im Nahkampf -> Nahkampf abseits wenn möglich."] = "- 소용돌이: 근접 밀쳐내기 -> 가능하면 근딜 떨어지기."
L["- Geysir: schleudert Spieler hoch -> verteilt stehen."] = "- 간헐천: 플레이어를 띄움 -> 산개."
L["- Abtauchen: Wachen und Hinterhältige auf Plattformen -> Adds töten."] = "- 잠수: 단상에 수호병과 매복자 등장 -> 쫄 처치."
L["Taktik: Boss zu Beginn angeln, Raid auf den Plattformen verteilt; bei Speien sofort ins Wasser."] = "공략: 시작 시 보스를 낚시로 불러내고 공격대는 단상에 산개; 분출 때 즉시 물속으로."
L["GRAUEN: Bei Speien ins Wasser springen!"] = "잠복꾼: 분출 때 물에 뛰어드세요!"
L["Abtauchen: Adds auf den Plattformen töten."] = "잠수: 단상 위 쫄 처치."
L["Leotheras der Blinde"] = "눈먼 레오테라스"
L["Leotheras der Blinde + Innere Dämonen"] = "눈먼 레오테라스 + 내면의 악마"
L["- Wirbelwind (Elfenform): Schaden um den Boss -> Nahkampf raus."] = "- 소용돌이 (엘프 형상): 보스 주변 피해 -> 근딜 빠지기."
L["- Dämonenform: Chaosstrahl -> Hexer tankt."] = "- 악마 형상: 혼돈의 화살 -> 흑마가 탱."
L["- Innerer Dämon: jeder Spieler muss seinen eigenen Dämon töten."] = "- 내면의 악마: 각자 자신의 악마를 처치해야 함."
L["- Ab 15%: Elf und Schatten getrennt -> zwei Tanks bereit."] = "- 15%부터: 엘프와 그림자 분리 -> 탱커 둘 대기."
L["Taktik: Krieger-Tank in Elfenform, Hexer-Tank in Dämonenform; innere Dämonen sofort töten."] = "공략: 엘프 형상엔 전사 탱, 악마 형상엔 흑마 탱; 내면의 악마 즉시 처치."
L["LEOTHERAS: Innere Dämonen sofort töten!"] = "레오테라스: 내면의 악마 즉시 처치!"
L["Wirbelwind: Nahkampf raus. Hexer-Tank bei Dämonenform."] = "소용돌이: 근딜 빠지기. 악마 형상엔 흑마 탱."
L["Tiefenlord Karathress"] = "심연의 군주 카라드레스"
L["Tiefenlord Karathress + Sharkkis, Tidalvess, Caribdis"] = "심연의 군주 카라드레스 + 샤르키스, 타이달베스, 카리브디스"
L["- Caribdis (Heiler): heilt die anderen -> unterbrechen, zuerst töten."] = "- 카리브디스 (힐러): 다른 보스 치유 -> 차단, 먼저 처치."
L["- Tidalvess: Totems (Feuerspeier) -> Totems sofort zerstören."] = "- 타이달베스: 토템 (불뱀) -> 토템 즉시 파괴."
L["- Sharkkis: Mehrfachschuss und Tier -> Tier mittanken."] = "- 샤르키스: 일제 사격과 야수 -> 야수도 함께 탱."
L["- Karathress: übernimmt Fähigkeiten getöteter Adds -> Totems weiter zerstören."] = "- 카라드레스: 처치된 쫄의 능력을 넘겨받음 -> 토템 계속 파괴."
L["Taktik: Jedes Add eigener Tank; übliche Reihenfolge Caribdis, Tidalvess, Sharkkis, dann Karathress."] = "공략: 쫄마다 전담 탱커; 일반적인 순서는 카리브디스, 타이달베스, 샤르키스, 이후 카라드레스."
L["KARATHRESS: Caribdis zuerst und unterbrechen!"] = "카라드레스: 카리브디스 먼저, 차단!"
L["Totems sofort zerstören."] = "토템 즉시 파괴."
L["Karathress"] = "카라드레스"
L["Totenkopf Caribdis, Kreuz Tidalvess, Viereck Sharkkis, Mond Karathress."] = "해골 카리브디스, 가위표 타이달베스, 네모 샤르키스, 달 카라드레스."
L["Morogrim Gezeitenwandler"] = "겅둥파도 모로그림"
L["Morogrim Gezeitenwandler + Murlocs"] = "겅둥파도 모로그림 + 멀록"
L["- Flutwelle: Frontalschaden -> Boss weg vom Raid drehen."] = "- 해일: 전방 피해 -> 보스를 공격대 반대로."
L["- Wassergrab: Spieler werden in Wassergräber teleportiert -> heilen."] = "- 물의 무덤: 플레이어가 물의 무덤으로 순간이동 -> 치유."
L["- Erdbeben: Murloc-Wellen -> per AoE töten."] = "- 지진: 멀록 웨이브 -> 광역 처치."
L["- Wasserkugeln ab 25%: folgen Spielern -> weglaufen/ausweichen."] = "- 25%부터 물방울: 플레이어를 따라옴 -> 도망/회피."
L["Taktik: Tank an der Wand, Murlocs per AoE; ab 25% Kugeln ausweichen."] = "공략: 탱커는 벽에, 멀록은 광역; 25%부터 물방울 피하기."
L["MOROGRIM: Murlocs mit AoE! Wassergrab-Spieler heilen!"] = "모로그림: 멀록 광역! 물의 무덤 대상 치유!"
L["Ab 25%: Wasserkugeln ausweichen."] = "25%부터: 물방울 피하기."
L["Lady Vashj"] = "여군주 바쉬"
L["Lady Vashj + Elementare und Schreiter"] = "여군주 바쉬 + 정령과 학살자"
L["- Phase 1: Schockschlag auf Tank, Statische Aufladung -> verteilt stehen."] = "- 1단계: 탱커에게 충격 타격, 전하 충전 -> 산개."
L["- Phase 2: Besudelter Kern von besudelten Elementaren -> zu den Generatoren weitergeben."] = "- 2단계: 오염된 정령이 떨구는 오염된 핵 -> 발전기로 전달."
L["- Verzauberte Elementare -> töten, bevor sie Vashj erreichen."] = "- 마력 깃든 정령 -> 바쉬에게 닿기 전에 처치."
L["- Echsenkrieger und Schreiter -> tanken/kiten."] = "- 나가 전사와 학살자 -> 탱/카이팅."
L["- Phase 3: Sporensegler -> grüne Wolken meiden."] = "- 3단계: 포자날개 -> 초록 구름 피하기."
L["Taktik: Kernweitergabe mit festen Spielern; Generatoren zügig aktivieren; Phase 3 schnell töten."] = "공략: 고정 인원으로 핵 전달; 발전기 빠르게 활성화; 3단계 빠르게 처치."
L["VASHJ: Kerne weitergeben, Generatoren aktivieren!"] = "바쉬: 핵 전달, 발전기 활성화!"
L["Elementare töten, bevor sie zu Vashj gelangen."] = "정령이 바쉬에게 닿기 전에 처치."
L["Sonnenbrunnenplateau"] = "태양샘 고원"
L["Kalecgos"] = "칼렉고스"
L["Kalecgos + Sathrovarr der Verderber (Dämonenreich)"] = "칼렉고스 + 타락의 사스로바르 (악마 영역)"
L["- Spektrale Explosion: Spieler werden ins Dämonenreich zu Sathrovarr teleportiert -> dort Sathrovarr tanken und Kalec (Elfengestalt) schützen."] = "- 망령 폭발: 플레이어가 악마 영역의 사스로바르에게 순간이동 -> 그곳에서 사스로바르를 탱하고 칼렉 (엘프 모습) 보호."
L["- Spektrale Erschöpfung: nach Rückkehr ca. 1 Min. kein Zutritt -> Gruppen planen und rotieren."] = "- 망령의 피로: 귀환 후 약 1분간 진입 불가 -> 조를 짜서 로테이션."
L["- Fluch der grenzenlosen Qual (Sathrovarr): steigender Schaden -> nur gezielt entfernen."] = "- 끝없는 고통의 저주 (사스로바르): 피해 증가 -> 골라서만 해제."
L["- Arkanpuffer und Wilde Magie (Kalecgos): stapelnder Arkanschaden und zufällige Effekte -> heilen, Debuffs beachten."] = "- 비전 버프와 야생 마법 (칼렉고스): 중첩 비전 피해와 무작위 효과 -> 치유, 디버프 주의."
L["- Kalecgos und Sathrovarr möglichst gleichmäßig senken -> unter 10% Raserei, Sathrovarr muss sterben, Kalecgos wird befreit."] = "- 칼렉고스와 사스로바르를 최대한 고르게 깎기 -> 10% 미만 광란, 사스로바르가 죽어야 칼렉고스 해방."
L["Taktik: Raid teilt sich auf: Hauptgruppe auf Kalecgos, Tanks und eine DPS-Gruppe rotieren ins Dämonenreich; Lebensbalken beider Bosse synchron halten."] = "공략: 공격대 분할: 본대는 칼렉고스, 탱커와 딜러 1개 조가 악마 영역 로테이션; 두 보스 생명력 동기화."
L["KALECGOS: Dämonenreich-Gruppen rotieren! Beide Bosse gleichmäßig senken!"] = "칼렉고스: 악마 영역 조 로테이션! 두 보스 고르게 깎기!"
L["Kalec im Dämonenreich am Leben halten. Sathrovarr muss sterben."] = "악마 영역의 칼렉 살려두기. 사스로바르가 죽어야 함."
L["Brutallus"] = "브루탈루스"
L["- Meteorschlag: Schaden im Frontalkegel, auf alle Getroffenen aufgeteilt, plus Debuff -> zwei Gruppen vor dem Boss im Wechsel."] = "- 유성 강타: 전방 부채꼴 피해, 맞은 인원 전체에 분배, 디버프 추가 -> 보스 앞 두 조가 교대."
L["- Brand: Feuer-DoT auf zufälligem Spieler, springt auf Umstehende -> nicht dicht stehen, durchheilen."] = "- 불태우기: 무작위 대상 화염 도트, 주변으로 전이 -> 붙어 서지 말고 버티며 치유."
L["- Stampfen: Tank wird zurückgestoßen und erleidet mehr Schaden -> Heiler reagieren, Tank sofort zurück."] = "- 발구르기: 탱커가 밀려나고 받는 피해 증가 -> 힐러 대응, 탱커 즉시 복귀."
L["- Hartes Enrage nach 6 Min. -> reiner DPS-Check."] = "- 6분 후 광폭 -> 순수 딜 체크."
L["Taktik: Tank plus Meteorgruppe vorne, zweite Gruppe wechselt, wenn der Debuff zu hoch ist; Rest seitlich verteilt, alle CDs früh."] = "공략: 탱커와 유성 조가 앞, 디버프가 너무 높으면 두 번째 조와 교대; 나머지 측면 산개, 쿨기는 초반에 전부."
L["BRUTALLUS: Meteorgruppen wechseln! Brand: Abstand halten!"] = "브루탈루스: 유성 조 교대! 불태우기: 거리 유지!"
L["6 Min. Enrage - alle Cooldowns nutzen."] = "6분 광폭 - 쿨기 전부 사용."
L["Teufelsruch"] = "지옥안개"
L["Teufelsruch + Unnachgiebige Tote"] = "지옥안개 + 불굴의 망자"
L["- Einkapseln: Spieler wird angehoben und verursacht Schaden um sich -> sofort von ihm weg."] = "- 감싸기: 플레이어가 공중에 뜨며 주변에 피해 -> 즉시 떨어지기."
L["- Ätzen: Tank-Debuff -> Tank heilen."] = "- 부식: 탱커 디버프 -> 탱커 치유."
L["- Gasnova: Schaden auf den Raid -> heilen."] = "- 가스 회오리: 공격대 피해 -> 치유."
L["- Luftphase: Dämonischer Dunst folgt Spielern und lässt Skelette entstehen -> Dunst wegziehen, Skelette per AoE töten."] = "- 공중 단계: 악마의 안개가 플레이어를 따라오며 해골 생성 -> 안개 끌고 가기, 해골 광역 처치."
L["- Nebel der Verderbnis: Atemangriff in Bahnen, Getroffene werden gedankenkontrolliert -> aus der Bahn des Atems gehen."] = "- 타락의 안개: 줄 단위 숨결, 맞으면 정신 지배 -> 숨결 경로에서 벗어나기."
L["Taktik: Raid verteilt, Nahkampf seitlich; in der Luftphase Dunst vom Raid wegziehen und vor dem Atem die Bahnen räumen."] = "공략: 공격대 산개, 근딜 측면; 공중 단계엔 안개를 공격대에서 떼어내고 숨결 전에 경로 비우기."
L["TEUFELSRUCH: Atem-Bahnen räumen! Einkapseln-Ziel meiden!"] = "지옥안개: 숨결 경로 비우기! 감싸기 대상 피하기!"
L["Dämonischen Dunst wegziehen, Skelette mit AoE töten."] = "악마의 안개 끌고 가기, 해골 광역 처치."
L["Eredarzwillinge"] = "에레다르 쌍둥이"
L["Eredarzwillinge (Lady Sacrolash und Großhexenmeisterin Alythess)"] = "에레다르 쌍둥이 (여군주 사크로래쉬와 대여흑마법사 알리데스)"
L["- Lady Sacrolash: Schattenklingen und Schattenbilder -> Nahkampftank, Schattenbilder per AoE töten."] = "- 여군주 사크로래쉬: 어둠의 칼날과 그림자 형상 -> 근접 탱, 그림자 형상 광역 처치."
L["- Großhexenmeisterin Alythess: Feuerzauber -> auf Distanz von Hexern tanken; Pyrogenik-Buff stehlen/reinigen."] = "- 대여흑마법사 알리데스: 화염 주문 -> 흑마가 원거리 탱; 불꽃 발화 버프 훔치기/정화."
L["- Feuersbrunst: Feuerschaden um ein Ziel -> verteilt stehen."] = "- 대화재: 대상 주변 화염 피해 -> 산개."
L["- Schattennova -> Ziel und Umstehende heilen."] = "- 암흑 회오리 -> 대상과 주변 치유."
L["- Gegenseitige Debuff-Stapel (Dunkel/Flamme berührt) -> Stapel beobachten."] = "- 상호 디버프 중첩 (어둠/불꽃의 손길) -> 중첩 확인."
L["Taktik: Beide getrennt tanken, meist zuerst Sacrolash; nach dem Tod eines Zwillings übernimmt der andere dessen Fähigkeiten."] = "공략: 둘을 따로 탱, 보통 사크로래쉬 먼저; 쌍둥이 하나가 죽으면 다른 쪽이 그 능력을 넘겨받음."
L["ZWILLINGE: Verteilt stehen! Pyrogenik stehlen/reinigen!"] = "쌍둥이: 산개! 불꽃 발화 훔치기/정화!"
L["Schattenbilder schnell töten. Debuff-Stapel beachten."] = "그림자 형상 빠르게 처치. 디버프 중첩 주의."
L["M'uru"] = "므우루"
L["M'uru + Leerenwächter und Schattenschwert-Adds / Entropius"] = "므우루 + 공허의 파수꾼과 어둠칼날 쫄 / 엔트로피우스"
L["- Dunkelheit: Leerezone unter Spielern -> sofort raus."] = "- 어둠: 플레이어 발밑 공허 지대 -> 즉시 나오기."
L["- Negative Energie: springt zwischen Spielern -> verteilt stehen."] = "- 부정적 에너지: 플레이어 사이로 튐 -> 산개."
L["- Leerenwächter: erscheinen aus der Dunkelheit -> tanken und töten."] = "- 공허의 파수꾼: 어둠에서 등장 -> 탱 후 처치."
L["- Schattenschwert-Berserker und Teufelsmagier aus den Türen -> abfangen, unterbrechen, töten."] = "- 어둠칼날 광전사와 지옥 마법사가 문에서 -> 막고, 차단, 처치."
L["- Phase 2 Entropius: Singularität (schwarzes Loch) und Dunkelheit -> ausweichen, volle DPS."] = "- 2단계 엔트로피우스: 특이점 (블랙홀)과 어둠 -> 피하기, 풀딜."
L["Taktik: Zwei Teams an den Türen für die Adds, Rest auf M'uru und Leerenwächter; Entropius schnell töten."] = "공략: 문마다 쫄 담당 두 조, 나머지는 므우루와 공허의 파수꾼; 엔트로피우스 빠르게 처치."
L["M'URU: Adds an den Türen abfangen! Raus aus der Dunkelheit!"] = "므우루: 문에서 쫄 막기! 어둠에서 나오세요!"
L["Entropius: Singularitäten ausweichen, volle DPS."] = "엔트로피우스: 특이점 피하기, 풀딜."
L["Kil'jaeden"] = "킬제덴"
L["Kil'jaeden + Hände des Betrügers"] = "킬제덴 + 기만자의 손"
L["- Hände des Betrügers: kanalisieren Kil'jaeden herbei -> zuerst töten."] = "- 기만자의 손: 킬제덴을 정신집중으로 불러냄 -> 먼저 처치."
L["- Feuerblüte: Debuff mit Schaden an Umstehenden -> verteilt stehen."] = "- 불꽃 개화: 주변 인원에게 피해 주는 디버프 -> 산개."
L["- Finstere Reflexionen: Kopien von Spielern -> schnell töten."] = "- 사악한 반영: 플레이어 복제 -> 빠르게 처치."
L["- Dunkelheit der tausend Seelen: tödlicher Raidschaden -> Kugeln der blauen Drachen für den Schild nutzen."] = "- 천 영혼의 어둠: 치명적인 공격대 피해 -> 푸른용 구슬로 보호막 사용."
L["- Armageddon: Meteore fallen -> Einschläge meiden."] = "- 아마겟돈: 유성 낙하 -> 낙하 지점 피하기."
L["Taktik: Raid verteilt; feste Spieler für die Kugeln; Reflexionen schnell beseitigen."] = "공략: 공격대 산개; 구슬 담당 고정; 반영은 빠르게 제거."
L["KIL'JAEDEN: Dunkelheit = Schild der Blauen!"] = "킬제덴: 어둠 = 푸른용 보호막!"
L["Feuerblüte: verteilen. Reflexionen töten, Armageddon meiden."] = "불꽃 개화: 산개. 반영 처치, 아마겟돈 피하기."
L["Festung der Stürme"] = "폭풍우 요새"
L["Al'ar"] = "알라르"
L["Al'ar + Glut von Al'ar"] = "알라르 + 알라르의 잿불"
L["- Flammenpuffer: Al'ar landet auf wechselnden Plattformen und trifft alle, wenn kein Tank in Nahkampfreichweite ist -> auf jeder Plattform ein Tank bereit."] = "- 화염 버프: 알라르가 바뀌는 단상에 내려앉고, 근접 사거리에 탱커가 없으면 전원 적중 -> 단상마다 탱커 대기."
L["- Flammenfedern: Al'ar fliegt in die Mitte und überzieht die Plattformen mit Feuer -> alle sofort nach unten in die Mitte."] = "- 불꽃 깃털: 알라르가 중앙으로 날아가 단상을 불로 뒤덮음 -> 전원 즉시 아래 중앙으로."
L["- Wiedergeburt: nach Phase 1 ersteht Al'ar mit Schaden um sich herum neu -> nicht in der Mitte stehen."] = "- 환생: 1단계 후 주변에 피해를 주며 부활 -> 중앙에 서지 말 것."
L["- Phase 2: Rüstung schmelzen auf dem Tank -> Tankwechsel; Flammenfelder am Boden -> raus."] = "- 2단계: 탱커에게 방어구 녹이기 -> 탱 교대; 바닥 불길 장판 -> 나오기."
L["- Sturzflug: Al'ar stürzt auf einen Spieler, Glut von Al'ar erscheint -> Glut tanken und töten (kostet Al'ar Leben), Explosion meiden."] = "- 급강하: 알라르가 플레이어에게 내리꽂히고 알라르의 잿불 등장 -> 잿불 탱 후 처치 (알라르 생명력 감소), 폭발 피하기."
L["Taktik: Phase 1 Tanks auf den Plattformen, Raid unten mittig verteilt; Phase 2 zwei Tanks im Wechsel, Gluten von Offtanks aufnehmen und töten."] = "공략: 1단계 탱커는 단상, 공격대는 아래 중앙 산개; 2단계 탱커 둘 교대, 잿불은 보조 탱커가 받아 처치."
L["AL'AR: Flammenfedern - sofort runter! Tank auf jeder Plattform!"] = "알라르: 불꽃 깃털 - 즉시 내려가세요! 단상마다 탱커!"
L["Phase 2: Tankwechsel bei Rüstung schmelzen. Gluten töten, Feuer meiden."] = "2단계: 방어구 녹이기 시 탱 교대. 잿불 처치, 불 피하기."
L["Leerhäscher"] = "공허의 절단기"
L["- Arkane Kugel: wird auf Fernkämpfer geworfen und explodiert am Zielort -> Fernkampf weit verteilt, Einschlagstelle verlassen."] = "- 비전 구슬: 원딜에게 던져져 목표 지점에서 폭발 -> 원딜 넓게 산개, 착탄 지점 벗어나기."
L["- Hämmern: Arkanschaden um den Boss -> Nahkampf und Tank heilen."] = "- 강타: 보스 주변 비전 피해 -> 근딜과 탱커 치유."
L["- Wegschlagen: Rückstoß und Bedrohungsverlust -> 2-3 Tanks mit ähnlicher Bedrohung."] = "- 후려치기: 밀쳐내기와 위협 손실 -> 위협 수준이 비슷한 탱커 2~3명."
L["- Enrage nach 10 Min. -> DPS-Check."] = "- 10분 후 광폭 -> 딜 체크."
L["Taktik: Boss mittig tanken, Fernkampf in großem Kreis verteilt und in Bewegung bei Kugeln; mehrere Tanks gegen Wegschlagen."] = "공략: 보스는 중앙 탱, 원딜은 큰 원으로 산개하고 구슬 때 이동; 후려치기 대비 탱커 여럿."
L["LEERHÄSCHER: Fernkampf verteilt! Arkanen Kugeln ausweichen!"] = "공허의 절단기: 원딜 산개! 비전 구슬 피하기!"
L["Tanks Bedrohung aufbauen (Wegschlagen). Enrage 10 Min."] = "탱커는 위협 수준 쌓기 (후려치기). 광폭 10분."
L["Hochastromantin Solarian"] = "고위 점성술사 솔라리안"
L["Hochastromantin Solarian + Agenten und Priester des Solariums"] = "고위 점성술사 솔라리안 + 솔라리움 요원과 사제"
L["- Zorn der Astromantin: nach kurzer Zeit Explosion um den Spieler -> Betroffener läuft sofort weg vom Raid."] = "- 점성술사의 격노: 잠시 후 대상 주변 폭발 -> 대상은 즉시 공격대에서 떨어지기."
L["- Arkane Geschosse: Schaden auf zufällige Spieler -> heilen."] = "- 신비한 화살: 무작위 대상 피해 -> 치유."
L["- Teilung: Solarian verschwindet, Agenten des Solariums erscheinen -> per AoE töten."] = "- 분열: 솔라리안이 사라지고 솔라리움 요원 등장 -> 광역 처치."
L["- Priester des Solariums: heilen -> unterbrechen und töten."] = "- 솔라리움 사제: 치유 -> 차단 후 처치."
L["- Leerenform (ab 20%): Psychischer Schrei (Furcht) -> Furchtschutz/Erdstoßtotem, volle DPS."] = "- 공허 형상 (20%부터): 영혼의 절규 (공포) -> 공포의 수호물/진동의 토템, 풀딜."
L["Taktik: Raid verteilt, Zorn-Ziele laufen zur Seite; in der Teilungsphase Agenten wegbomben und Priester unterbrechen."] = "공략: 공격대 산개, 격노 대상은 옆으로; 분열 단계엔 요원 광역, 사제 차단."
L["SOLARIAN: Zorn = sofort raus aus dem Raid!"] = "솔라리안: 격노 = 즉시 공격대 밖으로!"
L["Agenten per AoE, Priester unterbrechen. Ab 20%: Furcht."] = "요원 광역, 사제 차단. 20%부터: 공포."
L["Kael'thas Sonnenwanderer"] = "캘타스 선스트라이더"
L["Kael'thas Sonnenwanderer + 4 Berater und 7 Waffen"] = "캘타스 선스트라이더 + 조언자 4와 무기 7"
L["- Phase 1: Berater kommen nacheinander -> Thaladred fixiert (wegkiten), Sanguinar fürchtet (Furchtschutz), Capernian auf Distanz tanken, Telonicus Bomben meiden."] = "- 1단계: 조언자가 차례로 등장 -> 탈라드레드는 고정 (카이팅), 생귀나르는 공포 (공포의 수호물), 카퍼니안은 원거리 탱, 텔로니쿠스는 폭탄 피하기."
L["- Phase 2: 7 legendäre Waffen -> töten, plündern und in Phase 3/4 benutzen."] = "- 2단계: 전설 무기 7개 -> 처치, 획득 후 3/4단계에 사용."
L["- Phase 3: alle Berater stehen gleichzeitig wieder auf -> erneut tanken und töten."] = "- 3단계: 조언자 전원 동시 부활 -> 다시 탱 후 처치."
L["- Phase 4: Feuerball, Flammenschlag, Phönix, Gedankenkontrolle -> unterbrechen, Feuer meiden, Phönix samt Ei töten, Gedankenkontrollierte CC."] = "- 4단계: 화염구, 불기둥, 불사조, 정신 지배 -> 차단, 불 피하기, 불사조와 알 처치, 정신 지배 대상 CC."
L["- Schockbarriere + Pyroschlag: Schild schnell brechen und Pyroschlag unterbrechen."] = "- 충격 방벽 + 불덩이 작렬: 보호막 빠르게 깨고 불덩이 작렬 차단."
L["- Phase 5 (50%): Schwerkraftverlust -> schwebend verteilt bleiben, Netherdampf meiden."] = "- 5단계 (50%): 중력 상실 -> 공중에서 산개 유지, 황천 증기 피하기."
L["Taktik: Berater-Tanks fest einteilen und Waffen gezielt verteilen; in Phase 4/5 Unterbrecher-Rotation auf Kael."] = "공략: 조언자 탱커 고정 배정, 무기는 계획적으로 분배; 4/5단계엔 캘타스에 차단 로테이션."
L["Hinweis: Die Waffen sind nur im Kampf nutzbar; Waffen vorher fest an Spieler vergeben."] = "참고: 무기는 전투 중에만 사용 가능; 무기는 미리 플레이어별로 배정."
L["KAEL'THAS: Berater nacheinander! Waffen plündern und nutzen!"] = "캘타스: 조언자 차례로! 무기 획득 후 사용!"
L["Phase 4: Barriere brechen, Pyroschlag kicken. Phase 5: verteilt schweben."] = "4단계: 방벽 깨고 불덩이 작렬 차단. 5단계: 공중 산개."
L["Kael'thas (Berater)"] = "캘타스 (조언자)"
L["Totenkopf Thaladred, Kreuz Sanguinar, Viereck Capernian, Mond Telonicus."] = "해골 탈라드레드, 가위표 생귀나르, 네모 카퍼니안, 달 텔로니쿠스."
L["Zul'Aman"] = "줄아만"
L["Nalorakk"] = "날로라크"
L["Nalorakk (Bärengott)"] = "날로라크 (곰 신)"
L["- Brutaler Hieb (Trollform): Frontalschaden, auf alle Getroffenen aufgeteilt -> Nahkampf vor dem Boss teilt mit dem Tank."] = "- 잔혹한 베기 (트롤 형상): 전방 피해, 맞은 인원 전체에 분배 -> 보스 앞 근딜이 탱커와 분담."
L["- Woge: stürmt auf den entferntesten Spieler -> 1-2 feste Spieler mit viel Leben weit weg."] = "- 쇄도: 가장 먼 대상에게 돌진 -> 생명력 높은 고정 인원 1~2명을 멀리."
L["- Zerfleischen / Rotte Fleisch (Bärenform): Blutungen auf dem Tank -> Tank stark heilen."] = "- 할퀴기 / 살점 찢기 (곰 형상): 탱커에게 출혈 -> 탱커 집중 치유."
L["- Ohrenbetäubendes Gebrüll: Stille -> Heiler zuvor hochheilen."] = "- 귀청을 찢는 포효: 침묵 -> 그 전에 힐러가 풀힐."
L["- Formwechsel ca. alle 45 Sek. -> Tankwechsel."] = "- 약 45초마다 형상 변환 -> 탱 교대."
L["Taktik: Zwei Tanks wechseln bei Formwechsel; feste Woge-Ziele hinten, Nahkampf teilt Brutalen Hieb."] = "공략: 형상 변환 시 탱커 둘 교대; 쇄도 대상은 뒤에 고정, 근딜은 잔혹한 베기 분담."
L["NALORAKK: Tankwechsel bei Formwechsel! Woge-Ziel weit weg!"] = "날로라크: 형상 변환 시 탱 교대! 쇄도 대상 멀리!"
L["Nahkampf teilt Brutalen Hieb. Gebrüll = Stille."] = "근딜이 잔혹한 베기 분담. 포효 = 침묵."
L["Akil'zon"] = "아킬존"
L["Akil'zon + Adler"] = "아킬존 + 독수리"
L["- Elektrischer Sturm: ein Spieler wird angehoben, sein Umfeld ist sicher -> alle sammeln sich unter ihm."] = "- 전기 폭풍: 한 명이 공중에 뜨고 그 주변은 안전 -> 전원 그 아래로 모이기."
L["- Statische Störung: Naturschaden an Ziel und Umstehenden -> außerhalb des Sturms verteilt stehen."] = "- 정전기 방해: 대상과 주변에 자연 피해 -> 폭풍 밖에선 산개."
L["- Windbö: Spieler wird hochgeschleudert -> heilen."] = "- 돌풍: 플레이어를 띄움 -> 치유."
L["- Adler: Adds -> per AoE töten."] = "- 독수리: 쫄 -> 광역 처치."
L["Taktik: Raid locker verteilt, bei Elektrischem Sturm sofort unter dem angehobenen Spieler sammeln; Naturwiderstand hilft."] = "공략: 공격대 느슨하게 산개, 전기 폭풍 때 즉시 뜬 사람 아래로 모이기; 자연 저항 도움."
L["AKIL'ZON: Elektrischer Sturm - unter den Spieler stellen!"] = "아킬존: 전기 폭풍 - 뜬 사람 아래로!"
L["Sonst verteilt stehen. Adler per AoE."] = "그 외엔 산개. 독수리는 광역."
L["Jan'alai"] = "잔알라이"
L["Jan'alai + Brüter und Drachenfalken"] = "잔알라이 + 부화사와 용매"
L["- Flammenatem: Feuerlinie -> nicht vor dem Boss stehen."] = "- 화염 숨결: 불길 직선 -> 보스 앞에 서지 말 것."
L["- Feuerbomben: Bomben um den Boss -> Lücken suchen bzw. aus dem Bereich laufen."] = "- 화염 폭탄: 보스 주변 폭탄 -> 빈틈 찾거나 범위에서 나오기."
L["- Brüter der Amani'shi: brüten Eier aus -> Brüter einer Seite töten, nur wenige Eier schlüpfen lassen."] = "- 아마니쉬 부화사: 알 부화 -> 한쪽 부화사를 처치, 알은 조금만 부화시키기."
L["- Ab 35%: alle Eier schlüpfen -> Eier vorher reduzieren und Drachenfalken per AoE töten."] = "- 35%부터: 알 전부 부화 -> 미리 알 줄이고 용매 광역 처치."
L["Taktik: Jan'alai mittig, Raid verteilt; eine Seite der Eier kontrolliert ausbrüten, Rest bei 35% per AoE."] = "공략: 잔알라이는 중앙, 공격대 산개; 한쪽 알만 통제하며 부화, 나머지는 35%에 광역."
L["JAN'ALAI: Feuerbomben meiden! Brüter töten!"] = "잔알라이: 화염 폭탄 피하기! 부화사 처치!"
L["Drachenfalken per AoE, ab 35% schlüpfen alle Eier."] = "용매 광역, 35%부터 알 전부 부화."
L["Halazzi"] = "할라지"
L["Halazzi + Luchsgeist"] = "할라지 + 스라소니 영혼"
L["- Säbelpeitsche: Schaden auf alle Nahen aufgeteilt -> Nahkampf und Tanks zusammen am Boss."] = "- 톱니 채찍: 근처 인원 전체에 피해 분배 -> 근딜과 탱커 보스에 뭉치기."
L["- Teilung (75/50/25%): Troll und Luchsgeist trennen sich -> zwei Tanks."] = "- 분리 (75/50/25%): 트롤과 스라소니 영혼이 분리 -> 탱커 둘."
L["- Verderbtes Blitzschlagtotem -> sofort töten."] = "- 타락한 번개 토템 -> 즉시 처치."
L["- Flammenschock: Feuer-DoT -> bannen."] = "- 화염 충격: 화염 도트 -> 해제."
L["Taktik: Halazzi und Luchsgeist getrennt tanken, Totems sofort zerstören; unter 25% volle DPS."] = "공략: 할라지와 스라소니 영혼을 따로 탱, 토템 즉시 파괴; 25% 미만 풀딜."
L["HALAZZI: Totems sofort töten!"] = "할라지: 토템 즉시 처치!"
L["Teilung: Luchsgeist separat tanken. Flammenschock bannen."] = "분리: 스라소니 영혼 따로 탱. 화염 충격 해제."
L["Hexlord Malacrass"] = "주술 군주 말라크라스"
L["Hexlord Malacrass + 4 Adds"] = "주술 군주 말라크라스 + 쫄 4"
L["- Geistblitze: kanalisierter Schatten-AoE -> Heiler bereit, CDs."] = "- 영혼 화살: 정신집중 암흑 광역 -> 힐러 대기, 쿨기."
L["- Seele entziehen: übernimmt Klassenfähigkeiten eines Spielers -> darauf reagieren."] = "- 영혼 흡수: 플레이어의 직업 능력을 가져감 -> 그에 맞춰 대응."
L["- Kraft entziehen: stapelnder Debuff -> schnell töten."] = "- 힘 흡수: 중첩 디버프 -> 빠르게 처치."
L["- 4 zufällige Adds -> zuerst töten oder kontrollieren."] = "- 무작위 쫄 4 -> 먼저 처치 또는 제어."
L["Taktik: Adds zuerst, dann Malacrass; bei Geistblitzen heilen."] = "공략: 쫄 먼저, 다음 말라크라스; 영혼 화살 때 치유."
L["MALACRASS: Adds zuerst! Geistblitze heilen!"] = "말라크라스: 쫄 먼저! 영혼 화살 치유!"
L["Seele entziehen: Klassenfähigkeiten beachten."] = "영혼 흡수: 직업 능력 주의."
L["Malacrass"] = "말라크라스"
L["Ein Symbol pro Add, Totenkopf zuerst."] = "쫄마다 징표 하나, 해골 먼저."
L["Zul'jin"] = "줄진"
L["- Trollform: Wirbelwind und Grausamer Wurf (Blutung bis volle Gesundheit) -> Nahkampf raus, Ziele voll heilen."] = "- 트롤 형상: 소용돌이와 무자비한 투척 (생명력 가득 찰 때까지 출혈) -> 근딜 빠지기, 대상 풀힐."
L["- Bärenform (80%): Schleichende Paralyse -> bannen."] = "- 곰 형상 (80%): 서서히 퍼지는 마비 -> 해제."
L["- Adlerform (60%): Energiesturm (Zaubern verursacht Blitzschaden) und Wirbelstürme -> Wirbelstürmen ausweichen."] = "- 독수리 형상 (60%): 에너지 폭풍 (시전 시 번개 피해)과 회오리바람 -> 회오리바람 피하기."
L["- Luchsform (40%): Klauenwut und Luchsstürmen -> Ziele heilen."] = "- 스라소니 형상 (40%): 발톱 분노와 스라소니 돌진 -> 대상 치유."
L["- Drachenfalkenform (20%): Flammensäulen -> Säulen meiden."] = "- 용매 형상 (20%): 불기둥 -> 기둥 피하기."
L["Taktik: Phasen nacheinander mit festen Gegenmaßnahmen; Heiler auf Blutungen und Paralyse vorbereitet."] = "공략: 단계별 고정 대응; 힐러는 출혈과 마비에 대비."
L["ZUL'JIN: Formwechsel beachten! Paralyse bannen!"] = "줄진: 형상 변환 주의! 마비 해제!"
L["Adler: Wirbelstürme meiden. Drachenfalke: Flammensäulen meiden."] = "독수리: 회오리바람 피하기. 용매: 불기둥 피하기."
L["Prüfung des Kreuzfahrers"] = "십자군의 시험"
L["Anub'arak"] = "아눕아락"
L["Anub'arak + Nerubische Bohrer und Schwärmerskarabäen"] = "아눕아락 + 네루비안 굴착자와 무리 풍뎅이"
L["- Pfählen (Untergrundphase): ein Stachel verfolgt einen Spieler -> wegrennen und den Stachel über Permafrost (Eisfelder) führen, dort bricht er ab."] = "- 꿰뚫기 (지하 단계): 가시가 플레이어 한 명을 추적 -> 도망치면서 가시를 영구 서리(얼음 장판) 위로 유도, 거기서 가시가 끊김."
L["- Frostsphären: schweben im Raum -> runterschießen, sie erzeugen den Permafrost, den der Raid für Pfählen und die Bohrer braucht."] = "- 서리 구슬: 공중에 떠 있음 -> 원딜로 떨어뜨리기, 꿰뚫기와 굴착자 처리에 필요한 영구 서리를 생성함."
L["- Nerubische Bohrer: graben sich ein und heilen sich -> auf Permafrost tanken (dort können sie nicht eingraben), Schattenschlag unterbrechen."] = "- 네루비안 굴착자: 땅속으로 파고들며 스스로 회복 -> 영구 서리 위에서 탱 (거기선 파고들지 못함), 어둠의 일격 차단."
L["- Durchdringende Kälte: Frost-Debuff mit hohem Schaden -> Ziele gezielt heilen."] = "- 살을 에는 냉기: 피해량 높은 냉기 디버프 -> 대상자 집중 힐."
L["- Phase 3 (30 %): Heuschreckenschwarm mit dauerhaftem Raidschaden, Boss gräbt sich nicht mehr ein -> alle Abklingzeiten, schnell töten."] = "- 3단계 (30 %): 메뚜기 떼로 지속 공대 피해, 보스가 더 이상 잠복하지 않음 -> 모든 생존기/쿨기, 빠르게 처치."
L["Taktik: Boss in der Mitte tanken, Bohrer vom Offtank auf Permafrost sammeln und mit AoE töten. Pfählen-Ziel rennt zum Permafrost; ab 30 % Heldentum und alles auf den Boss."] = "공략: 보스는 중앙에서 탱, 굴착자는 부탱이 영구 서리 위로 모아 광역으로 처치. 꿰뚫기 대상은 영구 서리로 달리기; 30 %부터 영웅심 후 전원 보스 점사."
L["Heroisch: Bohrer unbedingt unterbrechen und kontrollieren, Permafrost knapp halten (Frostsphären nicht zu früh verbrauchen)."] = "영웅: 굴착자는 반드시 차단하고 CC, 영구 서리는 아껴 쓰기 (서리 구슬을 너무 일찍 소모하지 않기)."
L["ANUB'ARAK: Pfählen-Ziel zum Permafrost rennen! Bohrer auf Eis tanken!"] = "아눕아락: 꿰뚫기 대상은 영구 서리로 달리세요! 굴착자는 얼음 위에서 탱!"
L["Frostsphären runterschießen. Bei 30 % Heldentum, alles auf den Boss."] = "서리 구슬 떨어뜨리기. 30 %에 영웅심, 전원 보스 점사."
L["Fraktionschampions"] = "진영 대표 용사"
L["Fraktionschampions (6 bzw. 10 gegnerische Spieler-Champions)"] = "진영 대표 용사 (적 플레이어 용사 6명 또는 10명)"
L["- Heiler-Champions: heilen sich gegenseitig und bannen -> unterbrechen, kontrollieren und zuerst töten."] = "- 힐러 용사: 서로 치유하고 해제함 -> 차단, CC 후 가장 먼저 처치."
L["- Schutzzauber (Gottesschild, Eisblock, Schilde, HoTs) -> bannen bzw. Massenbannung auf Gottesschild."] = "- 보호 주문 (천상의 보호막, 얼음 방패, 보호막, 도트 힐) -> 해제 또는 천상의 보호막에 대규모 무효화."
L["- Kontrolleffekte (Furcht, Verwandlung, Betäubung) auf den Raid -> bannen, Freiheitsfähigkeiten nutzen, Heiler schützen."] = "- 공대에 거는 CC 효과 (공포, 변이, 기절) -> 해제, 해제기/탈출기 사용, 힐러 보호."
L["- Nahkampf-Champions springen auf Heiler und Stoffträger -> Offtanks und CC fangen sie ab."] = "- 근접 용사들이 힐러와 천 착용자에게 달려듦 -> 부탱과 CC로 막기."
L["- Abnehmende Wirkung (Diminishing Returns) gilt -> CC-Ziele fest einteilen, nicht doppelt kontrollieren."] = "- 점감 효과 (Diminishing Returns) 적용 -> CC 대상을 고정 배정, 중복 CC 금지."
L["Taktik: Raid steht kompakt auf einer Seite, alle Champions markieren. Fokus-Ziel strikt nach Symbol (meist Heiler zuerst), Rest per CC und Unterbrechungen kontrollieren."] = "공략: 공대는 한쪽에 뭉쳐 서고 모든 용사에 징표. 징표 순서대로 점사 (보통 힐러 먼저), 나머지는 CC와 차단으로 묶어두기."
L["Heroisch: Champions verursachen mehr Schaden; saubere Unterbrechungsrotation und CC-Zuweisungen sind Pflicht."] = "영웅: 용사들의 피해량 증가; 깔끔한 차단 로테이션과 CC 배정이 필수."
L["FRAKTIONSCHAMPIONS: Totenkopf fokussieren! Heiler unterbrechen, CC halten!"] = "진영 대표 용사: 해골 점사! 힐러 차단, CC 유지!"
L["Gottesschild/Eisblock bannen. Raid zusammen, Kontrolleffekte bannen."] = "천상의 보호막/얼음 방패 해제. 공대 뭉치기, CC 효과 해제."
L["Totenkopf = erstes Ziel, Kreuz = zweites, restliche Symbole für die CC-Ziele (Verwandlung, Furcht, Fesseln)."] = "해골 = 첫 번째 대상, 가위표 = 두 번째, 나머지 징표는 CC 대상 (변이, 공포, 속박)."
L["Lord Jaraxxus"] = "군주 자락서스"
L["Lord Jaraxxus + Infernos und Herrin des Schmerzes"] = "군주 자락서스 + 지옥불정령과 고통의 여군주"
L["- Teufelsfeuerball: starker Feuerzauber auf den Tank -> unterbrechen, verbliebenen Debuff bannen."] = "- 지옥불 화염구: 탱커에게 쓰는 강력한 화염 주문 -> 차단, 남은 디버프 해제."
L["- Legionsflamme: Spieler hinterlässt eine Feuerspur -> an den Rand laufen, Feuer nicht im Raid ablegen."] = "- 군단의 불길: 플레이어가 불길 자국을 남김 -> 가장자리로 이동, 공대 안에 불 깔지 않기."
L["- Fleischeinäscherung: Heilabsorb auf einem Spieler -> sofort komplett wegheilen, sonst Raidschaden."] = "- 살점 소각: 플레이어 한 명에게 치유 흡수 -> 즉시 전부 힐로 지우기, 아니면 공대 피해."
L["- Netherkraft: stapelbarer Magie-Buff auf dem Boss -> per Zauberraub/Magiebannung entfernen."] = "- 황천의 힘: 보스에게 중첩되는 마법 버프 -> 주문 훔치기/마법 해제로 제거."
L["- Netherportal / Infernalischer Vulkan: rufen Herrin des Schmerzes bzw. Infernos -> Herrin vom Offtank, Infernos per AoE."] = "- 황천 차원문 / 지옥불 화산: 고통의 여군주 또는 지옥불정령 소환 -> 여군주는 부탱, 지옥불정령은 광역으로."
L["Taktik: Boss in der Mitte tanken, Herrin des Schmerzes und Infernos vom Boss weg holen und zuerst töten. Feuerspuren an den Rand legen, Feuerball konsequent unterbrechen."] = "공략: 보스는 중앙에서 탱, 고통의 여군주와 지옥불정령은 보스에게서 떼어내 먼저 처치. 불길 자국은 가장자리에 깔고, 화염구는 철저히 차단."
L["Heroisch: Portale und Vulkane schnell zerstören, sonst kommen immer mehr Adds."] = "영웅: 차원문과 화산을 빠르게 파괴, 아니면 쫄이 계속 늘어남."
L["JARAXXUS: Teufelsfeuerball unterbrechen! Legionsflamme an den Rand!"] = "자락서스: 지옥불 화염구 차단! 군단의 불길은 가장자리로!"
L["Fleischeinäscherung wegheilen. Netherkraft stehlen/bannen, Adds zuerst."] = "살점 소각 힐로 지우기. 황천의 힘 훔치기/해제, 쫄 먼저."
L["Bestien von Nordend"] = "노스렌드의 야수들"
L["Bestien von Nordend: Gormok der Pfähler, Säureschlund & Schreckensschuppe, Eisheuler"] = "노스렌드의 야수들: 꿰뚫는 자 고르목, 산성아귀 & 공포비늘, 얼음울음"
L["- Gormok: Pfählen stapelt Blutungs-Debuff auf dem Tank -> Tankwechsel; Schneebolde springen auf Spieler -> sofort töten."] = "- 고르목: 꿰뚫기로 탱커에게 출혈 디버프 중첩 -> 탱 교대; 눈보라 코볼트가 플레이어에게 달라붙음 -> 즉시 처치."
L["- Säureschlund & Schreckensschuppe: Paralysegift und Brennende Galle -> vergiftete Spieler zu einem Galle-Ziel laufen, um die Paralyse aufzuheben."] = "- 산성아귀 & 공포비늘: 마비 독과 불타는 담즙 -> 중독된 플레이어는 담즙 대상에게 달려가 마비 해제."
L["- Würmer wechseln zwischen beweglich und stationär -> getrennt tanken, Giftpfützen meiden."] = "- 벌레들은 이동/고정 상태를 번갈아 바꿈 -> 따로 탱, 독 장판 피하기."
L["- Eisheuler: Massiver Krach stößt den Raid um, danach Wilder Ansturm auf einen Spieler -> aus der Laufbahn gehen, Boss ist nach Wandaufprall betäubt."] = "- 얼음울음: 거대한 굉음으로 공대를 넘어뜨린 뒤 플레이어 한 명에게 사나운 돌진 -> 돌진 경로에서 벗어나기, 벽에 부딪히면 보스 기절."
L["Taktik: Gormok am Eingang tanken und Schneebolde töten, Würmer möglichst gleichzeitig töten. Bei Eisheuler weit verteilen und dem Ansturm ausweichen, dann voller Schaden."] = "공략: 고르목은 입구에서 탱하고 코볼트 처치, 벌레는 가능한 동시에 처치. 얼음울음 때는 넓게 산개하고 돌진 회피, 그 후 딜 몰빵."
L["Heroisch: Die nächste Bestie kommt nach Zeit, auch wenn die vorige noch lebt – Schaden zählt."] = "영웅: 이전 야수가 살아 있어도 시간이 되면 다음 야수가 나옴 – 딜이 관건."
L["BESTIEN: Schneebolde töten! Gift-Spieler zu Brennende-Galle-Spielern!"] = "야수들: 코볼트 처치! 중독된 사람은 불타는 담즙 대상에게!"
L["Würmer gleichzeitig runter. Eisheuler: Ansturm ausweichen, dann Schaden."] = "벌레 동시에 잡기. 얼음울음: 돌진 피하고 딜."
L["Zwillingsval'kyr"] = "쌍둥이 발키르"
L["Zwillingsval'kyr: Fjola (Licht) und Eydis (Dunkelheit)"] = "쌍둥이 발키르: 피올라 (빛)와 에이디스 (어둠)"
L["- Licht-/Dunkelessenz: Spieler nehmen an den Portalen eine Farbe an -> Kugeln der eigenen Farbe einsammeln (Buff), Kugeln der Gegenfarbe meiden."] = "- 빛/어둠의 정수: 플레이어가 차원문에서 색을 받음 -> 같은 색 구슬 먹기 (버프), 반대 색 구슬 피하기."
L["- Wirbel (Licht oder Dunkel): großer Raidschaden -> vorher alle die Farbe des wirbelnden Bosses annehmen."] = "- 소용돌이 (빛 또는 어둠): 큰 공대 피해 -> 미리 소용돌이 쓰는 보스의 색으로 전원 변경."
L["- Schild + Zwillingspakt: Boss heilt sich -> Schild mit der Gegenfarbe brechen und den Pakt unterbrechen."] = "- 보호막 + 쌍둥이의 서약: 보스가 스스로 치유 -> 반대 색으로 보호막을 깨고 서약 차단."
L["- Berührung des Lichts/der Dunkelheit (Heroisch): Debuff -> Spieler wechselt auf die passende Essenz."] = "- 빛/어둠의 손길 (영웅): 디버프 -> 해당 플레이어는 맞는 정수로 변경."
L["Taktik: Beide Valkyr getrennt tanken, Raid nach Ansage auf die passende Farbe. Gemeinsamer Lebenspool – auf einen Boss Schaden machen, Schilde und Pakt sofort brechen."] = "공략: 두 발키르를 따로 탱, 공대는 콜에 따라 맞는 색으로. 생명력 공유 – 한 보스만 딜, 보호막과 서약은 즉시 깨기."
L["ZWILLINGE: Farbe des Wirbels annehmen! Schild brechen, Pakt unterbrechen!"] = "쌍둥이: 소용돌이 색으로 바꾸세요! 보호막 깨고 서약 차단!"
L["Eigene Farbe Kugeln sammeln, fremde Kugeln meiden."] = "같은 색 구슬 먹고, 다른 색 구슬 피하기."
L["Das Auge der Ewigkeit"] = "영원의 눈"
L["Malygos"] = "말리고스"
L["Malygos + Nexuslords, Funken der Macht, Ewigkeitsgeweihte"] = "말리고스 + 마력의 군주, 마력의 불꽃, 영원의 신봉자"
L["- Funke der Macht: fliegt zu Malygos und verstärkt ihn -> abfangen und von ihm weg töten, Spieler stehen in der Pfütze für Schadensbonus."] = "- 마력의 불꽃: 말리고스에게 날아가 강화시킴 -> 가로채서 보스에게서 떨어진 곳에서 처치, 플레이어는 웅덩이 안에 서서 피해 보너스 받기."
L["- Arkaner Atem / Wirbel: Raid wird hochgewirbelt -> Heiler halten den Raid oben, danach wieder sammeln."] = "- 비전 숨결 / 소용돌이: 공대가 공중으로 휘말림 -> 힐러는 공대 피 유지, 이후 다시 집결."
L["- Phase 2: Arkane Schübe und Nexuslords/Ewigkeitsgeweihte auf Scheiben -> unter Schutzblasen stellen, Adds töten und deren Scheiben übernehmen."] = "- 2단계: 비전 폭발과 원반 위의 마력의 군주/영원의 신봉자 -> 보호막 거품 아래 서기, 쫄 처치 후 원반 빼앗기."
L["- Phase 3: Raid fliegt auf roten Drachen -> Schadens-, Schild- und Heilfähigkeiten der Drachen koordiniert nutzen, Statischen Feldern ausweichen."] = "- 3단계: 공대가 붉은 용을 타고 비행 -> 용의 딜/보호막/힐 기술을 맞춰서 사용, 정전기장 피하기."
L["Taktik: P1 Boss am Rand tanken und Funken abfangen; P2 Adds per Fernkampf und Scheiben töten, Blasen nutzen; P3 Drachenfähigkeiten koordiniert einsetzen."] = "공략: 1단계 보스는 가장자리에서 탱하고 불꽃 가로채기; 2단계 쫄은 원딜과 원반으로 처치, 거품 활용; 3단계 용 기술 맞춰서 사용."
L["MALYGOS: Funken abfangen und von ihm weg töten! In der Pfütze stehen!"] = "말리고스: 불꽃 가로채서 보스에게서 떨어진 곳에서 처치! 웅덩이 안에 서세요!"
L["P2: Unter die Blase, Adds auf Scheiben töten. P3: Drachen-Combos nutzen."] = "2단계: 거품 아래로, 원반 위 쫄 처치. 3단계: 용 콤보 사용."
L["Eiskronenzitadelle"] = "얼음왕관 성채"
L["Sindragosa"] = "신드라고사"
L["- Entfesselte Magie: Zauberer erleiden Schaden pro Zauber -> bei hohen Stapeln kurz nicht zaubern; Nahkampf achtet auf Frost-Stapel (Bis auf die Knochen)."] = "- 해방된 마법: 주문 시전자는 주문마다 피해 -> 중첩이 높으면 잠시 시전 멈추기; 근딜은 냉기 중첩 (뼛속까지 시린 추위) 주의."
L["- Durchdringende Kälte (Blistering Cold): großer Schaden im Nahbereich nach Eisgriff -> sofort mindestens 25 m weg vom Boss."] = "- 살을 에는 추위 (Blistering Cold): 얼음 손아귀 후 근거리 큰 피해 -> 즉시 보스에게서 최소 25 m 이상 떨어지기."
L["- Frostleuchtfeuer: Ziele werden zu Eisgräbern -> in festgelegter Formation stehen, Gräber zum Sichtschutz nutzen."] = "- 서리 표지: 대상자가 얼음 무덤이 됨 -> 정해진 대형으로 서기, 무덤을 시야 가림막으로 사용."
L["- Luftphase: Frostbomben -> hinter Eisgrab verstecken, danach Gräber freischlagen."] = "- 공중 단계: 서리 폭탄 -> 얼음 무덤 뒤에 숨고, 이후 무덤 깨기."
L["- Phase 3 (35 %): Mysteriöse Energie stapelt auf Spielern -> per Sichtlinie hinter Eisgrab zurücksetzen."] = "- 3단계 (35 %): 신비한 에너지가 플레이어에게 중첩 -> 얼음 무덤 뒤로 시야를 끊어 초기화."
L["Taktik: Boss seitlich tanken, Raid hinter ihr gestaffelt. Eisgräber nach Plan platzieren, in P3 Tankwechsel und Stapel per Grab-Sichtschutz abbauen."] = "공략: 보스는 옆으로 탱, 공대는 보스 뒤쪽에 줄지어 배치. 얼음 무덤은 계획대로 배치, 3단계에선 탱 교대하고 중첩은 무덤 뒤 시야 끊기로 해제."
L["SINDRAGOSA: Nach Eisgriff sofort weg vom Boss! Frostbombe: hinter Eisgrab!"] = "신드라고사: 얼음 손아귀 후 즉시 보스에게서 멀어지세요! 서리 폭탄: 얼음 무덤 뒤로!"
L["Entfesselte Magie: weniger zaubern. P3 Stapel hinter Gräbern abbauen."] = "해방된 마법: 시전 줄이기. 3단계 중첩은 무덤 뒤에서 해제."
L["Valithria Traumwandler"] = "발리스리아 드림워커"
L["Valithria Traumwandler + untote Adds aus den Portalen"] = "발리스리아 드림워커 + 차원문에서 나오는 언데드 쫄"
L["- Ziel: Valithria auf 100 % heilen -> Heiler heilen nur sie, Schaden auf die Adds."] = "- 목표: 발리스리아를 100 %까지 치유 -> 힐러는 그녀만 힐, 딜러는 쫄 처리."
L["- Traumportale: Heiler fliegen in die Traumwelt und sammeln Nebelwolken -> starker Heilungsbonus."] = "- 꿈의 차원문: 힐러가 꿈의 세계로 날아가 안개 구름 수집 -> 큰 치유량 보너스."
L["- Unterdrücker: reduzieren die Heilung auf Valithria -> schnell töten bzw. kontrollieren."] = "- 억제자: 발리스리아에 대한 치유량 감소 -> 빠르게 처치 또는 CC."
L["- Brennende Skelette und Erzmagier: hoher Schaden/Raid-AoE -> sofort töten, Frostbomben-Zielen ausweichen."] = "- 불타는 해골과 대마법사: 높은 피해/공대 광역 -> 즉시 처치, 서리 폭탄 대상 피하기."
L["- Verderbte Abscheulichkeiten/Zombies: verlangsamen bzw. explodieren -> von Tanks gehalten, außerhalb des Raids töten."] = "- 타락한 누더기골렘/구울: 감속 또는 폭발 -> 탱커가 잡고 공대 밖에서 처치."
L["Taktik: Raid in zwei Gruppen an beiden Seiten für die Portale, Tanks sammeln die Adds. Heiler rotieren durch die Traumwelt, DPS fokussiert Unterdrücker und Skelette."] = "공략: 공대는 차원문을 위해 양쪽 두 그룹으로 나눔, 탱커는 쫄 모으기. 힐러는 돌아가며 꿈의 세계로, 딜러는 억제자와 해골 점사."
L["VALITHRIA: Heiler nur auf Valithria! Unterdrücker und Skelette zuerst!"] = "발리스리아: 힐러는 발리스리아만! 억제자와 해골 먼저!"
L["Heiler in die Portale, Nebel sammeln. Adds weg vom Raid tanken."] = "힐러는 차원문으로, 안개 수집. 쫄은 공대에서 떨어진 곳에서 탱."
L["Rat der Blutprinzen"] = "피의 공작 의회"
L["Rat der Blutprinzen: Valanar, Keleseth, Taldaram"] = "피의 공작 의회: 발라나르, 켈레세스, 탈다람"
L["- Nur ein Prinz ist verstärkt und nimmt echten Schaden -> Ziel beim Wechsel umstellen."] = "- 한 명의 공작만 강화되어 실제 피해를 받음 -> 전환 시 대상 변경."
L["- Valanar: Schockwirbel, verstärkt als großer Raidwirbel -> verteilen und aus Wirbeln raus."] = "- 발라나르: 충격 소용돌이, 강화 시 큰 공대 소용돌이 -> 산개 후 소용돌이에서 나오기."
L["- Keleseth: Schattenlanze und Dunkle Kerne -> von einem Fernkampf-Tank (z. B. Hexer) gehalten, Kerne mitnehmen."] = "- 켈레세스: 어둠의 창과 어둠의 핵 -> 원거리 탱 (예: 흑마법사)이 잡고, 핵은 몸에 지니기."
L["- Taldaram: Flammenkugel verfolgt einen Spieler -> Ziel zieht sie vom Raid weg."] = "- 탈다람: 화염 구슬이 플레이어 한 명을 추적 -> 대상자가 공대에서 멀리 끌고 가기."
L["- Kinetische Bomben: fallen langsam -> durch Fernkampf in der Luft halten, nicht aufschlagen lassen."] = "- 동역학 폭탄: 천천히 떨어짐 -> 원딜이 공중에 띄워두기, 바닥에 닿지 않게."
L["Taktik: Valanar und Taldaram von Nahkampf-Tanks, Keleseth vom Fernkampf-Tank; nur den verstärkten Prinzen voll beschießen, Bomben oben halten, Flammenkugeln kiten."] = "공략: 발라나르와 탈다람은 근접 탱, 켈레세스는 원거리 탱; 강화된 공작만 풀딜, 폭탄은 띄워두고 화염 구슬은 카이팅."
L["BLUTPRINZEN: Nur auf den verstärkten Prinzen! Kinetische Bomben oben halten!"] = "피의 공작: 강화된 공작만 치세요! 동역학 폭탄 띄워두기!"
L["Flammenkugel wegziehen. Bei Valanar-Wirbel verteilen."] = "화염 구슬 끌고 가기. 발라나르 소용돌이 때 산개."
L["Blutkönigin Lana'thel"] = "피의 여왕 라나텔"
L["- Essenz der Blutkönigin: gebissene Spieler müssen nach einiger Zeit einen anderen Spieler beißen -> feste Beißliste, sonst Gedankenkontrolle."] = "- 피의 여왕의 정수: 물린 플레이어는 일정 시간 후 다른 플레이어를 물어야 함 -> 고정 물기 순서, 아니면 정신 지배."
L["- Pakt der Dunkelgefallenen: verbundene Spieler nehmen Schaden -> sofort zueinander laufen."] = "- 타락한 자의 서약: 연결된 플레이어가 피해를 받음 -> 즉시 서로에게 달려가기."
L["- Schwärmende Schatten: Ziel hinterlässt Schattenpfütze -> am Rand ablegen, nicht durch den Raid laufen."] = "- 떼어둠: 대상자가 어둠 장판을 남김 -> 가장자리에 깔고, 공대를 가로지르지 않기."
L["- Luftphase: Blutwirbel und Furcht -> verteilt stehen, Heiler bereit."] = "- 공중 단계: 피의 소용돌이와 공포 -> 산개해서 서기, 힐러 대기."
L["Taktik: Boss zentral tanken, Fernkampf locker verteilt, Schatten an den Rand. Beißreihenfolge vorher festlegen (Schaden zuerst), Pakt-Spieler treffen sich sofort."] = "공략: 보스는 중앙에서 탱, 원딜은 느슨하게 산개, 어둠은 가장자리로. 물기 순서는 미리 정하기 (딜러 먼저), 서약 대상자는 즉시 만나기."
L["LANA'THEL: Beißliste einhalten! Pakt-Ziele sofort zueinander!"] = "라나텔: 물기 순서 지키세요! 서약 대상자 즉시 서로에게!"
L["Schwärmende Schatten an den Rand legen. Luftphase verteilt stehen."] = "떼어둠은 가장자리에 깔기. 공중 단계는 산개."
L["Der Lichkönig"] = "리치 왕"
L["Der Lichkönig + Ghule, Schreckliche Schrecken, Val'kyr, Eissphären, Wütende Geister"] = "리치 왕 + 구울, 끔찍한 공포, 발키르, 얼음 구슬, 격노한 영혼"
L["- Phase 1: Nekrotische Seuche springt beim Bannen -> auf einen Schrecklichen Schrecken bannen; Schrecken-Raserei per Einlullen beruhigen."] = "- 1단계: 괴저 역병은 해제 시 옮겨감 -> 끔찍한 공포에게 해제; 공포의 광란은 평정으로 해제."
L["- Zwischenphasen: Unbarmherziger Winter -> an den Rand, Eissphären und Wütende Geister töten bzw. ausweichen."] = "- 전환 단계: 무자비한 겨울 -> 가장자리로, 얼음 구슬과 격노한 영혼 처치 또는 회피."
L["- Phase 2: Val'kyr tragen Spieler zum Rand -> sofort töten bzw. verlangsamen; Entweihen -> aus dem Kreis raus, am Rand ablegen."] = "- 2단계: 발키르가 플레이어를 가장자리로 데려감 -> 즉시 처치 또는 감속; 부정 -> 원 밖으로, 가장자리에 깔기."
L["- Phase 3: Seele ernten zieht Spieler in Frostgram -> dort Geist töten/überleben; Üble Geister -> wegkiten, nicht berühren."] = "- 3단계: 영혼 수확이 플레이어를 서리한 안으로 끌어감 -> 그 안에서 영혼 처치/생존; 사악한 영혼 -> 카이팅, 닿지 않기."
L["- Zersprengen (Infest): Raidweiter Schaden -> Raid über 90 % hochheilen."] = "- 감염 (Infest): 공대 전체 피해 -> 공대 피를 90 % 이상으로 회복."
L["Taktik: Boss am Rand vom Eingang tanken, Adds sauber töten. P2 Val'kyr fokussieren und Entweihen am Rand ablegen, P3 Geister kiten und Seele ernten mit Abklingzeiten überbrücken."] = "공략: 보스는 입구 쪽 가장자리에서 탱, 쫄은 깔끔하게 처치. 2단계 발키르 점사하고 부정은 가장자리에, 3단계 영혼 카이팅하고 영혼 수확은 생존기로 버티기."
L["LICHKÖNIG: Val'kyr sofort töten! Entweihen am Rand ablegen!"] = "리치 왕: 발키르 즉시 처치! 부정은 가장자리에 깔기!"
L["Seuche auf Schrecken bannen. Winter: an den Rand, Sphären/Geister töten."] = "역병은 끔찍한 공포에게 해제. 겨울: 가장자리로, 구슬/영혼 처치."
L["Val'kyr"] = "발키르"
L["Totenkopf, Kreuz und Viereck auf die Val'kyr in Phase 2, in dieser Reihenfolge töten bzw. verlangsamen."] = "2단계 발키르에 해골, 가위표, 네모 – 이 순서로 처치 또는 감속."
L["Todesbringer Saurfang"] = "죽음의 인도자 사울팽"
L["Todesbringer Saurfang + Blutbestien"] = "죽음의 인도자 사울팽 + 피의 짐승"
L["- Mal des gefallenen Champions: betroffener Spieler wird auf Dauer geschwächt, sein Tod heilt den Boss -> Spieler unbedingt am Leben halten."] = "- 타락한 용사의 징표: 대상자가 영구적으로 약화되고, 사망 시 보스가 회복 -> 대상자는 반드시 살려두기."
L["- Blutmacht: Boss gewinnt Macht durch erlittenen/verursachten Schaden -> Schaden an Spielern möglichst gering halten."] = "- 피의 힘: 보스가 받은/준 피해로 힘을 얻음 -> 플레이어가 받는 피해를 최소화."
L["- Blutbestien: erscheinen periodisch -> Fernkampf tötet sie schnell, verlangsamen und nicht zum Raid lassen."] = "- 피의 짐승: 주기적으로 등장 -> 원딜이 빠르게 처치, 감속시키고 공대에 접근 못 하게."
L["- Kochendes Blut / Blutnova: Blutungs- und Flächenschaden -> Fernkampf verteilt, Heiler aufmerksam."] = "- 끓어오르는 피 / 피의 회오리: 출혈 및 광역 피해 -> 원딜 산개, 힐러 주의."
L["- Runenblut auf dem Tank -> Tankwechsel."] = "- 탱커에게 룬피 -> 탱 교대."
L["Taktik: Boss in der Mitte tanken, Fernkampf in einem lockeren Halbkreis. Bestien sofort mit Verlangsamung und Fokus töten, so wenig Male wie möglich zulassen."] = "공략: 보스는 중앙에서 탱, 원딜은 느슨한 반원 대형. 짐승은 즉시 감속과 점사로 처치, 징표는 최대한 적게 허용."
L["SAURFANG: Blutbestien sofort töten und verlangsamen! Male am Leben halten!"] = "사울팽: 피의 짐승 즉시 처치하고 감속! 징표 대상자 살려두세요!"
L["Fernkampf verteilt. Bei Runenblut Tankwechsel."] = "원딜 산개. 룬피 때 탱 교대."
L["Blutbestien"] = "피의 짐승"
L["Totenkopf zuerst, dann Kreuz usw.; Jäger und Frostzauberer verlangsamen die Bestien."] = "해골 먼저, 그다음 가위표 순; 사냥꾼과 냉기 법사는 짐승 감속."
L["Lady Todeswisper"] = "귀부인 데스위스퍼"
L["Lady Todeswisper + Kultfanatiker und Kultanhänger"] = "귀부인 데스위스퍼 + 교단 광신도와 교단 신봉자"
L["- Manabarriere (Phase 1): Schaden geht auf ihr Mana -> Fernkampf auf den Boss, bis das Mana leer ist."] = "- 마나 보호막 (1단계): 피해가 마나로 들어감 -> 원딜은 마나가 바닥날 때까지 보스 딜."
L["- Kultisten-Wellen von den Seiten -> Fanatiker an Tanks, Anhänger per Fernkampf; wiederbelebte Kultisten zuerst."] = "- 양쪽에서 교단 웨이브 -> 광신도는 탱커, 신봉자는 원딜; 부활한 교단원 먼저."
L["- Tod und Verfall: Schattenfeld auf dem Boden -> sofort raus."] = "- 죽음과 부패: 바닥의 어둠 장판 -> 즉시 나오기."
L["- Phase 2: Frostblitz und Frostblitzsalve -> unterbrechen; Berührung der Bedeutungslosigkeit stapelt -> Tankwechsel."] = "- 2단계: 얼음화살과 얼음화살 일제사격 -> 차단; 무의미의 손길 중첩 -> 탱 교대."
L["- Rachsüchtige Schatten: verfolgen einen Spieler -> weglaufen, Fernkampf tötet sie."] = "- 복수의 망령: 플레이어 한 명을 추적 -> 도망가기, 원딜이 처치."
L["Taktik: P1 Fernkampf baut Mana ab, Nahkampf und Tanks töten die Kultisten. P2 Boss in der Mitte tanken, Frostblitze unterbrechen und Schatten auskiten."] = "공략: 1단계 원딜은 마나 깎기, 근딜과 탱커는 교단원 처치. 2단계 보스는 중앙에서 탱, 얼음화살 차단하고 망령은 카이팅."
L["TODESWISPER: P1 Mana runter, Adds zuerst! Aus Tod und Verfall raus!"] = "데스위스퍼: 1단계 마나 깎고 쫄 먼저! 죽음과 부패에서 나오세요!"
L["P2: Frostblitz unterbrechen, Schatten wegkiten. Tankwechsel beachten."] = "2단계: 얼음화살 차단, 망령 카이팅. 탱 교대 주의."
L["Kultisten"] = "교단원"
L["Pro Welle Adds markieren, Totenkopf/Kreuz zuerst; Fanatiker an Tanks, Anhänger per Fernkampf."] = "웨이브마다 쫄에 징표, 해골/가위표 먼저; 광신도는 탱커, 신봉자는 원딜."
L["Luftschiffkampf"] = "비행선 전투"
L["Luftschiffkampf (Muradin Bronzebart bzw. Hochfürst Saurfang) + Entertrupps"] = "비행선 전투 (무라딘 브론즈비어드 또는 대군주 사울팽) + 승선 부대"
L["- Raketenrucksack: Entergruppe springt aufs feindliche Schiff -> Gewehrschützen/Axtwerfer und Mörser töten, Magier unterbrechen."] = "- 로켓 추진기: 승선조가 적 비행선으로 점프 -> 소총수/도끼 투척병과 박격포병 처치, 마법사 차단."
L["- Feindlicher Kampfmagier friert die Kanonen ein -> Magier töten, damit die Kanonen wieder feuern."] = "- 적 전투마법사가 대포를 얼림 -> 마법사를 처치해야 대포가 다시 발사됨."
L["- Kanonen: Spieler in den Kanonen schießen aufs Schiff -> Hitze beachten, Spezialschuss bei vollem Balken."] = "- 대포: 대포에 탄 플레이어가 적 비행선을 사격 -> 열기 주의, 게이지가 가득 차면 특수 사격."
L["- Enterer auf eigenem Schiff -> Tank holt sie, Raid tötet sie; Kommandant auf dem Gegnerschiff nur kurz tanken."] = "- 아군 비행선 위의 적 승선병 -> 탱커가 잡고 공대가 처치; 적 비행선의 지휘관은 잠깐만 탱."
L["Taktik: Zwei Spieler in die Kanonen, Entergruppe (Tank + DPS) springt über, Rest verteidigt das eigene Schiff. Schaden aufs feindliche Schiff bis es zerstört ist."] = "공략: 두 명은 대포에, 승선조 (탱 + 딜러)는 건너가고 나머지는 아군 비행선 방어. 적 비행선이 파괴될 때까지 딜."
L["LUFTSCHIFF: Magier auf dem Gegnerschiff töten, Kanonen feuern!"] = "비행선: 적 비행선의 마법사 처치, 대포 발사!"
L["Enterer auf eigenem Schiff töten, Entergruppe springt über."] = "아군 비행선 위 승선병 처치, 승선조는 건너가기."
L["Lord Mark'gar"] = "군주 마로우가르"
L["- Knochenstachel: spießt Spieler auf -> Stachel sofort zerstören."] = "- 뼈 가시: 플레이어를 꿰뚫음 -> 즉시 가시 파괴."
L["- Knochensturm: wirbelt durch den Raum mit hohem Schaden -> Abstand halten, Nahkampf kurz raus."] = "- 뼈의 폭풍: 높은 피해로 방 안을 휘젓고 다님 -> 거리 유지, 근딜은 잠시 빠지기."
L["- Kalte Flamme: Feuerlinien vom Boss -> ausweichen, nicht drin stehen."] = "- 차가운 불꽃: 보스에게서 뻗어나가는 불길 -> 피하고, 그 안에 서 있지 않기."
L["- Säbelhieb: Schaden wird auf die nahen Ziele aufgeteilt -> zwei Tanks nebeneinander vorne."] = "- 칼날 베기: 피해가 가까운 대상들에게 분산 -> 탱커 두 명이 앞에 나란히."
L["Taktik: Boss mittig tanken, Fernkampf locker verteilt. Knochenstacheln sofort zerstören, während Knochensturm verteilt stehen und Flammen ausweichen."] = "공략: 보스는 중앙에서 탱, 원딜은 느슨하게 산개. 뼈 가시는 즉시 파괴, 뼈의 폭풍 동안 산개하고 불꽃 피하기."
L["MARK'GAR: Knochenstacheln sofort zerstören! Kalten Flammen ausweichen!"] = "마로우가르: 뼈 가시 즉시 파괴! 차가운 불꽃 피하세요!"
L["Knochensturm: verteilt bleiben. Tanks nebeneinander für Säbelhieb."] = "뼈의 폭풍: 산개 유지. 칼날 베기 대비 탱커 나란히."
L["Fauldarm"] = "구린속"
L["- Inhalierte Seuche: nach 3 Stapeln folgt Durchdringender Ausbruch mit sehr hohem Schaden -> vorher Impfung gestapelt haben, Abklingzeiten nutzen."] = "- 역병 흡입: 3중첩 후 매우 강력한 날카로운 분출 -> 미리 접종 중첩 쌓기, 생존기 사용."
L["- Gasartige Sporen: auf mehreren Spielern -> Sporenträger in Gruppen platzieren, jeder bekommt Impfung."] = "- 가스 포자: 여러 플레이어에게 -> 포자 대상자를 그룹 안에 배치해 모두 접종 받기."
L["- Magenblähung: stapelt auf dem Tank -> Tankwechsel nach Absprache (vor 9 Stapeln)."] = "- 위장 팽창: 탱커에게 중첩 -> 콜에 맞춰 탱 교대 (9중첩 전에)."
L["- Übles Gas: Fernkampf-Spieler erhalten Schaden -> Fernkampf in Abstand verteilt in kleinen Gruppen."] = "- 악취 가스: 원딜 플레이어가 피해를 받음 -> 원딜은 거리를 두고 소그룹으로 산개."
L["Taktik: Boss in der Mitte tanken, Fernkampf in 2–3 Gruppen rundum. Sporen in die Gruppen verteilen, Tankwechsel nach Magenblähung, beim Ausbruch volle Heilung."] = "공략: 보스는 중앙에서 탱, 원딜은 주변에 2–3그룹. 포자는 그룹마다 분배, 위장 팽창 후 탱 교대, 분출 때 풀힐."
L["FAULDARM: Sporen-Gruppen bilden, Impfung stapeln! Tankwechsel beachten!"] = "구린속: 포자 그룹 만들고 접종 중첩! 탱 교대 주의!"
L["3. Seuchen-Stapel: Abklingzeiten. Fernkampf verteilt."] = "역병 3중첩: 생존기. 원딜 산개."
L["Professor Seuchenmord"] = "교수 퓨트리사이드"
L["Professor Seuchenmord + Schlamm und Gaswolke"] = "교수 퓨트리사이드 + 수액과 가스 구름"
L["- Instabiles Experiment: grüner Schlamm haftet an einem Spieler -> ganzer Raid stapelt auf dem Ziel, Schaden teilen."] = "- 불안정한 실험: 녹색 수액이 플레이어 한 명에게 달라붙음 -> 공대 전원이 대상자에게 뭉쳐 피해 분산."
L["- Orange Gaswolke: verfolgt einen Spieler -> Ziel kitet die Wolke, Rest verteilt sich; Schlamm/Wolke per Abscheulichkeit verlangsamen."] = "- 주황색 가스 구름: 플레이어 한 명을 추적 -> 대상자가 구름 카이팅, 나머지는 산개; 수액/구름은 누더기골렘으로 감속."
L["- Formbarer Schleim: wird auf Spieler geworfen -> ausweichen, stark verlangsamt."] = "- 끈적이는 점액: 플레이어에게 던짐 -> 피하기, 강한 감속."
L["- Phase 3: Mutierte Seuche stapelt auf den Tanks -> Tankwechsel."] = "- 3단계: 돌연변이 역병이 탱커에게 중첩 -> 탱 교대."
L["- Unbändige Seuche (Heroisch): wandert zwischen Spielern -> sofort weitergeben."] = "- 억제할 수 없는 역병 (영웅): 플레이어 사이를 옮겨다님 -> 즉시 넘기기."
L["Taktik: Boss tanken, ein Spieler steuert die Abscheulichkeit (verlangsamt Adds). Bei grünem Schlamm stapeln, bei oranger Wolke verteilen, P3 schnell mit Tankwechsel."] = "공략: 보스 탱, 한 명이 누더기골렘 조종 (쫄 감속). 녹색 수액엔 뭉치고, 주황 구름엔 산개, 3단계는 탱 교대하며 빠르게."
L["SEUCHENMORD: Grüner Schlamm -> alle stapeln! Orange Wolke -> verteilen!"] = "퓨트리사이드: 녹색 수액 -> 전원 뭉치기! 주황 구름 -> 산개!"
L["Formbarem Schleim ausweichen. Phase 3: Tankwechsel nach Seuche."] = "끈적이는 점액 피하기. 3단계: 역병 후 탱 교대."
L["Modermiene"] = "썩은얼굴"
L["Modermiene + kleine und große Schlammbrocken"] = "썩은얼굴 + 작은 수액과 큰 수액"
L["- Mutierte Infektion: Debuff -> Spieler läuft an den Rand und wird gebannt, dort entsteht ein kleiner Schlamm."] = "- 돌연변이 감염: 디버프 -> 대상자는 가장자리로 가서 해제받고, 그곳에 작은 수액 생성."
L["- Kleine Schlämme: verbinden sich zu großen -> Offtank sammelt kleine ein und führt den großen am Rand."] = "- 작은 수액: 합쳐져서 큰 수액이 됨 -> 부탱이 작은 수액을 모으고 큰 수액은 가장자리에서 끌고 다니기."
L["- Instabile Schlammexplosion: großer Schlamm explodiert bei 5 Stapeln -> Raid weit weg verteilen."] = "- 불안정한 수액 폭발: 큰 수액이 5중첩에 폭발 -> 공대는 멀리 산개."
L["- Schlammfontäne: Kegel vor dem Boss -> raus aus dem Kegel."] = "- 수액 분사: 보스 앞 부채꼴 -> 부채꼴에서 나오기."
L["Taktik: Boss in der Mitte tanken, Offtank kitet die Schlämme am Rand. Infizierte Spieler gehen zum Offtank, Explosionen ausweichen."] = "공략: 보스는 중앙에서 탱, 부탱은 가장자리에서 수액 카이팅. 감염된 플레이어는 부탱에게 가고, 폭발 피하기."
L["MODERMIENE: Infizierte zum Rand/Offtank! Explosion ausweichen!"] = "썩은얼굴: 감염자는 가장자리/부탱에게! 폭발 피하세요!"
L["Schlammfontäne: aus dem Kegel. Fernkampf locker verteilt."] = "수액 분사: 부채꼴에서 나오기. 원딜 느슨하게 산개."
L["Anub'Rekhan"] = "아눕레칸"
L["Anub'Rekhan + Gruftwachen und Gruftskarabäen"] = "아눕레칸 + 지하실 경비병과 지하실 풍뎅이"
L["- Heuschreckenschwarm: hoher Schaden um den Boss -> Tank kitet den Boss durch den Raum, Raid hält Abstand."] = "- 메뚜기 떼: 보스 주변에 높은 피해 -> 탱커가 보스를 방 안에서 카이팅, 공대는 거리 유지."
L["- Pfählen: Linie mit Wurf in die Luft -> ausweichen, Ziele heilen."] = "- 꿰뚫기: 직선으로 공중에 띄움 -> 피하고, 대상자 힐."
L["- Gruftwachen: Add mit Spalten -> vom Offtank halten und töten."] = "- 지하실 경비병: 가르기를 쓰는 쫄 -> 부탱이 잡고 처치."
L["Taktik: Boss am Rand tanken, Gruftwachen vom Offtank. Beim Schwarm kitet der Tank um den Raum, Raid bleibt weit weg und wartet ab."] = "공략: 보스는 가장자리에서 탱, 지하실 경비병은 부탱. 메뚜기 떼 동안 탱커가 방을 돌며 카이팅, 공대는 멀리 떨어져 기다리기."
L["ANUB'REKHAN: Heuschreckenschwarm -> weg vom Boss! Tank kiten!"] = "아눕레칸: 메뚜기 떼 -> 보스에게서 멀어지세요! 탱커 카이팅!"
L["Gruftwachen vom Offtank. Pfählen ausweichen."] = "지하실 경비병은 부탱. 꿰뚫기 피하기."
L["Großwitwe Faerlina"] = "귀부인 팰리나"
L["- Raserei: Boss teilt stark mehr Schaden aus -> einen Verehrer neben ihr töten (Witwenumarmung beendet die Raserei)."] = "- 광란: 보스 피해량 대폭 증가 -> 보스 옆에서 숭배자 처치 (과부의 포옹이 광란을 해제)."
L["- Giftblitzsalve: Raidweites Gift -> heilen, Gift entfernen."] = "- 독화살 일제사격: 공대 전체 독 -> 힐, 독 해제."
L["Taktik: Anhänger zuerst töten, Verehrer für die Raserei aufheben. Boss zentral tanken, Feuerregen meiden."] = "공략: 추종자 먼저 처치, 숭배자는 광란용으로 남겨두기. 보스는 중앙에서 탱, 불비 피하기."
L["FAERLINA: Anhänger zuerst! Raserei -> Verehrer neben Boss töten!"] = "팰리나: 추종자 먼저! 광란 -> 보스 옆에서 숭배자 처치!"
L["Feuerregen meiden. Gift entfernen."] = "불비 피하기. 독 해제."
L["Totenkopf/Kreuz auf die Anhänger (zuerst töten), Viereck/Mond auf die Verehrer für die Raserei."] = "추종자에 해골/가위표 (먼저 처치), 숭배자에 네모/달 (광란용)."
L["Maexxna"] = "맥스나"
L["- Netzwickel: Spieler hängen an der Wand -> Fernkampf befreit sie."] = "- 거미줄 감싸기: 플레이어가 벽에 매달림 -> 원딜이 풀어주기."
L["- Netzspray: Raid betäubt -> Heiler vorher HoTs und Tank vollheilen."] = "- 거미줄 분사: 공대 기절 -> 힐러는 미리 도트 힐, 탱커 풀피."
L["- Spinnenjunge: kleine Adds -> per AoE töten."] = "- 새끼 거미: 작은 쫄 -> 광역으로 처치."
L["- Raserei bei 30 % -> Abklingzeiten auf Tank."] = "- 30 %에 광란 -> 탱커에게 생존기."
L["Taktik: Boss mittig tanken, Fernkampf befreit Eingewickelte und tötet Junge. Vor dem Netzspray den Tank hochheilen."] = "공략: 보스는 중앙에서 탱, 원딜은 감싸인 사람 풀어주고 새끼 거미 처치. 거미줄 분사 전에 탱커 풀피."
L["MAEXXNA: Eingewickelte befreien! Vor Netzspray Tank voll heilen!"] = "맥스나: 감싸인 사람 풀어주세요! 거미줄 분사 전 탱커 풀피!"
L["Spinnenjunge per AoE. Bei 30 % Raserei: Abklingzeiten."] = "새끼 거미는 광역. 30 % 광란: 생존기."
L["Gluth"] = "글루스"
L["Gluth + Zombie-Hunde"] = "글루스 + 좀비 구울"
L["- Dezimieren: setzt alle auf 5 % -> Zombies kommen zum Boss und heilen ihn -> Zombies vorher kiten bzw. sofort töten."] = "- 학살: 전원을 5 %로 만듦 -> 좀비가 보스에게 와서 보스를 회복시킴 -> 좀비는 미리 카이팅하거나 즉시 처치."
L["- Tödliche Wunde: Heilung auf Tank reduziert -> Tankwechsel."] = "- 죽음의 상처: 탱커가 받는 치유량 감소 -> 탱 교대."
L["- Raserei -> Jäger beruhigen."] = "- 광란 -> 사냥꾼 평정."
L["Taktik: Boss tanken mit zwei Tanks im Wechsel, Offtank/Kiter hält die Zombies. Nach Dezimieren AoE auf Zombies und Raid hochheilen."] = "공략: 탱커 두 명이 번갈아 보스 탱, 부탱/카이터가 좀비 담당. 학살 후 좀비에 광역, 공대 힐업."
L["GLUTH: Zombies kiten, nach Dezimieren töten! Raserei beruhigen!"] = "글루스: 좀비 카이팅, 학살 후 처치! 광란은 평정!"
L["Tödliche Wunde: Tankwechsel."] = "죽음의 상처: 탱 교대."
L["Grobbulus"] = "그라불루스"
L["Grobbulus + Schleime"] = "그라불루스 + 진흙"
L["- Mutagene Injektion: Spieler hinterlässt Giftwolke -> an den Rand gehen."] = "- 돌연변이 주입: 플레이어가 독구름을 남김 -> 가장자리로 가기."
L["- Schleimspray: Kegel vor dem Boss erzeugt Schleime -> Tank dreht Boss weg, Schleime töten."] = "- 진흙 분사: 보스 앞 부채꼴에서 진흙 생성 -> 탱커가 보스를 돌리고, 진흙 처치."
L["- Giftwolken: Boss hinterlässt Wolken -> Boss langsam durch den Raum ziehen."] = "- 독구름: 보스가 구름을 남김 -> 보스를 천천히 방 안에서 끌고 다니기."
L["Taktik: Tank zieht den Boss im Kreis am Rand, injizierte Spieler laufen außen weg. Schleime per AoE."] = "공략: 탱커가 보스를 가장자리를 따라 원형으로 끌고, 주입 대상은 바깥쪽으로 빠지기. 진흙은 광역."
L["GROBBULUS: Injektion -> an den Rand! Wolken meiden!"] = "그라불루스: 주입 -> 가장자리로! 구름 피하세요!"
L["Schleimspray weg vom Raid, Schleime töten."] = "진흙 분사는 공대 반대쪽으로, 진흙 처치."
L["- Hasserfüllter Stoß: trifft das Ziel mit höchster Bedrohung im Nahkampf außer dem Haupttank -> 2–3 Tanks mit hoher Bedrohung."] = "- 증오의 일격: 메인 탱커를 제외하고 근접 범위에서 위협 수준이 가장 높은 대상을 공격 -> 위협 수준 높은 탱커 2–3명."
L["- Raserei bei 5 % -> Abklingzeiten."] = "- 5 %에 광란 -> 생존기."
L["- Berserker nach Zeitlimit -> reiner Schadenscheck."] = "- 시간 제한 후 광폭화 -> 순수 딜 체크."
L["Taktik: Haupttank und Stoß-Tanks vorne, Heiler fest auf Tanks. Alle Schaden, Heldentum nach Bedarf."] = "공략: 메인 탱커와 일격 탱커는 앞에, 힐러는 탱커 고정. 전원 딜, 필요 시 영웅심."
L["FLICKWERK: Schaden, Schaden, Schaden! Heiler auf die Stoß-Tanks!"] = "패치워크: 딜, 딜, 딜! 힐러는 일격 탱커에게!"
L["Bei 5 % Raserei: Abklingzeiten."] = "5 % 광란: 생존기."
L["Thaddius"] = "타디우스"
L["- Stalagg & Feugen (Phase 1): gleichzeitig töten, sonst Wiederbelebung."] = "- 스탈라그 & 퓨겐 (1단계): 동시에 처치, 아니면 부활."
L["- Polaritätsverschiebung: Plus/Minus -> Plus links, Minus rechts; gleiche Ladung zusammen stehen."] = "- 극성 변환: 플러스/마이너스 -> 플러스 왼쪽, 마이너스 오른쪽; 같은 극성끼리 모여 서기."
L["- Kettenblitz: Schaden springt -> verteilt stehen."] = "- 연쇄 번개: 피해가 튐 -> 산개해서 서기."
L["Taktik: P1 beide Adds gleichmäßig runter. P2 Raid nach Ladung aufgeteilt, bei jeder Polaritätsverschiebung sofort Seite wechseln."] = "공략: 1단계 두 쫄을 균등하게 깎기. 2단계 공대는 극성별로 나누고, 극성 변환 때마다 즉시 위치 변경."
L["THADDIUS: Plus links, Minus rechts! Bei Wechsel sofort umstellen!"] = "타디우스: 플러스 왼쪽, 마이너스 오른쪽! 변환 시 즉시 이동!"
L["P1: Stalagg und Feugen gleichzeitig töten."] = "1단계: 스탈라그와 퓨겐 동시에 처치."
L["Kel'Thuzad"] = "켈투자드"
L["Kel'Thuzad + Skelette, Seelenfresser, Abscheulichkeiten, Wächter von Eiskrone"] = "켈투자드 + 해골, 영혼 먹보, 누더기골렘, 얼음왕관 수호자"
L["- Phase 1: Adds strömen aus den Nischen -> abfangen, nicht in die Nischen laufen."] = "- 1단계: 쫄이 벽감에서 쏟아져 나옴 -> 가로채고, 벽감 안으로 들어가지 않기."
L["- Frostblitz: starker Zauber auf den Tank -> unterbrechen."] = "- 얼음화살: 탱커에게 쓰는 강력한 주문 -> 차단."
L["- Manadetonation: Ziel explodiert -> weg vom Raid."] = "- 마나 폭발: 대상자가 폭발 -> 공대에서 멀어지기."
L["- Frostschlag: friert Spieler ein -> heilen; Schattenspalt -> raus."] = "- 서리 작렬: 플레이어를 얼림 -> 힐; 어둠의 균열 -> 나오기."
L["- Phase 3: Wächter von Eiskrone -> fesseln (Priester) oder tanken."] = "- 3단계: 얼음왕관 수호자 -> 속박 (사제) 또는 탱."
L["Taktik: P1 Adds im Zentrum abfangen, P2 Boss zentral tanken und Frostblitz unterbrechen, P3 Wächter fesseln."] = "공략: 1단계 쫄은 중앙에서 가로채기, 2단계 보스는 중앙에서 탱하고 얼음화살 차단, 3단계 수호자 속박."
L["KEL'THUZAD: Frostblitz unterbrechen! Detonation weg vom Raid!"] = "켈투자드: 얼음화살 차단! 마나 폭발은 공대에서 멀리!"
L["P3: Wächter fesseln. Schattenspalt raus."] = "3단계: 수호자 속박. 어둠의 균열에서 나오기."
L["Symbole auf die Wächter von Eiskrone in P3; jeder Priester fesselt sein Symbol."] = "3단계 얼음왕관 수호자에 징표; 사제는 각자 자기 징표를 속박."
L["- Frostaura: dauerhafter Raidschaden -> Frostschutz, Heiler fest."] = "- 서리 오라: 지속적인 공대 피해 -> 냉기 저항, 힐러 고정."
L["- Lebensentzug: Fluch -> entfluchen."] = "- 생명력 흡수: 저주 -> 저주 해제."
L["- Luftphase: Eisblock-Ziele -> hinter Eisblock verstecken vor Frostatem."] = "- 공중 단계: 얼음 덩어리 대상 -> 서리 숨결을 피해 얼음 덩어리 뒤에 숨기."
L["- Blizzard: Bodenfläche -> raus."] = "- 눈보라: 바닥 장판 -> 나오기."
L["Taktik: Boss vorne tanken, Raid verteilt. Flüche entfernen, in der Luftphase hinter Eisblöcken verstecken."] = "공략: 보스는 앞쪽에서 탱, 공대는 산개. 저주 해제, 공중 단계엔 얼음 덩어리 뒤에 숨기."
L["SAPHIRON: Luftphase -> hinter Eisblock! Flüche entfernen!"] = "사피론: 공중 단계 -> 얼음 덩어리 뒤로! 저주 해제!"
L["Blizzard meiden, Frostschutz."] = "눈보라 피하기, 냉기 저항."
L["Gothik der Ernter"] = "영혼착취자 고딕"
L["Gothik der Ernter + lebende und tote Adds"] = "영혼착취자 고딕 + 산 자와 죽은 자 쫄"
L["- Adds erscheinen auf der lebenden Seite; getötete erscheinen als Geister auf der toten Seite -> beide Seiten besetzen."] = "- 쫄은 산 자 쪽에 등장; 처치된 쫄은 죽은 자 쪽에 영혼으로 다시 등장 -> 양쪽 모두 인원 배치."
L["- Tor öffnet nach Zeit -> Adds strömen über, AoE."] = "- 일정 시간 후 문이 열림 -> 쫄이 넘어옴, 광역."
L["- Boss teleportiert zwischen den Seiten -> beide Seiten Schaden."] = "- 보스가 양쪽 사이를 순간이동 -> 양쪽 모두 딜."
L["Taktik: Raid auf zwei Seiten aufteilen, Tanks auf beiden Seiten. Nach Toröffnung Adds sammeln und töten."] = "공략: 공대를 양쪽으로 나누고, 양쪽에 탱커 배치. 문이 열리면 쫄 모아서 처치."
L["GOTHIK: Beide Seiten halten! Tote-Seite-Adds sofort töten!"] = "고딕: 양쪽 유지! 죽은 자 쪽 쫄 즉시 처치!"
L["Tor offen -> Adds sammeln, AoE."] = "문 열림 -> 쫄 모으고 광역."
L["Die Vier Reiter"] = "4기사단"
L["Die Vier Reiter: Korth'azz, Rivendare, Blaumeux, Zeliek"] = "4기사단: 코스아즈, 리븐데어, 블라미우스, 젤리에크"
L["- Male: stapeln sich auf Spielern in Reichweite -> Tankwechsel zwischen den Ecken."] = "- 징표: 사거리 내 플레이어에게 중첩 -> 구석 사이에서 탱 교대."
L["- Meteor (Korth'azz): Schaden aufgeteilt -> Nahkampf zusammen."] = "- 유성 (코스아즈): 피해 분산 -> 근딜 뭉치기."
L["- Leerzone (Blaumeux): -> raus."] = "- 공허의 지대 (블라미우스): -> 나오기."
L["- Heiliger Zorn (Zeliek): -> Zeliek abseits tanken."] = "- 신성한 격노 (젤리에크): -> 젤리에크는 떨어진 곳에서 탱."
L["Taktik: Reiter in Ecken tanken, Fernkampf auf Blaumeux/Zeliek, Nahkampf auf Korth'azz/Rivendare. Tankwechsel nach Male."] = "공략: 기사들은 구석에서 탱, 원딜은 블라미우스/젤리에크, 근딜은 코스아즈/리븐데어. 징표에 따라 탱 교대."
L["VIER REITER: Male beachten, Tankwechsel! Leerzone raus!"] = "4기사단: 징표 주의, 탱 교대! 공허의 지대에서 나오세요!"
L["Nahkampf auf Korth'azz/Rivendare, Fernkampf auf Blaumeux/Zeliek."] = "근딜은 코스아즈/리븐데어, 원딜은 블라미우스/젤리에크."
L["Vier Reiter"] = "4기사단"
L["Jeder Reiter ein Symbol, Totenkopf zuerst; Tanks nach Symbol eingeteilt."] = "기사마다 징표 하나, 해골 먼저; 탱커는 징표별로 배정."
L["Instrukteur Razuvious"] = "훈련교관 라주비어스"
L["Instrukteur Razuvious + Todesritter-Reservisten"] = "훈련교관 라주비어스 + 죽음의 기사 예비생"
L["- Unterbrechungsruf: hoher Schaden auf Spieler in der Nähe -> Abstand halten, Heiler und Zauberer weit weg."] = "- 방해의 외침: 근처 플레이어에게 높은 피해 -> 거리 유지, 힐러와 캐스터는 멀리."
L["- Reservisten: werden über die Kristalle per Gedankenkontrolle übernommen -> tanken den Boss abwechselnd mit Knochenbarriere und Spott."] = "- 예비생: 수정구를 통해 정신 지배로 조종 -> 뼈의 보호막과 도발로 번갈아 보스 탱."
L["- Schwere Schläge auf den Reservisten-Tank -> rechtzeitig auf den nächsten Reservisten wechseln."] = "- 예비생 탱커에게 강한 타격 -> 제때 다음 예비생으로 교대."
L["- Reservisten-Knochenbarriere/Spott: Fähigkeiten der kontrollierten Reservisten -> im Wechsel nutzen, Gedankenkontrolle rechtzeitig erneuern."] = "- 예비생 뼈의 보호막/도발: 조종 중인 예비생의 기술 -> 번갈아 사용, 정신 지배 제때 갱신."
L["Taktik: Zwei Spieler steuern die Reservisten über die Kristalle und tanken den Boss im Wechsel, Raid macht Schaden auf Razuvious, nicht auf die Reservisten."] = "공략: 두 명이 수정구로 예비생을 조종해 번갈아 보스 탱, 공대는 예비생이 아닌 라주비어스에게 딜."
L["RAZUVIOUS: Nicht die Reservisten angreifen! Kontrolleure: Wechsel ansagen!"] = "라주비어스: 예비생 공격 금지! 조종자: 교대 콜!"
L["Abstand vom Boss halten, Unterbrechungsruf trifft die Nähe."] = "보스와 거리 유지, 방해의 외침은 근처를 공격."
L["Razuvious"] = "라주비어스"
L["Reservisten markieren, jeder Kontrolleur übernimmt sein Symbol."] = "예비생에 징표, 조종자는 각자 자기 징표 담당."
L["- Eruption: die Bodenzonen explodieren der Reihe nach -> Raid tanzt gemeinsam in die jeweils sichere Zone."] = "- 분출: 바닥 구역이 차례로 폭발 -> 공대가 함께 안전 구역으로 춤추듯 이동."
L["- Entkräftendes Fieber/Krankheiten: Schaden über Zeit -> Krankheiten heilen bzw. bannen."] = "- 쇠약의 열병/질병: 지속 피해 -> 질병 치료 또는 해제."
L["- Plattformphase: Boss teleportiert und die Eruptionen werden schneller -> ganzer Raid tanzt in der hintersten Zone."] = "- 단상 단계: 보스가 순간이동하고 분출이 빨라짐 -> 공대 전원이 가장 뒤쪽 구역에서 춤추기."
L["- Manaentzug in Bossnähe -> Heiler und Zauberer etwas weiter weg."] = "- 보스 근처에서 마나 흡수 -> 힐러와 캐스터는 조금 더 멀리."
L["Taktik: Tank hält den Boss in der ersten Zone, Raid tanzt als Gruppe. In der Plattformphase gemeinsam hin und her springen."] = "공략: 탱커는 첫 번째 구역에서 보스 유지, 공대는 한 그룹으로 춤추기. 단상 단계엔 함께 앞뒤로 이동."
L["HEIGAN: Tanzen! Alle gemeinsam in die sichere Zone!"] = "헤이건: 춤추세요! 전원 함께 안전 구역으로!"
L["Plattformphase: schneller tanzen, Krankheiten heilen."] = "단상 단계: 더 빠르게 춤추기, 질병 치료."
L["Loatheb"] = "로데브"
L["- Nekrotische Aura: verhindert die meiste Heilung -> Heiler nutzen die kurzen Heilfenster."] = "- 괴저의 오라: 치유 대부분 차단 -> 힐러는 짧은 힐 타이밍 활용."
L["- Sporen: geben beim Tod einen Kritbuff in der Nähe -> gezielt in Nahkampf-/Fernkampfgruppen töten."] = "- 포자: 처치 시 근처에 치명타 버프 제공 -> 근딜/원딜 그룹 안에서 계획적으로 처치."
L["- Unvermeidliches Verderben: Schattenschaden wird mit der Zeit immer schneller -> Schadensrennen, Tank hält durch."] = "- 피할 수 없는 파멸: 시간이 지날수록 점점 빨라지는 암흑 피해 -> 딜 경쟁, 탱커는 버티기."
L["Taktik: Heilfenster koordinieren und Sporen nach Plan in die Gruppen ziehen und töten. Volles Burst, bevor Verderben zu oft kommt."] = "공략: 힐 타이밍을 조율하고 포자는 계획대로 그룹 안으로 끌어와 처치. 파멸이 자주 오기 전에 풀 버스트."
L["LOATHEB: Heilfenster nutzen! Sporen in die Gruppen töten!"] = "로데브: 힐 타이밍 활용! 포자는 그룹 안에서 처치!"
L["Unvermeidliches Verderben steigt -> schnell töten."] = "피할 수 없는 파멸 증가 -> 빠르게 처치."
L["Noth der Seuchenfürst"] = "역병술사 노스"
L["Noth der Seuchenfürst + Skelette"] = "역병술사 노스 + 해골"
L["- Fluch des Seuchenfürsten: Flüche auf Spieler -> sofort entfluchen."] = "- 역병술사의 저주: 플레이어에게 저주 -> 즉시 저주 해제."
L["- Blinzeln: Noth teleportiert und setzt Bedrohung zurück -> Tank holt ihn sofort wieder."] = "- 점멸: 노스가 순간이동하며 위협 수준 초기화 -> 탱커가 즉시 다시 잡기."
L["- Balkonphase: Boss verschwindet, Skelettwellen erscheinen -> Tanks fangen sie ab, AoE."] = "- 발코니 단계: 보스가 사라지고 해골 웨이브 등장 -> 탱커가 잡고, 광역."
L["Taktik: Boss in der Mitte tanken, Flüche entfernen. In der Balkonphase Adds sammeln und töten."] = "공략: 보스는 중앙에서 탱, 저주 해제. 발코니 단계엔 쫄 모아서 처치."
L["NOTH: Flüche entfernen! Balkonphase: Adds sammeln!"] = "노스: 저주 해제! 발코니 단계: 쫄 모으기!"
L["Blinzeln: Bedrohung neu aufbauen."] = "점멸: 어그로 다시 쌓기."
L["Das Obsidiansanktum"] = "흑요석 성소"
L["Sartharion"] = "사르타리온"
L["Sartharion + Lavablitze, ggf. Tenebron, Shadron, Vesperon"] = "사르타리온 + 용암 정령, 상황에 따라 테네브론, 샤드론, 베스페론"
L["- Flammentsunami: Lavawellen rollen über die Plattform -> durch die Lücke bzw. auf die sichere Seite laufen."] = "- 화염 해일: 용암 파도가 단상 위를 휩쓸고 지나감 -> 빈틈으로 또는 안전한 쪽으로 이동."
L["- Feuerspalt / Lavablitz: Feuerzonen auf dem Boden und Lava-Adds -> raus aus dem Feuer, Adds vom Offtank töten."] = "- 화염 균열 / 용암 정령: 바닥의 화염 장판과 용암 쫄 -> 불에서 나오기, 쫄은 부탱이 잡고 처치."
L["- Flammenatem: Kegel vor dem Boss -> nur der Tank steht vorne."] = "- 화염 숨결: 보스 앞 부채꼴 -> 탱커만 앞에 서기."
L["- Drachen bleiben am Leben (Sartharion +1/+2/+3): jeder Drache landet nach Zeit und verstärkt den Boss -> mehr Beute, aber deutlich schwerer."] = "- 용을 살려둠 (사르타리온 +1/+2/+3): 각 용이 시간이 지나면 착지해 보스를 강화 -> 전리품 증가, 하지만 훨씬 어려움."
L["Taktik: Boss mit dem Rücken zum Raid tanken, Raid verteilt und für den Tsunami bereit. Ohne Drachen vorher Tenebron, Shadron, Vesperon einzeln töten; mit Drachen Offtanks und Portalgruppen fest einteilen."] = "공략: 보스는 공대를 등지게 탱, 공대는 산개하고 해일에 대비. 용 없이 하려면 먼저 테네브론, 샤드론, 베스페론을 하나씩 처치; 용과 함께라면 부탱과 차원문 그룹 고정 배정."
L["Sartharion mit 3 Drachen ist die Herausforderung (Erfolg/Mount im 25er) – Drachen dabei nacheinander bei der Landung abfangen."] = "3용 사르타리온이 도전 과제 (25인 업적/탈것) – 용은 착지할 때마다 차례로 잡기."
L["SARTHARION: Flammentsunami -> in die Lücke! Aus dem Feuer raus!"] = "사르타리온: 화염 해일 -> 빈틈으로! 불에서 나오세요!"
L["Lavablitze vom Offtank. Drachen nach Plan abholen."] = "용암 정령은 부탱. 용은 계획대로 잡기."
L["Shadron"] = "샤드론"
L["Shadron + Akolyth von Shadron (Zwielichtportal)"] = "샤드론 + 샤드론의 수행사제 (황혼의 차원문)"
L["- Zwielichtportal: Akolyth von Shadron erscheint im Zwielicht und macht den Drachen bzw. Sartharion fast immun -> Gruppe ins Portal, Akolyth töten."] = "- 황혼의 차원문: 샤드론의 수행사제가 황혼 세계에 나타나 용 또는 사르타리온을 거의 무적으로 만듦 -> 그룹이 차원문으로 들어가 수행사제 처치."
L["- Schattenfissur: dunkler Kreis auf dem Boden -> sofort raus."] = "- 어둠의 균열: 바닥의 어두운 원 -> 즉시 나오기."
L["- Schattenatem: Kegel vor dem Drachen -> nur der Tank steht vorne."] = "- 어둠의 숨결: 용 앞 부채꼴 -> 탱커만 앞에 서기."
L["Taktik: Drachen vom Raid weg drehen, eine Portalgruppe tötet den Akolythen, danach Schaden auf Shadron."] = "공략: 용을 공대 반대쪽으로 돌리고, 차원문 그룹이 수행사제 처치, 그 후 샤드론 딜."
L["SHADRON: Portalgruppe -> Akolyth töten! Fissur raus!"] = "샤드론: 차원문 그룹 -> 수행사제 처치! 균열에서 나오세요!"
L["Atem nur auf den Tank, Drachen weggedreht."] = "숨결은 탱커에게만, 용은 돌려두기."
L["Tenebron"] = "테네브론"
L["Tenebron + Zwielichtwelpen"] = "테네브론 + 황혼의 새끼용"
L["- Zwielichteier: im Zwielicht schlüpfen Welpen -> Eier im Portal zerstören oder die Welpen in der normalen Welt per AoE töten."] = "- 황혼의 알: 황혼 세계에서 새끼용이 부화 -> 차원문 안에서 알을 깨거나 일반 세계에서 새끼용을 광역으로 처치."
L["Taktik: Drachen vom Raid weg drehen, Welpen vom Offtank sammeln und per AoE töten, dann Schaden auf Tenebron."] = "공략: 용을 공대 반대쪽으로 돌리고, 새끼용은 부탱이 모아 광역으로 처치, 그 후 테네브론 딜."
L["TENEBRON: Welpen sammeln und töten! Fissur raus!"] = "테네브론: 새끼용 모아서 처치! 균열에서 나오세요!"
L["Vesperon"] = "베스페론"
L["Vesperon + Akolyth von Vesperon (Zwielichtportal)"] = "베스페론 + 베스페론의 수행사제 (황혼의 차원문)"
L["- Zwielichtportal: Akolyth von Vesperon erscheint, solange er lebt erleidet der Raid Zwielichtqual (Schaden pro verursachtem Schaden) -> Gruppe ins Portal, schnell töten."] = "- 황혼의 차원문: 베스페론의 수행사제가 등장, 살아 있는 동안 공대는 황혼의 고통을 받음 (준 피해만큼 피해) -> 그룹이 차원문으로 들어가 빠르게 처치."
L["Taktik: Drachen vom Raid weg drehen, Portalgruppe tötet den Akolythen; währenddessen wenig Schaden machen, danach Vesperon töten."] = "공략: 용을 공대 반대쪽으로 돌리고, 차원문 그룹이 수행사제 처치; 그동안 딜 자제, 그 후 베스페론 처치."
L["VESPERON: Akolyth schnell töten! Bis dahin Schaden zurückhalten!"] = "베스페론: 수행사제 빠르게 처치! 그때까지 딜 자제!"
L["Fissur raus, Atem nur auf den Tank."] = "균열에서 나오기, 숨결은 탱커에게만."
L["Onyxia"] = "오닉시아"
L["Onyxia + Onyxiawelpen und Onyxische Wachen"] = "오닉시아 + 오닉시아 새끼용과 오닉시아 경비병"
L["- Flammenatem und Schwanzfeger -> nur der Tank vorne, niemand hinter ihr; seitlich stehen."] = "- 화염 숨결과 꼬리 휘둘러치기 -> 탱커만 앞에, 뒤에는 아무도 없게; 옆에 서기."
L["- Phase 2 (65 %): Onyxia fliegt, Feuerbälle auf Spieler und Tiefer Atem über den Raum -> verteilt stehen, aus der Atemlinie raus."] = "- 2단계 (65 %): 오닉시아가 날아오르고, 플레이어에게 화염구와 방 전체에 깊은 숨결 -> 산개, 숨결 경로에서 나오기."
L["- Welpen und Onyxische Wachen aus den Höhlen -> Offtanks fangen ab, AoE auf Welpen."] = "- 동굴에서 새끼용과 오닉시아 경비병 -> 부탱이 잡고, 새끼용은 광역."
L["- Phase 3 (40 %): Massenfurcht und Lavaeruptionen aus dem Boden -> Furchtschutz/Totem nutzen, nicht über Risse laufen."] = "- 3단계 (40 %): 대규모 공포와 바닥에서 용암 분출 -> 공포의 수호물/토템 사용, 균열 위로 지나가지 않기."
L["Taktik: P1 an der Nordwand tanken, Raid an den Seiten; P2 verteilt unter ihr, Welpen per AoE; P3 Tank holt sie sofort wieder, Furcht kontern."] = "공략: 1단계 북쪽 벽에서 탱, 공대는 양옆; 2단계 오닉시아 아래에 산개, 새끼용은 광역; 3단계 탱커가 즉시 다시 잡고, 공포 대응."
L["ONYXIA: Nicht vor oder hinter sie! P2: Tiefer Atem -> aus der Linie!"] = "오닉시아: 앞이나 뒤에 서지 마세요! 2단계: 깊은 숨결 -> 경로에서 나오기!"
L["Welpen per AoE. P3: Furchtschutz, Lavarisse meiden."] = "새끼용은 광역. 3단계: 공포의 수호물, 용암 균열 피하기."
L["Das Rubinsanktum"] = "루비 성소"
L["Baltharus der Kriegsjünger"] = "전쟁술사 발타루스"
L["Baltharus der Kriegsjünger + Abbild"] = "전쟁술사 발타루스 + 분신"
L["- Abbild: Boss spaltet sich bei bestimmten Lebenspunkten -> Offtank übernimmt das Abbild, beide gleichmäßig töten."] = "- 분신: 일정 생명력에서 보스가 분열 -> 부탱이 분신을 잡고, 둘 다 균등하게 처치."
L["- Klingentempest: Wirbelangriff um den Boss -> Nahkampf kurz raus."] = "- 칼날 폭풍: 보스 주변 회전 공격 -> 근딜은 잠시 빠지기."
L["- Entkräftendes Brandmal: Debuff auf Spielern verstärkt den Boss in der Nähe -> Betroffene weg vom Boss und voneinander."] = "- 약화의 낙인: 플레이어의 디버프가 근처 보스를 강화 -> 대상자는 보스와 서로에게서 멀어지기."
L["- Abstoßende Welle: stößt den Raid zurück -> nicht am Rand stehen."] = "- 밀어내는 파동: 공대를 뒤로 밀어냄 -> 가장자리에 서지 않기."
L["Taktik: Boss und Abbild getrennt tanken, Brandmal-Spieler gehen weg, Nahkampf meidet den Wirbel."] = "공략: 보스와 분신은 따로 탱, 낙인 대상자는 멀어지고, 근딜은 칼날 폭풍 피하기."
L["BALTHARUS: Abbild vom Offtank! Brandmal-Ziele weg vom Boss!"] = "발타루스: 분신은 부탱! 낙인 대상자는 보스에게서 멀리!"
L["Klingentempest: Nahkampf raus."] = "칼날 폭풍: 근딜 빠지기."
L["Halion"] = "할리온"
L["Halion + Zwielichtreich (Halion im Zwielicht)"] = "할리온 + 황혼 영역 (황혼의 할리온)"
L["- Phase 1: Feuriger Brand (Debuff) -> Ziel sofort an den Rand laufen; Meteoritenschlag -> aus der Einschlagzone und den Flammen raus."] = "- 1단계: 이글거리는 불길 (디버프) -> 대상자는 즉시 가장자리로; 유성 강타 -> 충돌 지역과 불길에서 나오기."
L["- Phase 2 (75 %): Halion im Zwielicht, Seelenverzehrung (Debuff) -> Ziel zum Rand; rotierende Schattenkugeln -> den Lasern ausweichen."] = "- 2단계 (75 %): 황혼의 할리온, 영혼 소모 (디버프) -> 대상자는 가장자리로; 회전하는 어둠의 구슬 -> 레이저 피하기."
L["- Phase 3 (50 %): beide Reiche gleichzeitig -> Schaden gleichmäßig verteilen (Körperlichkeit), sonst wird ein Reich stärker."] = "- 3단계 (50 %): 두 영역 동시 -> 피해를 균등하게 분배 (실체), 아니면 한쪽 영역이 강해짐."
L["- Atem und Schwanzfeger in beiden Reichen -> Boss vom Raid weg drehen."] = "- 양쪽 영역의 숨결과 꼬리 휘둘러치기 -> 보스를 공대 반대쪽으로 돌리기."
L["Taktik: P1 Raid verteilt hinter Halion, Debuffs an den Rand. P2 alle ins Portal, Laserkugeln ausweichen. P3 Raid aufteilen und nach Körperlichkeit-Ansagen Schaden anpassen."] = "공략: 1단계 공대는 할리온 뒤에 산개, 디버프는 가장자리로. 2단계 전원 차원문으로, 레이저 구슬 피하기. 3단계 공대를 나누고 실체 콜에 맞춰 딜 조절."
L["Heroisch: Zusätzlich Kugeln/Meteore häufiger und der Schadensausgleich in P3 muss deutlich exakter sein."] = "영웅: 구슬/유성이 더 자주 오고, 3단계 딜 균형을 훨씬 정확하게 맞춰야 함."
L["HALION: Feuriger Brand / Seelenverzehrung -> zum Rand! Meteor raus!"] = "할리온: 이글거리는 불길 / 영혼 소모 -> 가장자리로! 유성 피하세요!"
L["P2 Laser ausweichen. P3 Schaden auf beide Reiche gleichmäßig verteilen."] = "2단계 레이저 피하기. 3단계 두 영역에 딜 균등 분배."
L["Saviana Wutfeuer"] = "사비아나 래그파이어"
L["- Raserei: Schaden steigt stark -> Wildtiere besänftigen/Raserei sofort entfernen."] = "- 격노: 피해량 크게 증가 -> 평정/격노 즉시 해제."
L["- Flammenatem: Kegel -> nur der Tank vorne."] = "- 화염 숨결: 부채꼴 -> 탱커만 앞에."
L["- Luftphase: Entflammen auf mehreren Spielern -> Betroffene weg vom Raid, nicht ineinander stehen."] = "- 공중 단계: 여러 플레이어에게 점화 -> 대상자는 공대에서 멀어지고, 서로 겹쳐 서지 않기."
L["Taktik: Boss seitlich tanken, Raserei konsequent entfernen. In der Luftphase verteilen und Entflammen-Ziele separieren."] = "공략: 보스는 옆으로 탱, 격노는 철저히 해제. 공중 단계엔 산개하고 점화 대상자 분리."
L["SAVIANA: Raserei sofort entfernen! Entflammen-Ziele weg vom Raid!"] = "사비아나: 격노 즉시 해제! 점화 대상자는 공대에서 멀리!"
L["Atem nur auf den Tank. Luftphase verteilen."] = "숨결은 탱커에게만. 공중 단계 산개."
L["General Zarithrian"] = "장군 자리스리안"
L["General Zarithrian + Onyx-Flammenrufer"] = "장군 자리스리안 + 마그마 불꽃소환사"
L["- Rüstung spalten: stapelt auf dem Tank -> Tankwechsel."] = "- 방어구 쪼개기: 탱커에게 중첩 -> 탱 교대."
L["- Onyx-Flammenrufer: Adds aus den Seiten -> Offtank fängt ab, schnell töten, Feuerzauber unterbrechen."] = "- 마그마 불꽃소환사: 양쪽에서 나오는 쫄 -> 부탱이 잡고 빠르게 처치, 화염 주문 차단."
L["- Einschüchterndes Gebrüll: Furcht -> Furchtschutz/Totem nutzen."] = "- 위협의 포효: 공포 -> 공포의 수호물/토템 사용."
L["Taktik: Boss mit zwei Tanks im Wechsel, Adds vom Offtank abfangen und getrennt töten. Furcht kontern."] = "공략: 탱커 두 명이 번갈아 보스 탱, 쫄은 부탱이 잡아 따로 처치. 공포 대응."
L["ZARITHRIAN: Flammenrufer abfangen und töten! Tankwechsel beachten!"] = "자리스리안: 불꽃소환사 잡고 처치! 탱 교대 주의!"
L["Gebrüll: Furchtschutz bereit."] = "포효: 공포의 수호물 준비."
L["Ulduar"] = "울두아르"
L["Algalon der Beobachter"] = "관찰자 알갈론"
L["Algalon der Beobachter + Kollabierende Sterne, Lebende Konstellationen"] = "관찰자 알갈론 + 붕괴하는 별, 살아있는 별자리"
L["- Großer Knall: tödlicher Raidschaden -> vor Ende des Zaubers in ein Schwarzes Loch springen und danach wieder herauskommen."] = "- 빅뱅: 치명적인 공대 피해 -> 시전이 끝나기 전에 블랙홀로 뛰어들고 이후 다시 나오기."
L["- Kollabierende Sterne: verlieren Leben und hinterlassen beim Tod ein Schwarzes Loch -> kontrolliert nahe am Raid töten."] = "- 붕괴하는 별: 생명력이 줄어들며 처치 시 블랙홀을 남김 -> 공대 근처에서 통제하며 처치."
L["- Phasenschlag: stapelt auf dem Tank, bei 5 Stapeln wird er in eine andere Phase versetzt -> rechtzeitig Tankwechsel."] = "- 위상 타격: 탱커에게 중첩, 5중첩 시 다른 위상으로 이동됨 -> 제때 탱 교대."
L["- Kosmischer Schlag: markierte Einschläge auf Spielern -> aus dem Einschlag raus, Schaden nimmt mit Entfernung ab."] = "- 우주의 강타: 플레이어에게 표시된 충돌 지점 -> 충돌 지점에서 나오기, 거리가 멀수록 피해 감소."
L["- Lebende Konstellationen: Adds -> in ein Schwarzes Loch ziehen, das schließt das Loch und tötet das Add."] = "- 살아있는 별자리: 쫄 -> 블랙홀로 끌고 가면 구멍이 닫히고 쫄이 죽음."
L["- Unter 20 %: alle Löcher werden zu Dunkle-Materie-Adds -> Adds kontrollieren, Schadensrennen auf den Boss."] = "- 20 % 미만: 모든 구멍이 암흑 물질 쫄로 변함 -> 쫄 통제, 보스 딜 경쟁."
L["Taktik: Boss in der Mitte tanken, Sterne rechtzeitig für den Großen Knall töten und die Löcher freihalten. Tankwechsel nach Phasenschlag, Konstellationen gezielt in Löcher ziehen."] = "공략: 보스는 중앙에서 탱, 빅뱅에 맞춰 별을 처치하고 구멍 확보. 위상 타격 후 탱 교대, 별자리는 구멍으로 유도."
L["Zeitlimit: Nach dem ersten Pull bleibt eine Stunde für den Kill, danach verschwindet Algalon."] = "시간 제한: 첫 풀 이후 1시간 안에 처치해야 하며, 그 후 알갈론이 사라짐."
L["ALGALON: Großer Knall -> ins Schwarze Loch! Sterne rechtzeitig töten!"] = "알갈론: 빅뱅 -> 블랙홀로! 별은 제때 처치!"
L["Phasenschlag: Tankwechsel. Kosmischer Schlag: raus."] = "위상 타격: 탱 교대. 우주의 강타: 나오기."
L["Auriaya"] = "아우리아야"
L["Auriaya + Wächter des Sanktums, Wildverteidiger"] = "아우리아야 + 성소 파수꾼, 야생 수호자"
L["- Schreckliches Kreischen: Furcht auf den Raid, danach kanalisiert sie Wächtersalve -> Furchtschutz/Totem, Salve sofort unterbrechen."] = "- 공포의 비명: 공대에 공포, 이후 파수꾼 일제사격 채널링 -> 공포의 수호물/토템, 일제사격 즉시 차단."
L["- Schallkreischen: Kegel vor ihr, Schaden wird geteilt -> Tank und möglichst viele Spieler vorne stapeln."] = "- 음파 비명: 앞쪽 부채꼴, 피해 분산 -> 탱커와 최대한 많은 플레이어가 앞에 뭉치기."
L["- Wildverteidiger: Add mit 9 Leben, jeder Tod hinterlässt eine Pfütze -> immer wieder töten, Pfütze verlassen."] = "- 야생 수호자: 목숨 9개인 쫄, 죽을 때마다 웅덩이 생성 -> 계속 처치, 웅덩이에서 나오기."
L["- Wächter des Sanktums: Rudel mit dem Boss gepullt -> per Offtank sammeln und zuerst töten."] = "- 성소 파수꾼: 보스와 함께 풀링되는 무리 -> 부탱이 모아 먼저 처치."
L["Taktik: Wächter vom Boss getrennt tanken und zuerst töten, dann Boss; Kreischen-Kegel mit Stapel teilen, Salve konsequent unterbrechen."] = "공략: 파수꾼은 보스와 따로 탱하고 먼저 처치, 그다음 보스; 비명 부채꼴은 뭉쳐서 나누고, 일제사격은 철저히 차단."
L["AURIAYA: Wächtersalve unterbrechen! Schallkreischen vorne teilen!"] = "아우리아야: 파수꾼 일제사격 차단! 음파 비명은 앞에서 나눠 맞기!"
L["Wildverteidiger immer wieder töten, Pfützen verlassen."] = "야생 수호자 계속 처치, 웅덩이에서 나오기."
L["Flammenleviathan"] = "거대 화염전차"
L["Flammenleviathan (Fahrzeugkampf: Belagerungsmaschinen, Demolierer, Motorräder)"] = "거대 화염전차 (탈것 전투: 공성 전차, 파괴전차, 오토바이)"
L["- Verfolgung: Boss jagt ein Fahrzeug -> verfolgtes Fahrzeug fährt weg, Motorräder legen Teer zum Verlangsamen."] = "- 추적: 보스가 탈것 하나를 쫓음 -> 추적당하는 탈것은 도망, 오토바이는 타르를 깔아 감속."
L["- Überladungskreislauf: Passagiere (aus dem Demolierer katapultiert) zerstören die Geschütze auf dem Boss -> Boss betäubt, volles Feuer."] = "- 회로 과부하: 승객 (파괴전차에서 발사)이 보스의 포탑 파괴 -> 보스 기절, 일제 사격."
L["- Pyrit: Fässer aus der Luft -> Motorräder/Belagerungsmaschinen sammeln für die Demolierer."] = "- 황철석: 공중에서 떨어지는 통 -> 오토바이/공성 전차가 모아서 파괴전차에 공급."
L["- Flammenschlote: Flächenschaden um den Boss -> Fahrzeuge reparieren bzw. Abstand halten."] = "- 화염 분출구: 보스 주변 광역 피해 -> 탈것 수리 또는 거리 유지."
L["- Türme der Wächter: jeder stehen gelassene Turm verstärkt den Boss (Hardmode) -> nach Plan zerstören."] = "- 수호자의 탑: 남겨둔 탑마다 보스 강화 (하드 모드) -> 계획대로 파괴."
L["Taktik: Fahrzeuge vor dem Pull fest einteilen: Belagerungsmaschinen rammen, Demolierer schießen von hinten, Motorräder verlangsamen und sammeln Pyrit; verfolgte Fahrzeuge kiten."] = "공략: 풀 전에 탈것 고정 배정: 공성 전차는 들이받기, 파괴전차는 뒤에서 사격, 오토바이는 감속과 황철석 수집; 추적당하는 탈것은 카이팅."
L["LEVIATHAN: Verfolgtes Fahrzeug weg! Überladung -> volles Feuer!"] = "거대 화염전차: 추적당하는 탈것 도망! 과부하 -> 일제 사격!"
L["Pyrit sammeln, Passagiere die Geschütze zerstören."] = "황철석 수집, 승객은 포탑 파괴."
L["Freya"] = "프레이야"
L["Freya + Ältester Bewahrer, Elementar-Trio, Explosive Peitscher"] = "프레이야 + 고대 수호정령, 정령 삼총사, 폭발하는 채찍덩굴"
L["- Elementar-Trio (Wassergeist, Sturmpeitscher, Schnappschling): müssen kurz nacheinander sterben -> gleichmäßig runter, zusammen töten."] = "- 정령 삼총사 (물의 정령, 폭풍 채찍덩굴, 탁탁 덩굴손): 짧은 간격으로 함께 죽어야 함 -> 균등하게 깎고 함께 처치."
L["- Ältester Bewahrer: Griff des Bewahrers -> unter die Gesunden Sporen (Pilze) stellen."] = "- 고대 수호정령: 수호정령의 손아귀 -> 건강한 포자 (버섯) 아래에 서기."
L["- Explosive Peitscher: viele kleine Adds explodieren -> per AoE, aber nicht am Raid."] = "- 폭발하는 채찍덩굴: 많은 작은 쫄이 폭발 -> 광역으로, 단 공대 근처는 피하기."
L["- Sonnenstrahl und Naturbomben -> sofort raus; Eisenwurzeln fesseln Spieler -> Wurzel töten."] = "- 햇살과 자연 폭탄 -> 즉시 나오기; 무쇠 뿌리가 플레이어를 묶음 -> 뿌리 처치."
L["- Eonars Geschenk heilt Freya -> sofort töten."] = "- 이오나의 선물이 프레이야를 치유 -> 즉시 처치."
L["Taktik: Phase 1: sechs Add-Wellen tanken und töten, Elementar-Trio zusammen. Phase 2: Freya selbst, Bodeneffekte meiden."] = "공략: 1단계: 쫄 웨이브 6번 탱하고 처치, 정령 삼총사는 함께. 2단계: 프레이야 본체, 바닥 효과 피하기."
L["Hardmode: Älteste (Eisenzweig, Hellblatt, Steinrinde) bleiben am Leben und verstärken Freya."] = "하드 모드: 장로들 (무쇠가지, 밝은잎, 돌껍질)을 살려두면 프레이야가 강화됨."
L["FREYA: Elementar-Trio gleichzeitig töten! Eonars Geschenk sofort!"] = "프레이야: 정령 삼총사 동시 처치! 이오나의 선물 즉시!"
L["Sonnenstrahl/Naturbomben raus. Eisenwurzeln befreien."] = "햇살/자연 폭탄에서 나오기. 무쇠 뿌리 풀어주기."
L["General Vezax"] = "장군 베작스"
L["General Vezax (+ Saronitanimus im Hardmode)"] = "장군 베작스 (+ 하드 모드에서 사로나이트 원혼)"
L["- Aura der Verzweiflung: keine Manaregeneration -> Saronitdampf (Wolke) gibt Mana, aber stapelnder Schaden; kurz rein, wieder raus."] = "- 절망의 오라: 마나 회복 불가 -> 사로나이트 증기 (구름)가 마나를 주지만 피해 중첩; 잠깐 들어갔다 나오기."
L["- Sengende Flammen: Zauber auf den Raid -> konsequent unterbrechen."] = "- 이글거리는 불길: 공대에 쓰는 주문 -> 철저히 차단."
L["- Schattenkrachen: Geschoss auf einen Spieler -> verteilt stehen und ausweichen."] = "- 어둠의 붕괴: 플레이어 한 명에게 투사체 -> 산개해서 피하기."
L["- Mal der Gesichtslosen: entzieht Leben aus der Umgebung -> Ziel geht weg vom Raid."] = "- 얼굴 없는 자의 징표: 주변 생명력 흡수 -> 대상자는 공대에서 멀어지기."
L["- Dunkelheitsschub: Boss teilt stark mehr Schaden aus -> Tank kitet bzw. Abklingzeiten."] = "- 어둠의 쇄도: 보스 피해량 대폭 증가 -> 탱커 카이팅 또는 생존기."
L["Taktik: Raid locker verteilt, Unterbrechungsrotation für Sengende Flammen. Mana-Klassen nutzen die Saronitwolken vorsichtig, Tank kitet beim Schub."] = "공략: 공대는 느슨하게 산개, 이글거리는 불길 차단 로테이션. 마나 직업은 사로나이트 구름을 조심해서 활용, 쇄도 때 탱커 카이팅."
L["Hardmode: Saronitwolken nicht nutzen; sie verschmelzen zum Saronitanimus, der zuerst getötet wird."] = "하드 모드: 사로나이트 구름을 쓰지 않기; 구름이 합쳐져 사로나이트 원혼이 되며, 먼저 처치."
L["VEZAX: Sengende Flammen unterbrechen! Schattenkrachen ausweichen!"] = "베작스: 이글거리는 불길 차단! 어둠의 붕괴 피하세요!"
L["Mal-Ziel weg vom Raid. Dunkelheitsschub: Tank kitet."] = "징표 대상자는 공대에서 멀리. 어둠의 쇄도: 탱커 카이팅."
L["Hodir"] = "호디르"
L["Hodir + eingefrorene NPC-Helfer"] = "호디르 + 얼어붙은 NPC 조력자"
L["- Beißende Kälte: stapelnder Frostschaden bei Stillstand -> regelmäßig bewegen bzw. springen."] = "- 살을 에는 추위: 가만히 있으면 냉기 피해 중첩 -> 주기적으로 움직이거나 점프."
L["- Blitzfrost: friert den Raid ein -> in den Schneehaufen der gefallenen Eiszapfen stehen."] = "- 순간 빙결: 공대를 얼림 -> 떨어진 고드름의 눈더미 위에 서기."
L["- Eiszapfen: fallen auf Spieler -> aus dem Schatten raus."] = "- 고드름: 플레이어에게 떨어짐 -> 그림자에서 나오기."
L["- Gefrorene Schläge: Boss stärker, Tank-Abklingzeiten; eingefrorene NPCs befreien -> Buffs (Feuer, Sternenlicht, Sturmkraft, Heilung)."] = "- 얼어붙은 강타: 보스 강화, 탱커 생존기; 얼어붙은 NPC 구출 -> 버프 (불, 별빛, 폭풍의 힘, 치유)."
L["Taktik: Raid bewegt sich ständig, NPCs zuerst befreien und ihre Buffs nutzen. Bei Blitzfrost in die Schneehaufen."] = "공략: 공대는 계속 움직이고, NPC 먼저 구출해 버프 활용. 순간 빙결 때 눈더미로."
L["Hardmode: Hodir innerhalb von 3 Minuten töten (seltene Beutetruhe)."] = "하드 모드: 3분 안에 호디르 처치 (희귀 전리품 상자)."
L["HODIR: Blitzfrost -> in die Schneehaufen! Bewegen gegen Kälte!"] = "호디르: 순간 빙결 -> 눈더미로! 추위 대비 계속 움직이세요!"
L["NPCs befreien, Eiszapfen ausweichen."] = "NPC 구출, 고드름 피하기."
L["Ignis, Meister des Ofens"] = "용광로 군주 이그니스"
L["Ignis, Meister des Ofens + Eisenkonstrukte"] = "용광로 군주 이그니스 + 무쇠 피조물"
L["- Eisenkonstrukte: werden durch Sengen erhitzt -> Offtank zieht sie durchs Feuer, bei Geschmolzen ins Wasser, dort werden sie spröde."] = "- 무쇠 피조물: 불태우기로 가열됨 -> 부탱이 불 속으로 끌고 다니다 녹으면 물속으로, 거기서 깨지기 쉬워짐."
L["- Spröde Konstrukte: zerspringen bei starkem Schaden -> sofort hart treffen, Splitter-Schaden für den Raid beachten."] = "- 깨지기 쉬운 피조물: 큰 피해에 산산조각 -> 즉시 강하게 때리기, 공대에 튀는 파편 피해 주의."
L["- Schlackentopf: Spieler sitzt im Topf und erleidet hohen Schaden -> sofort hochheilen."] = "- 용재 단지: 플레이어가 단지 안에서 큰 피해를 받음 -> 즉시 힐업."
L["- Flammenstrahlen: Raidschaden und Zauberunterbrechung -> Zauber gut timen, Heiler bereit."] = "- 화염 분사: 공대 피해와 주문 차단 -> 시전 타이밍 조절, 힐러 대기."
L["Taktik: Boss vom Wasser entfernt tanken, Konstrukte vom Offtank durchs Feuer ins Wasser ziehen und dort zerbrechen; Topf-Ziel sofort heilen."] = "공략: 보스는 물에서 떨어진 곳에서 탱, 피조물은 부탱이 불을 거쳐 물로 끌고 가 깨기; 단지 대상자 즉시 힐."
L["IGNIS: Konstrukte ins Wasser und zerbrechen! Schlackentopf heilen!"] = "이그니스: 피조물 물에 넣고 깨기! 용재 단지 힐!"
L["Sengen-Feuer meiden. Flammenstrahlen: Heiler bereit."] = "불태우기 불 피하기. 화염 분사: 힐러 대기."
L["Die Versammlung des Eisens"] = "무쇠 평의회"
L["Die Versammlung des Eisens: Stahlbrecher, Runenmeister Molgeim, Sturmrufer Brundir"] = "무쇠 평의회: 강철파괴자, 룬주인 몰가임, 폭풍소환사 브룬디르"
L["- Jeder Tod verstärkt die verbleibenden Mitglieder -> Tötungsreihenfolge vorher festlegen (sie bestimmt Schwierigkeit und Beute)."] = "- 한 명이 죽을 때마다 남은 멤버가 강화 -> 처치 순서는 미리 정하기 (난이도와 전리품 결정)."
L["- Brundir: Überladung (große Blitzexplosion) -> 30 m weg; Kettenblitz -> unterbrechen; Blitzranken verfolgen Spieler -> weglaufen."] = "- 브룬디르: 과부하 (큰 번개 폭발) -> 30 m 떨어지기; 연쇄 번개 -> 차단; 번개 덩굴손이 플레이어 추적 -> 도망가기."
L["- Molgeim: Rune der Macht -> Tanks ziehen die Bosse hinein, Raid steht drin; Rune des Todes -> sofort raus; Runenschild -> bannen/Zauberraub."] = "- 몰가임: 힘의 룬 -> 탱커가 보스를 그 안으로 끌고, 공대도 안에 서기; 죽음의 룬 -> 즉시 나오기; 룬 보호막 -> 해제/주문 훔치기."
L["- Stahlbrecher: Fusionsschlag auf den Tank -> Debuff bannen; Hohe Spannung pulsiert Raidschaden -> Heiler stark gefordert."] = "- 강철파괴자: 탱커에게 융합 타격 -> 디버프 해제; 고전압이 공대 피해를 주기적으로 줌 -> 힐러 부담 큼."
L["Taktik: Drei Tanks, Bosse getrennt voneinander halten. Leichter Modus: Stahlbrecher zuerst, dann Molgeim, Brundir zuletzt; Hardmode genau umgekehrt (Stahlbrecher zuletzt)."] = "공략: 탱커 세 명, 보스는 서로 떨어뜨려 유지. 쉬운 모드: 강철파괴자 먼저, 그다음 몰가임, 브룬디르 마지막; 하드 모드는 정반대 (강철파괴자 마지막)."
L["VERSAMMLUNG: Totenkopf zuerst! Überladung -> 30 m weg!"] = "평의회: 해골 먼저! 과부하 -> 30 m 떨어지기!"
L["Rune des Todes raus, Rune der Macht rein. Kettenblitz unterbrechen."] = "죽음의 룬에서 나오고, 힘의 룬 안으로. 연쇄 번개 차단."
L["Versammlung des Eisens"] = "무쇠 평의회"
L["Totenkopf = erstes, Kreuz = zweites, Viereck = drittes Ziel laut gewählter Tötungsreihenfolge."] = "해골 = 첫 번째, 가위표 = 두 번째, 네모 = 세 번째 대상 (정한 처치 순서대로)."
L["Kologarn"] = "콜로간"
L["Kologarn + Linker/Rechter Arm, Geröll-Adds"] = "콜로간 + 왼팔/오른팔, 바위 쫄"
L["- Steingriff (rechter Arm): packt Spieler -> genug Schaden auf den rechten Arm, um sie zu befreien."] = "- 바위 손아귀 (오른팔): 플레이어를 붙잡음 -> 오른팔에 충분한 딜을 넣어 풀어주기."
L["- Fokussierter Augenstrahl: zwei Strahlen verfolgen ein Ziel -> Ziel läuft den Strahl vom Raid weg."] = "- 집중된 눈빛: 두 줄기 광선이 대상을 추적 -> 대상자는 광선을 공대 반대쪽으로 끌고 가기."
L["- Überkopfschlag / Rüstung zermalmen: starker Tankschaden, stapelnder Debuff -> Tankwechsel."] = "- 머리 위 강타 / 방어구 분쇄: 강한 탱커 피해, 중첩 디버프 -> 탱 교대."
L["- Geröll: Adds nach dem Tod eines Arms -> Offtank sammelt, AoE."] = "- 바위 덩어리: 팔이 죽은 후 나오는 쫄 -> 부탱이 모으고 광역."
L["- Versteinernder Atem: wenn kein Nahkämpfer in Reichweite ist -> Tank immer in Reichweite halten."] = "- 석화의 숨결: 근접 범위에 아무도 없을 때 -> 탱커는 항상 근접 범위 유지."
L["Taktik: Kologarn steht fest, Tank und Nahkampf vorne, Fernkampf verteilt auf den Treppen. Arme nach Plan töten (Steingriff-Befreiung hat Vorrang), Augenstrahl kiten."] = "공략: 콜로간은 고정, 탱커와 근딜은 앞에, 원딜은 계단에 산개. 팔은 계획대로 처치 (바위 손아귀 구출 우선), 눈빛은 카이팅."
L["KOLOGARN: Steingriff -> rechten Arm runter! Augenstrahl vom Raid weg!"] = "콜로간: 바위 손아귀 -> 오른팔 처치! 눈빛은 공대 반대쪽으로!"
L["Geröll per AoE. Tankwechsel bei Rüstung zermalmen."] = "바위 덩어리는 광역. 방어구 분쇄 시 탱 교대."
L["Mimiron"] = "미미론"
L["Mimiron: Leviathan Mk II, VX-001, Luftkommandoeinheit, V-07-TR-0N"] = "미미론: 리바이어선 Mk II, VX-001, 공중 지휘 장치, V-07-TR-0N"
L["- Phase 1 (Leviathan Mk II): Schockschlag -> Nahkampf sofort raus; Annäherungsminen meiden; Napalmgranate trifft Fernkampf -> verteilt stehen."] = "- 1단계 (리바이어선 Mk II): 충격파 -> 근딜 즉시 빠지기; 근접 지뢰 피하기; 네이팜 포탄이 원딜을 공격 -> 산개해서 서기."
L["- Phase 2 (VX-001): Laserbarrage dreht sich -> hinter den Boss bzw. aus dem Strahl; Raketenschlag -> raus aus der Einschlagmarkierung."] = "- 2단계 (VX-001): 회전하는 레이저 탄막 -> 보스 뒤로 또는 광선에서 나오기; 로켓 공격 -> 충돌 표시에서 나오기."
L["- Phase 3 (Luftkommandoeinheit): fliegt -> Fernkampf/Heiler; Angriffsbots lassen Magnetkern fallen -> nutzen, um die Einheit runterzuholen; Bombenbots töten."] = "- 3단계 (공중 지휘 장치): 비행 -> 원딜/힐러; 공격 로봇이 자석 핵을 떨어뜨림 -> 사용해서 장치를 끌어내리기; 폭탄 로봇 처치."
L["- Phase 4 (V-07-TR-0N): alle drei Teile wieder kombiniert -> alle Mechaniken gleichzeitig, Teile kurz nacheinander töten."] = "- 4단계 (V-07-TR-0N): 세 부품이 다시 합체 -> 모든 기술이 동시에, 부품은 짧은 간격으로 처치."
L["Taktik: Phasen nacheinander, Nahkampf achtet in P1 und P4 auf Schockschlag. In P4 alle drei Teile gleichmäßig runter und innerhalb weniger Sekunden töten."] = "공략: 단계를 차례로 진행, 근딜은 1단계와 4단계에서 충격파 주의. 4단계엔 세 부품을 균등하게 깎아 몇 초 안에 처치."
L["Hardmode: Großer Roter Knopf startet Selbstzerstörung mit Feuer im Raum und Zeitlimit."] = "하드 모드: 커다란 빨간 단추를 누르면 방 안에 불길과 시간 제한이 있는 자폭 시작."
L["MIMIRON: Schockschlag -> Nahkampf raus! Laser und Raketen ausweichen!"] = "미미론: 충격파 -> 근딜 빠지기! 레이저와 로켓 피하세요!"
L["P3 Magnetkern nutzen. P4 alle drei Teile gleichzeitig töten."] = "3단계 자석 핵 사용. 4단계 세 부품 동시 처치."
L["Klingenschuppe"] = "칼날비늘"
L["Klingenschuppe + Dunkelrunen-Adds (Wächter, Wachposten, Behüter)"] = "칼날비늘 + 검은룬 쫄 (수호병, 파수병, 감시병)"
L["- Luftphase: Zwerge bauen Harpunen -> Harpunen abschießen, um Klingenschuppe herunterzuholen."] = "- 공중 단계: 드워프가 작살포를 만듦 -> 작살을 쏴서 칼날비늘을 끌어내리기."
L["- Dunkelrunen-Adds: kommen aus den Höhlen -> Offtanks, Behüter/Wachposten zuerst töten."] = "- 검은룬 쫄: 동굴에서 나옴 -> 부탱, 감시병/파수병 먼저 처치."
L["- Verschlingende Flamme: Feuerkreise am Boden -> sofort raus."] = "- 집어삼키는 불길: 바닥의 화염 원 -> 즉시 나오기."
L["- Nach Harpunentreffer: Boss am Boden und betäubt -> volles Burst; Flammenatem beim Aufstehen -> nicht vorne."] = "- 작살 명중 후: 보스가 바닥에서 기절 -> 풀 버스트; 일어날 때 화염 숨결 -> 앞에 서지 않기."
L["- Bodenphase (50 %): Rüstung schmelzen stapelt auf dem Tank -> Tankwechsel."] = "- 지상 단계 (50 %): 방어구 녹이기가 탱커에게 중첩 -> 탱 교대."
L["Taktik: Adds abfangen, Zwerge schützen, Harpunen bedienen und am Boden alles auf den Boss. Ab 50 % bleibt sie unten: Tankwechsel und Flammen meiden."] = "공략: 쫄 잡고, 드워프 보호, 작살포 조작, 바닥에 있을 땐 전원 보스 딜. 50 %부터 내려와 있음: 탱 교대하고 불길 피하기."
L["KLINGENSCHUPPE: Harpunen abschießen, am Boden Burst! Flammen raus!"] = "칼날비늘: 작살 발사, 바닥에서 버스트! 불길에서 나오세요!"
L["Adds vom Offtank. Ab 50 % Tankwechsel bei Rüstung schmelzen."] = "쫄은 부탱. 50 %부터 방어구 녹이기 시 탱 교대."
L["Thorim"] = "토림"
L["Thorim + Arena-Adds, Runenkoloss, Uralter Runenriese"] = "토림 + 투기장 쫄, 룬 거인, 고대 룬 거인"
L["- Arena (Phase 1): Adds strömen in die Arena, Thorim wirft Blitze -> Adds töten, Kettenblitz-Flächen meiden."] = "- 투기장 (1단계): 쫄이 투기장으로 몰려들고, 토림이 번개를 던짐 -> 쫄 처치, 연쇄 번개 장판 피하기."
L["- Gang: Gang-Team kämpft sich zu Thorim -> Runenkoloss (Ansturm-Bahnen ausweichen) und Uralter Runenriese töten."] = "- 통로: 통로 팀이 토림까지 뚫고 감 -> 룬 거인 (돌진 경로 피하기)과 고대 룬 거인 처치."
L["- Blitzladung: aufgeladene Kugel in der Arena -> nicht in den Blitzbereich."] = "- 번개 충전: 투기장의 충전된 구슬 -> 번개 범위에 들어가지 않기."
L["- Phase 2: Thorim springt runter, Kegelblitz -> nicht vor ihm; Unausgeglichener Schlag -> Tankwechsel."] = "- 2단계: 토림이 뛰어내림, 부채꼴 번개 -> 앞에 서지 않기; 불안정한 일격 -> 탱 교대."
L["Taktik: Raid teilen: Gang-Team (Tank, Heiler, DPS) läuft durch den Gang, Rest hält die Arena. Wenn Thorim springt, alle auf ihn, Tankwechsel nach Schlag."] = "공략: 공대 분할: 통로 팀 (탱, 힐러, 딜러)은 통로를 지나고 나머지는 투기장 유지. 토림이 뛰어내리면 전원 점사, 일격 후 탱 교대."
L["Hardmode: Thorim innerhalb des Zeitfensters erreichen, dann kämpft Sif mit."] = "하드 모드: 제한 시간 안에 토림에게 도달하면 시프가 함께 싸움."
L["THORIM: Gang-Team los! Arena-Adds töten, Blitzfelder meiden!"] = "토림: 통로 팀 출발! 투기장 쫄 처치, 번개 장판 피하기!"
L["P2: Nicht vor den Boss, Tankwechsel."] = "2단계: 보스 앞에 서지 말고, 탱 교대."
L["XT-002 Dekonstruktor"] = "XT-002 해체자"
L["XT-002 Dekonstruktor + Schrottbots, Bumm-Bots, Hackbots"] = "XT-002 해체자 + 고철 로봇, 폭발 로봇, 파괴 로봇"
L["- Tympanischer Wutanfall: kanalisierter Raidschaden -> Raid hochheilen, Abklingzeiten."] = "- 고막 찢는 분노: 채널링 공대 피해 -> 공대 힐업, 생존기."
L["- Sengendes Licht / Gravitationsbombe: Debuffs auf Spielern -> Betroffene raus aus dem Raid."] = "- 타오르는 빛 / 중력 폭탄: 플레이어에게 디버프 -> 대상자는 공대 밖으로."
L["- Herzphase (75/50/25 %): Herz freigelegt -> voller Schaden auf das Herz."] = "- 심장 단계 (75/50/25 %): 심장 노출 -> 심장에 풀딜."
L["- Schrottbots: heilen XT -> töten, bevor sie ihn erreichen."] = "- 고철 로봇: XT를 치유 -> 도달하기 전에 처치."
L["- Bumm-Bots: explodieren -> nicht im Nahkampf töten."] = "- 폭발 로봇: 폭발함 -> 근접 범위에서 처치하지 않기."
L["Taktik: XT mittig tanken, Fernkampf verteilt. Bomben-Ziele rausgehen, Herzphase burst, Adds vor dem Erreichen töten."] = "공략: XT는 중앙에서 탱, 원딜 산개. 폭탄 대상자는 빠지기, 심장 단계 버스트, 쫄은 도달 전에 처치."
L["Hardmode: Herz töten -> XT voll geheilt und stärker."] = "하드 모드: 심장 처치 -> XT 완전 회복 및 강화."
L["XT-002: Bomben-Ziele raus aus dem Raid! Herzphase burst!"] = "XT-002: 폭탄 대상자는 공대 밖으로! 심장 단계 버스트!"
L["Schrottbots töten bevor sie heilen. Bumm-Bots weg vom Nahkampf."] = "고철 로봇은 치유 전에 처치. 폭발 로봇은 근딜에서 멀리."
L["Yogg-Saron"] = "요그사론"
L["Yogg-Saron + Sara, Wächter, Tentakel, Gehirn"] = "요그사론 + 사라, 수호자, 촉수, 두뇌"
L["- Phase 1 (Sara): Wächter von Yogg-Saron aus Wolken -> töten neben Sara (Schattennova schadet ihr)."] = "- 1단계 (사라): 구름에서 요그사론의 수호자 등장 -> 사라 옆에서 처치 (어둠 회오리가 사라에게 피해)."
L["- Phase 2: Tentakel (Würger, Verderber, Zermalmer) und Portale -> Portalgruppe ins Gehirn, Einfluss-Tentakel töten, Gehirn schaden."] = "- 2단계: 촉수 (조르는 촉수, 타락시키는 촉수, 분쇄 촉수)와 차원문 -> 차원문 그룹은 두뇌로, 영향력의 촉수 처치 후 두뇌 딜."
L["- Wahnsinn: Verstand sinkt -> Verstandsquelle (Freya) nutzen, unter 0 wird man gedankenkontrolliert."] = "- 광기: 정신력 감소 -> 정신력의 샘 (프레이야) 활용, 0 미만이 되면 정신 지배당함."
L["- Todesstrahl: wandert -> ausweichen."] = "- 죽음의 광선: 이동함 -> 피하기."
L["- Phase 3: Blick des Wahnsinns -> wegsehen; Unsterbliche Wächter -> töten."] = "- 3단계: 광기의 시선 -> 시선 돌리기; 불멸의 수호자 -> 처치."
L["Taktik: P1 Wächter zu Sara ziehen und dort töten, Wolken meiden. P2 feste Portalgruppe ins Gehirn, Rest tötet Tentakel; P3 bei Blick des Wahnsinns wegdrehen und alles auf Yogg."] = "공략: 1단계 수호자를 사라에게 끌고 가 처치, 구름 피하기. 2단계 고정 차원문 그룹이 두뇌로, 나머지는 촉수 처치; 3단계 광기의 시선 때 돌아서고 전원 요그 점사."
L["Hardmode: Je weniger Hüter (Freya, Hodir, Thorim, Mimiron) helfen, desto schwerer; ohne Hüter ist es die schwerste Variante."] = "하드 모드: 돕는 수호자 (프레이야, 호디르, 토림, 미미론)가 적을수록 어려움; 수호자 없이가 가장 어려운 난이도."
L["YOGG-SARON: Blick des Wahnsinns -> wegsehen! Verstand halten!"] = "요그사론: 광기의 시선 -> 시선 돌리세요! 정신력 유지!"
L["P2: Portalgruppe ins Gehirn, Würger-Tentakel sofort töten."] = "2단계: 차원문 그룹은 두뇌로, 조르는 촉수 즉시 처치."
L["Archavons Kammer"] = "아카본 석실"
L["Archavon der Steinwächter"] = "바위 감시인 아카본"
L["- Felssplitter: Steingeschosse auf Spieler -> Fernkampf verteilt, gezielt heilen."] = "- 바위 파편: 플레이어에게 돌 투사체 -> 원딜 산개, 대상자 힐."
L["- Zermalmender Sprung: springt auf einen Spieler und hinterlässt eine Erstickende Wolke -> sofort raus aus der Wolke."] = "- 분쇄 도약: 플레이어에게 도약해 질식의 구름을 남김 -> 즉시 구름에서 나오기."
L["- Stampfen + Pfählen: betäubt die Nähe, danach Pfählen auf den Tank -> zweiter Tank übernimmt sofort (Tankwechsel)."] = "- 발구르기 + 꿰뚫기: 근처 기절 후 탱커에게 꿰뚫기 -> 두 번째 탱커가 즉시 넘겨받기 (탱 교대)."
L["- Raserei nach 5 Minuten -> reiner Schadenscheck."] = "- 5분 후 광폭화 -> 순수 딜 체크."
L["Taktik: Zwei Tanks nebeneinander, Fernkampf verteilt. Nach Stampfen spottet der zweite Tank, Wolken meiden und vor der Raserei töten."] = "공략: 탱커 두 명 나란히, 원딜 산개. 발구르기 후 두 번째 탱커가 도발, 구름 피하고 광폭화 전에 처치."
L["ARCHAVON: Nach Pfählen sofort Tankwechsel! Raus aus den Wolken!"] = "아카본: 꿰뚫기 후 즉시 탱 교대! 구름에서 나오세요!"
L["Fernkampf verteilt. Raserei nach 5 Minuten."] = "원딜 산개. 5분 후 광폭화."
L["Emalon der Sturmwächter"] = "폭풍 감시인 에말론"
L["Emalon der Sturmwächter + 4 Sturmdiener"] = "폭풍 감시인 에말론 + 폭풍 하수인 4마리"
L["- Blitznova: großer Schaden im Nahbereich -> Nahkampf rechtzeitig raus."] = "- 번개 회오리: 근거리 큰 피해 -> 근딜은 제때 빠지기."
L["- Kettenblitz: springt zwischen Spielern -> verteilt stehen."] = "- 연쇄 번개: 플레이어 사이를 튐 -> 산개해서 서기."
L["- Überladung: ein Sturmdiener wird größer und explodiert nach kurzer Zeit -> sofort töten."] = "- 과충전: 폭풍 하수인 하나가 커지고 잠시 후 폭발 -> 즉시 처치."
L["- Sturmdiener werden neu belebt -> getrennt tanken, Boss ist das Hauptziel."] = "- 폭풍 하수인은 다시 살아남 -> 따로 탱, 보스가 주 대상."
L["Taktik: Boss und Diener getrennt tanken, Raid verteilt. Überladenen Diener sofort töten, sonst Schaden auf Emalon."] = "공략: 보스와 하수인은 따로 탱, 공대 산개. 과충전된 하수인은 즉시 처치, 그 외엔 에말론 딜."
L["EMALON: Überladenen Diener sofort töten! Blitznova -> Nahkampf raus!"] = "에말론: 과충전된 하수인 즉시 처치! 번개 회오리 -> 근딜 빠지기!"
L["Kettenblitz: verteilt stehen."] = "연쇄 번개: 산개해서 서기."
L["Emalon"] = "에말론"
L["Die vier Sturmdiener markieren, damit der überladene schnell angesagt werden kann."] = "폭풍 하수인 네 마리에 징표, 과충전된 하수인을 빠르게 콜할 수 있게."
L["Koralon der Flammenwächter"] = "화염 감시인 코랄론"
L["- Meteorfäuste: Schläge werden auf nahe Ziele verteilt -> zwei Tanks nebeneinander, teilen."] = "- 유성 주먹: 타격이 가까운 대상들에게 분산 -> 탱커 두 명이 나란히 나눠 맞기."
L["- Flammende Glut: Feuerflächen am Boden -> raus."] = "- 타오르는 불씨: 바닥의 화염 장판 -> 나오기."
L["- Brennender Atem: Kegel nach vorne -> Raid nicht vor den Boss."] = "- 불타는 숨결: 앞쪽 부채꼴 -> 공대는 보스 앞에 서지 않기."
L["- Brennende Wut: stapelnder Raidschaden -> Heiler steigern die Heilung, Kampf schnell beenden."] = "- 불타는 분노: 중첩되는 공대 피해 -> 힐러는 힐량 올리고, 빠르게 전투 끝내기."
L["Taktik: Zwei Tanks teilen die Meteorfäuste, Raid hinter dem Boss verteilt, Feuer meiden."] = "공략: 탱커 두 명이 유성 주먹을 나눠 맞고, 공대는 보스 뒤에 산개, 불 피하기."
L["KORALON: Tanks teilen Meteorfäuste! Aus dem Feuer raus!"] = "코랄론: 탱커는 유성 주먹 나눠 맞기! 불에서 나오세요!"
L["Nicht vor den Boss. Brennende Wut stapelt -> zügig töten."] = "보스 앞에 서지 않기. 불타는 분노 중첩 -> 빠르게 처치."
L["Toravon der Eiswächter"] = "얼음 감시인 토라본"
L["Toravon der Eiswächter + Gefrorene Kugeln"] = "얼음 감시인 토라본 + 얼어붙은 구슬"
L["- Gefrorene Kugel: Adds mit Frostschaden -> Offtank sammelt, Fernkampf tötet sie."] = "- 얼어붙은 구슬: 냉기 피해를 주는 쫄 -> 부탱이 모으고 원딜이 처치."
L["- Gefrierender Boden: Eisflächen -> sofort raus."] = "- 얼어붙는 땅: 얼음 장판 -> 즉시 나오기."
L["- Erfrierung: stapelt auf dem Tank -> Tankwechsel."] = "- 동상: 탱커에게 중첩 -> 탱 교대."
L["- Weißwerden: stapelnder Raidschaden -> Heiler stark fordern, zügig töten."] = "- 백색화: 중첩되는 공대 피해 -> 힐러 부담 큼, 빠르게 처치."
L["Taktik: Zwei Tanks im Wechsel, Kugeln sammeln und töten, Eisflächen meiden."] = "공략: 탱커 두 명이 번갈아 탱, 구슬은 모아서 처치, 얼음 장판 피하기."
L["TORAVON: Gefrorene Kugeln töten! Tankwechsel bei Erfrierung!"] = "토라본: 얼어붙은 구슬 처치! 동상 시 탱 교대!"
L["Gefrierender Boden: sofort raus."] = "얼어붙는 땅: 즉시 나오기."
L["Baradinfestung"] = "바라딘 요새"
L["Argaloth"] = "아갈로스"
L["- Meteorschlag: frontaler Schaden, wird auf alle Spieler vor dem Boss aufgeteilt; Debuff erhöht den nächsten Treffer -> zwei Gruppen abwechselnd vor den Boss stellen, Tankwechsel."] = "- 유성 강타: 정면 피해, 보스 앞의 모든 플레이어에게 분산; 디버프가 다음 피격 피해 증가 -> 두 그룹이 번갈아 보스 앞에 서기, 탱 교대."
L["- Verzehrende Dunkelheit: starker Schattenschaden über Zeit auf mehreren Spielern -> Heiler gezielt gegenheilen."] = "- 집어삼키는 어둠: 여러 플레이어에게 강한 암흑 지속 피해 -> 힐러가 집중 힐."
L["- Teuflischer Feuersturm (bei 66 % und 33 %): Feuerflächen am Boden -> sofort rauslaufen, Raid wird stark beschädigt."] = "- 지옥의 화염폭풍 (66 %와 33 %): 바닥의 화염 장판 -> 즉시 빠져나오기, 공대 피해 큼."
L["Taktik: Zwei Gruppen teilen sich abwechselnd den Meteorschlag, Tanks wechseln mit. Bei den Feuerstürmen bewegen und Heil-Cooldowns nutzen."] = "공략: 두 그룹이 번갈아 유성 강타를 나눠 맞고, 탱커도 함께 교대. 화염폭풍 때 움직이며 힐 쿨기 사용."
L["ARGALOTH: Meteorschlag in zwei Gruppen abwechselnd teilen!"] = "아갈로스: 유성 강타는 두 그룹이 번갈아 나눠 맞기!"
L["Feuersturm bei 66/33 %: aus dem Feuer laufen, Heil-CDs."] = "66/33 % 화염폭풍: 불에서 빠져나오기, 힐 쿨기."
L["Occu'thar + Augen von Occu'thar"] = "오쿠타르 + 오쿠타르의 눈"
L["- Sengende Schatten: starker Frontalschaden auf den Tank mit Debuff -> Tankwechsel."] = "- 이글거리는 어둠: 탱커에게 강한 정면 피해와 디버프 -> 탱 교대."
L["- Fokussiertes Feuer: Feuerfläche unter einem Spieler -> sofort rauslaufen."] = "- 집중된 화염: 플레이어 발밑에 화염 장판 -> 즉시 빠져나오기."
L["- Augen von Occu'thar: auf jedem Spieler erscheint ein Auge, das kanalisiert und explodiert -> zusammenstehen und die Augen schnell mit Flächenschaden töten."] = "- 오쿠타르의 눈: 모든 플레이어에게 눈이 나타나 채널링 후 폭발 -> 뭉쳐 서서 광역으로 눈을 빠르게 처치."
L["Taktik: Raid steht eng zusammen für Flächenschaden auf die Augen, Tanks wechseln bei Sengende Schatten."] = "공략: 눈에 광역을 넣기 위해 공대는 바짝 뭉치고, 이글거리는 어둠 때 탱 교대."
L["OCCU'THAR: Augen sofort mit AoE töten! Zusammen stehen."] = "오쿠타르: 눈은 즉시 광역으로 처치! 뭉쳐 서기."
L["Feuer am Boden meiden, Tankwechsel bei Sengende Schatten."] = "바닥 불 피하기, 이글거리는 어둠 시 탱 교대."
L["Alizabal, Herrin des Hasses"] = "증오의 여군주 알리자발"
L["- Aufspießen: Tank wird aufgespießt und erhält mehr Schaden durch Brodelnder Hass -> Tankwechsel."] = "- 꿰뚫기: 탱커가 꿰뚫리고 들끓는 증오로 받는 피해 증가 -> 탱 교대."
L["- Brodelnder Hass: Schaden auf ein Ziel, aufgeteilt auf alle in der Nähe -> Raid stellt sich zum Ziel dazu."] = "- 들끓는 증오: 한 대상에게 피해, 근처 모두에게 분산 -> 공대가 대상에게 모이기."
L["- Klingentanz: Alizabal wirbelt und springt zu zufälligen Spielern -> verteilen und vom Wirbel weglaufen."] = "- 칼날 춤: 알리자발이 회전하며 무작위 플레이어에게 도약 -> 산개하고 회전에서 도망가기."
L["Taktik: Normalphase: zusammen stehen für Brodelnder Hass. Klingentanz: verteilt im Raum stehen und ausweichen."] = "공략: 일반 단계: 들끓는 증오 대비 뭉쳐 서기. 칼날 춤: 방 안에 산개하고 피하기."
L["ALIZABAL: Brodelnder Hass gemeinsam teilen, Klingentanz verteilen!"] = "알리자발: 들끓는 증오 함께 나눠 맞고, 칼날 춤 때 산개!"
L["Tankwechsel bei Aufspießen."] = "꿰뚫기 시 탱 교대."
L["Die Bastion des Zwielichts"] = "황혼의 요새"
L["Rat der Aszendenten (Feludius, Ignacious, Arion, Terrastra, Elementiummonstrosität)"] = "승천 의회 (펠루디우스, 이그나시우스, 아리온, 테라스트라, 엘레멘티움 괴물)"
L["- Phase 1 Feludius/Ignacious: Hydrolanze und Aufsteigende Flammen unterbrechen; Durchnässt (Wasser) löscht Feuer-Debuffs, Gefroren-Spieler befreien."] = "- 1단계 펠루디우스/이그나시우스: 물의 창과 상승하는 불길 차단; 흠뻑 젖음 (물)은 화염 디버프를 지움, 얼어붙은 플레이어 풀어주기."
L["- Phase 2 Arion/Terrastra: Blitzableiter -> vom Raid weglaufen; vor Beben den Geerdet-Buff holen, vor Donnerschock den Wirbelwind-Buff."] = "- 2단계 아리온/테라스트라: 피뢰침 -> 공대에서 멀리 도망; 지진 전에 접지 버프 받기, 천둥 충격 전에 회오리바람 버프 받기."
L["- Feuer- und Gravitationsbrunnen am Boden: nicht hineinlaufen."] = "- 바닥의 화염 및 중력 웅덩이: 들어가지 않기."
L["- Phase 3 Elementiummonstrosität: Flüssiges Eis wächst unter dem Boss -> Tank kitet ihn am Raumrand im Kreis, Raid verteilt gegen Elektrische Instabilität."] = "- 3단계 엘레멘티움 괴물: 보스 아래에 액체 얼음이 퍼짐 -> 탱커가 방 가장자리를 따라 원형 카이팅, 공대는 전기 불안정 대비 산개."
L["Taktik: Phase 1+2 die Bosse getrennt tanken und Unterbrecher fest einteilen; Leben gleichmäßig senken (Phase 3 startet mit gemeinsamem Leben). Phase 3 kiten und burnen."] = "공략: 1+2단계 보스는 따로 탱하고 차단자 고정 배정; 생명력은 균등하게 깎기 (3단계는 공유 생명력으로 시작). 3단계 카이팅하며 녹이기."
L["RAT: Unterbrechen! Blitzableiter raus, Buffs vor Beben/Donnerschock holen!"] = "의회: 차단! 피뢰침 빠지기, 지진/천둥 충격 전 버프 받기!"
L["Phase 3: Eis kiten, verteilen, burnen."] = "3단계: 얼음 카이팅, 산개, 녹이기."
L["Rat der Aszendenten"] = "승천 의회"
L["Totenkopf und Kreuz auf die zwei aktiven Ratsmitglieder je Phase (Unterbrecher fest zuordnen)."] = "단계마다 활성화된 의회원 두 명에 해골과 가위표 (차단자 고정 배정)."
L["Cho'gall + Anhänger und Elementare"] = "초갈 + 추종자와 정령"
L["- Zorn von Cho'gall: stapelnder Debuff auf dem Tank -> Tankwechsel."] = "- 초갈의 분노: 탱커에게 중첩 디버프 -> 탱 교대."
L["- Bekehrung: Spieler werden zu Anbetern -> sie kurz kontrollieren oder wegschlagen, bis sie frei sind."] = "- 개종: 플레이어가 숭배자가 됨 -> 풀릴 때까지 잠시 CC하거나 때려서 깨우기."
L["- Verderbte Anhänger: verbreiten Verderbnis, Verderbtheit unterbrechen -> Anhänger sofort töten."] = "- 타락한 추종자: 타락을 퍼뜨림, 타락 시전 차단 -> 추종자 즉시 처치."
L["- Verderbnis-Leiste: steigt durch Fähigkeiten; hohe Verderbnis schwächt Spieler stark -> Flächen meiden, Verderbnis niedrig halten."] = "- 타락 게이지: 기술로 상승; 높은 타락은 플레이어를 크게 약화 -> 장판 피하고 타락 낮게 유지."
L["- Phase 2 (25 %): Tentakel der Verderbnis erscheinen -> schnell töten, Raidschaden steigt stark."] = "- 2단계 (25 %): 타락의 촉수 등장 -> 빠르게 처치, 공대 피해 크게 증가."
L["Taktik: Anhänger und Elementare haben Priorität, Tanks wechseln. Ab 25 % alle Cooldowns und schnell burnen."] = "공략: 추종자와 정령이 우선, 탱커 교대. 25 %부터 모든 쿨기 쓰고 빠르게 녹이기."
L["CHO'GALL: Anhänger zuerst töten und unterbrechen!"] = "초갈: 추종자 먼저 처치하고 차단!"
L["Bekehrte Spieler kontrollieren. Ab 25 %: Tentakel weg, Burn!"] = "개종된 플레이어 CC. 25 %부터: 촉수 처리, 녹이기!"
L["Cho'gall"] = "초갈"
L["Totenkopf und Kreuz auf die Verderbten Anhänger, Unterbrecher fest einteilen."] = "타락한 추종자에 해골과 가위표, 차단자 고정 배정."
L["Halfus Wyrmbrecher + Proto-Behemoth und Drachen"] = "할푸스 웜브레이커 + 원시 거수와 용"
L["- Bösartige Schläge: stapelnder Heilungs-Verringerungs-Debuff auf dem Tank -> Tankwechsel."] = "- 사악한 강타: 탱커에게 치유 감소 디버프 중첩 -> 탱 교대."
L["- Wütendes Gebrüll: Raidschaden in Serie -> Halfus mit den Fähigkeiten befreiter Drachen stoppen bzw. Heil-CDs."] = "- 분노의 포효: 연속 공대 피해 -> 풀려난 용의 능력으로 할푸스 저지 또는 힐 쿨기."
L["- Proto-Behemoth: Feuerbälle bzw. Sengendes Feuer auf den Raid -> verteilen."] = "- 원시 거수: 공대에 화염구 또는 이글거리는 화염 -> 산개."
L["- Drachen: jeder befreite Drache gibt Halfus einen Effekt, jeder getötete Drache schwächt ihn -> Drachen nacheinander befreien und töten."] = "- 용: 풀려난 용마다 할푸스에게 효과를 주고, 처치한 용마다 할푸스 약화 -> 용을 하나씩 풀어주고 처치."
L["Taktik: Drachen in fester Reihenfolge freilassen und töten (die aktiven Drachen wechseln wöchentlich), dann Halfus. Tanks wechseln regelmäßig."] = "공략: 정해진 순서로 용을 풀어주고 처치 (활성화된 용은 매주 바뀜), 그다음 할푸스. 탱커는 주기적으로 교대."
L["HALFUS: Drachen nacheinander befreien und töten, dann Halfus!"] = "할푸스: 용을 하나씩 풀어주고 처치, 그다음 할푸스!"
L["Tankwechsel bei Bösartige Schläge, verteilen gegen Feuerbälle."] = "사악한 강타 시 탱 교대, 화염구 대비 산개."
L["Halfus"] = "할푸스"
L["Totenkopf, Kreuz, Viereck auf die Drachen in Tötungsreihenfolge."] = "처치 순서대로 용에 해골, 가위표, 네모."
L["Sinestra + Welpen und Zwielichtadds (nur Heroisch)"] = "시네스트라 + 새끼용과 황혼 쫄 (영웅 전용)"
L["- Peinigen: Debuff wird stärker und springt beim Bannen auf zwei Spieler über -> kontrolliert und fest eingeteilt bannen."] = "- 파멸: 디버프가 점점 강해지고 해제 시 두 플레이어에게 옮겨감 -> 통제하며 고정 배정으로 해제."
L["- Flammenatem: Raidschaden -> Heil-Cooldowns."] = "- 화염 숨결: 공대 피해 -> 힐 쿨기."
L["- Zwielichtwelpen: töten; ihre Essenz erhöht den eigenen Schaden."] = "- 황혼의 새끼용: 처치; 정수가 자신의 피해량을 증가."
L["- Phase 2: Sinestra wird immun, Zwielichtpanzer-Eier müssen fallen, während Calen den Strahl hält -> Spitecaller-Adds abfangen, Eier zerstören."] = "- 2단계: 시네스트라 무적, 칼렌이 광선을 유지하는 동안 황혼 껍질 알을 깨야 함 -> 원한의 소환사 쫄 잡고, 알 파괴."
L["Taktik: Start bei 60 %. Phase 1 bis 30 % Welpen kontrolliert töten, Phase 2 Eier zerstören und Calen unterstützen, dann Sinestra burnen."] = "공략: 60 %에서 시작. 1단계 30 %까지 새끼용 통제하며 처치, 2단계 알 파괴하고 칼렌 지원, 그 후 시네스트라 녹이기."
L["Nur im heroischen Modus verfügbar."] = "영웅 난이도에서만 가능."
L["SINESTRA: Peinigen nur nach Plan bannen! Welpen töten."] = "시네스트라: 파멸은 계획대로만 해제! 새끼용 처치."
L["Phase 2: Eier zerstören, Adds abfangen, Calen schützen."] = "2단계: 알 파괴, 쫄 잡고, 칼렌 보호."
L["Sinestra"] = "시네스트라"
L["Totenkopf und Kreuz auf die beiden Zwielichteier in Phase 2."] = "2단계 황혼 알 두 개에 해골과 가위표."
L["Valiona und Theralion"] = "발리오나와 테랄리온"
L["- Blackout (Valiona): Debuff auf einem Spieler, Schaden wird aufgeteilt -> alle zusammenstellen, nicht bannen."] = "- 암흑 (발리오나): 플레이어 한 명에게 디버프, 피해 분산 -> 전원 함께 서기, 해제 금지."
L["- Verschlingende Flammen (Valiona): Kegel-Feuerschaden -> aus dem Kegel hinter den Boss laufen."] = "- 집어삼키는 불길 (발리오나): 부채꼴 화염 피해 -> 부채꼴에서 보스 뒤로 이동."
L["- Einhüllende Magie (Theralion): Spieler schadet Verbündeten in der Nähe -> sofort aus dem Raid laufen."] = "- 감싸는 마법 (테랄리온): 플레이어가 근처 아군에게 피해 -> 즉시 공대 밖으로."
L["- Tiefer Atem / Zwielichtmeteore in der Flugphase: Bahnen der Drachen meiden, Meteor gemeinsam teilen bzw. verteilen."] = "- 비행 단계의 깊은 숨결 / 황혼의 유성: 용의 경로 피하기, 유성은 함께 나눠 맞거나 산개."
L["Taktik: Immer ein Drache am Boden, einer in der Luft; Boden-Drachen tanken und Fokus darauf, Leben beider gleichmäßig senken."] = "공략: 항상 용 하나는 바닥, 하나는 공중; 바닥의 용을 탱하고 점사, 두 용의 생명력을 균등하게 깎기."
L["VALIONA & THERALION: Blackout zusammen stehen, Einhüllende Magie raus!"] = "발리오나와 테랄리온: 암흑 때 뭉치기, 감싸는 마법은 빠지기!"
L["Kegel hinter dem Boss meiden, Atem-Bahnen ausweichen."] = "보스 뒤 부채꼴 피하기, 숨결 경로 피하기."
L["Pechschwingenabstieg"] = "검은날개 강림지"
L["Atramedes"] = "아트라메데스"
L["- Schall-Leiste: jeder Laut erhöht die Leiste, bei 100 % Tod -> Schallwellen und Schallpulse meiden."] = "- 소리 게이지: 소리가 날 때마다 게이지 증가, 100 %면 사망 -> 음파와 음파 진동 피하기."
L["- Sengende Flamme: Raidschaden -> mit dem Gong (Antikes Zwergenschild) unterbrechen."] = "- 이글거리는 불길: 공대 피해 -> 징 (고대 드워프 방패)으로 차단."
L["- Modulation: Raidschaden und Schall -> gegenheilen."] = "- 변조: 공대 피해와 소리 -> 힐로 대응."
L["- Flugphase: Brüllender Flammenatem verfolgt einen Spieler -> wegkiten oder per Gong befreien; Schallringe meiden."] = "- 비행 단계: 포효하는 화염 숨결이 플레이어 한 명을 추적 -> 카이팅하거나 징으로 해제; 음파 고리 피하기."
L["Taktik: Boden: Boss ruhig tanken, Schall meiden. Flugphase: verfolgter Spieler kitet, bei Bedarf Gong schlagen. Gongs sparsam einsetzen."] = "공략: 지상: 보스는 가만히 탱, 소리 피하기. 비행 단계: 추적 대상자는 카이팅, 필요 시 징 치기. 징은 아껴 쓰기."
L["ATRAMEDES: Schall meiden! Gong gegen Sengende Flamme nutzen."] = "아트라메데스: 소리 피하기! 이글거리는 불길엔 징 사용."
L["Flugphase: Verfolgter kitet den Atem, alle anderen verteilen."] = "비행 단계: 추적 대상자는 숨결 카이팅, 나머지는 산개."
L["Schimaeron + Bilotron 800"] = "키마이론 + 빌로트론 800"
L["- Massaker: tödlicher Schaden auf alle; Finkles Mixtur lässt Spieler über 10.000 HP mit 1 HP überleben -> alle vorher und danach hochheilen."] = "- 대학살: 모두에게 치명적인 피해; 핀클의 혼합물로 10,000 HP 이상인 플레이어는 1 HP로 생존 -> 전후로 전원 힐업."
L["- Ätzender Schleim: Schaden wird aufgeteilt -> in Gruppen zusammenstehen."] = "- 부식성 점액: 피해 분산 -> 그룹별로 뭉쳐 서기."
L["- Doppelangriff/Zerschmettern: stapelnder Debuff auf dem Tank -> Tankwechsel."] = "- 이중 공격/분쇄: 탱커에게 중첩 디버프 -> 탱 교대."
L["- Fehde: kurz keine Heilung -> vorher volles Leben."] = "- 반목: 잠시 동안 치유 불가 -> 미리 풀피."
L["- Sterblichkeit (20 %): Heilung unmöglich -> nur noch burnen."] = "- 필멸 (20 %): 치유 불가 -> 녹이기만."
L["Taktik: Raid in feste Gruppen aufteilen, nach jedem Massaker sofort hochheilen. Ab 20 % alle Cooldowns und burnen."] = "공략: 공대를 고정 그룹으로 나누고, 대학살 후 즉시 힐업. 20 %부터 모든 쿨기 쓰고 녹이기."
L["SCHIMAERON: Alle über 10k HP halten! Gruppen gegen Schleim!"] = "키마이론: 전원 10k HP 이상 유지! 점액 대비 그룹 뭉치기!"
L["Tankwechsel. Ab 20 %: keine Heilung mehr – BURN!"] = "탱 교대. 20 %부터: 힐 불가 – 녹이세요!"
L["Omnotron-Verteidigungssystem (Arkanotron, Elektron, Magmatron, Toxitron)"] = "전자골렘 방어 시스템 (비전골렘, 전기골렘, 용암골렘, 독골렘)"
L["- Arkanotron: Kraftumwandlung und Arkane Vernichtung -> unterbrechen."] = "- 비전골렘: 마력 변환과 비전 소멸 -> 차단."
L["- Elektron: Blitzableiter -> vom Raid weglaufen."] = "- 전기골렘: 피뢰침 -> 공대에서 멀리 도망."
L["- Magmatron: Zielerfassung/Flammenwerfer auf einen Spieler -> verteilen; während der Barriere keinen Schaden machen."] = "- 용암골렘: 대상 획득/화염방사기가 플레이어 한 명에게 -> 산개; 방벽 중에는 딜 금지."
L["- Toxitron: Chemische Wolke und Giftbomben-Schleime -> Schleime kiten/töten, Wolke beachten."] = "- 독골렘: 화학 구름과 독폭탄 점액 -> 점액 카이팅/처치, 구름 주의."
L["Taktik: Immer zwei Golems aktiv, der Schild wechselt. Je ein Tank pro aktivem Golem, Unterbrecher für Arkanotron, Schaden auf die aktiven Golems."] = "공략: 항상 골렘 두 개가 활성화, 보호막은 교대로 바뀜. 활성 골렘마다 탱커 한 명, 비전골렘 차단자 배정, 활성 골렘에 딜."
L["OMNOTRON: Arkanotron unterbrechen! Blitzableiter raus!"] = "전자골렘: 비전골렘 차단! 피뢰침 빠지기!"
L["Magmatron-Barriere nicht angreifen. Schleime kiten."] = "용암골렘 방벽 공격 금지. 점액 카이팅."
L["Magmaul + Lavaparasiten"] = "용암아귀 + 용암 기생충"
L["- Magmaspucke/Lavaspucke: Raidschaden -> Heil-CDs bei Lavaspucke."] = "- 용암 침/용암 뱉기: 공대 피해 -> 용암 뱉기 때 힐 쿨기."
L["- Flammensäule: Lavaparasiten schlüpfen -> töten, nicht befallen lassen."] = "- 화염 기둥: 용암 기생충 부화 -> 처치, 감염되지 않게."
L["- Zermalmen: Tank wird gepackt und stark beschädigt -> Heiler fokussieren, danach Massaker meiden."] = "- 집어삼키기: 탱커가 붙잡혀 큰 피해 -> 힐러 집중, 이후 학살 피하기."
L["- Aufspießen: nach Zermalmen springt ein Spieler auf die Zange und kettet den Kopf an -> Kopf ist freigelegt, Schadensfenster."] = "- 꿰뚫기: 집어삼키기 후 플레이어 한 명이 집게 위로 뛰어올라 머리를 사슬로 묶음 -> 머리 노출, 딜 타이밍."
L["Taktik: Tank vor dem Boss, Raid verteilt, Parasiten schnell töten. Nach jedem Zermalmen den Kopf anketten lassen und dann mit allem Schaden auf den Kopf."] = "공략: 탱커는 보스 앞, 공대 산개, 기생충 빠르게 처치. 집어삼키기 후마다 머리를 묶고 머리에 전원 딜."
L["MAGMAUL: Parasiten töten! Nach Zermalmen Kopf anketten!"] = "용암아귀: 기생충 처치! 집어삼키기 후 머리 묶기!"
L["Kopf freigelegt = volle Burst-CDs auf den Kopf."] = "머리 노출 = 머리에 버스트 쿨기 전부."
L["Maloriak + Aberrationen"] = "말로리악 + 돌연변이"
L["- Rote Phiole: Versengende Explosion (Kegel) und Verzehrende Flammen -> Raid steht zusammen, Kegel vom Raid weg."] = "- 붉은 약병: 이글거리는 폭발 (부채꼴)과 집어삼키는 불길 -> 공대 뭉치기, 부채꼴은 공대 반대쪽으로."
L["- Blaue Phiole: Beißende Kälte und Blitzgefrieren -> eingefrorene Spieler befreien, verteilen."] = "- 푸른 약병: 살을 에는 추위와 순간 빙결 -> 얼어붙은 플레이어 풀어주기, 산개."
L["- Grüne Phiole: Schwächender Schleim -> Schadensfenster, Aberrationen von Tank aufnehmen."] = "- 녹색 약병: 약화의 점액 -> 딜 타이밍, 돌연변이는 탱커가 잡기."
L["- Arkaner Sturm und Aberrationen freilassen: unterbrechen; Heilmittel vom Boss reinigen/stehlen."] = "- 비전 폭풍과 돌연변이 방출: 차단; 보스의 치료제는 정화/훔치기."
L["- Phase 2 (20 %): Urerschaffungen, Magmastrahlen, Absoluter Null -> burnen."] = "- 2단계 (20 %): 태고의 창조물, 용암 분출, 절대 영도 -> 녹이기."
L["Taktik: Unterbrecher fest einteilen, Aberrationen gezielt freilassen und mit Flächenschaden töten. Ab 20 % Cooldowns und Boss burnen."] = "공략: 차단자 고정 배정, 돌연변이는 계획적으로 풀어주고 광역으로 처치. 20 %부터 쿨기 쓰고 보스 녹이기."
L["MALORIAK: Arkaner Sturm und Aberrationen unterbrechen!"] = "말로리악: 비전 폭풍과 돌연변이 방출 차단!"
L["Phiolen beachten: Rot zusammen, Blau verteilen. 20 % Burn!"] = "약병 주의: 빨강은 뭉치기, 파랑은 산개. 20 % 녹이기!"
L["Maloriak"] = "말로리악"
L["Totenkopf, Kreuz, Viereck markieren die Unterbrecher-Reihenfolge am Boss."] = "해골, 가위표, 네모로 보스 차단 순서 표시."
L["Nefarian + Onyxia + Belebte Knochenkrieger"] = "네파리안 + 오닉시아 + 되살아난 뼈 전사"
L["- Phase 1: Onyxia lädt Elektrische Überladung auf -> Onyxia zuerst töten; Nefarians Elektrisieren bei jeden 10 % Leben."] = "- 1단계: 오닉시아가 전기 과부하를 충전 -> 오닉시아 먼저 처치; 네파리안의 감전은 생명력 10 %마다."
L["- Belebte Knochenkrieger: von Schattenflammenfunken wiederbelebt -> kiten, kontrollieren oder weiter tanken."] = "- 되살아난 뼈 전사: 암흑불꽃 불씨로 부활 -> 카이팅, CC 또는 계속 탱."
L["- Phase 2: Lava steigt -> auf die Säulen, Chromatische Prototypen (Druckwellennova) unterbrechen und töten."] = "- 2단계: 용암이 차오름 -> 기둥 위로, 오색 원형체 (폭발 회오리) 차단 후 처치."
L["- Phase 3: Schattenflammensperrfeuer und Knochenkrieger -> verteilen, Adds wegkiten, Boss burnen."] = "- 3단계: 암흑불꽃 탄막과 뼈 전사 -> 산개, 쫄 카이팅, 보스 녹이기."
L["Taktik: P1 Onyxia und Nefarian getrennt tanken, Onyxia zuerst. P2 drei Gruppen auf den Säulen gegen die Prototypen. P3 Adds kiten, Nefarian töten."] = "공략: 1단계 오닉시아와 네파리안 따로 탱, 오닉시아 먼저. 2단계 세 그룹이 기둥 위에서 원형체 처리. 3단계 쫄 카이팅, 네파리안 처치."
L["NEFARIAN: Onyxia zuerst! Phase 2 auf die Säulen!"] = "네파리안: 오닉시아 먼저! 2단계 기둥 위로!"
L["Prototypen unterbrechen. Phase 3: Knochenkrieger kiten, burnen."] = "원형체 차단. 3단계: 뼈 전사 카이팅, 녹이기."
L["Nefarian"] = "네파리안"
L["Ein Symbol je Chromatischer Prototyp auf den Säulen (Unterbrecher-Gruppen)."] = "기둥 위 오색 원형체마다 징표 하나 (차단 그룹)."
L["Drachenseele"] = "용의 영혼"
L["Kriegsmeister Schwarzhorn + Goriona + Zwielichtdrachen"] = "전투대장 블랙혼 + 고리오나 + 황혼의 용"
L["- Zwielichtsperrfeuer: Geschosse auf das Schiff -> Spieler fangen sie ab, sonst nimmt das Schiff Schaden."] = "- 황혼의 탄막: 비행선에 떨어지는 투사체 -> 플레이어가 받아내기, 아니면 비행선이 피해를 받음."
L["- Zwielichtangriff: große Einschlagzone -> mit mehreren Spielern hineinstellen, um den Schaden zu teilen."] = "- 황혼의 맹공: 큰 충돌 지역 -> 여러 명이 들어가 피해 분산."
L["- Pioniere: springen aufs Deck und explodieren -> abfangen, verlangsamen und töten."] = "- 공병: 갑판에 뛰어내려 폭발 -> 잡아서 감속 후 처치."
L["- Phase 2: Verwüsten (Tankwechsel), Schockwelle frontal -> nicht vor dem Boss stehen."] = "- 2단계: 파멸 (탱 교대), 정면 충격파 -> 보스 앞에 서지 않기."
L["Taktik: Phase 1: Drachen per Harpune runterholen und töten, Sperrfeuer abfangen. Phase 2: Schwarzhorn tanken, Goriona aufhalten, burnen."] = "공략: 1단계: 작살로 용을 끌어내려 처치, 탄막 받아내기. 2단계: 블랙혼 탱, 고리오나 저지, 녹이기."
L["SCHWARZHORN: Sperrfeuer abfangen! Pioniere sofort töten!"] = "블랙혼: 탄막 받아내기! 공병 즉시 처치!"
L["Phase 2: Tankwechsel bei Verwüsten, Schockwelle meiden."] = "2단계: 파멸 시 탱 교대, 충격파 피하기."
L["Schwarzhorn"] = "블랙혼"
L["Totenkopf und Kreuz auf die Zwielicht-Angriffsdrachen bzw. Pioniere."] = "황혼의 맹공 용 또는 공병에 해골과 가위표."
L["Hagara die Sturmbinderin"] = "폭풍결속사 하가라"
L["- Eislanze: Strahlen von Eiskugeln -> zugewiesene Spieler stellen sich in die Strahlen."] = "- 얼음 창: 얼음 구슬에서 나오는 광선 -> 배정된 플레이어가 광선 안에 서기."
L["- Eisgrab: Spieler werden eingefroren -> Gräber schnell zerschlagen."] = "- 얼음 무덤: 플레이어가 얼어붙음 -> 무덤을 빠르게 깨기."
L["- Konzentrierter Angriff: schnelle frontale Angriffe -> nur der Tank steht vor dem Boss."] = "- 집중 공격: 빠른 정면 공격 -> 탱커만 보스 앞에 서기."
L["- Frostphase: Eiswände rotieren -> ausweichen und die vier Gefrorenen Bindungskristalle zerstören."] = "- 서리 단계: 얼음벽이 회전 -> 피하면서 얼어붙은 결속 수정 네 개 파괴."
L["- Blitzphase: Blitzleiter-Kette zu den vier Leitkristallen aufbauen -> danach Rückkopplung = Schadensfenster."] = "- 번개 단계: 네 개의 전도 수정까지 번개 전도 사슬 만들기 -> 이후 역류 = 딜 타이밍."
L["Taktik: Normalphase Eislanze soaken und Gräber brechen. In den Spezialphasen Kristalle aktivieren/zerstören, dann während Rückkopplung burnen."] = "공략: 일반 단계엔 얼음 창 받아내고 무덤 깨기. 특수 단계엔 수정 활성화/파괴, 그 후 역류 동안 녹이기."
L["HAGARA: Eislanzen soaken! Eisgräber zerschlagen!"] = "하가라: 얼음 창 받아내기! 얼음 무덤 깨세요!"
L["Frostphase: Wände meiden, Kristalle. Blitzphase: Kette bilden."] = "서리 단계: 벽 피하고 수정. 번개 단계: 사슬 만들기."
L["Wahnsinn von Todesschwinge + Gliedmaßen"] = "데스윙의 광기 + 사지"
L["- Gliedmaßen: an jeder Plattform eine Gliedmaße töten, bevor Kataklysmus durch ist."] = "- 사지: 대격변 시전이 끝나기 전에 각 단상에서 사지 하나 처치."
L["- Mutierte Verderbnis: Aufspießen -> Tankwechsel; Zermalmen meiden."] = "- 돌연변이 타락: 꿰뚫기 -> 탱 교대; 분쇄 피하기."
L["- Elementiumblitz: schlägt auf einer Plattform ein -> Aspekt-Hilfe nutzen (z.B. Nozdormus Zeitzone)."] = "- 엘레멘티움 화살: 단상 하나에 떨어짐 -> 위상의 도움 활용 (예: 노즈도르무의 시간 지대)."
L["- Phase 2 (Kopf): Elementiumfragmente, Elementiumschrecken -> Adds töten, Verderbtes Blut stapelt Raidschaden."] = "- 2단계 (머리): 엘레멘티움 파편, 엘레멘티움 공포 -> 쫄 처치, 타락한 피가 공대 피해 중첩."
L["Taktik: Plattformen nacheinander abarbeiten und die Fähigkeit des jeweiligen Aspekts nutzen. Phase 2: Fragmente und Schrecken töten, Kopf burnen."] = "공략: 단상을 하나씩 처리하고 해당 위상의 능력 활용. 2단계: 파편과 공포 처치, 머리 녹이기."
L["TODESSCHWINGE: Gliedmaße vor Kataklysmus töten!"] = "데스윙: 대격변 전에 사지 처치!"
L["Aspekt-Fähigkeiten nutzen. Phase 2: Adds töten, Kopf burnen."] = "위상 능력 활용. 2단계: 쫄 처치, 머리 녹이기."
L["Morchok"] = "모르초크"
L["- Stampfen: Schaden wird auf Spieler in der Nähe aufgeteilt -> Tanks und Nahkampf nah dran."] = "- 발구르기: 근처 플레이어에게 피해 분산 -> 탱커와 근딜은 가까이."
L["- Resonanzkristall: explodiert, Schaden je nach Entfernung -> eingeteilte Spieler nah beim Kristall."] = "- 공명하는 수정: 폭발, 거리에 따라 피해 -> 배정된 플레이어는 수정 가까이."
L["- Erdenwirbel + Schwarzes Blut der Erde: Raid wird angezogen, dann Bodenschaden -> hinter die Felssäulen gehen."] = "- 대지의 소용돌이 + 대지의 검은 피: 공대를 끌어당긴 후 바닥 피해 -> 바위 기둥 뒤로 가기."
L["- Wütend (20 %): mehr Schaden -> Cooldowns."] = "- 분노 (20 %): 피해량 증가 -> 쿨기."
L["Taktik: Zwei Tanks nah am Boss gegen Stampfen, drei Spieler soaken Kristalle. Bei Schwarzes Blut hinter die Säulen."] = "공략: 발구르기 대비 탱커 두 명은 보스 가까이, 세 명이 수정 받아내기. 검은 피 때 기둥 뒤로."
L["Heroisch: Zwilling Kohcrom erscheint und muss getrennt getankt werden."] = "영웅: 쌍둥이 코크롬이 등장하며 따로 탱해야 함."
L["MORCHOK: Kristalle soaken, Stampfen mit Nahkampf teilen!"] = "모르초크: 수정 받아내고, 발구르기는 근딜과 나눠 맞기!"
L["Schwarzes Blut: hinter die Felssäulen! Ab 20 % Cooldowns."] = "검은 피: 바위 기둥 뒤로! 20 %부터 쿨기."
L["Rückgrat von Todesschwinge + Verderbnis, Amalgamation"] = "데스윙의 등 + 타락, 융합체"
L["- Verderbnis: Feurige Umklammerung hält Spieler -> Verderbnis-Tentakel töten bzw. Umklammerung brechen."] = "- 타락: 불타는 손아귀가 플레이어를 붙잡음 -> 타락의 촉수 처치 또는 손아귀 풀기."
L["- Abscheuliche Amalgamation: sammelt Blut-Stapel; bei voller Ladung zu einer Panzerplatte ziehen und dort töten -> Platte wird gelöst."] = "- 가증스러운 융합체: 피 중첩을 모음; 가득 차면 장갑판으로 끌고 가서 처치 -> 장갑판이 떨어짐."
L["- Brennende Sehne: nach Plattenlösen erscheint die Sehne -> sofort burnen."] = "- 불타는 힘줄: 장갑판이 떨어지면 힘줄 등장 -> 즉시 녹이기."
L["- Rolle: Todesschwinge rollt -> Raid auf die richtige Seite verteilen, sonst fliegen alle runter."] = "- 회전: 데스윙이 몸을 굴림 -> 공대를 올바른 쪽에 분배, 아니면 전원 떨어짐."
L["- Sengendes Plasma: Heilabsorption -> Heiler gegenheilen."] = "- 이글거리는 플라스마: 치유 흡수 -> 힐러가 힐로 지우기."
L["Taktik: Drei Panzerplatten nacheinander lösen: Amalgamation stapeln und an der Platte töten, Sehne burnen. Gewicht auf dem Rücken ausgleichen."] = "공략: 장갑판 세 개를 차례로 떼어내기: 융합체 중첩 쌓고 장갑판 위에서 처치, 힘줄 녹이기. 등 위의 무게 균형 맞추기."
L["RÜCKGRAT: Amalgamation an der Platte töten, Sehne burnen!"] = "데스윙의 등: 융합체는 장갑판에서 처치, 힘줄 녹이기!"
L["Bei Rolle Gewicht verteilen. Verderbnis-Tentakel töten."] = "회전 때 무게 분배. 타락의 촉수 처치."
L["Rückgrat"] = "데스윙의 등"
L["Ein Symbol je Verderbnis-Tentakel, Totenkopf zuerst."] = "타락의 촉수마다 징표 하나, 해골 먼저."
L["Ultraxion"] = "울트락시온"
L["- Stunde des Zwielichts: tödlicher Schaden auf den Raid -> Tank/eingeteilte Spieler nehmen ihn, alle anderen Heldenhafter Wille."] = "- 황혼의 시간: 공대에 치명적인 피해 -> 탱커/배정된 플레이어가 받고, 나머지는 영웅의 의지."
L["- Verblassendes Licht: Debuff, beim Ablaufen tödlich -> kurz vorher Heldenhafter Wille drücken."] = "- 사그라지는 빛: 디버프, 끝나면 사망 -> 끝나기 직전에 영웅의 의지 누르기."
L["- Instabile Monstrosität: stetig steigender Raidschaden -> Heil-CDs rotieren."] = "- 불안정한 괴물: 계속 증가하는 공대 피해 -> 힐 쿨기 로테이션."
L["- Gaben der Aspekte: Letzter Verteidiger (Tanks), Gabe des Lebens, Quell der Magie usw. aktiv einsetzen."] = "- 위상의 선물: 최후의 수호자 (탱커), 생명의 선물, 마법의 샘 등을 적극 활용."
L["Taktik: Raid steht eng zusammen, Tanks wechseln über Stunde des Zwielichts. Heldenhafter Wille exakt timen, Burn vor dem Wutanfall."] = "공략: 공대는 바짝 뭉치고, 탱커는 황혼의 시간마다 교대. 영웅의 의지 타이밍 정확히, 광폭화 전에 녹이기."
L["ULTRAXION: Heldenhafter Wille kurz vor Ablauf drücken!"] = "울트락시온: 영웅의 의지는 끝나기 직전에 누르세요!"
L["Stunde des Zwielichts nach Plan soaken. Gaben nutzen."] = "황혼의 시간은 계획대로 받아내기. 선물 활용."
L["Yor'sahj der Unermüdliche + Kügelchen"] = "잠들지 않는 요르사지 + 방울"
L["- Kügelchen: mehrere farbige Kugeln rollen zum Boss -> vorher zwei (heroisch drei) töten, der Rest bestimmt Yor'sahjs Fähigkeiten."] = "- 방울: 여러 색 구슬이 보스에게 굴러감 -> 미리 두 개 (영웅은 세 개) 처치, 남은 것이 요르사지의 기술을 결정."
L["- Grün: Säure auf Spielern -> verteilen."] = "- 녹색: 플레이어에게 산성 -> 산개."
L["- Rot: Sengendes Blut -> zusammenstehen."] = "- 빨강: 타오르는 피 -> 뭉치기."
L["- Schwarz: Adds -> AoE. Blau: Manaleere -> töten. Lila: Heilung schadet bzw. stapelt -> Heilung zurückhalten."] = "- 검정: 쫄 -> 광역. 파랑: 마나 공허 -> 처치. 보라: 치유가 피해를 주거나 중첩 -> 힐 자제."
L["- Leerenblitz: Tank-Stapel -> Tankwechsel."] = "- 공허의 화살: 탱커 중첩 -> 탱 교대."
L["Taktik: Feste Prioritätsliste für die Kugel-Kombinationen, Gruppen auf die Kugeln aufteilen. Danach Mechanik der verbliebenen Farbe spielen."] = "공략: 구슬 조합별 고정 우선순위 목록, 그룹을 구슬마다 분배. 그 후 남은 색의 기술 대응."
L["YOR'SAHJ: Kügelchen nach Priorität töten!"] = "요르사지: 우선순위대로 방울 처치!"
L["Grün verteilen, Rot zusammen, Lila: Heilung stoppen. Tankwechsel."] = "녹색 산개, 빨강 뭉치기, 보라: 힐 중지. 탱 교대."
L["Kriegsherr Zon'ozz + Tentakel"] = "장군 존오즈 + 촉수"
L["- Leere des Entwerdens: Kugel prallt zwischen Raid und Boss hin und her -> Raid fängt sie gemeinsam, Stapel erhöhen Schaden auf Boss."] = "- 소멸의 공허: 구슬이 공대와 보스 사이를 튕겨 다님 -> 공대가 함께 받아내고, 중첩이 보스가 받는 피해 증가."
L["- Störende Schatten: Magie-Debuff mit Rückstoß beim Bannen -> erst bannen, wenn der Spieler sicher steht."] = "- 교란의 어둠: 해제 시 밀쳐내는 마법 디버프 -> 플레이어가 안전한 위치에 있을 때만 해제."
L["- Psychische Entziehung: frontaler Schaden auf den Tank -> nicht vor dem Boss stehen."] = "- 정신 흡수: 탱커에게 정면 피해 -> 보스 앞에 서지 않기."
L["- Schwarzes Blut von Go'rath: Tentakel (Augen, Klaue, Peitsche) -> schnell töten, Augen mit AoE."] = "- 고라스의 검은 피: 촉수 (눈, 발톱, 채찍) -> 빠르게 처치, 눈은 광역."
L["Taktik: Raid eng zusammen, Kugel gezielt mehrfach aufprallen lassen. In der Blutphase Tentakel töten, dann Boss burnen."] = "공략: 공대는 바짝 뭉치고, 구슬을 의도적으로 여러 번 튕기게 하기. 피 단계에서 촉수 처치 후 보스 녹이기."
L["ZON'OZZ: Kugel zusammen fangen! Tentakel töten!"] = "존오즈: 구슬 함께 받아내기! 촉수 처치!"
L["Störende Schatten nur an sicherer Stelle bannen."] = "교란의 어둠은 안전한 위치에서만 해제."
L["Feuerlande"] = "불의 땅"
L["Alysrazar + Druiden, Brutlinge, Lavawürmer"] = "알리스라조르 + 드루이드, 새끼 불매, 용암 벌레"
L["- Geschmolzene Federn: einsammeln, um zu fliegen -> Flieger durch Feuerringe fliegen und Schaden machen."] = "- 녹은 깃털: 모아서 날기 -> 비행자는 불의 고리를 통과하며 딜."
L["- Feuerbrut-Brutlinge: werden wütend, wenn nicht gefüttert -> auf Lavawürmer ziehen."] = "- 불꽃매 새끼: 먹이를 못 먹으면 격노 -> 용암 벌레 위로 끌고 가기."
L["- Druiden der Flammenkralle: Feuerspucke unterbrechen, Brennende Klaue auf Tank."] = "- 불꽃발톱 드루이드: 화염 침 차단, 탱커에게 불타는 발톱."
L["- Feuertornados: in Phase 2 kreisen Tornados -> ausweichen."] = "- 화염 회오리: 2단계에 회오리가 돌아다님 -> 피하기."
L["- Ausbrennen: Alysrazar ist energielos -> Schadensfenster, Raidschaden beachten."] = "- 소진: 알리스라조르가 기력 고갈 -> 딜 타이밍, 공대 피해 주의."
L["Taktik: 1–2 Spieler fliegen, Rest am Boden gegen Brutlinge und Druiden. Tornados meiden, beim Ausbrennen alles auf den Boss."] = "공략: 1–2명은 비행, 나머지는 바닥에서 새끼 불매와 드루이드 처리. 회오리 피하고, 소진 때 전원 보스 점사."
L["ALYSRAZAR: Federn sammeln, Brutlinge tanken, Druiden unterbrechen!"] = "알리스라조르: 깃털 모으고, 새끼 불매 탱, 드루이드 차단!"
L["Tornados ausweichen. Ausbrennen = BURN!"] = "회오리 피하기. 소진 = 녹이기!"
L["Alysrazar"] = "알리스라조르"
L["Totenkopf und Kreuz auf die zwei Brutlinge."] = "새끼 불매 두 마리에 해골과 가위표."
L["Baloroc, der Torwächter"] = "문지기 베일록"
L["- Splitter der Qual: Kristall schießt auf den nächsten Spieler -> zwei Gruppen wechseln sich beim Soaken ab (Gequält-Debuff)."] = "- 고통의 파편: 수정이 가장 가까운 플레이어를 공격 -> 두 그룹이 번갈아 받아내기 (고통 디버프)."
L["- Inferno-Klinge: hoher Feuerschaden auf Tank -> Tank-CDs."] = "- 지옥불 칼날: 탱커에게 높은 화염 피해 -> 탱커 생존기."
L["- Dezimierungsklinge: Treffer kosten 90 % Leben -> Tank sofort hochheilen."] = "- 학살의 칼날: 적중 시 생명력 90 % 감소 -> 탱커 즉시 힐업."
L["- Heiler: Lebendige Funken/Flammen stapeln durch Heilung auf Zielen nahe am Kristall."] = "- 힐러: 살아있는 불꽃/화염이 수정 근처 대상을 치유하면 중첩."
L["Taktik: Raid steht hinter dem Boss, Soak-Rotation fest. Tanks wechseln je nach Klinge."] = "공략: 공대는 보스 뒤에 서고, 받아내기 로테이션 고정. 탱커는 칼날에 따라 교대."
L["BALOROC: Kristall-Rotation einhalten!"] = "베일록: 수정 로테이션 지키세요!"
L["Dezimierungsklinge: Tank sofort hochheilen."] = "학살의 칼날: 탱커 즉시 힐업."
L["Beth'tilac + Glutnetzspinner, Drohnen, Spinnlinge"] = "베스틸락 + 잿불그물 방적거미, 일벌레, 새끼거미"
L["- Glimmende Verwüstung: bei leerer Feuerenergie hoher Schaden auf alle oben im Netz -> Spieler oben rechtzeitig runterspringen."] = "- 잿불 황폐: 불꽃 에너지가 바닥나면 거미줄 위의 모두에게 큰 피해 -> 위에 있는 플레이어는 제때 뛰어내리기."
L["- Glutnetzspinner: hängen an Fäden -> runterziehen und töten; ihr Faden bringt Spieler nach oben ins Netz."] = "- 잿불그물 방적거미: 실에 매달려 있음 -> 끌어내려 처치; 그 실로 플레이어가 거미줄 위로 올라감."
L["- Glutnetzdrohnen: tanken und töten, sie füllen sonst Beth'tilacs Energie auf."] = "- 잿불그물 일벌레: 탱하고 처치, 아니면 베스틸락의 기력을 채움."
L["- Spinnlinge: krabbeln zu den Drohnen -> verlangsamen und mit AoE töten."] = "- 새끼거미: 일벌레에게 기어감 -> 감속시키고 광역으로 처치."
L["- Phase 2 (nach der 3. Verwüstung): Beth'tilac kommt runter, Witwenkuss stapelt auf dem Tank -> Tankwechsel, Raidschaden steigt."] = "- 2단계 (3번째 황폐 후): 베스틸락이 내려옴, 과부의 입맞춤이 탱커에게 중첩 -> 탱 교대, 공대 피해 증가."
L["Taktik: Eine Gruppe (Tank + Schaden) oben am Boss, der Rest unten gegen Adds. Phase 2: alle auf den Boss, Tankwechsel, Heil-CDs."] = "공략: 한 그룹 (탱 + 딜러)은 위에서 보스, 나머지는 아래에서 쫄 처리. 2단계: 전원 보스, 탱 교대, 힐 쿨기."
L["BETH'TILAC: Oben vor der Verwüstung runterspringen!"] = "베스틸락: 위에 있는 사람은 황폐 전에 뛰어내리세요!"
L["Unten: Spinner runterziehen, Drohnen tanken, Spinnlinge AoE."] = "아래: 방적거미 끌어내리기, 일벌레 탱, 새끼거미 광역."
L["Beth'tilac"] = "베스틸락"
L["Totenkopf und Kreuz auf die aktuellen Drohnen (Tank und Schaden)."] = "현재 일벌레에 해골과 가위표 (탱과 딜)."
L["Majordomus Hirschhaupt"] = "청지기 스태그헬름"
L["- Katzengestalt – Springende Flammen: springt auf Spieler und hinterlässt Feuer -> verteilt stehen, Feuer meiden."] = "- 표범 변신 – 도약하는 불길: 플레이어에게 도약해 불을 남김 -> 산개해서 서고, 불 피하기."
L["- Skorpiongestalt – Flammensense: frontaler Schaden, aufgeteilt auf alle Getroffenen -> ganzer Raid steht zusammen vor dem Boss."] = "- 전갈 변신 – 화염 낫: 정면 피해, 맞은 모두에게 분산 -> 공대 전원 보스 앞에 뭉치기."
L["- Formwechsel bei voller Energie bzw. Lebensschwellen: Raid muss Aufstellung sofort wechseln."] = "- 기력 가득 또는 생명력 구간에서 변신: 공대는 즉시 대형 변경."
L["- Menschliche Form – Sengende Samen: explodieren nach Zeit -> verteilen. Brennende Kugeln: Spieler werden beschossen -> Kugeln abfangen/gegenheilen."] = "- 인간 형상 – 이글거리는 씨앗: 일정 시간 후 폭발 -> 산개. 불타는 구슬: 플레이어를 공격 -> 구슬 막기/힐로 대응."
L["Taktik: Raidleiter sagt jeden Formwechsel an: Katze = verteilen, Skorpion = eng zusammen vor dem Boss. Schaden und Heilung steigen mit jedem Zyklus."] = "공략: 공대장이 변신마다 콜: 표범 = 산개, 전갈 = 보스 앞에 바짝 뭉치기. 주기마다 피해와 치유량이 증가."
L["HIRSCHHAUPT: Katze = VERTEILEN, Skorpion = ZUSAMMEN vor dem Boss!"] = "스태그헬름: 표범 = 산개, 전갈 = 보스 앞에 뭉치기!"
L["Sengende Samen: verteilen. Formwechsel sofort umsetzen."] = "이글거리는 씨앗: 산개. 변신 즉시 대응."
L["Ragnaros + Söhne der Flamme, Lavaabkömmlinge"] = "라그나로스 + 화염의 아들, 용암 자손"
L["- Sulfurasschmettern: Lavawellen breiten sich aus -> seitlich ausweichen."] = "- 설퍼라스 강타: 용암 파도가 퍼져나감 -> 옆으로 피하기."
L["- Magmafalle: Spieler löst die Falle aus und schleudert den Raid hoch -> eingeteilter Spieler soakt, Raid auf Schaden vorbereitet."] = "- 용암 덫: 플레이어가 덫을 밟으면 공대가 튕겨 오름 -> 배정된 플레이어가 받아내고, 공대는 피해 대비."
L["- Zorn von Ragnaros: Rückstoß auf Spieler in der Nähe -> Nahkampf nicht zu nah, nicht in die Lava fallen."] = "- 라그나로스의 분노: 근처 플레이어 밀쳐내기 -> 근딜은 너무 가까이 붙지 말고, 용암에 떨어지지 않기."
L["- Zwischenphasen (70 % / 40 %): Söhne der Flamme laufen zu Sulfuras -> verlangsamen und töten, bevor sie ankommen."] = "- 전환 단계 (70 % / 40 %): 화염의 아들이 설퍼라스로 달려감 -> 도착하기 전에 감속시키고 처치."
L["- Phase 2: Geschmolzene Samen -> verteilen, dann weglaufen. Phase 3: Lebendiger Meteor verfolgt Spieler -> wegkiten, zurückstoßen."] = "- 2단계: 녹아내린 씨앗 -> 산개 후 도망. 3단계: 살아있는 유성이 플레이어 추적 -> 카이팅, 밀쳐내기."
L["Taktik: Phase 1 Lavawellen und Fallen spielen, Zwischenphasen alle Söhne töten. Phase 2 Samen meiden, Phase 3 Meteore kiten und Boss burnen."] = "공략: 1단계 용암 파도와 덫 대응, 전환 단계엔 아들 전부 처치. 2단계 씨앗 피하기, 3단계 유성 카이팅하고 보스 녹이기."
L["Heroisch: zusätzliche Phase 4 mit Cenarius, Malfurion und Hamuul."] = "영웅: 세나리우스, 말퓨리온, 하뮬이 등장하는 4단계 추가."
L["RAGNAROS: Lavawellen ausweichen! Zwischenphase: Söhne töten!"] = "라그나로스: 용암 파도 피하세요! 전환 단계: 아들 처치!"
L["Samen verteilen, Meteore kiten. Nicht in die Lava!"] = "씨앗 산개, 유성 카이팅. 용암에 빠지지 마세요!"
L["Lord Rhyolith + Fragmente und Funken"] = "군주 라이올리스 + 파편과 불꽃"
L["- Steuerung: Schaden auf linkes bzw. rechtes Bein lenkt den Boss -> gezielt auf aktive Vulkane steuern."] = "- 조종: 왼다리 또는 오른다리에 딜을 넣어 보스 조종 -> 활성 화산 쪽으로 조종."
L["- Obsidianrüstung: verringert erlittenen Schaden -> Rhyolith über aktive Vulkane laufen lassen, um Stapel abzubauen."] = "- 흑요석 갑옷: 받는 피해 감소 -> 라이올리스가 활성 화산 위를 지나가게 해서 중첩 감소."
L["- Magmaflüsse und Lava: Bodenschaden -> ausweichen."] = "- 용암 흐름과 용암: 바닥 피해 -> 피하기."
L["- Fragmente von Rhyolith: schnell mit AoE töten. Funke von Rhyolith: Add weg tanken."] = "- 라이올리스의 파편: 광역으로 빠르게 처치. 라이올리스의 불꽃: 쫄은 떨어진 곳에서 탱."
L["- Phase 2 (25 %): Rhyolith ohne Rüstung, Schaden steigt -> Tank übernimmt, burnen."] = "- 2단계 (25 %): 갑옷 없는 라이올리스, 피해 증가 -> 탱커가 잡고, 녹이기."
L["Taktik: Zwei Gruppen auf linkes und rechtes Bein, Raidleiter steuert. Adds schnell töten, ab 25 % alles auf den Boss."] = "공략: 두 그룹이 왼다리와 오른다리 담당, 공대장이 조종. 쫄 빠르게 처치, 25 %부터 전원 보스 점사."
L["RHYOLITH: Beine gezielt schlagen, auf Vulkane steuern!"] = "라이올리스: 다리 골라 때리고, 화산 쪽으로 조종!"
L["Fragmente töten. Ab 25 % Burn!"] = "파편 처치. 25 %부터 녹이기!"
L["Shannox + Riplimb und Rageface"] = "샤녹스 + 립림과 레이지페이스"
L["- Riplimb: stapelnder Blutungs-Debuff auf seinem Tank; holt den geworfenen Speer zurück -> Tankwechsel bei hohen Stapeln."] = "- 립림: 탱커에게 출혈 디버프 중첩; 던진 창을 물어옴 -> 중첩이 높으면 탱 교대."
L["- Rageface: springt Spieler an und zerfleischt sie -> schwer zu treffen, schnell befreien."] = "- 레이지페이스: 플레이어에게 덤벼들어 물어뜯음 -> 맞추기 어려움, 빠르게 풀어주기."
L["- Speer: Shannox wirft den Speer, um ihn entstehen Feuerflächen -> rauslaufen."] = "- 창: 샤녹스가 창을 던지면 주변에 화염 장판 생성 -> 빠져나오기."
L["- Kristallgefängnisfalle: hält den ersten Treffer fest -> Hunde hineinführen."] = "- 수정 감옥 덫: 처음 밟은 대상을 가둠 -> 사냥개를 덫으로 유도."
L["- Hunde nicht zu weit von Shannox wegziehen, sonst werden sie stärker."] = "- 사냥개를 샤녹스에게서 너무 멀리 끌고 가지 않기, 아니면 강해짐."
L["Taktik: Shannox und die Hunde nah beieinander tanken, Hunde mit Fallen kontrollieren. Gängige Reihenfolge: Rageface zuerst, dann Shannox."] = "공략: 샤녹스와 사냥개는 서로 가까이에서 탱, 사냥개는 덫으로 통제. 일반적인 순서: 레이지페이스 먼저, 그다음 샤녹스."
L["SHANNOX: Hunde in Fallen ziehen, nah am Boss tanken!"] = "샤녹스: 사냥개를 덫으로, 보스 가까이에서 탱!"
L["Feuer am Speer meiden. Rageface zuerst."] = "창 주변 불 피하기. 레이지페이스 먼저."
L["Thron der Vier Winde"] = "네 바람의 왕좌"
L["Al'Akir + Sturmlinge"] = "알아키르 + 폭풍 정령"
L["- Böenlinie: Wand aus Tornados mit Lücke -> durch die Lücke laufen bzw. sich mitnehmen lassen."] = "- 돌풍 전선: 빈틈이 있는 회오리 벽 -> 빈틈으로 지나가거나 휩쓸려 이동."
L["- Statischer Schock / Blitzschlag: bestraft Nicht-Nahkampf am Boss -> Tank immer in Nahkampfreichweite halten."] = "- 정전기 충격 / 번개 강타: 보스 근접 범위에 없으면 처벌 -> 탱커는 항상 근접 범위 유지."
L["- Phase 2 (80 %): Säureregen stapelt Raidschaden -> schnell zur Phase 3; Sturmlinge töten."] = "- 2단계 (80 %): 산성비로 공대 피해 중첩 -> 빠르게 3단계로; 폭풍 정령 처치."
L["- Phase 3 (25 %): alle fliegen; Blitzableiter -> verteilen, Gewitterwolken ausweichen."] = "- 3단계 (25 %): 전원 비행; 피뢰침 -> 산개, 뇌운 피하기."
L["Taktik: Phase 1 am Boss, Böenlinien beachten. Phase 2 Sturmlinge töten und durchschieben. Phase 3 in der Luft verteilen und burnen."] = "공략: 1단계 보스 근처에서, 돌풍 전선 주의. 2단계 폭풍 정령 처치하고 빠르게 밀기. 3단계 공중에서 산개하고 녹이기."
L["AL'AKIR: Böenlinie – Lücke suchen! Phase 2 schnell durch!"] = "알아키르: 돌풍 전선 – 빈틈 찾기! 2단계 빠르게 밀기!"
L["Phase 3: verteilen, Gewitterwolken meiden."] = "3단계: 산개, 뇌운 피하기."
L["Konklave des Windes (Anshal, Nezir, Rohash)"] = "바람의 비밀의회 (안샬, 네지르, 로하시)"
L["- Anshal: ruft Kriecher -> Kriecher töten, nicht in Beruhigende Brise stehen."] = "- 안샬: 덩굴손 소환 -> 덩굴손 처치, 진정의 산들바람 안에 서지 않기."
L["- Nezir: Windkälte stapelt auf seinem Tank -> Tank nutzt CDs, Eisflächen meiden."] = "- 네지르: 바람 냉기가 탱커에게 중첩 -> 탱커 생존기 사용, 얼음 장판 피하기."
L["- Rohash: Sturmschneide und Hurrikan -> Fernkampf auf seiner Plattform halten."] = "- 로하시: 폭풍 칼날과 허리케인 -> 원딜이 그의 단상을 유지."
L["- Ultimate bei voller Energie: Plattformen sofort verlassen."] = "- 기력 가득 시 궁극기: 즉시 단상 떠나기."
L["- Alle drei müssen innerhalb kurzer Zeit fallen, sonst steht der Rest wieder auf."] = "- 셋 모두 짧은 시간 안에 쓰러져야 함, 아니면 나머지가 다시 일어남."
L["Taktik: Drei Gruppen auf die drei Plattformen, Schaden gleichmäßig verteilen. Bei Ultimate zurück in die Mitte."] = "공략: 세 그룹이 세 단상에 배치, 딜을 균등하게 분배. 궁극기 때 중앙으로 복귀."
L["KONKLAVE: Alle drei gleichzeitig töten!"] = "비밀의회: 셋 모두 동시에 처치!"
L["Ultimate: Plattform verlassen!"] = "궁극기: 단상 떠나기!"
L["Konklave"] = "비밀의회"
L["Totenkopf, Kreuz, Viereck auf Anshal, Nezir, Rohash."] = "안샬, 네지르, 로하시에 해골, 가위표, 네모."
L["Herz der Angst"] = "공포의 심장"
L["Kaiserlicher Wesir Zor'lok"] = "황실 장관 조르로크"
L["- Ausatmen: Kanalisierung auf einen Spieler -> Tank/Spieler stellen sich in die Linie, um den Schaden abzufangen."] = "- 숨 내쉬기: 플레이어 한 명에게 정신 집중 -> 탱커/플레이어가 경로에 서서 피해를 대신 받기."
L["- Abschwächung: Schallringe laufen über den Boden -> durch die Lücken der Ringe laufen."] = "- 약화: 음파 고리가 바닥을 지나감 -> 고리의 틈으로 통과."
L["- Kraft und Elan: großer Raidschaden -> in die Schallblase (Geräuschunterdrückung) stellen."] = "- 힘과 활력: 큰 공격대 피해 -> 음파 거품(소음 제거) 안으로 들어가기."
L["- Bekehren (heroisch/später): Spieler werden gedankenkontrolliert -> kontrollieren bzw. schnell runterschaden."] = "- 개종 (영웅/후반): 플레이어가 정신 지배됨 -> 군중 제어 또는 빠르게 딜로 처리."
L["- Pheromone des Eifers: Gas am Boden -> auf den Plattformen bleiben."] = "- 열정의 페로몬: 바닥에 가스 -> 단상 위에 머물기."
L["Taktik: Der Boss wechselt Plattformen; Raid folgt geschlossen. Bei Kraft und Elan sofort in die Blasen, Ausatmen-Ziel absichern."] = "공략: 보스가 단상을 옮겨 다님; 공대는 뭉쳐서 따라감. 힘과 활력 시 즉시 거품 안으로, 숨 내쉬기 대상 보호."
L["ZOR'LOK: Bei Kraft und Elan in die Blasen! Ringe durch Lücken!"] = "조르로크: 힘과 활력 시 거품 안으로! 고리는 틈으로!"
L["Ausatmen-Linie blocken, nicht ins Gas am Boden."] = "숨 내쉬기 경로 막기, 바닥 가스 밟지 말 것."
L["Klingenfürst Ta'yak"] = "칼날 군주 타야크"
L["- Unsichtbarer Schlag: Ziel wird markiert -> gesamter Raid stellt sich zum Ziel, um den Schaden zu teilen."] = "- 보이지 않는 일격: 대상이 징표로 표시됨 -> 공대 전원이 대상 옆에 서서 피해 분담."
L["- Überwältigender Angriff: Tankdebuff -> Tankwechsel."] = "- 압도적인 공격: 탱커 디버프 -> 탱 교대."
L["- Windschritt: Teleport mit Blutungen auf nahe Spieler -> Heiler bereit."] = "- 바람 걸음: 순간이동 후 근처 플레이어에게 출혈 -> 힐러 대기."
L["- Sturmhieb: Wirbelstürme laufen durch den Raum -> ausweichen."] = "- 폭풍 베기: 회오리가 방을 가로지름 -> 피하기."
L["- Phase 2 (20 %): Sturm entfesselt, Boss am Ende des Korridors -> Wirbelwinden ausweichen, gegen den Wind halten."] = "- 2단계 (20 %): 폭풍 해방, 보스는 복도 끝으로 -> 회오리 피하고 바람에 맞서 버티기."
L["Taktik: Raid locker hinter dem Boss, bei Unsichtbarem Schlag zum markierten Spieler. Ab 20 % mit Cooldowns zügig beenden."] = "공략: 공대는 보스 뒤에 느슨하게, 보이지 않는 일격 시 표시된 플레이어에게 모이기. 20 %부터 생존기로 빠르게 마무리."
L["TA'YAK: Bei Unsichtbarem Schlag alle zum markierten Spieler!"] = "타야크: 보이지 않는 일격 시 전원 표시된 플레이어에게!"
L["Tankwechsel nach Stapeln, Wirbelstürmen ausweichen."] = "중첩 후 탱 교대, 회오리 피하기."
L["Garalon (Riesenkäfer mit vier Beinen)"] = "가랄론 (다리 네 개 달린 거대 딱정벌레)"
L["- Pheromone: Träger hinterlässt eine Spur und stapelt Schaden -> Pheromone kontrolliert weitergeben, Spur meiden."] = "- 페로몬: 보유자가 흔적을 남기고 피해가 중첩됨 -> 페로몬을 계획대로 넘기고 흔적 피하기."
L["- Wütender Hieb: frontaler Hieb muss mindestens zwei Spieler treffen -> Tanks zusammen vorne stehen, sonst Wut."] = "- 격노의 후려치기: 전방 공격이 최소 두 명을 맞혀야 함 -> 탱커 둘이 함께 앞에 서기, 아니면 격노."
L["- Zerquetschen: Garalon wirft sich auf den Boden -> unter dem Boss sofort raus."] = "- 짓누르기: 가랄론이 바닥에 몸을 던짐 -> 보스 밑에서 즉시 나오기."
L["- Beine: zerstörte Beine machen Garalon langsamer und verwundbarer, wachsen aber nach -> Nahkampf auf Beine."] = "- 다리: 파괴된 다리는 가랄론을 느리고 취약하게 하지만 다시 자람 -> 근딜은 다리 공격."
L["Taktik: Nahkampf zerstört Beine, Fernkampf auf den Körper. Pheromonträger kitet am Rand entlang, Raid hält sich aus der Spur."] = "공략: 근딜은 다리 파괴, 원딜은 몸통. 페로몬 보유자는 가장자리를 따라 카이팅, 공대는 흔적 밖에 있기."
L["GARALON: Nahkampf auf Beine, Fernkampf Körper! Zwei Tanks vorne!"] = "가랄론: 근딜 다리, 원딜 몸통! 탱커 둘 앞에!"
L["Pheromonspur meiden, bei Zerquetschen raus unter dem Boss."] = "페로몬 흔적 피하기, 짓누르기 시 보스 밑에서 나오기."
L["Windfürst Mel'jarak + Klingenmeister, Bernfallensteller und Kampfheiler"] = "바람 군주 멜자라크 + 칼날 대가, 호박석 덫사냥꾼, 전투 치유사"
L["- Adds in drei Gruppen: stirbt ein Add, werden die anderen seiner Art stärker -> eine Gruppe nach der anderen töten, Rest kontrollieren."] = "- 쫄 세 그룹: 쫄 하나가 죽으면 같은 종류의 나머지가 강해짐 -> 한 그룹씩 처치, 나머지는 군중 제어."
L["- Klingenregen: Raidschaden -> Heiler-Cooldowns."] = "- 칼날 비: 공격대 피해 -> 힐러 생존기."
L["- Windbombe: Bombe am Boden -> nicht hineinlaufen."] = "- 바람 폭탄: 바닥에 폭탄 -> 밟지 말 것."
L["- Ätzendes Harz: Bewegung erzeugt Pfützen -> stehen bleiben bzw. kontrolliert ablegen."] = "- 부식성 수지: 움직이면 웅덩이 생성 -> 가만히 있거나 계획적으로 내려놓기."
L["- Bernkerker: Spieler eingeschlossen -> ein anderer Spieler befreit ihn."] = "- 호박석 감옥: 플레이어가 갇힘 -> 다른 플레이어가 풀어주기."
L["Taktik: CC zuteilen, eine Add-Gruppe gezielt töten (oft die Heiler zuerst), danach Boss. Nicht unkontrolliert AoE auf CC-Ziele."] = "공략: 군중 제어 분배, 쫄 한 그룹을 집중 처치 (보통 치유사 먼저), 이후 보스. 군중 제어 대상에 무분별한 광역 금지."
L["MEL'JARAK: Nur Add-Gruppe X töten, CC-Ziele nicht anfassen!"] = "멜자라크: 쫄 그룹 X만 처치, 군중 제어 대상 건드리지 말 것!"
L["Keine AoE auf CC! Bernkerker befreien, Windbomben meiden."] = "군중 제어에 광역 금지! 호박석 감옥 풀어주기, 바람 폭탄 피하기."
L["Mel'jarak (CC)"] = "멜자라크 (군중 제어)"
L["Jedes zu kontrollierende Add ein Symbol; CC-Spieler halten ihr Symbol, Stern zuerst."] = "제어할 쫄마다 징표 하나; 군중 제어 담당은 자기 징표 유지, 별 먼저."
L["Bernformer Un'sok + Lebendiger Bern und Bernmonstrosität"] = "호박석 조형사 운속 + 살아있는 호박석과 호박석 괴물"
L["- Leben umformen: Spieler wird zum Konstrukt -> Bernexplosionen (eigene und der Monstrosität) unterbrechen, Willenskraft beachten, rechtzeitig ausbrechen."] = "- 생명 재형성: 플레이어가 구조물로 변함 -> 호박석 폭발(자신과 괴물의 것) 차단, 의지력 확인, 제때 탈출."
L["- Bernskalpell: Strahl folgt einem Spieler und hinterlässt Lebendigen Bern -> zum Rand führen, Adds töten."] = "- 호박석 메스: 광선이 플레이어를 따라가며 살아있는 호박석을 남김 -> 가장자리로 유도, 쫄 처치."
L["- Parasitäres Wachstum: Heilung verstärkt den Schaden auf dem Ziel -> Ziel sparsam heilen."] = "- 기생 성장: 치유가 대상의 피해를 증가시킴 -> 대상은 아껴서 힐."
L["- Phase 2: Bernmonstrosität -> Konstrukte unterbrechen ihre Explosion, Tank hält sie weg."] = "- 2단계: 호박석 괴물 -> 구조물이 괴물의 폭발 차단, 탱커가 괴물을 멀리 유지."
L["- Phase 3 (Konzentrierte Mutation): mehr Konstrukte, hoher Raidschaden -> schnell beenden."] = "- 3단계 (집중된 돌연변이): 구조물 증가, 큰 공격대 피해 -> 빠르게 마무리."
L["Taktik: Konstrukte schaden auf die Monstrosität/den Boss und unterbrechen; Lebendigen Bern am Rand kontrolliert töten, Pfützen nur von Konstrukten fressen lassen."] = "공략: 구조물은 괴물/보스를 공격하고 차단; 살아있는 호박석은 가장자리에서 계획적으로 처치, 웅덩이는 구조물만 먹게 하기."
L["UN'SOK: Konstrukte: Explosionen unterbrechen! Skalpell an den Rand!"] = "운속: 구조물: 폭발 차단! 메스는 가장자리로!"
L["Parasitäres Wachstum nicht überheilen. Monstrosität weg vom Raid."] = "기생 성장은 오버힐 금지. 괴물은 공대에서 멀리."
L["Großkaiserin Shek'zeer + Kor'thik-Häscher und Set'thik-Windklingen"] = "대여제 셰크지르 + 코르시크 포획자와 세트시크 바람칼날"
L["- Augen der Kaiserin: Tankdebuff stapelt bis zur Gedankenkontrolle -> Tankwechsel."] = "- 여제의 눈: 탱커 디버프가 정신 지배까지 중첩 -> 탱 교대."
L["- Schrei des Terrors: Raidschaden -> in die Dissonanzfelder stellen."] = "- 공포의 비명: 공격대 피해 -> 불협화음 장 안에 서기."
L["- Dienerin der Kaiserin: Spieler werden gedankenkontrolliert -> kontrollieren, nicht töten."] = "- 여제의 하수인: 플레이어가 정신 지배됨 -> 군중 제어, 죽이지 말 것."
L["- Phase 2 (Adds): Häscher in klebriges Harz/Bernfallen ziehen -> Häscher fangen, Windklingen töten; Giftbomben meiden."] = "- 2단계 (쫄): 포획자를 끈적한 수지/호박석 덫으로 유도 -> 포획자 붙잡고 바람칼날 처치; 독 폭탄 피하기."
L["- Phase 3 (30 %): Sha-Energie, Todesvisionen und Unheil -> verteilen und Cooldowns nutzen."] = "- 3단계 (30 %): 샤 에너지, 죽음의 환영과 재앙 -> 산개하고 생존기 사용."
L["Taktik: Phase 1 Boss mit Felder-Disziplin, Phase 2 Adds strikt nach Zuweisung, Phase 3 alle Cooldowns, Kampfrausch."] = "공략: 1단계는 장 운영 철저히, 2단계 쫄은 배정대로 엄격히, 3단계 모든 생존기와 블러드."
L["SHEK'ZEER: Bei Schrei in die Felder! Häscher in die Harzfallen!"] = "셰크지르: 비명 시 장 안으로! 포획자는 수지 덫으로!"
L["Tankwechsel bei Augen-Stapeln. Phase 3: Kampfrausch."] = "눈 중첩 시 탱 교대. 3단계: 블러드."
L["Mogu'shangewölbe"] = "모구샨 금고"
L["Die Steinwache (Jaspis-, Jade-, Kobalt- und Amethystwächter; im 10er nur 3 davon)"] = "바위 파수꾼 (벽옥, 비취, 코발트, 자수정 파수꾼; 10인에서는 그중 3마리)"
L["- Energie: Wächter gewinnen Energie, besonders wenn sie nah beieinander stehen; bei 100 Energie Überladung mit Raidschaden -> Abstand der Wächter über die Tanks steuern."] = "- 기력: 파수꾼은 기력을 얻으며, 서로 가까울수록 더 빠름; 기력 100에 과충전으로 공격대 피해 -> 탱커가 파수꾼 간 거리 조절."
L["- Versteinerung: ein Element versteinert den Raid langsam (Verlangsamung bis Stillstand) -> genau den Wächter dieses Elements überladen lassen, das beendet die Versteinerung."] = "- 석화: 한 원소가 공대를 서서히 석화시킴 (감속 후 정지) -> 바로 그 원소의 파수꾼을 과충전시키면 석화가 끝남."
L["- Jaspisketten: verbinden zwei Spieler, Schaden bei Abstand -> verkettete Spieler zusammenbleiben."] = "- 벽옥 사슬: 두 플레이어를 연결, 멀어지면 피해 -> 연결된 플레이어끼리 붙어 있기."
L["- Kobaltminen: wurzeln Spieler fest -> Minen meiden bzw. von Tanks gezielt auslösen lassen."] = "- 코발트 지뢰: 플레이어를 묶음 -> 지뢰 피하거나 탱커가 계획적으로 터뜨리기."
L["- Amethystpfützen und Jadesplitter: Bodeneffekte und Raidschaden -> Pfützen sofort verlassen, Heiler-Cooldowns auf Jade."] = "- 자수정 웅덩이와 비취 파편: 바닥 효과와 공격대 피해 -> 웅덩이 즉시 벗어나기, 비취 시 힐러 생존기."
L["Taktik: Tanks halten je einen bzw. zwei Wächter, ziehen nur den Wächter der aktiven Versteinerung zum Nachbarn, damit genau er überlädt. Wächter gleichmäßig runterschaden (geteilte Gesundheit)."] = "공략: 탱커는 파수꾼을 하나 또는 둘씩 잡고, 활성 석화의 파수꾼만 옆 파수꾼에게 끌어와 그것만 과충전시킴. 파수꾼은 균등하게 딜 (생명력 공유)."
L["STEINWACHE: Nur der Wächter der aktiven Versteinerung darf überladen!"] = "바위 파수꾼: 활성 석화의 파수꾼만 과충전시킬 것!"
L["Kettenpartner zusammen, Pfützen und Minen meiden, Wächter gleichmäßig."] = "사슬 짝은 함께, 웅덩이와 지뢰 피하기, 파수꾼 균등 딜."
L["Steinwache"] = "바위 파수꾼"
L["Je ein Symbol pro Wächter, damit die Tanks Zuweisungen und Positionen ansagen können."] = "파수꾼마다 징표 하나, 탱커가 배정과 위치를 콜할 수 있게."
L["Feng der Verfluchte (Flamme, Blitz, Arkan; heroisch zusätzlich Schatten)"] = "저주받은 펭 (화염, 번개, 비전; 영웅에서는 암흑 추가)"
L["- Flammenphase: Lauffeuerfunke auf Spielern -> aus dem Raid laufen und das Feuer am Rand ablegen; Flammenspeer zwingt zum Tankwechsel."] = "- 화염 단계: 플레이어에게 들불 불꽃 -> 공대 밖으로 나가 가장자리에 불 내려놓기; 화염 창으로 탱 교대 강제."
L["- Blitzphase: Epizentrum pulsiert großen Schaden um Feng -> weit weglaufen; Blitzfäuste frontal -> nicht vor dem Boss stehen."] = "- 번개 단계: 진원지가 펭 주변에 큰 피해 파동 -> 멀리 도망; 번개 주먹은 전방 -> 보스 앞에 서지 말 것."
L["- Arkanphase: Arkane Resonanz auf Spielern -> verteilen; Arkane Geschwindigkeit trifft nahe Spieler stärker -> Abstand halten."] = "- 비전 단계: 플레이어에게 비전 공명 -> 산개; 비전 속도는 가까운 플레이어에게 더 큰 피해 -> 거리 유지."
L["- Tankdebuffs jeder Phase stapeln -> Tankwechsel nach Stapeln; Schilde/Barrieren der Phasen (Nullifizierung, Reflexion) gezielt nutzen."] = "- 단계마다 탱커 디버프 중첩 -> 중첩 후 탱 교대; 단계별 방어막/보호막 (무효화, 반사)을 계획적으로 사용."
L["Taktik: Boss mittig tanken, Fernkampf verteilt außen. Phasenwechsel bei 66 % und 33 %, die Fähigkeit (Spielerknopf) für Barriere bzw. Schild vorher an Tanks/Heiler einteilen."] = "공략: 보스는 중앙에서 탱킹, 원딜은 바깥에 산개. 66 %와 33 %에 단계 전환, 방어막 또는 보호막용 능력 (엑스트라 버튼)은 미리 탱커/힐러에게 배정."
L["FENG: Epizentrum wegrennen, Funken nach außen tragen, in Arkan verteilen!"] = "펭: 진원지는 도망, 불꽃은 바깥으로, 비전에서 산개!"
L["Tanks wechseln nach Stapeln. Barriere-Spieler auf Ansage."] = "탱커는 중첩 후 교대. 방어막 담당은 콜에 맞춰."
L["Gara'jal der Geisterbinder + Geistertotems, Seelentrenner und Geister"] = "혼령결속사 가라잘 + 혼령 토템, 영혼 분리자, 혼령"
L["- Voodoopuppen: Schaden an den Puppen-Spielern wird geteilt, der Tank ist eine Puppe -> Tankwechsel nach Ansage."] = "- 부두 인형: 인형 플레이어에게 들어간 피해가 분담되며, 탱커도 인형 -> 콜에 맞춰 탱 교대."
L["- Geistertotem: zerstörtes Totem schickt nahe Spieler in die Geisterwelt -> dort Seelentrenner töten und die Seelen der Puppen befreien."] = "- 혼령 토템: 파괴된 토템이 근처 플레이어를 혼령 세계로 보냄 -> 그곳에서 영혼 분리자 처치하고 인형들의 영혼 해방."
L["- Verbannung: Tank wird in die Geisterwelt verbannt -> Tank tötet dort sein Add schnell und kommt zurück."] = "- 추방: 탱커가 혼령 세계로 추방됨 -> 탱커는 그곳의 쫄을 빨리 잡고 복귀."
L["- Geisterwelt erschöpft: zurückgekehrte Spieler können eine Zeit lang nicht erneut hinüber -> Gruppen rotieren."] = "- 혼령 세계 탈진: 돌아온 플레이어는 한동안 다시 넘어갈 수 없음 -> 그룹 순환."
L["- Raserei bei 20 %: Boss wird deutlich stärker -> Cooldowns und Kampfrausch hier."] = "- 20 %에 광폭: 보스가 크게 강해짐 -> 여기서 생존기와 블러드."
L["Taktik: Zwei feste DPS-Gruppen für die Geisterwelt abwechselnd. Totems gesteuert auf 1–2 Gruppen platzieren, Bosstank wechselt nach jeder Verbannung."] = "공략: 혼령 세계용 고정 딜러 두 그룹을 번갈아 운영. 토템은 1–2그룹 쪽에 계획적으로 설치, 보스 탱커는 추방마다 교대."
L["GARA'JAL: Totemgruppe rein, Seelentrenner töten und zurück!"] = "가라잘: 토템 그룹 진입, 영혼 분리자 잡고 복귀!"
L["Tankwechsel bei Verbannung. Bei 20 % alle Cooldowns!"] = "추방 시 탱 교대. 20 %에 모든 생존기!"
L["Die Geisterkönige: Qiang, Subetai, Zian und Meng (nacheinander aktiv)"] = "혼령 왕: 강, 수베타이, 지안, 멩 (차례로 활성화)"
L["- Qiang: Vernichten (gerade Linie vor ihm) -> nicht vor dem Boss stehen; Flankierende Truppen kommen von der Seite -> ausweichen."] = "- 강: 섬멸 (전방 직선) -> 보스 앞에 서지 말 것; 측면 부대가 옆에서 옴 -> 피하기."
L["- Subetai: Pfeilsalven und Pfeilregen -> Bodeneffekte verlassen; Plündern springt auf Spieler -> Heiler aufpassen."] = "- 수베타이: 화살 일제 사격과 화살비 -> 바닥 효과 벗어나기; 약탈이 플레이어에게 도약 -> 힐러 주의."
L["- Zian: Schattenblitze unterbrechen; Unsterbliche Schatten als Adds -> beim Tod entsteht eine Pfütze, raus da."] = "- 지안: 암흑 화살 차단; 쫄로 불멸의 그림자 -> 죽을 때 웅덩이 생성, 벗어나기."
L["- Meng: Feigheit wirft Schaden zurück und Wahnsinnsrufe treffen den Raid -> Schaden und Heilung nach Ansage dosieren."] = "- 멩: 비겁함이 피해를 반사하고 광기의 외침이 공대를 타격 -> 콜에 맞춰 딜과 힐 조절."
L["Taktik: Immer zwei Könige sind gleichzeitig aktiv (der nächste mit passiven Effekten). Nahkampf hinter dem Boss, Fernkampf verteilt, Unterbrecher für Zian fest einteilen."] = "공략: 항상 왕 둘이 동시에 활성 (다음 왕은 지속 효과만). 근딜은 보스 뒤, 원딜은 산개, 지안 차단 담당 고정 배정."
L["GEISTERKÖNIGE: Nicht vor Qiang stehen, Zian unterbrechen!"] = "혼령 왕: 강 앞에 서지 말 것, 지안 차단!"
L["Pfeilregen meiden, bei Meng Schaden dosieren."] = "화살비 피하기, 멩에서 딜 조절."
L["Elegon + Himmlische Beschützer und Energieladungen"] = "엘레곤 + 천상의 수호자와 에너지 충전물"
L["- Überladung: Elegon stapelt ständig Raidschaden -> zügig Phasen schaffen, Heiler-Cooldowns planen."] = "- 과충전: 엘레곤이 공격대 피해를 계속 중첩 -> 단계를 빠르게 넘기고 힐러 생존기 계획."
L["- Himmlischer Beschützer: Add mit starkem Tank-Druck -> außen am Rand tanken und dort töten."] = "- 천상의 수호자: 탱커 압박이 큰 쫄 -> 바깥 가장자리에서 탱킹하고 거기서 처치."
L["- Energie entziehen (Phase 2): Energieladungen wandern zu Elegon und stärken ihn -> alle Ladungen vorher töten."] = "- 에너지 흡수 (2단계): 에너지 충전물이 엘레곤에게 이동해 강화 -> 도달 전에 모든 충전물 처치."
L["- Energiewirbel in der Mitte: wer zu nah steht, nimmt Schaden -> aus der inneren Zone raus."] = "- 중앙의 에너지 소용돌이: 너무 가까우면 피해 -> 안쪽 구역에서 나오기."
L["- Bodenphase: der Plattformboden verschwindet zeitweise -> Fokusse/Spitzen paarweise zerstören, nicht herunterfallen."] = "- 바닥 단계: 단상 바닥이 일시적으로 사라짐 -> 초점/첨탑을 짝지어 파괴, 떨어지지 말 것."
L["Taktik: Boss und Adds getrennt tanken, DPS wechselt auf Beschützer und Ladungen. Fernkampf an den Ladungs-Laufwegen."] = "공략: 보스와 쫄은 따로 탱킹, 딜러는 수호자와 충전물로 전환. 원딜은 충전물 이동 경로에."
L["ELEGON: Energieladungen töten, bevor sie Elegon erreichen!"] = "엘레곤: 에너지 충전물은 엘레곤에게 닿기 전에 처치!"
L["Beschützer außen tanken. Nicht in die Mitte!"] = "수호자는 바깥에서 탱킹. 중앙 금지!"
L["Wille des Kaisers: Jan-xi und Qin-xi + Wut, Stärke und Mut des Kaisers"] = "황제의 의지: 잔시와 친시 + 황제의 분노, 힘, 용기"
L["- Verheerender Bogen / Kombo: harte Schläge der Kolosse -> nur Tanks vorne, Arme gezielt angreifen um die Kombo zu unterbrechen."] = "- 파괴의 호 / 연속기: 거대 골렘의 강타 -> 탱커만 앞에, 팔을 집중 공격해 연속기 끊기."
L["- Wut des Kaisers: kleine Adds, die Spieler verfolgen -> schnell aufsammeln und mit Flächenschaden töten."] = "- 황제의 분노: 플레이어를 쫓는 작은 쫄 -> 빠르게 모아서 광역으로 처치."
L["- Stärke des Kaisers: schweres Add mit Stampfangriff -> Offtank hält es, nicht in den Stampfer."] = "- 황제의 힘: 발 구르기를 쓰는 강한 쫄 -> 부탱이 잡기, 발 구르기에 서지 말 것."
L["- Mut des Kaisers: blockt Angriffe von vorn und fixiert einen Spieler -> von hinten angreifen."] = "- 황제의 용기: 정면 공격을 막고 플레이어 한 명을 고정 -> 뒤에서 공격."
L["- Magnetrüstung / Erdbeben: Spieler werden angezogen bzw. getroffen -> Position halten, Heilung bereit."] = "- 자력 갑옷 / 지진: 플레이어가 끌려가거나 피해를 받음 -> 위치 유지, 힐 대기."
L["Taktik: Zwei Tanks auf Jan-xi und Qin-xi, die Adds haben Vorrang. Kolosse sind immun, bis die Kraft des Kaisers fließt – DPS dann voll auf die Bosse."] = "공략: 탱커 둘은 잔시와 친시, 쫄이 우선. 거대 골렘은 황제의 힘이 흐를 때까지 면역 – 그때 딜러는 전력으로 보스."
L["WILLE DES KAISERS: Adds zuerst! Mut nur von hinten angreifen!"] = "황제의 의지: 쫄 먼저! 용기는 뒤에서만 공격!"
L["Nicht vor die Kolosse, Wut-Adds sammeln und AoE."] = "거대 골렘 앞 금지, 분노 쫄 모아서 광역."
L["Wille des Kaisers"] = "황제의 의지"
L["Totenkopf auf Stärke, Kreuz auf Mut, Viereck auf das nächste Wut-Add."] = "해골은 힘, 가위표는 용기, 네모는 다음 분노 쫄."
L["Schlacht um Orgrimmar"] = "오그리마 공성전"
L["Immerseus + Sha-Pfützen und Verunreinigte Pfützen"] = "이머서스 + 샤 웅덩이와 오염된 웅덩이"
L["- Shablitz: Wasserblasen auf Spielern -> verteilen, Pfützen meiden."] = "- 샤 화살: 플레이어에게 물방울 -> 산개, 웅덩이 피하기."
L["- Wirbeln: Wasserwirbel -> nicht in die Linien laufen."] = "- 소용돌이: 물 소용돌이 -> 경로에 들어가지 말 것."
L["- Ätzender Stoß: Frontalangriff -> Tankwechsel."] = "- 부식성 강타: 전방 공격 -> 탱 교대."
L["- Teilung (Splitphase): Immerseus zerfällt -> DPS tötet Sha-Pfützen, Heiler heilen Verunreinigte Pfützen."] = "- 분열 (분리 단계): 이머서스가 분열 -> 딜러는 샤 웅덩이 처치, 힐러는 오염된 웅덩이 힐."
L["Taktik: Je mehr Pfützen erledigt werden, desto weniger Verderbnis kehrt zurück. Phasenweise zügig wechseln."] = "공략: 처리한 웅덩이가 많을수록 돌아오는 타락이 줄어듦. 단계별로 빠르게 전환."
L["IMMERSEUS: Teilung: DPS auf Sha-Pfützen, Heiler auf Verunreinigte!"] = "이머서스: 분열: 딜러는 샤 웅덩이, 힐러는 오염된 웅덩이!"
L["Wirbel meiden, Tankwechsel bei Ätzendem Stoß."] = "소용돌이 피하기, 부식성 강타 시 탱 교대."
L["Die gefallenen Beschützer: Rook Steinzeh, He Sanftfuß, Sun Sanftherz"] = "타락한 수호자: 루크 스톤토, 허 소프트풋, 선 텐더하트"
L["- Verzweiflungsmaßnahmen (66 % und 33 %): jeder Beschützer startet eine Sonderphase -> Mechanik schnell abarbeiten."] = "- 필사의 조치 (66 %와 33 %): 수호자마다 특수 단계 시작 -> 기믹을 빠르게 처리."
L["- Rook: Elendverkörperung, Schwermut und Trauer -> Adds töten."] = "- 루크: 불행의 화신, 우울함, 슬픔 -> 쫄 처치."
L["- He: Mal der Pein -> Kette von Spieler zu Spieler, an Tanks weitergeben."] = "- 허: 고통의 징표 -> 플레이어에서 플레이어로 사슬, 탱커에게 넘기기."
L["- Sun: Wort der Schatten: Bann -> bannen; Dunkle Meditation -> in das Feld stellen."] = "- 선: 어둠의 권능: 파멸 -> 해제; 어둠의 명상 -> 장 안에 서기."
L["- Erneuerung: getötete Beschützer stehen wieder auf -> alle drei möglichst gleichzeitig töten."] = "- 갱신: 처치된 수호자가 다시 일어남 -> 셋을 최대한 동시에 처치."
L["Taktik: Alle drei Bosse gleichmäßig runterschaden, gegen Ende synchron töten. Unterbrecher und Banner einteilen."] = "공략: 보스 셋을 균등하게 딜, 막판에 동시 처치. 차단과 깃발 배정."
L["GEFALLENE BESCHÜTZER: Gleichmäßig schaden, zeitgleich töten!"] = "타락한 수호자: 균등 딜, 동시 처치!"
L["Wort der Schatten bannen, Mal der Pein an Tanks geben."] = "어둠의 권능 해제, 고통의 징표는 탱커에게."
L["Gefallene Beschützer"] = "타락한 수호자"
L["Je ein Symbol auf Rook, He und Sun für Tank- und Schadenszuteilung."] = "루크, 허, 선에게 각각 징표 하나, 탱커와 딜 배정용."
L["Norushen + Amalgam der Verderbnis"] = "노루셴 + 타락의 융합체"
L["- Blick nach innen: Spieler betreten das Reich der Verderbnis -> Prüfung (Tank, Heiler oder DPS) bestehen."] = "- 내면 들여다보기: 플레이어가 타락의 영역에 입장 -> 시험 (탱커, 힐러 또는 딜러) 통과."
L["- Verderbnis: Balken der Spieler -> Prüfungen absolvieren, um Verderbnis zu senken."] = "- 타락: 플레이어 게이지 -> 시험을 완료해 타락 감소."
L["- Blinder Hass: Strahl um den Boss -> ausweichen."] = "- 맹목적인 증오: 보스 주변 광선 -> 피하기."
L["- Manifestationen der Verderbnis: Adds -> schnell töten, Rest-Verderbnis meiden."] = "- 타락의 현신: 쫄 -> 빠르게 처치, 남은 타락 피하기."
L["- Phase ab 50 %: zusätzliche Adds -> Cooldowns."] = "- 50 % 이후 단계: 추가 쫄 -> 생존기."
L["Taktik: Raid gestaffelt in Prüfungen schicken, Tanks wechseln über ihre eigene Prüfung. Amalgam mittig tanken."] = "공략: 공대를 순차적으로 시험에 보냄, 탱커는 자신의 시험으로 교대. 융합체는 중앙에서 탱킹."
L["NORUSHEN: Prüfungen bestehen! Blinden Hass meiden!"] = "노루셴: 시험 통과! 맹목적인 증오 피하기!"
L["Manifestationen schnell töten. Tanks wechseln über Prüfung."] = "현신은 빠르게 처치. 탱커는 시험으로 교대."
L["Sha des Stolzes + Manifestationen des Stolzes und Reflexionen"] = "교만의 샤 + 교만의 현신과 반영"
L["- Stolz: Balken steigt bei vielen Fehlern -> bei 100 Stolz Kontrollverlust, also keine Fehler."] = "- 교만: 실수가 많으면 게이지 상승 -> 교만 100에 제어 상실, 그러니 실수 금지."
L["- Gabe der Titanen: Spieler mit Gabe stellen sich zusammen -> Macht der Titanen."] = "- 티탄의 선물: 선물 받은 플레이어끼리 모이기 -> 티탄의 힘."
L["- Mal der Arroganz: Debuff bannen gibt Stolz -> sparsam bannen."] = "- 오만의 징표: 디버프 해제 시 교만 증가 -> 아껴서 해제."
L["- Verderbte Gefängnisse: Spieler eingesperrt -> andere befreien."] = "- 타락한 감옥: 플레이어가 갇힘 -> 다른 플레이어가 풀어주기."
L["- Anschwellender Stolz: Raidschaden steigt mit Stolz -> Cooldowns."] = "- 부푸는 교만: 교만에 따라 공격대 피해 증가 -> 생존기."
L["Taktik: Stolz der Spieler niedrig halten, Gabe-Spieler zusammen. Bei 30 % Entfesselt: Cooldowns und Kampfrausch."] = "공략: 플레이어 교만을 낮게 유지, 선물 받은 플레이어 모이기. 30 % 해방 시: 생존기와 블러드."
L["SHA DES STOLZES: Stolz niedrig! Gabe der Titanen zusammen!"] = "교만의 샤: 교만 낮게! 티탄의 선물 모이기!"
L["Gefängnisse befreien, Manifestationen töten."] = "감옥 풀어주기, 현신 처치."
L["Galakras + Drachenmal-Truppen und Türme"] = "갈라크라스 + 용아귀 부대와 탑"
L["- Wellen von Adds: Fahnenträger, Knochenbrecher, Proto-Drachen -> Fahnen zuerst, Adds priorisieren."] = "- 쫄 웨이브: 깃발 운반자, 뼈분쇄자, 원시비룡 -> 깃발 먼저, 쫄 우선순위."
L["- Türme: Gruppen erobern die Türme und töten Verteidiger -> Flugabwehrkanonen benutzen."] = "- 탑: 그룹이 탑을 점령하고 수비병 처치 -> 대공포 사용."
L["- Kanonen: Spieler schießen auf Galakras -> bis er landet."] = "- 대포: 플레이어가 갈라크라스에게 사격 -> 착지할 때까지."
L["- Phase 2: Galakras landet -> Flammen von Galakrond teilen, Tankwechsel."] = "- 2단계: 갈라크라스 착지 -> 갈라크론드의 불꽃 분담, 탱 교대."
L["Taktik: Turmgruppen fest einteilen, Rest hält Adds unten. Ab Landung alle Cooldowns, Schadensteilung bei Flammen."] = "공략: 탑 그룹 고정 배정, 나머지는 아래에서 쫄 정리. 착지부터 모든 생존기, 불꽃 피해 분담."
L["GALAKRAS: Turmgruppen los! Fahnenträger zuerst!"] = "갈라크라스: 탑 그룹 출발! 깃발 운반자 먼저!"
L["Phase 2: Flammen teilen, Tankwechsel. Cooldowns!"] = "2단계: 불꽃 분담, 탱 교대. 생존기!"
L["Eiserner Koloss (Angriffs- und Belagerungsmodus)"] = "철갑 거대전차 (공격 모드와 공성 모드)"
L["- Laserverbrennung: Tankdebuff -> Tankwechsel."] = "- 레이저 화상: 탱커 디버프 -> 탱 교대."
L["- Krabbelminen: explodieren -> von Spielern auslösen lassen."] = "- 기어가는 지뢰: 폭발 -> 플레이어가 터뜨리기."
L["- Mörser und Bohrer: Bodeneffekte -> ausweichen."] = "- 박격포와 드릴: 바닥 효과 -> 피하기."
L["- Belagerungsmodus: Schockimpuls (Rückstoß), Explosiver Teer, Schneidelaser -> Laser durch Teer führen."] = "- 공성 모드: 충격 파동 (넉백), 폭발성 타르, 절단 레이저 -> 레이저를 타르 위로 유도."
L["- Seismische Aktivität: Raidschaden -> Cooldowns."] = "- 지진 활동: 공격대 피해 -> 생존기."
L["Taktik: Angriffsmodus voll Schaden, Belagerungsmodus Positionen halten. Minen kontrolliert sprengen."] = "공략: 공격 모드에선 풀딜, 공성 모드에선 위치 유지. 지뢰는 계획적으로 터뜨리기."
L["EISERNER KOLOSS: Minen sprengen, Laser durch Teer!"] = "철갑 거대전차: 지뢰 터뜨리기, 레이저는 타르 위로!"
L["Tankwechsel bei Laserverbrennung. Rückstoß beachten."] = "레이저 화상 시 탱 교대. 넉백 주의."
L["Dunkelschamanen der Kor'kron: Erdbrecher Haromm und Wellenbinderin Kardris (auf Wölfen)"] = "코르크론 암흑 주술사: 대지파괴자 하롬과 파도결속사 카드리스 (늑대 탑승)"
L["- Gemeinsame Phasen: bei bestimmten Gesundheitswerten erhalten beide neue Fähigkeiten -> gleichmäßig schaden."] = "- 공유 단계: 특정 생명력에서 둘 다 새 능력 획득 -> 균등하게 딜."
L["- Giftsturm / Faulstrom: Wirbel und Strahlen -> ausweichen."] = "- 독성 폭풍 / 부패의 물결: 소용돌이와 광선 -> 피하기."
L["- Aschewand: Mauer bewegt sich -> Lücke finden."] = "- 잿더미 벽: 벽이 움직임 -> 틈 찾기."
L["- Eisernes Grab: Gefängnisse -> herauslaufen."] = "- 강철 무덤: 감옥 -> 빠져나오기."
L["- Fallende Asche: großer Einschlag -> gemeinsam soaken."] = "- 떨어지는 잿더미: 큰 충격 -> 함께 맞기."
L["Taktik: Beide Schamanen nah beieinander tanken, Spaltung durch den Raid. Wölfe nicht wegziehen."] = "공략: 두 주술사를 가까이 붙여 탱킹, 공대 쪽으로 쪼개기 금지. 늑대는 떼어놓지 말 것."
L["DUNKELSCHAMANEN: Gleichmäßig schaden! Fallende Asche soaken!"] = "암흑 주술사: 균등 딜! 떨어지는 잿더미 맞기!"
L["Giftsturm und Aschewand meiden."] = "독성 폭풍과 잿더미 벽 피하기."
L["General Nazgrim + Kor'kron-Adds"] = "장군 나즈그림 + 코르크론 쫄"
L["- Haltungen: Kampfhaltung, Berserkerhaltung (mehr Schaden), Verteidigungshaltung -> bei Verteidigung keine Angriffe (gibt Wut)."] = "- 태세: 전투 태세, 광포한 태세 (피해 증가), 방어 태세 -> 방어 태세 중엔 공격 금지 (분노 제공)."
L["- Rüstungsspaltender Schlag: Tankdebuff -> Tankwechsel."] = "- 방어구 가르기: 탱커 디버프 -> 탱 교대."
L["- Heroische Schockwelle: Sprung -> Zone meiden."] = "- 영웅의 충격파: 도약 -> 구역 피하기."
L["- Kor'kron-Banner: Adds verstärkt -> Banner töten."] = "- 코르크론 깃발: 쫄 강화 -> 깃발 처치."
L["- Adds (Klingenträger, Bogenweber, Assassinen, Kriegsschamanen) -> Bogenweber unterbrechen, Schamanen zuerst."] = "- 쫄 (칼날 전사, 활술사, 암살자, 전쟁 주술사) -> 활술사 차단, 주술사 먼저."
L["Taktik: Adds zuerst, bei Verteidigungshaltung nur Adds angreifen. Kriegsgesang mit Cooldowns."] = "공략: 쫄 먼저, 방어 태세 중엔 쫄만 공격. 전쟁의 노래에 생존기."
L["NAZGRIM: Verteidigungshaltung: nicht angreifen! Adds zuerst!"] = "나즈그림: 방어 태세: 공격 금지! 쫄 먼저!"
L["Banner töten, Bogenweber unterbrechen. Tankwechsel."] = "깃발 처치, 활술사 차단. 탱 교대."
L["Nazgrim (Adds)"] = "나즈그림 (쫄)"
L["Totenkopf auf Kriegsschamanen, Kreuz auf Bogenweber, Viereck/Mond auf weitere Adds."] = "해골은 전쟁 주술사, 가위표는 활술사, 네모/달은 나머지 쫄."
L["Malkorok"] = "말코록"
L["- Bogenschlag: drei Schläge mit Lücken -> zwischen den Bögen stehen."] = "- 호 강타: 틈이 있는 세 번의 강타 -> 호 사이에 서기."
L["- Odem von Y'Shaarj: folgt Bogenschlag -> Sicherheitszonen nutzen."] = "- 이샤라즈의 숨결: 호 강타 뒤에 따라옴 -> 안전 구역 이용."
L["- Alte Miasmen: Heilung wird zu Schild -> überheilen ist erwünscht."] = "- 고대의 독기: 치유가 보호막으로 바뀜 -> 오버힐 환영."
L["- Blutraserei: Energie freigesetzt -> wegschieben, Implosion soaken."] = "- 피의 광란: 에너지 방출 -> 밀어내고 내파 맞기."
L["- Tödlicher Schlag: Tankdebuff -> Tankwechsel."] = "- 죽음의 일격: 탱커 디버프 -> 탱 교대."
L["Taktik: Raid locker verteilen, Bogenzonen beachten. Heiler halten Schilde."] = "공략: 공대 느슨하게 산개, 호 구역 주의. 힐러는 보호막 유지."
L["MALKOROK: In die sicheren Zonen nach Bogenschlag!"] = "말코록: 호 강타 후 안전 구역으로!"
L["Tankwechsel. Implosionen soaken."] = "탱 교대. 내파 맞기."
L["Schätze Pandarias (Kisten mit Mogu- und Mantis-Adds)"] = "판다리아의 전리품 (모구와 사마귀 쫄이 든 상자)"
L["- Kisten öffnen: kleine, mittlere, große -> Adds je nach Größe kontrolliert freisetzen."] = "- 상자 열기: 소형, 중형, 대형 -> 크기에 맞춰 쫄을 계획적으로 풀기."
L["- Zeitlimit: Sicherheitssystem -> Fortschritt rechtzeitig erzielen."] = "- 시간 제한: 보안 시스템 -> 제때 진행도 달성."
L["- Mogu-Kisten: Steinstatuen und Zauberer -> unterbrechen, Bodeneffekte meiden."] = "- 모구 상자: 돌 조각상과 주술사 -> 차단, 바닥 효과 피하기."
L["- Mantis-Kisten: Windklingen und Bernfallen -> ausweichen, Fokus."] = "- 사마귀 상자: 바람칼날과 호박석 덫 -> 피하기, 점사."
L["- Sha-Gegenstände: Adds mit gefährlichen Effekten -> priorisieren."] = "- 샤 물품: 위험한 효과를 지닌 쫄 -> 우선 처치."
L["Taktik: Raid in zwei Gruppen teilen, Kisten gleichmäßig öffnen. Adds sauber nach Priorität."] = "공략: 공대를 두 그룹으로 나누고 상자를 균등하게 열기. 쫄은 우선순위대로 깔끔하게."
L["SCHÄTZE: Kisten kontrolliert öffnen, Adds nach Priorität!"] = "전리품: 상자는 계획적으로 열기, 쫄은 우선순위대로!"
L["Zauber unterbrechen, Bodeneffekte meiden."] = "주문 차단, 바닥 효과 피하기."
L["Thok der Blutrünstige + Gefangene"] = "피에 굶주린 토크 + 포로"
L["- Furchteinflößendes Brüllen: Tankdebuff -> Tankwechsel."] = "- 공포의 포효: 탱커 디버프 -> 탱 교대."
L["- Schwanzpeitsche: hinter Thok -> nicht dahinter stehen."] = "- 꼬리 채찍: 토크 뒤쪽 -> 뒤에 서지 말 것."
L["- Betäubendes Kreischen: Raidschaden -> Cooldowns."] = "- 귀청을 찢는 비명: 공격대 피해 -> 생존기."
L["- Blutraserei: Thok fixiert einen Spieler -> kiten."] = "- 피의 광란: 토크가 플레이어 한 명을 고정 -> 카이팅."
L["- Gefängnisschlüssel: Gefangene befreien -> Thok erhält neue Fähigkeiten."] = "- 감옥 열쇠: 포로 해방 -> 토크가 새 능력 획득."
L["Taktik: Phase 1 Schaden, Phase 2 kiten. Gefangene nach Plan befreien."] = "공략: 1단계 딜, 2단계 카이팅. 포로는 계획대로 해방."
L["THOK: Fixierte Spieler kiten! Nicht hinter Thok stehen!"] = "토크: 고정된 플레이어는 카이팅! 토크 뒤에 서지 말 것!"
L["Tankwechsel bei Brüllen. Cooldowns bei Kreischen."] = "포효 시 탱 교대. 비명 시 생존기."
L["Belagerungsingenieur Rußschmied + Fließband-Waffen"] = "공성기술자 블랙퓨즈 + 컨베이어 벨트 무기"
L["- Fließband: Waffen kommen auf das Band -> Spieler zerstören sie."] = "- 컨베이어 벨트: 무기가 벨트에 올라옴 -> 플레이어가 파괴."
L["- Automatisierte Schredder: Adds -> Offtank, schnell töten."] = "- 자동 분쇄기: 쫄 -> 부탱, 빠르게 처치."
L["- Elektrostatische Ladung: Tankdebuff -> Tankwechsel."] = "- 정전기 충전: 탱커 디버프 -> 탱 교대."
L["- Magnetzerquetschung: zieht Spieler -> Abstand halten."] = "- 자력 분쇄: 플레이어를 끌어당김 -> 거리 유지."
L["- Laser und Minen: Bodeneffekte -> ausweichen."] = "- 레이저와 지뢰: 바닥 효과 -> 피하기."
L["Taktik: Feste Fließband-Gruppe, Rest auf Boss und Schredder."] = "공략: 컨베이어 벨트 고정 그룹, 나머지는 보스와 분쇄기."
L["RUSSSCHMIED: Fließband-Gruppe los! Schredder töten!"] = "블랙퓨즈: 벨트 그룹 출발! 분쇄기 처치!"
L["Tankwechsel bei Ladung. Laser und Minen meiden."] = "충전 시 탱 교대. 레이저와 지뢰 피하기."
L["Getreue der Klaxxi (9 Getreue, je 3 gleichzeitig)"] = "클락시 용사 (용사 9명, 동시에 3명씩)"
L["- Nachfolge: stirbt ein Getreuer, kommt der nächste -> Reihenfolge festlegen."] = "- 계승: 용사 하나가 죽으면 다음 용사 등장 -> 순서 정하기."
L["- Essenzen: tote Getreue hinterlassen Bernstein -> Spieler übernehmen Fähigkeiten."] = "- 정수: 죽은 용사가 호박석을 남김 -> 플레이어가 능력을 이어받음."
L["- Diverse Mechaniken: Kegel, Pfützen, Fixierungen -> ausweichen bzw. kiten."] = "- 다양한 기믹: 부채꼴, 웅덩이, 고정 -> 피하거나 카이팅."
L["- Tankdebuffs: Tankwechsel nach Stapeln."] = "- 탱커 디버프: 중첩 후 탱 교대."
L["Taktik: Getreue nach Plan töten, Essenzen verteilen. Raid passt sich den aktiven Getreuen an."] = "공략: 용사는 계획대로 처치, 정수 분배. 공대는 활성 용사에 맞춰 대응."
L["KLAXXI: Ziel nach Symbol! Essenzen aufnehmen!"] = "클락시: 징표대로 타겟! 정수 획득!"
L["Kegeln und Pfützen ausweichen. Tankwechsel."] = "부채꼴과 웅덩이 피하기. 탱 교대."
L["Getreue der Klaxxi"] = "클락시 용사"
L["Totenkopf zuerst, dann Kreuz und Viereck für die nächsten Getreuen."] = "해골 먼저, 그다음 가위표와 네모로 다음 용사들."
L["Garrosh Höllschrei + Kriegsbringer, Wolfsreiter, Belagerungsingenieure"] = "가로쉬 헬스크림 + 전쟁인도자, 늑대기수, 공성 기술자"
L["- Phase 1: Wolfsreiter (Kettenblitz/Heilung) -> unterbrechen; Belagerungsingenieure -> Eisensterne verhindern."] = "- 1단계: 늑대기수 (연쇄 번개/치유) -> 차단; 공성 기술자 -> 강철 별 저지."
L["- Entweihen: Schwert erzeugt Zone -> Schwert zerstören."] = "- 모독: 검이 구역 생성 -> 검 파괴."
L["- Zwischenphase: Reich von Y'Shaarj -> Adds töten, Vernichten meiden."] = "- 중간 단계: 이샤라즈의 영역 -> 쫄 처치, 섬멸 피하기."
L["- Phase 2: Berührung von Y'Shaarj (Gedankenkontrolle) -> kontrollieren, nicht töten."] = "- 2단계: 이샤라즈의 손길 (정신 지배) -> 군중 제어, 죽이지 말 것."
L["- Phase 3: Verstärkte Fähigkeiten -> Cooldowns."] = "- 3단계: 강화된 능력 -> 생존기."
L["Taktik: Adds priorisieren, Wolfsreiter unterbrechen. Ab Phase 2 Gedankenkontrolle kontrollieren."] = "공략: 쫄 우선, 늑대기수 차단. 2단계부터 정신 지배는 군중 제어."
L["GARROSH: Wolfsreiter unterbrechen! Schwerter zerstören!"] = "가로쉬: 늑대기수 차단! 검 파괴!"
L["Gedankenkontrolle kontrollieren. Phase 3: Cooldowns."] = "정신 지배는 군중 제어. 3단계: 생존기."
L["Garrosh (Adds)"] = "가로쉬 (쫄)"
L["Totenkopf/Kreuz auf Wolfsreiter, Viereck/Mond auf weitere Adds."] = "해골/가위표는 늑대기수, 네모/달은 나머지 쫄."
L["Terrasse des Endlosen Frühlings"] = "영원한 봄의 정원"
L["Beschützer des Endlosen: Beschützer Kaolan, Ältester Regail, Älteste Asani"] = "영원한 수호자: 수호자 카올란, 장로 레가일, 장로 아사니"
L["- Verderbnis: stirbt ein Beschützer, werden die anderen verderbt und stärker -> Tötungsreihenfolge festlegen."] = "- 타락: 수호자 하나가 죽으면 나머지가 타락해 강해짐 -> 처치 순서 정하기."
L["- Regail: Blitzgefängnis auf Spielern -> verteilen; Blitzsturm als Raidschaden."] = "- 레가일: 플레이어에게 번개 감옥 -> 산개; 번개 폭풍은 공격대 피해."
L["- Asani: Reinigende Wasser heilen die Gegner -> Bosse aus der Pfütze ziehen; Wasserblitz unterbrechen; Sha-Kugeln töten."] = "- 아사니: 정화의 물이 적을 치유 -> 보스를 웅덩이 밖으로 끌기; 물 화살 차단; 샤 구슬 처치."
L["- Kaolan: Berührung des Sha (Schaden auf Spielern) und verderbter Boden -> Heilung halten, aus dem Boden raus."] = "- 카올란: 샤의 손길 (플레이어에게 피해)과 타락한 바닥 -> 힐 유지, 바닥에서 나오기."
L["Taktik: Bosse getrennt tanken, Fokus auf das Ziel der Reihenfolge, Unterbrecher auf Asani. Nach jedem Tod Cooldowns für die stärkeren Restbosse."] = "공략: 보스는 따로 탱킹, 처치 순서 대상에 점사, 아사니에 차단 담당. 하나 죽을 때마다 강해진 남은 보스에 생존기."
L["BESCHÜTZER: Fokusziel nach Symbol! Asani unterbrechen, aus Wasser ziehen!"] = "영원한 수호자: 징표대로 점사! 아사니 차단, 물 밖으로 끌기!"
L["Bei Blitzgefängnis verteilen, verderbten Boden verlassen."] = "번개 감옥 시 산개, 타락한 바닥 벗어나기."
L["Beschützer des Endlosen"] = "영원한 수호자"
L["Totenkopf zuerst, Kreuz als Zweites, Viereck zuletzt (Reihenfolge der Beschützer)."] = "해골 먼저, 가위표 두 번째, 네모 마지막 (수호자 처치 순서)."
L["Tsulong (Nacht feindlich, Tag freundlich)"] = "술롱 (밤에는 적대, 낮에는 우호)"
L["- Nacht: Schattenodem auf den Tank -> Tankwechsel; Albträume als Bodeneffekte -> ausweichen."] = "- 밤: 탱커에게 그림자 숨결 -> 탱 교대; 바닥 효과로 악몽 -> 피하기."
L["- Tag: Tsulong wird freundlich -> Heiler heilen Tsulong hoch, DPS auf Adds."] = "- 낮: 술롱이 우호적으로 변함 -> 힐러는 술롱을 힐, 딜러는 쫄."
L["- Verkörperter Schrecken und Schreckensbrut (Tag): Adds -> zügig töten."] = "- 공포의 화신과 공포의 피조물 (낮): 쫄 -> 빠르게 처치."
L["- Instabiler Sha: Adds laufen zu Tsulong und heilen/stärken ihn -> abfangen und töten."] = "- 불안정한 샤: 쫄이 술롱에게 가서 치유/강화 -> 가로막고 처치."
L["- Sonnenstrahl: entfernt Schreckensdebuffs -> bei Bedarf hineinstellen."] = "- 햇살: 공포 디버프 제거 -> 필요 시 안에 서기."
L["Taktik: Nacht = Boss schaden, Tag = Tsulong heilen und Adds töten. Der Kampf endet, wenn Tsulong geheilt bzw. die Sha-Kraft gebrochen ist."] = "공략: 밤 = 보스 딜, 낮 = 술롱 힐하고 쫄 처치. 술롱이 다 치유되거나 샤의 힘이 꺾이면 전투 종료."
L["TSULONG: Nacht Schaden, Tag heilen! Instabile Sha abfangen!"] = "술롱: 밤엔 딜, 낮엔 힐! 불안정한 샤 가로막기!"
L["Tankwechsel bei Schattenodem, Sonnenstrahl gegen Schrecken."] = "그림자 숨결 시 탱 교대, 공포는 햇살로 해제."
L["Lei Shi + Belebte Beschützer"] = "레이 스 + 생기 넘치는 수호자"
L["- Sprühen: stapelnder Frostschaden auf dem Tank -> Tankwechsel."] = "- 분사: 탱커에게 냉기 피해 중첩 -> 탱 교대."
L["- Verschwindet!: Lei Shi stößt alle zurück -> gegen den Wind zu ihr laufen, nicht vom Rand fallen."] = "- 사라져라!: 레이 스가 모두를 밀쳐냄 -> 바람을 거슬러 그녀에게 달려가기, 가장자리에서 떨어지지 말 것."
L["- Beschützen (bei 80/60/40/20 %): Belebte Beschützer + Schild -> Adds töten."] = "- 보호 (80/60/40/20 %): 생기 넘치는 수호자 + 보호막 -> 쫄 처치."
L["- Verstecken: Lei Shi wird unsichtbar -> mit Flächenschaden finden und angreifen."] = "- 숨기: 레이 스가 투명해짐 -> 광역으로 찾아서 공격."
L["Taktik: Boss mittig, Raid nah dran, Adds schnell töten. Bei Verstecken AoE, bis sie auftaucht."] = "공략: 보스는 중앙, 공대는 가까이, 쫄은 빠르게 처치. 숨기 시 나타날 때까지 광역."
L["LEI SHI: Adds bei Beschützen sofort töten! Bei Verstecken AoE!"] = "레이 스: 보호 시 쫄 즉시 처치! 숨기 시 광역!"
L["Gegen den Rückstoß anlaufen. Tankwechsel nach Sprühen."] = "넉백에 맞서 달리기. 분사 후 탱 교대."
L["Sha der Angst + Schreckensbrut und Wächter auf den äußeren Plattformen"] = "공포의 샤 + 공포의 피조물과 외곽 단상의 수호병"
L["- Odem der Angst: Furcht für alle außerhalb des Lichts -> in der Lichtmauer des Champions stehen."] = "- 공포의 숨결: 빛 밖에 있는 모두에게 공포 -> 용사의 빛의 벽 안에 서기."
L["- Ominöses Gackern: schleudert Spieler auf äußere Plattformen -> dort Wächter besiegen und zurück."] = "- 불길한 웃음: 플레이어를 외곽 단상으로 날려보냄 -> 그곳에서 수호병 처치 후 복귀."
L["- Dreschen: hoher Tankschaden -> Tanks mit Cooldowns und Heilfokus."] = "- 타작: 큰 탱커 피해 -> 탱커 생존기와 힐 집중."
L["- Champion des Lichts: Spieler mit Licht-Buff hält die Lichtmauer -> Buff nicht verlieren."] = "- 빛의 용사: 빛 버프를 가진 플레이어가 빛의 벽 유지 -> 버프 잃지 말 것."
L["Taktik: Raid in der Lichtmauer vor dem Boss stapeln; Gruppen auf den äußeren Plattformen erledigen ihren Wächter und kehren zurück."] = "공략: 공대는 보스 앞 빛의 벽 안에 뭉치기; 외곽 단상 그룹은 수호병 처치 후 복귀."
L["Heroisch: Phase 2 mit Furchtsaat, Umgekehrten Schatten und Aufteilung auf Plattformen."] = "영웅: 2단계에서 공포의 씨앗, 반전된 그림자, 단상별 분배."
L["SHA DER ANGST: Im Licht bleiben! Plattform-Gruppen Wächter töten!"] = "공포의 샤: 빛 안에 머물기! 단상 그룹은 수호병 처치!"
L["Tanks Cooldowns bei Dreschen. Champion hält die Lichtmauer."] = "타작 시 탱커 생존기. 용사는 빛의 벽 유지."
L["Thron des Donners"] = "천둥의 왕좌"
L["Jin'rokh der Zerstörer"] = "파괴자 진로크"
L["- Statischer Ausbruch: Tankdebuff -> Tankwechsel."] = "- 정전기 폭발: 탱커 디버프 -> 탱 교대."
L["- Fokussierter Blitz: Kugel verfolgt einen Spieler -> wegkiten, nicht durch Wasser führen."] = "- 집중된 번개: 구슬이 플레이어 한 명을 추적 -> 멀리 카이팅, 물 위로 끌지 말 것."
L["- Donnernder Wurf: Tank wird auf eine Statue geworfen, es entsteht leitfähiges Wasser -> Wasser gibt Buff, aber bei Blitzsturm wird es elektrisiert."] = "- 천둥 투척: 탱커가 석상으로 던져지고 전도성 물이 생김 -> 물은 버프를 주지만 번개 폭풍 때 감전됨."
L["- Blitzsturm: Raidschaden -> aus dem elektrisierten Wasser raus, Heiler-Cooldowns."] = "- 번개 폭풍: 공격대 피해 -> 감전된 물에서 나오기, 힐러 생존기."
L["- Ionisierung (heroisch): Debuff verteilt Schaden -> vor Ablauf weit verteilen."] = "- 이온화 (영웅): 디버프가 피해를 퍼뜨림 -> 만료 전에 넓게 산개."
L["Taktik: Boss nacheinander bei den Statuen tanken, damit Pfützen nicht den ganzen Raum füllen. Fokus-Blitz-Ziel kitet."] = "공략: 보스를 석상마다 차례로 탱킹해 웅덩이가 방 전체를 덮지 않게. 집중된 번개 대상은 카이팅."
L["JIN'ROKH: Blitzkugel wegkiten! Raus aus elektrisiertem Wasser!"] = "진로크: 번개 구슬 카이팅! 감전된 물에서 나오기!"
L["Tankwechsel bei Statischem Ausbruch. Wasser nur gezielt nutzen."] = "정전기 폭발 시 탱 교대. 물은 계획적으로만 사용."
L["Horridon + Stämme (Farraki, Gurubashi, Drakkari, Amani) und Kriegsgott Jalak"] = "호리돈 + 부족 (파라키, 구루바시, 드락카리, 아마니)과 전쟁신 잘라크"
L["- Dreifacher Stich: Tankdebuff -> Tankwechsel."] = "- 삼중 찌르기: 탱커 디버프 -> 탱 교대."
L["- Ansturm + Doppelter Hieb: Horridon stürmt auf einen Spieler -> Spieler weicht aus, Raid nicht vor/hinter ihm stehen."] = "- 돌진 + 이중 베기: 호리돈이 플레이어에게 돌진 -> 대상은 피하고, 공대는 앞/뒤에 서지 말 것."
L["- Dinomant pro Tor: hinterlässt eine Kugel der Kontrolle -> anklicken, um Horridon zu betäuben (Schadensfenster)."] = "- 문마다 공룡조련사: 지배의 구슬을 남김 -> 클릭해 호리돈 기절 (딜 타이밍)."
L["- Stammes-Adds: Steinblick-Basilisken (Betäubung), Giftpriester, Amani-Schamanen -> Zauber unterbrechen, Verhexungen bannen."] = "- 부족 쫄: 돌시선 바실리스크 (기절), 독 사제, 아마니 주술사 -> 주문 차단, 사술 해제."
L["- Phase 2: Kriegsgott Jalak springt in den Kampf -> Jalak schnell töten, Horridon wird sonst wütend."] = "- 2단계: 전쟁신 잘라크가 전투에 합류 -> 잘라크 빠르게 처치, 아니면 호리돈 격노."
L["Taktik: Boss mittig, Adds an den Toren abfangen und töten; feste Unterbrecher, Dinomant priorisieren und Kugel nutzen."] = "공략: 보스는 중앙, 쫄은 문에서 가로막아 처치; 차단 고정 배정, 공룡조련사 우선 처치 후 구슬 사용."
L["HORRIDON: Dinomant töten und Kugel klicken! Adds unterbrechen!"] = "호리돈: 공룡조련사 잡고 구슬 클릭! 쫄 차단!"
L["Ansturm ausweichen, Tankwechsel. Phase 2: Jalak zuerst!"] = "돌진 피하기, 탱 교대. 2단계: 잘라크 먼저!"
L["Horridon (Unterbrechen)"] = "호리돈 (차단)"
L["Totenkopf auf den Dinomanten, Kreuz/Viereck/Mond auf Zauberer-Adds für feste Unterbrecher."] = "해골은 공룡조련사, 가위표/네모/달은 주문 쓰는 쫄에 차단 고정 배정용."
L["Ältestenrat: Frostkönig Malakk, Kazra'jin, Sul der Sandkriecher, Hohepriesterin Mar'li"] = "원로회: 서리왕 말라크, 카즈라진, 모래군주 술, 대여사제 마를리"
L["- Gara'jals Geist besetzt einen Ältesten: er lädt Dunkle Macht auf und verstärkt sich -> Besessenen bevorzugt angreifen, nach Schaden wechselt der Geist."] = "- 가라잘의 혼령이 원로 하나에 빙의: 어둠의 힘을 충전하며 강해짐 -> 빙의된 원로 우선 공격, 피해를 입히면 혼령이 옮겨감."
L["- Malakk: Frostbiss/Beißende Kälte -> Spieler verteilen bzw. Frostbiss-Stapel teilen; Tankwechsel bei Frostigem Angriff."] = "- 말라크: 동상/살을 에는 추위 -> 산개 또는 동상 중첩 분담; 서리 공격 시 탱 교대."
L["- Sul: Treibsand -> nicht hineinlaufen; Sandsturm verbindet Treibsand zu Adds -> Adds töten."] = "- 술: 유사 -> 들어가지 말 것; 모래 폭풍이 유사를 쫄로 합침 -> 쫄 처치."
L["- Mar'li: Loa-Geister wandern zu Spielern bzw. zum Rat -> Geister schnell töten."] = "- 마를리: 로아 혼령이 플레이어나 원로회로 이동 -> 혼령 빠르게 처치."
L["- Kazra'jin: Rücksichtsloser Sturmangriff -> Aufprallzone meiden."] = "- 카즈라진: 무모한 돌진 -> 충돌 구역 피하기."
L["Taktik: Tanks halten Malakk und Kazra'jin nahe beieinander, AoE-Spaltung möglich. Tötungsreihenfolge festlegen, Dunkle Macht nie zu hoch werden lassen."] = "공략: 탱커는 말라크와 카즈라진을 가까이 붙여 광역 쪼개기 가능. 처치 순서 정하고 어둠의 힘이 너무 오르지 않게."
L["ÄLTESTENRAT: Besessenen Ältesten angreifen! Loa-Geister töten!"] = "원로회: 빙의된 원로 공격! 로아 혼령 처치!"
L["Treibsand meiden, bei Beißender Kälte verteilen."] = "유사 피하기, 살을 에는 추위 시 산개."
L["Ältestenrat"] = "원로회"
L["Totenkopf auf das erste Ziel der Reihenfolge, dann Kreuz, Viereck, Mond für die übrigen Ältesten."] = "해골은 처치 순서 첫 대상, 그다음 가위표, 네모, 달은 나머지 원로."
L["Tortos + Wirbelschildkröten und Vampirhöhlenfledermäuse"] = "토르토스 + 회오리 거북과 흡혈 동굴 박쥐"
L["- Wütender Steinatem: großer Raidschaden -> mit einem getretenen Panzer unterbrechen."] = "- 격노의 바위 숨결: 큰 공격대 피해 -> 걷어찬 등껍질로 차단."
L["- Wirbelschildkröten: getötet werden sie zu Panzern -> Panzer in Tortos treten (Panzer treten), wenn der Steinatem kommt."] = "- 회오리 거북: 처치하면 등껍질이 됨 -> 바위 숨결이 오면 등껍질을 토르토스에게 걷어차기 (등껍질 차기)."
L["- Bebenstampfer: Raidschaden und herabfallende Steine -> Steinen ausweichen, Heiler-Cooldowns."] = "- 지진 발구르기: 공격대 피해와 떨어지는 바위 -> 바위 피하기, 힐러 생존기."
L["- Fledermäuse: saugen Leben -> Offtank sammelt, AoE."] = "- 박쥐: 생명력 흡수 -> 부탱이 모으고 광역."
L["- Zuschnappender Biss: Tankschaden -> Tankwechsel nach Bedarf."] = "- 물어뜯기: 탱커 피해 -> 필요 시 탱 교대."
L["Taktik: Schildkröten kontrolliert töten, immer einen Panzer für den nächsten Atem bereit. Fledermäuse beim Offtank stapeln."] = "공략: 거북은 계획적으로 처치, 다음 숨결용 등껍질을 항상 준비. 박쥐는 부탱에게 모으기."
L["TORTOS: Panzer in Tortos treten, wenn der Steinatem kommt!"] = "토르토스: 바위 숨결이 오면 등껍질을 토르토스에게 차기!"
L["Fledermäuse zum Offtank, AoE. Fallenden Steinen ausweichen."] = "박쥐는 부탱에게, 광역. 떨어지는 바위 피하기."
L["Megaera (Hydra mit Flammen-, Frost-, Gift- und heroisch Arkankopf)"] = "메가에라 (화염, 냉기, 독, 영웅에서는 비전 머리가 있는 히드라)"
L["- Kopftod: nach jedem getöteten Kopf Raserei mit hohem Raidschaden und neuen Köpfen -> Heiler-Cooldowns pro Raserei."] = "- 머리 처치: 머리를 잡을 때마다 큰 공격대 피해의 격노와 새 머리 -> 격노마다 힐러 생존기."
L["- Flammenkopf (Asche): Debuff -> abseits des Raids bannen, Feuerpfütze bleibt liegen."] = "- 화염 머리 (잿더미): 디버프 -> 공대에서 떨어져서 해제, 불 웅덩이가 남음."
L["- Frostkopf (Eisstrom): Strahl verfolgt einen Spieler -> an den Rand kiten."] = "- 냉기 머리 (얼음 급류): 광선이 플레이어를 추적 -> 가장자리로 카이팅."
L["- Giftkopf (Säureregen): Pfützen im Raid -> verteilen und ausweichen."] = "- 독 머리 (산성 비): 공대 안에 웅덩이 -> 산개하고 피하기."
L["- Tankdebuffs der Köpfe: Tankwechsel zwischen den aktiven Köpfen."] = "- 머리별 탱커 디버프: 활성 머리 간에 탱 교대."
L["Taktik: Köpfe gezielt nacheinander töten; nach jeder Raserei neue Kopf-Kombination beachten. Ausreichend Platz für Pfützen lassen."] = "공략: 머리를 계획적으로 하나씩 처치; 격노 후 새 머리 조합 확인. 웅덩이용 공간 충분히 남기기."
L["MEGAERA: Asche abseits bannen, Eisstrom an den Rand kiten!"] = "메가에라: 잿더미는 떨어져서 해제, 얼음 급류는 가장자리로 카이팅!"
L["Nach Kopftod Raserei: Cooldowns! Säureregen ausweichen."] = "머리 처치 후 격노: 생존기! 산성 비 피하기."
L["Ji-Kun + Nester mit Jungvögeln"] = "지쿤 + 새끼 새가 있는 둥지"
L["- Nester: Eier und Jungvögel schlüpfen -> Nestgruppen fliegen hin und töten sie."] = "- 둥지: 알과 새끼 새가 부화 -> 둥지 그룹이 날아가서 처치."
L["- Krallenhieb: Tankdebuff -> Tankwechsel."] = "- 발톱 할퀴기: 탱커 디버프 -> 탱 교대."
L["- Abwind: Ji-Kun drückt Spieler weg -> gegen den Wind laufen, nicht von der Plattform fallen."] = "- 하강 기류: 지쿤이 플레이어를 밀어냄 -> 바람을 거슬러 달리기, 단상에서 떨어지지 말 것."
L["- Federkiele: Raidschaden -> Heiler-Cooldowns."] = "- 깃촉: 공격대 피해 -> 힐러 생존기."
L["- Fütterung: grüne Bälle fallen -> Spieler fangen sie, damit sie nicht die Jungen nähren."] = "- 먹이 주기: 초록 구슬이 떨어짐 -> 플레이어가 받아서 새끼가 먹지 못하게."
L["Taktik: Feste Nestgruppen (unten und oben) per Federn hinfliegen lassen. Auf der Plattform zusammen bleiben und bei Abwind laufen."] = "공략: 고정 둥지 그룹 (아래와 위)을 깃털로 날려 보내기. 단상에서는 뭉쳐 있고 하강 기류 때 달리기."
L["JI-KUN: Nestgruppe rein, Jungvögel töten! Bei Abwind dagegen laufen!"] = "지쿤: 둥지 그룹 진입, 새끼 새 처치! 하강 기류엔 거슬러 달리기!"
L["Tankwechsel bei Krallenhieb. Federkiele: Cooldowns."] = "발톱 할퀴기 시 탱 교대. 깃촉: 생존기."
L["Durumu der Vergessene + Nebel (Purpur, Azur, Bernstein)"] = "잊혀진 두루무 + 안개 (진홍, 하늘, 호박)"
L["- Lichtspektrum: Strahlen (gelb, blau, rot) decken versteckte Nebel auf -> Strahlenträger laufen langsam zu den Nebeln, Raid tötet sie."] = "- 빛의 스펙트럼: 광선 (노랑, 파랑, 빨강)이 숨은 안개를 드러냄 -> 광선 대상은 천천히 안개 쪽으로, 공대가 처치."
L["- Lebensentzug: Strahl auf einen Spieler -> andere Spieler stellen sich in die Linie, um zu teilen."] = "- 생명력 흡수: 플레이어 한 명에게 광선 -> 다른 플레이어가 경로에 서서 분담."
L["- Desintegrationsstrahl: Labyrinth aus Augen am Boden -> Strahl folgt, den Lücken folgen."] = "- 분해 광선: 바닥에 눈알 미로 -> 광선을 따라 틈으로 이동."
L["- Kraft des Willens: Rückstoß -> aus der Kegelrichtung laufen."] = "- 의지의 힘: 넉백 -> 부채꼴 방향에서 벗어나기."
L["- Verweilender Blick: Kreise am Boden -> herauslaufen."] = "- 오래 머무는 시선: 바닥에 원 -> 빠져나오기."
L["Taktik: Aufgabenverteilung bei Farbstrahlen vorher festlegen. Im Labyrinth eng zusammen der Lücke folgen."] = "공략: 색 광선 역할 분담을 미리 정하기. 미로에서는 바짝 붙어 틈을 따라가기."
L["DURUMU: Farbstrahlen zu den Nebeln, Nebel töten! Labyrinth folgen!"] = "두루무: 색 광선은 안개로, 안개 처치! 미로 따라가기!"
L["Lebensentzug teilen, Kraft des Willens ausweichen."] = "생명력 흡수 분담, 의지의 힘 피하기."
L["Primordius + Lebendige Flüssigkeiten"] = "프리모르디우스 + 살아있는 액체"
L["- Lebendige Flüssigkeit: Pfützen geben Mutationen -> zugeteilte Spieler sammeln positive Mutationen."] = "- 살아있는 액체: 웅덩이가 돌연변이 부여 -> 배정된 플레이어가 긍정적 돌연변이 수집."
L["- Schlechte Mutationen: Stapel schwächen Spieler -> nicht zu viele aufnehmen."] = "- 부정적 돌연변이: 중첩이 플레이어를 약화 -> 너무 많이 먹지 말 것."
L["- Volle Mutation: genug positive Stapel -> großer Bonus, Schaden auf den Boss erhöhen."] = "- 완전 돌연변이: 긍정 중첩이 충분하면 -> 큰 보너스, 보스 딜 증가."
L["- Primordialer Schlag / Fehlgebildetes Blut: Tankdebuff -> Tankwechsel."] = "- 원시의 일격 / 기형의 피: 탱커 디버프 -> 탱 교대."
L["- Evolution: Boss erhält zusätzliche Fähigkeiten -> Raid passt sich an, Cooldowns."] = "- 진화: 보스가 추가 능력 획득 -> 공대가 대응, 생존기."
L["Taktik: Feste Sammelgruppe für Pfützen, Rest auf den Boss. Viskose Schrecken (heroisch) separat tanken."] = "공략: 웅덩이 수집 고정 그룹, 나머지는 보스. 끈적한 공포 (영웅)는 따로 탱킹."
L["PRIMORDIUS: Sammler nehmen positive Mutationen, keine schlechten!"] = "프리모르디우스: 수집 담당은 긍정 돌연변이만, 부정 금지!"
L["Tankwechsel bei Schlag. Evolution beachten."] = "일격 시 탱 교대. 진화 주의."
L["Dunkler Animus + Animagolems (klein, mittel, groß)"] = "암흑의 애니머스 + 령 골렘 (소형, 중형, 대형)"
L["- Anima-Golems: beim Tod springt ihre Anima auf andere -> kontrolliert töten, nicht wahllos AoE."] = "- 령 골렘: 죽으면 령이 다른 골렘에게 옮겨감 -> 계획적으로 처치, 무분별한 광역 금지."
L["- Animaring: Kugeln um Spieler -> ausweichen bzw. soaken."] = "- 령 고리: 플레이어 주변 구슬 -> 피하거나 맞기."
L["- Unterbrechender Ruck: Zauberer werden unterbrochen -> rechtzeitig Zaubern stoppen."] = "- 방해의 경련: 시전자가 차단됨 -> 제때 시전 멈추기."
L["- Materietausch: tauscht Spieler -> bannen bzw. Heilung bereit."] = "- 물질 교환: 플레이어 위치 교환 -> 해제 또는 힐 대기."
L["- Explosiver Hieb: Tankschaden -> Tankwechsel."] = "- 폭발 강타: 탱커 피해 -> 탱 교대."
L["Taktik: Golems in fester Reihenfolge, Animus spät aktivieren. Animus wird mit Anima immer stärker – zügig beenden."] = "공략: 골렘은 정해진 순서로, 애니머스는 늦게 활성화. 애니머스는 령으로 계속 강해짐 – 빠르게 마무리."
L["DUNKLER ANIMUS: Golems kontrolliert, kein wildes AoE!"] = "암흑의 애니머스: 골렘은 계획적으로, 무분별한 광역 금지!"
L["Bei Unterbrechendem Ruck Zaubern stoppen. Animaring ausweichen."] = "방해의 경련 시 시전 멈추기. 령 고리 피하기."
L["Eiserner Qon + Quilen Ro'shak (Feuer), Quet'zal (Sturm), Dam'ren (Frost)"] = "강철의 콘 + 기린 로샤크 (화염), 퀘트잘 (폭풍), 담렌 (냉기)"
L["- Aufspießen: Tankdebuff -> Tankwechsel."] = "- 꿰뚫기: 탱커 디버프 -> 탱 교대."
L["- Ro'shak: Entfesselte Flamme trifft nahe Spieler -> Gruppen teilen den Schaden; brennende Asche meiden."] = "- 로샤크: 해방된 화염이 가까운 플레이어 타격 -> 그룹이 피해 분담; 불타는 잿더미 피하기."
L["- Quet'zal: Blitzsturm -> verteilen; Windsturm mit Rückstoß -> Positionen halten."] = "- 퀘트잘: 번개 폭풍 -> 산개; 넉백이 있는 바람 폭풍 -> 위치 유지."
L["- Dam'ren: Tote Zone und Gefrorenes Blut -> nur von den offenen Seiten angreifen, Eispfützen meiden."] = "- 담렌: 죽음의 지대와 얼어붙은 피 -> 열린 쪽에서만 공격, 얼음 웅덩이 피하기."
L["- Phase 4: Qon kämpft selbst (Faustschlag) -> Cooldowns."] = "- 4단계: 콘이 직접 싸움 (주먹 강타) -> 생존기."
L["Taktik: Quilen nacheinander töten, Qon begleitet die Phasen mit Speerwürfen. Feuerpfützen klein halten, Raidwechsel zügig."] = "공략: 기린을 차례로 처치, 콘은 창 투척으로 단계마다 함께함. 불 웅덩이는 작게, 공대 이동은 빠르게."
L["EISERNER QON: Ro'shak teilen, Quet'zal verteilen, Dam'ren nur offene Seiten!"] = "강철의 콘: 로샤크 분담, 퀘트잘 산개, 담렌은 열린 쪽만!"
L["Tankwechsel bei Aufspießen. Feuerpfützen meiden."] = "꿰뚫기 시 탱 교대. 불 웅덩이 피하기."
L["Zwillingsgemahlinnen: Lu'lin (Mond) und Suen (Sonne)"] = "쌍둥이 왕비: 루린 (달)과 수엔 (태양)"
L["- Nacht: Lu'lin aktiv, Bestien der Albträume und kosmischer Beschuss -> Spieler verteilen, Bestien tanken."] = "- 밤: 루린 활성, 악몽의 야수와 우주 포격 -> 산개, 야수 탱킹."
L["- Tag: Suen aktiv, Fächer der Flammen auf Tank -> Tankwechsel; Flammen der Leidenschaft meiden."] = "- 낮: 수엔 활성, 탱커에게 불꽃 부채 -> 탱 교대; 열정의 불꽃 피하기."
L["- Dämmerung: beide aktiv -> Fähigkeiten beider beachten."] = "- 황혼: 둘 다 활성 -> 둘의 능력 모두 주의."
L["- Eiskomet: erzeugt Eis -> zum Löschen von Feuer nutzen."] = "- 얼음 혜성: 얼음 생성 -> 불 끄는 데 사용."
L["- Himmelsgestalt/Sterne: Raidschaden -> Cooldowns."] = "- 천상의 형상/별: 공격대 피해 -> 생존기."
L["Taktik: Schaden phasenweise auf die aktive Gemahlin, beide Bosse gleichmäßig senken. Nachts Tank für Bestie, tags Tankwechsel."] = "공략: 단계마다 활성 왕비에게 딜, 두 보스 생명력을 균등하게. 밤엔 야수용 탱커, 낮엔 탱 교대."
L["ZWILLINGSGEMAHLINNEN: Nachts verteilen, Tags Tankwechsel!"] = "쌍둥이 왕비: 밤엔 산개, 낮엔 탱 교대!"
L["Eiskomet zum Löschen nutzen. Dämmerung: beide aktiv."] = "얼음 혜성으로 불 끄기. 황혼: 둘 다 활성."
L["Lei Shen + Leitungen (4 Quadranten)"] = "레이 션 + 도관 (4구역)"
L["- Statischer Schock: Schaden auf ein Ziel -> mitstapeln, um zu teilen."] = "- 정전기 충격: 대상 한 명에게 피해 -> 함께 뭉쳐 분담."
L["- Diffusionskette: springt zwischen Spielern -> verteilen."] = "- 확산 사슬: 플레이어 사이를 튐 -> 산개."
L["- Überladung: Ring um das Ziel -> weg vom Ziel."] = "- 과부하: 대상 주변 고리 -> 대상에게서 떨어지기."
L["- Springender Blitz: Kugeln landen im Raid -> soaken."] = "- 튀는 번개: 구슬이 공대에 떨어짐 -> 맞기."
L["- Enthaupten / Donnerschlag: Tankdebuff bzw. Speer -> Tankwechsel, Speer-Zone verlassen."] = "- 참수 / 천둥 강타: 탱커 디버프 또는 창 -> 탱 교대, 창 구역 벗어나기."
L["Taktik: Boss in einem Quadranten tanken, um die Leitung zu stärken bzw. deaktivieren; Phasen bei 65 % und 30 %. Ab Phase 3 Peitschen und Winde beachten."] = "공략: 보스를 한 구역에서 탱킹해 도관을 강화 또는 비활성화; 65 %와 30 %에 단계 전환. 3단계부터 채찍과 바람 주의."
L["Heroisch: Leitungen bleiben aktiv, Aufteilung entscheidend."] = "영웅: 도관이 활성 유지, 분배가 핵심."
L["LEI SHEN: Schock teilen, Diffusion verteilen, Überladung weg!"] = "레이 션: 충격 분담, 확산 산개, 과부하는 떨어지기!"
L["Tankwechsel bei Enthaupten. Kugeln soaken, Speer-Zone meiden."] = "참수 시 탱 교대. 구슬 맞기, 창 구역 피하기."
L["Ra-den (nur heroisch) + Anima und Vita"] = "라덴 (영웅 전용) + 령과 생명력"
L["- Materialien der Schöpfung: Ra-den wählt Anima oder Vita -> Anima-Kugeln töten oder soaken, Vita trifft den fernsten Spieler."] = "- 창조의 재료: 라덴이 령 또는 생명력 선택 -> 령 구슬은 처치하거나 맞기, 생명력은 가장 먼 플레이어 타격."
L["- Instabile Vita: springt zum entferntesten Spieler -> Abstände gezielt einteilen."] = "- 불안정한 생명력: 가장 먼 플레이어에게 튐 -> 거리 계획적으로 분배."
L["- Instabile Anima: Schaden auf nahe Spieler -> verteilen."] = "- 불안정한 령: 가까운 플레이어에게 피해 -> 산개."
L["- Verderbte Kugeln: stärken Ra-den, wenn sie ihn erreichen -> abfangen und töten."] = "- 타락한 구슬: 라덴에게 닿으면 강화 -> 가로막고 처치."
L["- Phase 2 (40 %): Ruin und Katastrophe -> starker Raidschaden, schnell beenden."] = "- 2단계 (40 %): 파멸과 재앙 -> 강한 공격대 피해, 빠르게 마무리."
L["Taktik: Ra-den gilt als härtester Boss des Raids. Kugeln konsequent abfangen, Vita-Rotation planen."] = "공략: 라덴은 공격대에서 가장 어려운 보스로 꼽힘. 구슬은 철저히 가로막고, 생명력 순환 계획."
L["RA-DEN: Kugeln abfangen! Vita-Rotation einhalten!"] = "라덴: 구슬 가로막기! 생명력 순환 지키기!"
L["Phase 2: Katastrophe, alle Cooldowns."] = "2단계: 재앙, 모든 생존기."
L["Schwarzfelsgießerei"] = "검은바위 용광로"
L["Gruul"] = "그룰"
L["- Infernoschnitt: frontaler Kegel, Schaden wird auf alle Getroffenen aufgeteilt -> zwei feste Soak-Gruppen im Wechsel vor den Tank stellen."] = "- 지옥불 베기: 전방 부채꼴, 피해가 맞은 모두에게 분담 -> 고정 분담 그룹 둘이 번갈아 탱커 앞에 서기."
L["- Überwältigende Schläge: stapelnder Tank-Debuff -> Tankwechsel nach Ansage."] = "- 압도적인 강타: 중첩되는 탱커 디버프 -> 콜에 맞춰 탱 교대."
L["- Versteinernder Hieb: Spieler werden nach kurzer Zeit zu Stein und treffen Umstehende -> sofort verteilen."] = "- 석화의 강타: 플레이어가 잠시 후 돌이 되어 주변을 타격 -> 즉시 산개."
L["- Wüten (Raserei-Phase): Gruul stürmt durch den Raum und lässt Felsen fallen -> Boden beachten, Abstand halten."] = "- 광란 (광폭 단계): 그룰이 방을 돌진하며 바위를 떨어뜨림 -> 바닥 주의, 거리 유지."
L["- Einsturz: Felsbrocken fallen auf Spieler -> nicht in markierten Bereichen stehen."] = "- 붕괴: 바위가 플레이어에게 떨어짐 -> 표시된 구역에 서지 말 것."
L["Taktik: Gruul mittig tanken, Soak-Gruppen für den Infernoschnitt fest einteilen und abwechseln; bei Versteinerung immer verteilen."] = "공략: 그룰은 중앙에서 탱킹, 지옥불 베기 분담 그룹을 고정 배정해 번갈아; 석화 시 항상 산개."
L["GRUUL: Schnitt-Gruppen abwechselnd soaken! Bei Versteinern verteilen!"] = "그룰: 베기 그룹 번갈아 맞기! 석화 시 산개!"
L["Tankwechsel nach Stapeln. Bei Wüten Felsen ausweichen."] = "중첩 후 탱 교대. 광란 시 바위 피하기."
L["Erzfresser"] = "광석포식자"
L["- Säureschwall: frontaler Strahl auf den Tank -> zweiter Tank steht direkt dahinter und teilt den Schaden."] = "- 산성 분출: 탱커에게 전방 광선 -> 두 번째 탱커가 바로 뒤에 서서 피해 분담."
L["- Säureschlund: stapelnder Tank-Debuff -> Tankwechsel."] = "- 산성 아귀: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Ausgewürgter Schwarzfels: Brocken hinterlassen Flächen -> sofort raus, Boss aus den Pfützen ziehen."] = "- 토해낸 검은바위: 덩어리가 장판을 남김 -> 즉시 나오고, 보스를 웅덩이 밖으로 끌기."
L["- Explosive Splitter: Splitter explodieren nach kurzer Zeit -> wegbewegen (Nahkampf beachten)."] = "- 폭발성 파편: 파편이 잠시 후 폭발 -> 이동하기 (근딜 주의)."
L["- Phase 2 (Energie leer): Erzfresser rollt durch das Labyrinth und frisst Erz -> nicht überrollen lassen, Erz selbst zerstören/nicht ihm überlassen."] = "- 2단계 (기력 소진): 광석포식자가 미로를 굴러다니며 광석을 먹음 -> 깔리지 말 것, 광석은 직접 파괴/보스에게 넘기지 말 것."
L["Taktik: Phase 1 Boss am Rand tanken, Tanks teilen den Säureschwall; in Phase 2 im Labyrinth nicht überrollen lassen, danach wieder sammeln."] = "공략: 1단계는 보스를 가장자리에서 탱킹, 탱커 둘이 산성 분출 분담; 2단계는 미로에서 깔리지 말고, 이후 다시 모이기."
L["ERZFRESSER: Zweiter Tank hinter den Tank (Säureschwall)! Aus Pfützen raus!"] = "광석포식자: 두 번째 탱커는 탱커 뒤에 (산성 분출)! 웅덩이에서 나오기!"
L["Phase 2: Rollendem Boss im Labyrinth ausweichen."] = "2단계: 미로에서 굴러오는 보스 피하기."
L["Hochofen + Ingenieure, Blasebalgbediener, Ursprüngliche Elementaristen, Schlackeelementare"] = "용광로 + 기술자, 풀무 조작자, 원시 정령술사, 슬래그 정령"
L["- Ingenieure: reparieren die Hitzeregulatoren und lassen Bomben fallen -> töten, Bomben aufnehmen und auf die Regulatoren werfen."] = "- 기술자: 열 조절기를 수리하고 폭탄을 떨어뜨림 -> 처치, 폭탄을 주워 조절기에 던지기."
L["- Blasebalgbediener: erhöhen die Hitze -> schnell töten."] = "- 풀무 조작자: 열을 올림 -> 빠르게 처치."
L["- Phase 2: Ursprüngliche Elementaristen sind geschützt -> Schlackeelementare (fixieren Spieler) beim Elementaristen sterben lassen, um den Schild zu brechen."] = "- 2단계: 원시 정령술사가 보호됨 -> 슬래그 정령 (플레이어 고정)을 정령술사 옆에서 죽여 보호막 깨기."
L["- Feuerrufer / Flüchtiges Feuer: Spieler explodieren -> raus aus dem Raid laufen."] = "- 화염 소환사 / 불안정한 불길: 플레이어가 폭발 -> 공대 밖으로 나가기."
L["- Phase 3 (Herz des Berges): Explosion trifft den Raid mit wachsender Stärke -> Defensivfähigkeiten, Herz schnell töten."] = "- 3단계 (산의 심장): 폭발이 점점 강하게 공대를 타격 -> 방어 생존기, 심장 빠르게 처치."
L["Taktik: Phase 1 beide Hitzeregulatoren gleichmäßig zerstören, Phase 2 die vier Elementaristen nacheinander, Phase 3 alles auf das Herz."] = "공략: 1단계는 열 조절기 둘을 균등하게 파괴, 2단계는 정령술사 넷을 차례로, 3단계는 전부 심장에."
L["HOCHOFEN: Bomben aufheben und auf Regulatoren werfen! Ingenieure töten!"] = "용광로: 폭탄 주워서 조절기에 던지기! 기술자 처치!"
L["P2: Schlackeelementare zum Elementaristen ziehen. P3: alles aufs Herz."] = "2단계: 슬래그 정령은 정령술사에게. 3단계: 전부 심장."
L["Hochofen (Elementaristen)"] = "용광로 (정령술사)"
L["Ein Symbol je Elementarist, Tötungsreihenfolge Totenkopf, Kreuz, Viereck, Mond."] = "정령술사마다 징표 하나, 처치 순서는 해골, 가위표, 네모, 달."
L["Hans'gar und Franzok"] = "한스가르와 프란조크"
L["- Lähmender Suplex: ein Bruder packt einen Tank und schleudert ihn -> zweiter Tank steht nahe, Heiler vorbereiten."] = "- 무력화 수플렉스: 형제 하나가 탱커를 잡아 내던짐 -> 두 번째 탱커가 가까이, 힐러 대비."
L["- Zerschmetterte Wirbel: Tank-Debuff -> Tankwechsel zwischen den Brüdern."] = "- 박살난 척추: 탱커 디버프 -> 형제 간 탱 교대."
L["- Störendes Gebrüll: unterbricht Zauber in der Nähe -> rechtzeitig Zauber abbrechen."] = "- 방해의 포효: 근처 주문 시전 차단 -> 제때 시전 취소."
L["- Stampfpressen (bei ca. 85/55/30 %): Brüder springen auf die Fließbänder -> auf die Bänder wechseln und den Pressen ausweichen."] = "- 압착기 (약 85/55/30 %): 형제가 컨베이어 벨트로 점프 -> 벨트로 이동해 압착기 피하기."
L["- Sengende Platten: Bodenplatten werden heiß -> nicht auf glühenden Platten stehen."] = "- 타오르는 판: 바닥 판이 뜨거워짐 -> 달아오른 판 위에 서지 말 것."
L["Taktik: Brüder getrennt tanken, Tanks tauschen nach Debuff; in den Pressen-Phasen den Pressen auf den Fließbändern ausweichen."] = "공략: 형제는 따로 탱킹, 디버프 후 탱 교대; 압착기 단계에선 벨트 위에서 압착기 피하기."
L["HANS'GAR & FRANZOK: In Pressen-Phase auf die Bänder, Pressen ausweichen!"] = "한스가르와 프란조크: 압착기 단계엔 벨트로, 압착기 피하기!"
L["Gebrüll: Zauber stoppen. Tankwechsel nach Wirbel-Debuff."] = "포효: 시전 멈추기. 척추 디버프 후 탱 교대."
L["Flammenbändigerin Ka'graz + Aknor Stahlbringer, Glutwölfe"] = "화염술사 카그라즈 + 아크노르 스틸브링어, 잉걸불 늑대"
L["- Glutwölfe: fixieren Spieler und überhitzen -> fixierte Spieler kiten, Wölfe von Tanks aufnehmen lassen."] = "- 잉걸불 늑대: 플레이어를 고정하고 과열 -> 고정된 플레이어는 카이팅, 늑대는 탱커가 잡기."
L["- Geschmolzener Strom: großer Feuerball auf einen Spieler -> mit einer Gruppe zusammen soaken."] = "- 녹아내린 급류: 플레이어 한 명에게 큰 화염구 -> 그룹이 함께 맞기."
L["- Lavaschnitt: Linie aus Lava -> ausweichen."] = "- 용암 베기: 용암 선 -> 피하기."
L["- Steigende Flammen: stapelnder Tank-Debuff -> Tankwechsel."] = "- 솟구치는 불길: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Feuersturm (100 Energie): starker Raid-Schaden -> Heiler-Defensivfähigkeiten, Wölfe danach wieder aufnehmen."] = "- 불폭풍 (기력 100): 강한 공격대 피해 -> 힐러 방어 생존기, 이후 늑대 다시 잡기."
L["Taktik: Aknor zuerst töten, Wölfe abseits halten und gesammelt umhauen; Feuersturm mit Cooldowns überstehen."] = "공략: 아크노르 먼저 처치, 늑대는 떨어진 곳에 모아서 한꺼번에 잡기; 불폭풍은 생존기로 버티기."
L["KA'GRAZ: Aknor zuerst! Fixierte Spieler Wölfe kiten!"] = "카그라즈: 아크노르 먼저! 고정된 플레이어는 늑대 카이팅!"
L["Geschmolzenen Strom zusammen soaken. Feuersturm: Cooldowns."] = "녹아내린 급류 함께 맞기. 불폭풍: 생존기."
L["Kromog"] = "크로모그"
L["- Runen der Greifenden Erde: Hände packen alle -> vorher auf eine Rune stellen, je Spieler eine Rune, dann Hände zerstören."] = "- 움켜쥐는 대지의 룬: 손이 모두를 붙잡음 -> 미리 룬 위에 서기, 플레이어당 룬 하나, 이후 손 파괴."
L["- Donnernde Schläge: Raid wird weggestoßen -> auf einer Rune stehen, um festgehalten zu werden."] = "- 천둥 강타: 공대가 밀려남 -> 룬 위에 서서 붙잡히기."
L["- Nachhall: Wellen durch den Raum -> ausweichen."] = "- 반향: 방을 가로지르는 파동 -> 피하기."
L["- Steinatem: starker Raid-Schaden über Zeit -> Heiler-Cooldowns."] = "- 바위 숨결: 강한 지속 공격대 피해 -> 힐러 생존기."
L["- Hieb / Verzogene Rüstung: Tank-Debuff -> Tankwechsel."] = "- 강타 / 뒤틀린 갑옷: 탱커 디버프 -> 탱 교대."
L["Taktik: Boss stationär tanken, bei Greifender Erde schnell eigene Rune einnehmen und Hände wegschießen, sonst ausweichen."] = "공략: 보스는 고정 위치에서 탱킹, 움켜쥐는 대지 시 빠르게 자기 룬을 차지하고 손을 처치, 그 외엔 피하기."
L["KROMOG: Bei Greifender Erde auf eine Rune! Hände sofort zerstören!"] = "크로모그: 움켜쥐는 대지 시 룬 위로! 손은 즉시 파괴!"
L["Nachhall ausweichen. Tankwechsel nach Debuff."] = "반향 피하기. 디버프 후 탱 교대."
L["Bestienlord Darmac + Bestien (Wolf, Wyrm, Elekk)"] = "야수군주 다마크 + 야수 (늑대, 고룡, 엘레크)"
L["- Speere / Festnageln: Speere nageln Spieler fest -> Speer zerstören, Betroffene befreien."] = "- 창 / 꿰어 고정: 창이 플레이어를 고정 -> 창을 파괴해 대상 풀어주기."
L["- Wolf: Reißen und Zerren auf den Tank, Wildes Heulen (Wutanfall) -> beruhigen bzw. Tank-Cooldown."] = "- 늑대: 탱커에게 찢고 끌기, 야만의 울부짖음 (격노) -> 진정 또는 탱커 생존기."
L["- Wyrm: Feuer-Debuffs auf Spieler -> bannen bzw. vom Raid weggehen."] = "- 고룡: 플레이어에게 화염 디버프 -> 해제하거나 공대에서 떨어지기."
L["- Elekk: Ansturm durch den Raid -> Laufwege freihalten, ausweichen."] = "- 엘레크: 공대를 가로지르는 돌진 -> 이동 경로 비우고 피하기."
L["- Darmac reitet bei ca. 85/65/45 % auf eine Bestie auf und erhält deren Fähigkeiten -> Bestien vorher getrennt töten."] = "- 다마크는 약 85/65/45 %에 야수에 올라타 그 능력을 얻음 -> 야수를 미리 따로 처치."
L["Taktik: Darmac und die Bestien getrennt tanken, Bestien in fester Reihenfolge töten; Fähigkeiten des Reittiers gehen auf Darmac über."] = "공략: 다마크와 야수는 따로 탱킹, 야수는 정해진 순서로 처치; 탈것의 능력은 다마크에게 넘어감."
L["DARMAC: Speere zerstören, Festgenagelte befreien!"] = "다마크: 창 파괴, 고정된 플레이어 풀어주기!"
L["Bestien getrennt tanken, Wutanfall beruhigen."] = "야수는 따로 탱킹, 격노는 진정."
L["Maschinist Thogar + Zug-Adds (Feuerheiler, Eisenräuber, Grom'kar)"] = "운전사 토가르 + 열차 쫄 (화염 치유사, 강철 약탈자, 그롬카르)"
L["- Züge: fahren auf vier Gleisen ein -> nie auf aktivem Gleis stehen, Ansagen (DBM) beachten."] = "- 열차: 선로 네 개로 진입 -> 활성 선로에 절대 서지 말 것, 경보(DBM) 확인."
L["- Grom'kar-Feuerheiler: heilt Adds -> unterbrechen und zuerst töten."] = "- 그롬카르 화염 치유사: 쫄을 치유 -> 차단하고 먼저 처치."
L["- Entfachen: Tank-Debuff -> Tankwechsel."] = "- 점화: 탱커 디버프 -> 탱 교대."
L["- Prototyp-Impulsgranate: Feuerflächen -> Boss herausziehen, nicht reinstehen."] = "- 시제품 충격 수류탄: 불 장판 -> 보스를 밖으로 끌고 들어가지 말 것."
L["- Verzögerte Belagerungsbombe: Spieler explodieren -> vom Raid weggehen."] = "- 지연 공성 폭탄: 플레이어가 폭발 -> 공대에서 떨어지기."
L["Taktik: Feste Laufwege zwischen den Gleisen, Adds aus den Zügen schnell töten (Heiler zuerst unterbrechen), Boss abseits tanken."] = "공략: 선로 사이에 고정 이동 경로, 열차에서 나온 쫄은 빠르게 처치 (치유사 먼저 차단), 보스는 떨어진 곳에서 탱킹."
L["THOGAR: Nie auf aktiven Gleisen stehen! Feuerheiler unterbrechen!"] = "토가르: 활성 선로에 절대 서지 말 것! 화염 치유사 차단!"
L["Adds aus den Zügen zuerst. Bomben vom Raid weg."] = "열차 쫄 먼저. 폭탄은 공대에서 멀리."
L["Thogar"] = "토가르"
L["Totenkopf auf den Feuerheiler (unterbrechen), Kreuz auf das nächste Add."] = "해골은 화염 치유사 (차단), 가위표는 다음 쫄."
L["Admiralin Gar'an, Marak die Blutige, Vollstreckerin Sorka"] = "제독 가란, 피의 마라크, 집행자 소르카"
L["- Bei 100 Energie springt eine Jungfer auf das Schiff -> Bootsgruppe fährt hinauf und erledigt die Aufgabe dort, der Rest kämpft unten weiter."] = "- 기력 100에 처녀 하나가 배로 점프 -> 배 그룹이 올라가 그곳 임무 수행, 나머지는 아래에서 계속 전투."
L["- Gar'an - Schnellfeuer: verfolgt einen Spieler -> aus dem Raid kiten."] = "- 가란 - 속사: 플레이어 한 명 추적 -> 공대 밖으로 카이팅."
L["- Gar'an - Durchdringender Schuss: Linie -> mehrere Spieler stellen sich in die Linie und teilen den Schaden."] = "- 가란 - 관통 사격: 직선 -> 여러 명이 경로에 서서 피해 분담."
L["- Marak - Blutgetränkter Herzsucher: springt zwischen markierten Spielern -> vom Raid weg, Heiler fokussieren."] = "- 마라크 - 피에 젖은 심장추적자: 표시된 플레이어 사이를 튐 -> 공대에서 떨어지기, 힐러 집중."
L["- Sorka - Klingensturm und Krampfartige Schatten -> ausweichen bzw. Debuff mit Bedacht bannen."] = "- 소르카 - 칼날 폭풍과 경련의 그림자 -> 피하거나 디버프는 신중하게 해제."
L["Taktik: Jungfern gemeinsam tanken und Schaden gleichmäßig verteilen; Bootsgruppe vorher einteilen."] = "공략: 처녀들은 함께 탱킹하고 딜을 균등하게 분배; 배 그룹은 미리 배정."
L["EISERNE JUNGFERN: Bootsgruppe bei 100 Energie aufs Schiff!"] = "강철 처녀: 기력 100에 배 그룹 배로!"
L["Schnellfeuer weg vom Raid kiten. Durchdringender Schuss soaken."] = "속사는 공대 밖으로 카이팅. 관통 사격 맞기."
L["Schwarzfaust"] = "블랙핸드"
L["- Phase 1 - Zum Tode verurteilt: markierte Spieler werden mit Durchbohrendem Wurf getroffen -> Wurf durch herabgefallene Trümmer leiten."] = "- 1단계 - 죽음의 선고: 표시된 플레이어가 꿰뚫는 투척에 맞음 -> 떨어진 잔해를 통해 투척 유도."
L["- Zerschmetternder Hieb: Raid-Schaden, wird auf Nahestehende geteilt -> sammeln, außer markierte Spieler."] = "- 박살내는 강타: 공격대 피해, 가까이 있는 이들에게 분담 -> 표시된 플레이어 외엔 모이기."
L["- Phase 2 - Belagerungsmaschinen: fixieren Spieler und feuern Mörser -> wegkiten, Maschinen zerstören."] = "- 2단계 - 공성 전차: 플레이어를 고정하고 박격포 발사 -> 멀리 카이팅, 전차 파괴."
L["- Phase 3 - Schlackebomben: Bomben am Tank explodieren -> Tank weg vom Raid, nach Explosion Tankwechsel."] = "- 3단계 - 슬래그 폭탄: 탱커에게서 폭탄 폭발 -> 탱커는 공대에서 멀리, 폭발 후 탱 교대."
L["- Gewaltiger Zerschmetternder Hieb (P3): stößt alle zurück -> nahe am Boss stehen, nicht von der Plattform fallen."] = "- 거대한 박살내는 강타 (3단계): 모두를 밀쳐냄 -> 보스 가까이 서기, 단상에서 떨어지지 말 것."
L["Taktik: Drei Phasen auf zwei Ebenen: Trümmer in P1 nutzen, in P2 Maschinen zerstören, in P3 dicht stehen und Schlacke ausweichen."] = "공략: 두 층에서 세 단계: 1단계는 잔해 활용, 2단계는 전차 파괴, 3단계는 붙어 서서 슬래그 피하기."
L["SCHWARZFAUST: Markierte durch Trümmer werfen lassen, sonst sammeln!"] = "블랙핸드: 표시된 플레이어는 잔해 쪽으로 투척 유도, 나머지는 모이기!"
L["P2 Maschinen zerstören. P3 nah am Boss bleiben, nicht runterfallen."] = "2단계 전차 파괴. 3단계 보스 가까이, 떨어지지 말 것."
L["Höllenfeuerzitadelle"] = "지옥불 성채"
L["Belagerungsmeisterin Mar'tak + Belagerungsfahrzeuge und Adds"] = "공성대장 마르탁 + 공성 차량과 쫄"
L["- Belagerungsfahrzeuge: greifen das Tor an -> priorisiert zerstören, bevor sie es erreichen."] = "- 공성 차량: 성문을 공격 -> 도달 전에 우선 파괴."
L["- Teufelsfeuermunition: von zerstörten Fahrzeugen -> aufheben und zu den Kanonen bringen."] = "- 지옥불 탄약: 파괴된 차량에서 나옴 -> 주워서 대포로 운반."
L["- Gorebound-Teufelszauberer und Ingenieure: Zauber/Reparaturen -> unterbrechen."] = "- 피의 구속 지옥 술사와 기술자: 주문/수리 -> 차단."
L["- Mar'tak - Heulende Axt und Schockwelle -> markierte Spieler raus, Frontal meiden."] = "- 마르탁 - 울부짖는 도끼와 충격파 -> 표시된 플레이어는 나가기, 전방 피하기."
L["Taktik: Raid in Gruppen aufteilen: Fahrzeuge zuerst, Adds unterbrechen und töten, Mar'tak nebenbei tanken."] = "공략: 공대를 그룹으로 나누기: 차량 먼저, 쫄은 차단하고 처치, 마르탁은 틈틈이 탱킹."
L["HÖLLENFEUERANGRIFF: Fahrzeuge zuerst! Zauberer unterbrechen!"] = "지옥불 공격: 차량 먼저! 술사 차단!"
L["Munition zu den Kanonen bringen. Axt-Ziele raus."] = "탄약은 대포로 운반. 도끼 대상은 나가기."
L["Eiserner Häscher"] = "강철 약탈자"
L["- Artillerie: Debuff, explodiert nach Ablauf -> mit Debuff vom Raid weglaufen."] = "- 포격: 디버프, 만료 시 폭발 -> 디버프 받으면 공대에서 멀어지기."
L["- Sperrfeuer: Frontalkegel -> nur der Tank vorne."] = "- 탄막: 전방 부채꼴 -> 탱커만 앞에."
L["- Instabile Kugel: Schaden um Fernkämpfer -> verteilen."] = "- 불안정한 구슬: 원딜 주변 피해 -> 산개."
L["- Blitz: schnelle Ansturmlinien -> ausweichen."] = "- 섬광: 빠른 돌진 경로 -> 피하기."
L["- Luftphase: Feuerbomben fallen -> Bomben zerstören, bevor sie explodieren, Raid-Cooldowns."] = "- 공중 단계: 화염 폭탄이 떨어짐 -> 폭발 전에 파괴, 공대 생존기."
L["Taktik: Fernkampf verteilt, Artillerie-Ziele raus; in der Luftphase Bomben nach Art priorisiert zerstören."] = "공략: 원딜 산개, 포격 대상은 나가기; 공중 단계에선 폭탄 종류별 우선순위로 파괴."
L["EISERNER HÄSCHER: Artillerie-Ziele raus aus dem Raid!"] = "강철 약탈자: 포격 대상은 공대 밖으로!"
L["Luftphase: Bomben sofort zerstören. Blitz ausweichen."] = "공중 단계: 폭탄 즉시 파괴. 섬광 피하기."
L["Kormrok"] = "코름록"
L["- Runen (Explosiv, Faulig, Schatten): Kormrok taucht in Pfützen und verstärkt die nächste Fähigkeit -> Pfützenfarbe beachten."] = "- 룬 (폭발, 부패, 암흑): 코름록이 웅덩이에 잠겨 다음 능력 강화 -> 웅덩이 색 확인."
L["- Greifende Hände: Hände packen Spieler -> Hände schnell töten bzw. soaken."] = "- 움켜쥐는 손: 손이 플레이어를 붙잡음 -> 손을 빠르게 처치 또는 맞기."
L["- Teufelsausbruch: Wellen durch den Raum -> in Lücken bewegen."] = "- 지옥 분출: 방을 가로지르는 파동 -> 틈으로 이동."
L["- Schlag / Explosiver Ausbruch: Tank-Debuff -> Tankwechsel, Raid bei Explosionen sammeln."] = "- 강타 / 폭발성 분출: 탱커 디버프 -> 탱 교대, 폭발 때 공대 모이기."
L["- Hämmern: Raid-Schaden über Zeit -> sammeln für Heilung."] = "- 망치질: 지속 공격대 피해 -> 힐 받게 모이기."
L["Taktik: Kormrok nahe der jeweiligen Pfütze tanken, Mechanik je Pfützenfarbe vorher absprechen."] = "공략: 코름록은 해당 웅덩이 근처에서 탱킹, 웅덩이 색별 기믹은 미리 상의."
L["KORMROK: Wellen ausweichen, Hände sofort töten!"] = "코름록: 파동 피하기, 손은 즉시 처치!"
L["Tankwechsel nach Schlag. Pfützenfarbe ansagen."] = "강타 후 탱 교대. 웅덩이 색 콜."
L["Dia Dunkelflüster, Gurtogg Siedeblut, Klingenmeister Jubei'thos"] = "디아 다크위스퍼, 구르토그 블러드보일, 검의 대가 주베이토스"
L["- Dia - Ernten: Schatten-AoE -> verteilen; Albtraumgestalt -> Tankwechsel."] = "- 디아 - 수확: 암흑 광역 -> 산개; 악몽의 형상 -> 탱 교대."
L["- Jubei'thos - Spiegelbilder: erzeugt Kopien -> schnell töten bzw. Flächenschaden."] = "- 주베이토스 - 거울상: 분신 생성 -> 빠르게 처치 또는 광역."
L["- Gurtogg - Teufelswut / Blutsieden: fixiert Spieler -> fixierte Spieler kiten, Blutsieden auf Nahkampf rotieren."] = "- 구르토그 - 지옥 격노 / 끓는 피: 플레이어 고정 -> 고정된 플레이어는 카이팅, 끓는 피는 근딜이 순환."
L["- Stirbt ein Ratsmitglied, verstärken sich die anderen -> Leben ausgleichen bzw. feste Reihenfolge."] = "- 의회원 하나가 죽으면 나머지가 강해짐 -> 생명력 맞추거나 순서 고정."
L["Taktik: Feste Tötungsreihenfolge (meist Dia zuerst), Mitglieder getrennt tanken, auf Spiegelbilder und Fixierung reagieren."] = "공략: 처치 순서 고정 (보통 디아 먼저), 의회원은 따로 탱킹, 거울상과 고정에 대응."
L["HOHER RAT: Dia zuerst! Bei Ernten verteilen!"] = "고위 의회: 디아 먼저! 수확 시 산개!"
L["Spiegelbilder töten. Gurtoggs Fixierung kiten."] = "거울상 처치. 구르토그 고정은 카이팅."
L["Hoher Rat"] = "고위 의회"
L["Totenkopf Dia, Kreuz Gurtogg, Viereck Jubei'thos (Tötungsreihenfolge)."] = "해골 디아, 가위표 구르토그, 네모 주베이토스 (처치 순서)."
L["Kilrogg Totauge + Blutdürster-Adds, Terrorwachen"] = "킬로그 데드아이 + 피에 굶주린 쫄, 공포의 수호병"
L["- Herzsucher: Spieler hinterlassen Blutpfützen -> am Rand ablegen."] = "- 심장추적자: 플레이어가 피 웅덩이를 남김 -> 가장자리에 내려놓기."
L["- Todesvision: Spieler betreten Visionen und kehren mit Schutz-Buff zurück -> eingeteilte Spieler rein."] = "- 죽음의 환영: 플레이어가 환영에 들어갔다 보호 버프를 받고 복귀 -> 배정된 플레이어 진입."
L["- Speichelnde Blutdürster: laufen zu Kilrogg -> töten, bevor sie ihn erreichen."] = "- 침 흘리는 흡혈귀: 킬로그에게 이동 -> 도달 전에 처치."
L["- Panzerzerreißen: stapelnder Tank-Debuff -> Tankwechsel."] = "- 방어구 찢기: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Todeszuckungen: Raid-Schaden -> Defensivfähigkeiten, verteilt stehen."] = "- 죽음의 경련: 공격대 피해 -> 방어 생존기, 산개해서 서기."
L["Taktik: Boss mittig tanken, Pfützen außen ablegen, Blutdürster vor Erreichen des Bosses töten, Visionen rotieren."] = "공략: 보스는 중앙에서 탱킹, 웅덩이는 바깥에 내려놓기, 흡혈귀는 보스 도달 전에 처치, 환영 순환."
L["KILROGG: Blutdürster töten, bevor sie den Boss erreichen!"] = "킬로그: 흡혈귀는 보스에 닿기 전에 처치!"
L["Pfützen am Rand ablegen. Tankwechsel nach Stapeln."] = "웅덩이는 가장자리에. 중첩 후 탱 교대."
L["Blutschatten"] = "고어핀드"
L["- Berührung der Verdammnis: explodiert am Spieler -> raus aus dem Raid."] = "- 파멸의 손길: 플레이어에게서 폭발 -> 공대 밖으로."
L["- Schatten des Todes: Spieler landen im Magen -> dort Adds töten und rechtzeitig wieder hinaus."] = "- 죽음의 그림자: 플레이어가 위장으로 떨어짐 -> 그곳 쫄 처치 후 제때 탈출."
L["- Geteiltes Schicksal: verbindet Spieler -> zusammenlaufen, um sich zu befreien."] = "- 공유된 운명: 플레이어를 연결 -> 서로 모여 풀려나기."
L["- Blutschatten-Geister: laufen zum Boss -> verlangsamen und töten."] = "- 고어핀드의 영혼: 보스에게 이동 -> 감속하고 처치."
L["- Seelenfest (100 Energie): Raid-Schaden -> Cooldowns."] = "- 영혼의 만찬 (기력 100): 공격대 피해 -> 생존기."
L["Taktik: Magen-Gruppen festlegen, Geister nicht zum Boss lassen; Seelenfest mit Raid-Cooldowns heilen."] = "공략: 위장 그룹 정하기, 영혼이 보스에게 가지 못하게; 영혼의 만찬은 공대 생존기로 힐."
L["BLUTSCHATTEN: Geister nicht zum Boss lassen! Verdammnis raus!"] = "고어핀드: 영혼이 보스에 닿지 않게! 파멸은 밖으로!"
L["Magen: Adds töten und wieder raus. Geteiltes Schicksal zusammen."] = "위장: 쫄 잡고 다시 나오기. 공유된 운명은 함께."
L["Schattenfürst Iskar + Zwischenphasen-Adds"] = "그림자 군주 이스카르 + 중간 단계 쫄"
L["- Auge von Anzu: wird zwischen Spielern weitergegeben -> nur der Träger kann bestimmte Debuffs bannen."] = "- 안주의 눈: 플레이어 사이에 전달 -> 보유자만 특정 디버프 해제 가능."
L["- Phantomwinde: wehen Spieler von der Plattform -> Auge an Betroffene geben."] = "- 환영 바람: 플레이어를 단상 밖으로 날려버림 -> 대상에게 눈 넘기기."
L["- Teufelschakram: springt zwischen Spielern -> verteilen."] = "- 지옥 차크람: 플레이어 사이를 튐 -> 산개."
L["- Adds in den Zwischenphasen: töten, Zauber unterbrechen."] = "- 중간 단계 쫄: 처치, 주문 차단."
L["Taktik: Auge gezielt weitergeben, Adds schnell töten, verteilt stehen gegen Chakram."] = "공략: 눈은 계획적으로 전달, 쫄은 빠르게 처치, 차크람 대비 산개."
L["ISKAR: Auge weitergeben! Phantomwinde: Auge an Betroffene!"] = "이스카르: 눈 넘기기! 환영 바람: 대상에게 눈!"
L["Adds in Zwischenphase töten. Gegen Chakram verteilen."] = "중간 단계 쫄 처치. 차크람 대비 산개."
L["Iskar"] = "이스카르"
L["Totenkopf, Kreuz, Viereck auf die Zwischenphasen-Adds (Tötungsreihenfolge)."] = "해골, 가위표, 네모는 중간 단계 쫄 (처치 순서)."
L["Socrethar der Ewige + Seelengebundenes Konstrukt"] = "영원한 소크레타르 + 영혼 속박 구조물"
L["- Seelengebundenes Konstrukt: ein Spieler übernimmt das Konstrukt -> Konstrukt gegen Socrethar einsetzen."] = "- 영혼 속박 구조물: 플레이어 하나가 구조물을 조종 -> 구조물로 소크레타르 공격."
L["- Sargerei-Dominatoren: Gabe der Man'ari / Herrschaft -> unterbrechen und schnell töten."] = "- 사게레이 지배자: 만아리의 선물 / 지배 -> 차단하고 빠르게 처치."
L["- Spukende Seelen: zahlreiche Adds -> Flächenschaden."] = "- 출몰하는 영혼: 다수의 쫄 -> 광역."
L["- Überladung / Raidschaden: Konstrukt-Fähigkeiten -> Raid-Cooldowns."] = "- 과부하 / 공격대 피해: 구조물 능력 -> 공대 생존기."
L["Taktik: Konstrukt von einem festen Spieler steuern lassen, Dominatoren priorisieren, Adds zusammenziehen."] = "공략: 구조물은 고정된 한 명이 조종, 지배자 우선, 쫄은 모으기."
L["SOCRETHAR: Dominatoren unterbrechen und zuerst töten!"] = "소크레타르: 지배자 차단하고 먼저 처치!"
L["Konstrukt-Pilot einsetzen. Seelen mit AoE wegräumen."] = "구조물 조종사 투입. 영혼은 광역으로 정리."
L["Socrethar"] = "소크레타르"
L["Totenkopf und Kreuz auf die Dominatoren."] = "해골과 가위표는 지배자."
L["Tyrannin Velhari + Uralter Vollstrecker, Uralter Herold, Uralter Herrscher"] = "폭군 벨하리 + 고대의 집행자, 고대의 전령, 고대의 군주"
L["- Aura der Unterdrückung (P1): Bewegung verursacht Schaden -> nur wenig bewegen."] = "- 억압의 오라 (1단계): 움직이면 피해 -> 최소한만 이동."
L["- Aura der Verachtung (P2): senkt die Heilung -> Heiler-Cooldowns."] = "- 경멸의 오라 (2단계): 치유량 감소 -> 힐러 생존기."
L["- Aura der Bösartigkeit (P3): Schaden bei Heilung -> Raid-Cooldowns."] = "- 악의의 오라 (3단계): 치유 시 피해 -> 공대 생존기."
L["- Uralter Herold: heilt -> unterbrechen und schnell töten."] = "- 고대의 전령: 치유 -> 차단하고 빠르게 처치."
L["- Edikt der Verurteilung: Schaden wird geteilt -> markierte Spieler zusammenbringen."] = "- 단죄의 칙령: 피해 분담 -> 표시된 플레이어끼리 모이기."
L["Taktik: Adds je Phase zuerst töten, Herold unterbrechen, Velhari danach; Auren mit Cooldowns überstehen."] = "공략: 단계마다 쫄 먼저, 전령 차단, 그다음 벨하리; 오라는 생존기로 버티기."
L["VELHARI: Adds zuerst! Herold unterbrechen!"] = "벨하리: 쫄 먼저! 전령 차단!"
L["Unterdrückung: wenig bewegen. Edikt zusammen teilen."] = "억압: 최소한만 이동. 칙령은 함께 분담."
L["Velhari"] = "벨하리"
L["Totenkopf auf das aktuelle Add, Kreuz auf den Herold (unterbrechen)."] = "해골은 현재 쫄, 가위표는 전령 (차단)."
L["Teufelsfürst Zakuun"] = "지옥 군주 자쿤"
L["- Samen der Zerstörung: Spieler explodieren -> an festgelegten Punkten ablegen."] = "- 파괴의 씨앗: 플레이어가 폭발 -> 정해진 지점에 내려놓기."
L["- Entwaffnet: Boss wirft Waffen und erzeugt Spalten -> Spalten mit Befleckt-Debuff schließen."] = "- 무장 해제: 보스가 무기를 던져 균열 생성 -> 오염 디버프로 균열 닫기."
L["- Befleckt: Heilabsorb -> Spieler mit Debuff gehen in Spalten."] = "- 오염: 치유 흡수 -> 디버프 받은 플레이어가 균열로."
L["- Kavitation: Wellen -> ausweichen."] = "- 공동 현상: 파동 -> 피하기."
L["- Schwer bewaffnet: Tank-Schaden -> Cooldowns, Tankwechsel."] = "- 중무장: 탱커 피해 -> 생존기, 탱 교대."
L["Taktik: Samen an feste Positionen tragen, Spalten von Befleckten schließen lassen, Wellen ausweichen."] = "공략: 씨앗은 정해진 위치로, 균열은 오염된 플레이어가 닫기, 파동 피하기."
L["ZAKUUN: Samen an Positionen tragen! Befleckte in die Spalten!"] = "자쿤: 씨앗은 위치로! 오염된 플레이어는 균열로!"
L["Kavitation ausweichen. Tankwechsel nach Ansage."] = "공동 현상 피하기. 콜에 맞춰 탱 교대."
L["Xhul'horac + Teufelswichtel, Vanguard Akkelion, Omnus"] = "줄호락 + 지옥 임프, 선봉대 아켈리온, 옴누스"
L["- Teufels- und Leerenschlag: Tank-Debuffs -> Tankwechsel nach Combo."] = "- 지옥 강타와 공허 강타: 탱커 디버프 -> 연속기 후 탱 교대."
L["- Teufelswichtel: Debuff-bringende Adds -> schnell töten."] = "- 지옥 임프: 디버프를 거는 쫄 -> 빠르게 처치."
L["- Pfützen (Teufel/Leere): bilden Flächen -> herausziehen."] = "- 웅덩이 (지옥/공허): 장판 형성 -> 밖으로 끌기."
L["- Schwarzes Loch: zieht Spieler an -> ausweichen bzw. soaken."] = "- 블랙홀: 플레이어를 끌어당김 -> 피하거나 맞기."
L["- Akkelion und Omnus: Adds je Phase -> tanken und töten."] = "- 아켈리온과 옴누스: 단계별 쫄 -> 탱킹하고 처치."
L["Taktik: Boss getrennt von Adds tanken, Wichtel priorisieren, Pfützen am Rand ablegen."] = "공략: 보스와 쫄은 따로 탱킹, 임프 우선, 웅덩이는 가장자리에."
L["XHUL'HORAC: Wichtel sofort töten! Tankwechsel nach Combo!"] = "줄호락: 임프 즉시 처치! 연속기 후 탱 교대!"
L["Pfützen am Rand ablegen. Schwarzes Loch meiden."] = "웅덩이는 가장자리에. 블랙홀 피하기."
L["Xhul'horac"] = "줄호락"
L["Totenkopf und Kreuz auf die Wichtel bzw. Vanguard-Adds."] = "해골과 가위표는 임프 또는 선봉대 쫄."
L["Mannoroth + Teufelswichtel, Verdammnislords, Höllenbestien, Beschwörer"] = "만노로스 + 지옥 임프, 파멸의 군주, 지옥불정령, 소환사"
L["- Beschwörer (P1): drei Beschwörer erzeugen Adds -> töten, um Mannoroth zu befreien."] = "- 소환사 (1단계): 소환사 셋이 쫄 생성 -> 처치해 만노로스 해방."
L["- Fluch der Legion: Debuff spawnt Verdammnislord -> bannen, Lord töten."] = "- 군단의 저주: 디버프가 파멸의 군주 소환 -> 해제, 군주 처치."
L["- Mal der Verdammnis: Explosion -> verteilen."] = "- 파멸의 징표: 폭발 -> 산개."
L["- Schattenblitzsalve (Verdammnislords): -> unterbrechen."] = "- 어둠의 화살 일제 사격 (파멸의 군주): -> 차단."
L["- Gleve-Combo / Gewaltige Explosion: Tank-Mechanik -> Tankwechsel."] = "- 글레이브 연속기 / 거대한 폭발: 탱커 기믹 -> 탱 교대."
L["Taktik: P1 Beschwörer und Adds, dann Mannoroth; ab P2 verstärkt er sich mit Teufelsstrahlen, Raid-Cooldowns einplanen."] = "공략: 1단계는 소환사와 쫄, 그다음 만노로스; 2단계부터 지옥 광선으로 강해짐, 공대 생존기 계획."
L["MANNOROTH: Beschwörer zuerst! Verdammnislords unterbrechen!"] = "만노로스: 소환사 먼저! 파멸의 군주 차단!"
L["Mal der Verdammnis: verteilen. Tankwechsel nach Combo."] = "파멸의 징표: 산개. 연속기 후 탱 교대."
L["Mannoroth"] = "만노로스"
L["Ein Symbol je Beschwörer bzw. Verdammnislord, Totenkopf zuerst."] = "소환사 또는 파멸의 군주마다 징표 하나, 해골 먼저."
L["Archimonde + Teufelsgeborene Übeldämonen, Verdammnisfeuergeister"] = "아키몬드 + 지옥 태생 악령, 파멸의 불길 정령"
L["- Verdammnisfeuer: Geister hinterlassen wachsende Feuerspuren -> Feuer nicht durch den Raid ziehen, nicht reinstehen."] = "- 파멸의 불길: 정령이 커지는 불길 자국을 남김 -> 불을 공대로 끌고 오지 말고, 들어가지 말 것."
L["- Gefesselte Qual: Spieler sind angekettet -> nacheinander aus dem Kreis laufen, um die Kette zu brechen (Schaden für den Raid)."] = "- 속박된 고통: 플레이어가 사슬에 묶임 -> 차례로 원 밖으로 나가 사슬 끊기 (공대 피해)."
L["- Todesbrandmal: starker Tank-Treffer und Add-Spawn -> Tankwechsel, Add schnell töten."] = "- 죽음의 낙인: 강한 탱커 공격과 쫄 생성 -> 탱 교대, 쫄 빠르게 처치."
L["- Geschmiedetes Chaos: verbundene Spieler feuern Strahlen aufeinander -> Strahlen vom Raid weg ausrichten."] = "- 벼려진 혼돈: 연결된 플레이어가 서로에게 광선 발사 -> 광선을 공대 반대쪽으로."
L["- Mal der Legion: mehrere Spieler explodieren nacheinander -> in feste Ecken laufen."] = "- 군단의 징표: 여러 플레이어가 차례로 폭발 -> 정해진 구석으로 달리기."
L["- Netherverbannung (P3): Gruppe wird in den Wirbelnden Nether verbannt -> dort Adds töten und zurückkehren."] = "- 황천 추방 (3단계): 그룹이 소용돌이치는 황천으로 추방 -> 그곳 쫄 처치 후 복귀."
L["Taktik: Drei Phasen: Feuer am Rand ablegen und Ketten kontrolliert brechen, in P2 Strahlen und Male sauber, in P3 Nether-Gruppen rotieren."] = "공략: 세 단계: 불은 가장자리에 내려놓고 사슬은 계획적으로 끊기, 2단계는 광선과 징표 깔끔하게, 3단계는 황천 그룹 순환."
L["Mythisch: eigene Phase im Wirbelnden Nether mit stark veränderten Mechaniken."] = "신화: 소용돌이치는 황천에서 기믹이 크게 바뀐 별도 단계."
L["ARCHIMONDE: Feuer am Rand ablegen! Ketten nacheinander brechen!"] = "아키몬드: 불은 가장자리에! 사슬은 차례로 끊기!"
L["Strahlen vom Raid weg. Mal der Legion: in die Ecken."] = "광선은 공대 반대쪽으로. 군단의 징표: 구석으로."
L["Hochfels"] = "높은망치"
L["Kargath Messerfaust + Tribünen-Adds"] = "카르가스 블레이드피스트 + 관중석 쫄"
L["- Durchbohren: Tank-Debuff mit Schaden über Zeit -> Tankwechsel."] = "- 꿰뚫기: 지속 피해가 있는 탱커 디버프 -> 탱 교대."
L["- Berserkeransturm: verfolgt einen Spieler mit steigendem Schaden -> kiten und Kargath durch eine Flammensäule führen."] = "- 광폭한 돌진: 피해가 증가하며 플레이어 한 명을 추적 -> 카이팅해서 카르가스를 화염 기둥으로 유도."
L["- Kettenwurf: schleudert die nächsten Spieler auf die Tribüne -> dort Adds töten und wieder hinunterspringen."] = "- 사슬 던지기: 가장 가까운 플레이어들을 관중석으로 날려보냄 -> 그곳 쫄 처치 후 다시 뛰어내리기."
L["- Klingentanz: Sprünge zwischen Spielern mit Flächenschaden -> verteilt stehen."] = "- 칼날춤: 광역 피해를 주며 플레이어 사이 도약 -> 산개해서 서기."
L["- Flammensäulen und Tiger in der Arena -> Feuer und Tiger meiden, Tiger ggf. abfangen."] = "- 경기장의 화염 기둥과 호랑이 -> 불과 호랑이 피하고, 필요 시 호랑이 가로막기."
L["Taktik: Kargath zentral tanken, feste Kettenwurf-Gruppe neben dem Boss; Berserkeransturm immer in eine Flammensäule leiten."] = "공략: 카르가스는 중앙에서 탱킹, 사슬 던지기 고정 그룹은 보스 옆에; 광폭한 돌진은 항상 화염 기둥으로 유도."
L["KARGATH: Berserkeransturm in Flammensäule führen!"] = "카르가스: 광폭한 돌진은 화염 기둥으로!"
L["Kettenwurf-Gruppe: Tribünen-Adds töten. Tankwechsel nach Durchbohren."] = "사슬 던지기 그룹: 관중석 쫄 처치. 꿰뚫기 후 탱 교대."
L["Der Schlachter"] = "도살자"
L["- Spalten: Schaden wird auf alle Nahestehenden aufgeteilt -> Nahkampf und Fernkampf in zwei engen Gruppen stapeln."] = "- 쪼개기: 피해가 근처 모두에게 분담 -> 근딜과 원딜이 두 무리로 촘촘히 뭉치기."
L["- Spalter / Fleischklopfer: Tank-Debuffs -> Tankwechsel nach Ansage."] = "- 식칼 / 고기 망치: 탱커 디버프 -> 콜에 맞춰 탱 교대."
L["- Klaffende Wunden: Stapel durch Spalten -> Spieler mit vielen Stapeln kurz aus der Gruppe."] = "- 벌어진 상처: 쪼개기로 중첩 -> 중첩 많은 플레이어는 잠시 무리에서 이탈."
L["- Raserei (unter 30 %): Schaden und Tempo steigen -> Cooldowns, Burn-Phase."] = "- 광폭 (30 % 미만): 피해와 속도 증가 -> 생존기, 딜 몰기."
L["- Fleischige Brocken (Heroisch): Adds aus Schlachtresten -> töten bzw. nicht ignorieren."] = "- 살덩이 (영웅): 도살 잔해에서 나오는 쫄 -> 처치, 무시하지 말 것."
L["Taktik: Reiner Schadens-Check: dicht stapeln, Tanks wechseln, Heiler-Cooldowns auf die Raserei sparen."] = "공략: 순수 딜 체크: 촘촘히 뭉치고, 탱커 교대, 힐러 생존기는 광폭용으로 아끼기."
L["SCHLACHTER: Eng stapeln, Spalten teilen! Tankwechsel nach Ansage!"] = "도살자: 촘촘히 뭉쳐 쪼개기 분담! 콜에 맞춰 탱 교대!"
L["Unter 30 %: Raserei, Cooldowns zünden!"] = "30 % 미만: 광폭, 생존기 사용!"
L["Tectus + Splitter von Tectus, Bröckchen von Tectus"] = "텍투스 + 텍투스의 파편, 텍투스의 조각"
L["- Tektonischer Umbruch: Tectus teilt sich beim 'Tod' in Splitter, diese wiederum in Bröckchen -> gleichmäßig runterschaden."] = "- 지각 변동: 텍투스는 '죽을' 때 파편으로, 파편은 다시 조각으로 분열 -> 균등하게 딜."
L["- Kristallines Sperrfeuer: Kristallspur folgt einem Spieler -> vom Raid weglaufen."] = "- 수정 탄막: 수정 자국이 플레이어를 따라감 -> 공대에서 멀어지기."
L["- Erdsäulen: erscheinen unter Spielern -> rechtzeitig rausgehen."] = "- 대지 기둥: 플레이어 밑에 생성 -> 제때 벗어나기."
L["- Brechen: Fläche auf zufälligen Spielern -> ausweichen."] = "- 부수기: 무작위 플레이어에게 장판 -> 피하기."
L["- Akkretion / Energie: bei voller Energie starker Raid-Schaden -> Splitter nicht zu lange leben lassen."] = "- 부착 / 기력: 기력이 가득 차면 강한 공격대 피해 -> 파편을 너무 오래 살려두지 말 것."
L["Taktik: Tectus, dann zwei Splitter, dann Bröckchen jeweils möglichst gleichzeitig töten; Tanks übernehmen je einen Splitter."] = "공략: 텍투스, 다음 파편 둘, 다음 조각들을 각각 최대한 동시에 처치; 탱커가 파편을 하나씩 담당."
L["TECTUS: Splitter gleichmäßig runterschaden! Sperrfeuer vom Raid weg!"] = "텍투스: 파편 균등하게 딜! 탄막은 공대 밖으로!"
L["Erdsäulen ausweichen. Bröckchen am Ende gemeinsam töten."] = "대지 기둥 피하기. 마지막에 조각 함께 처치."
L["Tectus (Splitter)"] = "텍투스 (파편)"
L["Totenkopf und Kreuz auf die zwei Splitter, je ein Tank pro Symbol."] = "해골과 가위표는 파편 둘, 징표마다 탱커 하나."
L["Brackenspore + Pilz-Adds"] = "브래켄스포어 + 버섯 쫄"
L["- Nekrotischer Atem: frontaler Kegel -> nur der Tank vorne, Rest seitlich."] = "- 괴저의 숨결: 전방 부채꼴 -> 탱커만 앞에, 나머지는 옆."
L["- Fäulnis: stapelnder Tank-Debuff -> Tankwechsel."] = "- 부패: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Kriechendes Moos: heilt Boss und Adds -> mit den Flammenwerfern am Rand wegbrennen."] = "- 기어오는 이끼: 보스와 쫄 치유 -> 가장자리 화염방사기로 태우기."
L["- Pilzfleischfresser: Zerfall-Zauber -> unterbrechen und zuerst töten."] = "- 버섯 살점포식자: 부패 주문 -> 차단하고 먼저 처치."
L["- Befallende Sporen (100 Energie): Raid-Schaden -> Flammenwerfer bzw. Raid-Cooldowns, Heilpilze nutzen."] = "- 감염의 포자 (기력 100): 공격대 피해 -> 화염방사기 또는 공대 생존기, 치유 버섯 활용."
L["Taktik: Boss langsam durch den Raum tanken, Spieler an den Flammenwerfern einteilen, Fleischfresser unterbrechen und töten."] = "공략: 보스를 천천히 방을 가로질러 탱킹, 화염방사기 담당 배정, 살점포식자 차단 후 처치."
L["BRACKENSPORE: Fleischfresser unterbrechen und töten! Moos wegbrennen!"] = "브래켄스포어: 살점포식자 차단하고 처치! 이끼 태우기!"
L["Atem nur auf den Tank. Tankwechsel nach Fäulnis."] = "숨결은 탱커에게만. 부패 후 탱 교대."
L["Brackenspore"] = "브래켄스포어"
L["Totenkopf auf den aktuellen Pilzfleischfresser (unterbrechen und töten)."] = "해골은 현재 버섯 살점포식자 (차단 후 처치)."
L["Phemos und Pol"] = "페모스와 폴"
L["- Pol - Schildansturm: stürmt in einer Linie auf einen Spieler -> aus der Laufbahn gehen."] = "- 폴 - 방패 돌진: 플레이어 한 명에게 직선 돌진 -> 경로에서 비키기."
L["- Pol - Unterbrechender Schrei: unterbricht alle Zauber in Reichweite -> kurz vorher Zauber abbrechen."] = "- 폴 - 방해의 외침: 범위 내 모든 주문 차단 -> 직전에 시전 취소."
L["- Pol - Zermalmen: Flächen um Spieler -> verteilen und Steinen ausweichen."] = "- 폴 - 분쇄: 플레이어 주변 장판 -> 산개하고 돌 피하기."
L["- Phemos - Wirbelwind: hoher Nahkampfschaden und Feuerflächen -> Nahkampf vorsichtig, aus Feuer raus."] = "- 페모스 - 소용돌이: 큰 근접 피해와 불 장판 -> 근딜 주의, 불에서 나오기."
L["- Phemos - Schwächendes Gebrüll: Schaden wird auf alle Getroffenen geteilt -> eng zusammen stapeln."] = "- 페모스 - 약화의 포효: 피해가 맞은 모두에게 분담 -> 촘촘히 뭉치기."
L["Taktik: Beide Ogron nahe beieinander, aber Rücken zum Raid tanken; Fähigkeiten kommen nach Energiestand, Ansagen beachten und gleichmäßig Schaden machen."] = "공략: 오그론 둘을 가까이 붙이되 공대에 등을 돌리게 탱킹; 능력은 기력에 따라 나오니 콜 확인하고 균등하게 딜."
L["Mythisch: zusätzlich Arkane Volatilität (Spieler explodieren) -> stärker verteilen."] = "신화: 추가로 비전 변동성 (플레이어 폭발) -> 더 넓게 산개."
L["ZWILLINGSOGRON: Schildansturm ausweichen! Beim Schrei Zauber stoppen!"] = "쌍둥이 오그론: 방패 돌진 피하기! 외침 시 시전 멈추기!"
L["Gebrüll: eng stapeln. Wirbelwind: aus Feuer raus."] = "포효: 촘촘히 뭉치기. 소용돌이: 불에서 나오기."
L["Ko'ragh"] = "코라그"
L["- Barriere der Annullierung: Schild absorbiert Magieschaden -> mit körperlichem Schaden brechen, danach kanalisiert Ko'ragh und erhält Schadensbonus."] = "- 무효화의 방벽: 보호막이 마법 피해 흡수 -> 물리 피해로 깨기, 이후 코라그가 정신 집중하며 피해 증가 효과 획득."
L["- Überfließende Energie: Kugeln fallen auf den Boden -> von eingeteilten Spielern abfangen lassen, sonst Raid-Schaden."] = "- 넘치는 에너지: 구슬이 바닥에 떨어짐 -> 배정된 플레이어가 받기, 아니면 공격대 피해."
L["- Magie ausstoßen - Feuer: Explosion um den Spieler -> Raid teilt den Schaden durch Stapeln, Ziel bleibt stehen."] = "- 마법 방출 - 화염: 플레이어 주변 폭발 -> 공대가 뭉쳐서 피해 분담, 대상은 가만히."
L["- Magie ausstoßen - Arkan / Frost / Schatten: Tank-Debuff, verlangsamende Frostkugel, Heilabsorb -> Tank raus, Kugel ausweichen, gezielt heilen."] = "- 마법 방출 - 비전 / 냉기 / 암흑: 탱커 디버프, 감속시키는 냉기 구슬, 치유 흡수 -> 탱커 나가기, 구슬 피하기, 집중 힐."
L["- Unterdrückungsfeld: Fläche auf Spielern -> sofort verlassen."] = "- 억제 장막: 플레이어에게 장판 -> 즉시 벗어나기."
L["Taktik: Ko'ragh mittig tanken, Fänger für die Energiekugeln fest einteilen, Barriere schnell brechen und Ausstoßen-Mechanik je Element ansagen."] = "공략: 코라그는 중앙에서 탱킹, 에너지 구슬 받는 담당 고정 배정, 방벽은 빠르게 깨고 원소별 방출 기믹 콜."
L["KO'RAGH: Energiekugeln fangen! Barriere schnell brechen!"] = "코라그: 에너지 구슬 받기! 방벽 빠르게 깨기!"
L["Feuer: stapeln. Arkan: Tank raus. Frostkugel ausweichen."] = "화염: 뭉치기. 비전: 탱커 나가기. 냉기 구슬 피하기."
L["Imperator Mar'gok + Arkane Aberrationen, Gorische Adds"] = "황제 마르고크 + 비전 변형체, 고리안 쫄"
L["- Mal des Chaos: Tank-Debuff, explodiert -> Tank raus, Tankwechsel."] = "- 혼돈의 징표: 탱커 디버프, 폭발 -> 탱커 나가기, 탱 교대."
L["- Zerstörerische Resonanz: Minen -> ausweichen."] = "- 파괴의 공명: 지뢰 -> 피하기."
L["- Arkaner Zorn: springt zwischen Spielern -> verteilen."] = "- 비전 격노: 플레이어 사이를 튐 -> 산개."
L["- Arkane Aberrationen: Adds -> töten, Rückstoß beim Tod beachten."] = "- 비전 변형체: 쫄 -> 처치, 죽을 때 넉백 주의."
L["- Zwischenphasen: Gorische Adds -> unterbrechen und töten."] = "- 중간 단계: 고리안 쫄 -> 차단하고 처치."
L["Taktik: Vier Phasen mit Runen (Verdrängung, Befestigung, Replikation), Adds zuerst."] = "공략: 룬 (전위, 강화, 복제)이 있는 네 단계, 쫄 먼저."
L["Mythisch: zusätzliche Phase mit Cho'gall."] = "신화: 초갈과의 추가 단계."
L["MAR'GOK: Mal des Chaos - Tank raus! Minen ausweichen!"] = "마르고크: 혼돈의 징표 - 탱커 나가기! 지뢰 피하기!"
L["Adds zuerst. Zwischenphase: unterbrechen."] = "쫄 먼저. 중간 단계: 차단."
L["Mar'gok"] = "마르고크"
L["Totenkopf und Kreuz auf die Zwischenphasen-Adds."] = "해골과 가위표는 중간 단계 쫄."
L["Antorus, der Brennende Thron"] = "불타는 왕좌 안토러스"
L["Garothi Weltenbrecher + Dezimator- und Annihilatorkanone"] = "세계파괴자 가로시 + 학살자 대포와 섬멸자 대포"
L["- Dezimierung: markierte Spieler bekommen einen Treffer mit Flächenschaden -> markierte Spieler laufen vom Raid weg an den Rand."] = "- 학살: 표시된 플레이어가 광역 피해 공격을 받음 -> 표시된 플레이어는 공대에서 떨어져 가장자리로."
L["- Annihilation: Einschlagzonen auf dem Boden -> jede Zone mit mehreren Spielern soaken, sonst trifft es den ganzen Raid."] = "- 섬멸: 바닥에 충돌 구역 -> 구역마다 여러 명이 맞기, 아니면 공대 전체 피해."
L["- Teufelsbombardement: Tank-Debuff, hinterlässt Feuer -> Tank läuft aus dem Raid, Tankwechsel."] = "- 지옥 폭격: 탱커 디버프, 불을 남김 -> 탱커는 공대 밖으로, 탱 교대."
L["- Ausrottung (bei ca. 65 % und 35 %): starker Schaden je nach Nähe -> alle weit vom Boss weglaufen."] = "- 근절 (약 65 %와 35 %): 거리에 따라 강한 피해 -> 전원 보스에게서 멀리."
L["- Gemetzel (zwischen den Phasen): Raidschaden -> Heiler-Cooldowns bereithalten."] = "- 대학살 (단계 사이): 공격대 피해 -> 힐러 생존기 대기."
L["Taktik: Fernkampf locker verteilt hinter dem Boss, Soak-Gruppen für Annihilation fest einteilen. Bei den Phasenwechseln die Kanone zerstören, deren Mechanik für den Raid unangenehmer ist."] = "공략: 원딜은 보스 뒤에 느슨하게 산개, 섬멸 분담 그룹 고정 배정. 단계 전환 시 공대에 더 까다로운 기믹의 대포 파괴."
L["GAROTHI: Annihilation-Zonen soaken, Dezimierung raus an den Rand!"] = "가로시: 섬멸 구역 맞기, 학살 대상은 가장자리로!"
L["Bei Ausrottung alle weg vom Boss. Tankwechsel nach Bombardement."] = "근절 시 전원 보스에게서 멀리. 폭격 후 탱 교대."
L["F'harg + Shatug (zwei Teufelshunde)"] = "프하르그 + 샤투그 (지옥사냥개 둘)"
L["- Getrennte Hunde: F'harg (Feuer) und Shatug (Schatten) teilen Stärkungen, wenn sie zu nahe beieinander stehen -> Hunde weit auseinander tanken."] = "- 떨어진 사냥개: 프하르그 (화염)와 샤투그 (암흑)는 너무 가까우면 강화 효과 공유 -> 사냥개를 멀리 떨어뜨려 탱킹."
L["- Entflammte Verderbnis (F'harg): Spieler mit Debuff explodieren -> verteilt stehen, Feuerkreise am Rand ablegen."] = "- 불타는 부패 (프하르그): 디버프 받은 플레이어 폭발 -> 산개해서 서기, 불 원은 가장자리에."
L["- Verschlingende Sphäre (Shatug): Sphäre zieht Spieler an -> von der Sphäre weglaufen, nicht hineinziehen lassen."] = "- 집어삼키는 구체 (샤투그): 구체가 플레이어를 끌어당김 -> 구체에서 멀어지기, 빨려 들어가지 말 것."
L["- Trostloser Blick: markierte Spieler werden mit Linien verbunden -> sich so stellen, dass niemand sonst getroffen wird."] = "- 황량한 시선: 표시된 플레이어가 선으로 연결 -> 다른 사람이 맞지 않게 위치 잡기."
L["- Tank-Debuffs (Geschmolzene Berührung / Verderbender Biss) -> Tankwechsel nach Ansage."] = "- 탱커 디버프 (녹아내린 손길 / 타락의 이빨) -> 콜에 맞춰 탱 교대."
L["Taktik: Ein Tank pro Hund, Hunde an gegenüberliegenden Seiten, Raid in der Mitte. Schaden gleichmäßig verteilen, damit beide Hunde etwa gleichzeitig sterben."] = "공략: 사냥개마다 탱커 하나, 사냥개는 서로 반대편에, 공대는 중앙. 딜을 균등하게 해서 둘이 거의 동시에 죽게."
L["HUNDE: F'harg und Shatug weit auseinander tanken! Gleichmäßig schaden!"] = "지옥사냥개: 프하르그와 샤투그 멀리 떨어뜨려 탱킹! 균등 딜!"
L["Debuff-Spieler raus aus dem Raid, von Sphären weg. Tankwechsel nach Ansage."] = "디버프 대상은 공대 밖으로, 구체에서 멀리. 콜에 맞춰 탱 교대."
L["Teufelshunde"] = "지옥사냥개"
L["Totenkopf auf F'harg, Kreuz auf Shatug."] = "해골은 프하르그, 가위표는 샤투그."
L["Admiral Svirax + Chefingenieur Ishkar + General Erodus + Adds"] = "제독 스비락스 + 수석 기술자 이쉬카르 + 장군 에로더스 + 쫄"
L["- Kommandokapseln: ein aktiver Offizier kämpft, die anderen sitzen in Kapseln -> Spieler nutzen freie Kapseln für zusätzliche Fähigkeiten (z. B. Schild gegen Salve)."] = "- 지휘 포드: 활성 장교 하나만 싸우고 나머지는 포드에 탑승 -> 플레이어가 빈 포드로 추가 능력 사용 (예: 일제 사격 대비 보호막)."
L["- Salve (Svirax): hoher Raidschaden -> Raid stellt sich in den Schild des Kapselspielers oder nutzt Cooldowns."] = "- 일제 사격 (스비락스): 큰 공격대 피해 -> 공대가 포드 플레이어의 보호막 안에 서거나 생존기 사용."
L["- Entropische Minen (Ishkar): Minen am Boden -> nicht hineinlaufen, gezielt räumen."] = "- 엔트로피 지뢰 (이쉬카르): 바닥 지뢰 -> 밟지 말고 계획적으로 제거."
L["- Verstärkung (Erodus): Teufelsklingen-Stoßtruppler und Pyromanten -> Adds schnell töten, Zauber unterbrechen."] = "- 증원 (에로더스): 지옥칼날 돌격병과 화염술사 -> 쫄 빠르게 처치, 주문 차단."
L["- Schwäche ausnutzen: Tank-Debuff -> Tankwechsel nach Stapeln."] = "- 약점 공략: 탱커 디버프 -> 중첩 후 탱 교대."
L["Taktik: Aktiven Offizier fokussieren, Adds sofort umschalten. Kapselspieler fest einteilen und ihre Fähigkeiten auf Ansage nutzen."] = "공략: 활성 장교 점사, 쫄은 즉시 전환. 포드 플레이어 고정 배정, 콜에 맞춰 능력 사용."
L["OBERKOMMANDO: Adds sofort töten, bei Salve in den Schild!"] = "최고 사령부: 쫄 즉시 처치, 일제 사격 시 보호막 안으로!"
L["Kapselspieler nach Plan, Minen meiden. Tankwechsel nach Stapeln."] = "포드 플레이어는 계획대로, 지뢰 피하기. 중첩 후 탱 교대."
L["Oberkommando"] = "최고 사령부"
L["Totenkopf auf den aktiven Offizier, Kreuz und Viereck auf die Adds in Tötungsreihenfolge."] = "해골은 활성 장교, 가위표와 네모는 처치 순서대로 쫄."
L["Portalhüterin Hasabel + Portalwelten (Xoroth, Rancora, Nathreza)"] = "차원문 수호자 하사벨 + 차원문 세계 (조로스, 란코라, 나스레자)"
L["- Riss in der Realität: Tank-Debuff -> Tankwechsel nach Stapeln."] = "- 현실의 균열: 탱커 디버프 -> 중첩 후 탱 교대."
L["- Zusammenbrechende Welt: Einschlagzone vor dem Boss -> herauslaufen."] = "- 무너지는 세계: 보스 앞 충돌 구역 -> 빠져나오기."
L["- Teufelssturm-Sperrfeuer: Linien quer durch den Raum -> ausweichen."] = "- 지옥폭풍 탄막: 방을 가로지르는 선 -> 피하기."
L["- Portale: Hasabel öffnet Portale zu drei Welten, deren Wächter Adds herüberschicken -> Portal-Teams gehen hinein, töten den Wächter und schließen das Portal."] = "- 차원문: 하사벨이 세 세계로 차원문을 열고 수호자가 쫄을 보냄 -> 차원문 팀이 들어가 수호자 처치 후 차원문 닫기."
L["- Adds der Welten (z. B. Wichtel, Vulkanare): gefährliche Fähigkeiten -> unterbrechen und schnell töten."] = "- 세계별 쫄 (예: 임프, 화산정령): 위험한 능력 -> 차단하고 빠르게 처치."
L["Taktik: Kleine Teams (meist 3-5 Spieler mit Heiler) für die Portale einteilen, der Rest bleibt am Boss. Portale zügig schließen, sonst steigt der Raidschaden stark an."] = "공략: 차원문용 소규모 팀 (보통 힐러 포함 3-5명) 배정, 나머지는 보스. 차원문은 빨리 닫기, 아니면 공격대 피해 급증."
L["HASABEL: Portal-Teams rein, Wächter töten, Portal schließen!"] = "하사벨: 차원문 팀 진입, 수호자 처치, 차원문 닫기!"
L["Linien ausweichen, Adds unterbrechen. Tankwechsel nach Riss."] = "선 피하기, 쫄 차단. 균열 후 탱 교대."
L["Hasabel (Portale)"] = "하사벨 (차원문)"
L["Totenkopf, Kreuz und Viereck markieren die drei Portale (Xoroth, Rancora, Nathreza) für die Teams."] = "해골, 가위표, 네모로 팀용 차원문 셋 (조로스, 란코라, 나스레자) 표시."
L["Essenz von Eonar + Wellen der Legion"] = "이오나의 정수 + 군단의 웨이브"
L["- Essenz von Eonar: muss überleben -> Heiler heilen die Essenz, Adds dürfen sie nicht erreichen."] = "- 이오나의 정수: 살아남아야 함 -> 힐러가 정수를 힐, 쫄이 닿으면 안 됨."
L["- Drei Wege (oben, Mitte, unten): Adds kommen über verschiedene Pfade -> Gruppen fest auf die Wege verteilen."] = "- 세 갈래 길 (위, 중앙, 아래): 쫄이 여러 경로로 옴 -> 그룹을 길마다 고정 배정."
L["- Teufelszerstörer und Verhüller: starke Adds mit Schilden/Unsichtbarkeit -> priorisiert töten."] = "- 지옥 파괴자와 은폐자: 보호막/투명화가 있는 강한 쫄 -> 우선 처치."
L["- Läuterer: Adds, die die Essenz angreifen -> sofort töten."] = "- 정화자: 정수를 공격하는 쫄 -> 즉시 처치."
L["- Paraxis-Beschuss (Regen des Teufels, Speer der Verdammnis): Einschläge und Linien -> ausweichen."] = "- 파락시스 포격 (지옥의 비, 파멸의 창): 충돌과 선 -> 피하기."
L["Taktik: Raid in Teams aufteilen und mit den Sprungfeldern zu den Wegen wechseln. Heiler halten die Essenz hoch und kümmern sich zusätzlich um den Raid."] = "공략: 공대를 팀으로 나누고 도약 패드로 길 사이 이동. 힐러는 정수를 유지하면서 공대도 챙기기."
L["Mythisch: Paraxis muss zusätzlich beschädigt werden (Spieler fliegen hoch), dafür eigenes Team einteilen."] = "신화: 파락시스도 공격해야 함 (플레이어가 위로 날아감), 전용 팀 배정."
L["EONAR: Adds auf allen Wegen töten, Essenz am Leben halten!"] = "이오나: 모든 길의 쫄 처치, 정수 살리기!"
L["Teams auf ihre Wege, Läuterer sofort töten. Einschlägen ausweichen."] = "팀은 각자 길로, 정화자 즉시 처치. 충돌 피하기."
L["Imonar der Seelenjäger"] = "영혼사냥꾼 이모나르"
L["- Schocklanze: Tank-Debuff -> Tankwechsel nach Stapeln."] = "- 충격 창: 탱커 디버프 -> 중첩 후 탱 교대."
L["- Schlafkanister: Spieler schläft ein -> nicht in der Nähe anderer stehen, Heiler bannen erst, wenn der Spieler allein steht."] = "- 수면 가스통: 플레이어가 잠듦 -> 다른 사람 근처에 서지 말 것, 힐러는 혼자 있을 때만 해제."
L["- Pulsgranate: Flächenschaden an markierter Stelle -> ausweichen."] = "- 파동 수류탄: 표시된 지점에 광역 피해 -> 피하기."
L["- Zwischenphasen: Imonar flieht über die Brücke und legt Fallen -> Fallen ausweichen und ihm folgen."] = "- 중간 단계: 이모나르가 다리를 건너 도주하며 덫 설치 -> 덫 피하며 따라가기."
L["- Spätere Phasen: Sprengsprengladungen und Feuer -> sauber laufen, Raidschaden steigt."] = "- 후반 단계: 폭파 장약과 불 -> 깔끔하게 이동, 공격대 피해 증가."
L["Taktik: Boss am Rand der Plattform tanken, Raid locker verteilt. In den Zwischenphasen gemeinsam über die Brücke laufen und Fallen meiden."] = "공략: 보스는 단상 가장자리에서 탱킹, 공대는 느슨하게 산개. 중간 단계엔 함께 다리를 건너고 덫 피하기."
L["IMONAR: Schlafende Spieler weg vom Raid, dann bannen!"] = "이모나르: 잠든 플레이어는 공대에서 멀리, 그다음 해제!"
L["Zwischenphase: Fallen ausweichen, Boss folgen. Tankwechsel nach Schocklanze."] = "중간 단계: 덫 피하고 보스 따라가기. 충격 창 후 탱 교대."
L["Kin'garoth + Konstrukte"] = "킨가로스 + 구조물"
L["- Verheerer: Strahl fegt über die Plattform -> ausweichen."] = "- 파괴자: 광선이 단상을 휩쓺 -> 피하기."
L["- Diabolische Bombe: Bomben müssen gesoakt werden -> mehrere Spieler pro Bombe."] = "- 악마의 폭탄: 폭탄은 맞아야 함 -> 폭탄마다 여러 명."
L["- Schmiedeschlag / Widerhallender Schlag: starke Tank-Treffer -> Tankwechsel."] = "- 연마의 강타 / 울려 퍼지는 강타: 강한 탱커 공격 -> 탱 교대."
L["- Abriss: markierte Spieler -> gemeinsam soaken lassen, nicht weglaufen."] = "- 철거: 표시된 플레이어 -> 함께 맞게 하기, 도망가지 말 것."
L["- Initialisierungsphase: Konstrukte (Dezimator, Annihilator, Abrissmaschine) werden gebaut -> vorher Schaden aufbauen, Konstrukte schnell zerstören."] = "- 초기화 단계: 구조물 (학살자, 섬멸자, 철거 기계) 건설 -> 미리 딜 준비, 구조물 빠르게 파괴."
L["Taktik: In der Initialisierungsphase die Konstrukte fokussieren, in der Angriffsphase Bomben soaken und Verheerer ausweichen. Tanks wechseln nach jedem schweren Schlag."] = "공략: 초기화 단계엔 구조물 점사, 공격 단계엔 폭탄 맞고 파괴자 피하기. 무거운 강타마다 탱 교대."
L["KIN'GAROTH: Konstrukte schnell zerstören, Bomben soaken!"] = "킨가로스: 구조물 빠르게 파괴, 폭탄 맞기!"
L["Verheerer ausweichen. Tankwechsel nach Schlag."] = "파괴자 피하기. 강타 후 탱 교대."
L["Kin'garoth"] = "킨가로스"
L["Totenkopf, Kreuz und Viereck auf die Konstrukte in Tötungsreihenfolge."] = "해골, 가위표, 네모는 처치 순서대로 구조물."
L["Varimathras"] = "바리마트라스"
L["- Qualen (Flammen, Frost, Teufel, Schatten): wechselnde Umgebungsgefahr -> auf die jeweilige Mechanik achten (z. B. Feuer am Boden, Frost-Zonen)."] = "- 고문 (화염, 냉기, 지옥, 암흑): 바뀌는 환경 위험 -> 해당 기믹 주의 (예: 바닥 불, 냉기 구역)."
L["- Elend: Spieler werden getroffen -> nicht in andere Spieler hineinlaufen."] = "- 불행: 플레이어가 피해를 받음 -> 다른 플레이어 쪽으로 가지 말 것."
L["- Dunkle Spalte: Flächen am Boden -> herausgehen."] = "- 어둠의 균열: 바닥 장판 -> 벗어나기."
L["- Nekrotische Umarmung: Debuff springt auf nahe Spieler -> Spieler mit Debuff steht allein am Rand."] = "- 괴저의 포옹: 디버프가 가까운 플레이어에게 튐 -> 디버프 받은 플레이어는 혼자 가장자리에."
L["- Tank-Mechanik (Schattenstoß / Allein in der Finsternis): Tanks müssen nahe beieinander stehen -> Tankwechsel nach Ansage."] = "- 탱커 기믹 (암흑 일격 / 어둠 속에 홀로): 탱커는 가까이 붙어 있어야 함 -> 콜에 맞춰 탱 교대."
L["Taktik: Boss in der Mitte tanken, Raid verteilt. Debuff-Spieler sofort raus, Heiler-Cooldowns für die späten Qualen planen."] = "공략: 보스는 중앙에서 탱킹, 공대는 산개. 디버프 대상은 즉시 나가기, 후반 고문에 힐러 생존기 계획."
L["VARIMATHRAS: Nekrotische Umarmung sofort weg vom Raid!"] = "바리마트라스: 괴저의 포옹은 즉시 공대 밖으로!"
L["Spalten meiden, Tanks nah zusammen. Auf aktuelle Qual achten."] = "균열 피하기, 탱커는 가까이. 현재 고문 주의."
L["Asara + Noura + Diima + Thu'raya (Zirkel der Shivarra)"] = "아사라 + 누라 + 디이마 + 투라야 (쉬바라 집회)"
L["- Qualen der Titanen: Geister von Aman'Thul, Khaz'goroth, Golganneth und Norgannon greifen nacheinander an -> je nach Titan Linien, Kugeln oder Stürmen ausweichen."] = "- 티탄의 고문: 아만툴, 카즈고로스, 골가네스, 노르간논의 혼령이 차례로 공격 -> 티탄에 따라 선, 구슬, 폭풍 피하기."
L["- Wirbelnder Säbel / Feuriger Schlag: Tank-Fähigkeiten -> Tankwechsel."] = "- 회전하는 언월도 / 불타는 일격: 탱커 능력 -> 탱 교대."
L["- Explodierender Puls (Noura): Spieler explodieren -> verteilt stehen."] = "- 폭발 파동 (누라): 플레이어 폭발 -> 산개해서 서기."
L["- Gekühltes Blut (Diima): Heilabsorption -> gezielt wegheilen."] = "- 차가운 피 (디이마): 치유 흡수 -> 집중 힐로 지우기."
L["- Sturm der Dunkelheit (Asara): Raidschaden -> im Schutzbereich stehen."] = "- 어둠의 폭풍 (아사라): 공격대 피해 -> 보호 구역 안에 서기."
L["Taktik: Immer nur die aktiven Schwestern angreifen, Schaden auf die gefährlichste fokussieren. Raid verteilt, Heiler priorisieren Gekühltes Blut."] = "공략: 항상 활성 자매만 공격, 가장 위험한 자매에 점사. 공대는 산개, 힐러는 차가운 피 우선."
L["ZIRKEL: Titan-Geistern ausweichen, Gekühltes Blut wegheilen!"] = "집회: 티탄 혼령 피하기, 차가운 피 힐로 지우기!"
L["Verteilt stehen. Tankwechsel nach Ansage."] = "산개해서 서기. 콜에 맞춰 탱 교대."
L["Zirkel der Shivarra"] = "쉬바라 집회"
L["Je ein Symbol pro Schwester (Totenkopf Asara, Kreuz Noura, Viereck Diima, Mond Thu'raya)."] = "자매마다 징표 하나 (해골 아사라, 가위표 누라, 네모 디이마, 달 투라야)."
L["Aggramar + Glut von Taeshalach"] = "아그라마르 + 타에샬라크의 잉걸불"
L["- Taeshalachs Reichweite: stapelnder Tank-Debuff -> Tankwechsel."] = "- 타에샬라크의 사거리: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Taeshalachs Technik: Kombo aus Flammenriss (Soak vor dem Boss), Tempest/Feuerwellen und Wuchtschlag -> Ansage folgen, Flammenriss mit vielen Spielern soaken."] = "- 타에샬라크의 기술: 화염 균열 (보스 앞 맞기), 폭풍/화염 파도, 강타로 이어지는 연속기 -> 콜 따르기, 화염 균열은 여럿이 맞기."
L["- Sengende Flammen: Feuerflächen -> herauslaufen."] = "- 이글거리는 불길: 불 장판 -> 빠져나오기."
L["- Zwischenphasen (80 % / 40 %): Glut von Taeshalach erscheint -> Glut töten, bevor sie den Boss erreicht."] = "- 중간 단계 (80 % / 40 %): 타에샬라크의 잉걸불 등장 -> 보스에게 닿기 전에 처치."
L["- Wogende Flammen: Linien am Boden -> ausweichen."] = "- 솟구치는 불길: 바닥의 선 -> 피하기."
L["Taktik: Raid hinter dem Boss, Nahkampf/Fernkampf soaken die Flammenrisse nach Einteilung. In den Zwischenphasen alle Gluten verlangsamen und töten."] = "공략: 공대는 보스 뒤, 근딜/원딜이 배정대로 화염 균열 맞기. 중간 단계엔 잉걸불 모두 감속 후 처치."
L["AGGRAMAR: Flammenriss soaken, in Zwischenphasen Glut töten!"] = "아그라마르: 화염 균열 맞기, 중간 단계엔 잉걸불 처치!"
L["Feuerlinien ausweichen. Tankwechsel nach Stapeln."] = "불 선 피하기. 중첩 후 탱 교대."
L["Argus der Zerrütter + Konstellare und Adds"] = "파멸자 아르거스 + 별자리 전사와 쫄"
L["- Schwungvolle Sense: stapelnder Tank-Debuff -> Tankwechsel."] = "- 휩쓰는 낫: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Seelenfäule: Spieler mit Debuff -> raus aus dem Raid, Kugeln nicht treffen lassen."] = "- 영혼 부패: 디버프 받은 플레이어 -> 공대 밖으로, 구슬에 맞지 않게."
L["- Geschenk des Himmels / des Meeres: Spieler mit diesen Buffs -> getrennt voneinander stehen, Rest verteilt."] = "- 하늘의 선물 / 바다의 선물: 이 버프를 받은 플레이어 -> 서로 떨어져 서기, 나머지는 산개."
L["- Seelenbombe / Seelenexplosion (Phase 2): markierte Spieler -> nach Plan weglaufen bzw. sammeln."] = "- 영혼 폭탄 / 영혼 폭발 (2단계): 표시된 플레이어 -> 계획대로 도망가거나 모이기."
L["- Phase 3: Pantheon-Konstellaren und Module -> Adds töten, Seelen der Pantheon nutzen."] = "- 3단계: 판테온 별자리 전사와 모듈 -> 쫄 처치, 판테온의 영혼 활용."
L["Taktik: Mehrphasiger Endkampf mit Tankwechseln und vielen Positionen; Debuff-Spieler laufen vor dem Ablauf raus. Raid-Cooldowns für die Phasenübergänge planen."] = "공략: 탱 교대와 많은 위치 선정이 필요한 다단계 최종 전투; 디버프 대상은 만료 전에 나가기. 단계 전환에 공대 생존기 계획."
L["ARGUS: Debuff-Spieler raus, Himmel und Meer getrennt!"] = "아르거스: 디버프 대상은 나가기, 하늘과 바다는 떨어지기!"
L["Phasen nach Plan, Adds schnell töten. Tankwechsel nach Sense."] = "단계는 계획대로, 쫄 빠르게 처치. 낫 후 탱 교대."
L["Der Smaragdgrüne Albtraum"] = "에메랄드의 악몽"
L["Nythendra"] = "니센드라"
L["- Befallener Atem: Kegelangriff -> nicht vor dem Boss stehen."] = "- 감염된 숨결: 부채꼴 공격 -> 보스 앞에 서지 말 것."
L["- Fäulnis: Spieler mit Debuff hinterlassen Gift am Boden -> an den Rand laufen und dort ablegen."] = "- 부패: 디버프 받은 플레이어가 바닥에 독을 남김 -> 가장자리로 가서 내려놓기."
L["- Instabile Fäulnis: Tank-Debuff explodiert -> Tankwechsel, Tank läuft kurz vor Ablauf weg."] = "- 불안정한 부패: 탱커 디버프 폭발 -> 탱 교대, 탱커는 만료 직전에 멀어지기."
L["- Herz des Schwarms: Nythendra zieht sich zurück, Käfer aus den Giftflächen -> Flächen meiden, Käfer schnell töten."] = "- 무리의 심장: 니센드라가 물러나고 독 장판에서 벌레 생성 -> 장판 피하기, 벌레 빠르게 처치."
L["Taktik: Raid verteilt hinter dem Boss, Giftflächen nur am Rand ablegen, damit die Mitte frei bleibt."] = "공략: 공대는 보스 뒤에 산개, 독 장판은 가장자리에만 내려놓아 중앙을 비워두기."
L["NYTHENDRA: Fäulnis am Rand ablegen, nicht vor den Boss!"] = "니센드라: 부패는 가장자리에, 보스 앞 금지!"
L["Käfer beim Herz des Schwarms töten. Tankwechsel nach Instabiler Fäulnis."] = "무리의 심장 때 벌레 처치. 불안정한 부패 후 탱 교대."
L["Auge von Il'gynoth + Tentakel + Albtraumichor"] = "일기노스의 눈 + 촉수 + 악몽의 영액"
L["- Albtraumichor: Adds explodieren beim Tod -> am Auge töten, damit die Explosion das Auge beschädigt; Spieler stehen nicht in der Explosion."] = "- 악몽의 영액: 쫄이 죽을 때 폭발 -> 눈 옆에서 처치해 폭발로 눈에 피해; 플레이어는 폭발 범위 밖에."
L["- Todesstarrtentakel: wirken Gedankenschinden -> unterbrechen."] = "- 죽음의 시선 촉수: 정신의 채찍 시전 -> 차단."
L["- Herrschertentakel: Tank-Adds -> von Tanks abholen lassen."] = "- 지배의 촉수: 탱커용 쫄 -> 탱커가 잡기."
L["- Verderbertentakel: spucken Verderbnis -> Spieler mit Debuff aus dem Raid."] = "- 타락의 촉수: 타락을 뱉음 -> 디버프 받은 플레이어는 공대 밖으로."
L["- Herzphase: Ist das Auge tot, geht der Raid ins Innere und beschädigt das Herz -> Schaden-Cooldowns hier nutzen."] = "- 심장 단계: 눈이 죽으면 공대가 내부로 들어가 심장 공격 -> 여기서 딜 쿨기 사용."
L["Taktik: Außen Adds kontrollieren, Ichor am Auge töten. In der Herzphase alle Cooldowns, dann wiederholt sich der Zyklus."] = "공략: 밖에선 쫄 관리, 영액은 눈 옆에서 처치. 심장 단계엔 모든 쿨기, 이후 순환 반복."
L["IL'GYNOTH: Ichor am Auge töten, Tentakel unterbrechen!"] = "일기노스: 영액은 눈 옆에서 처치, 촉수 차단!"
L["Herzphase: alle Cooldowns aufs Herz."] = "심장 단계: 모든 쿨기를 심장에."
L["Il'gynoth"] = "일기노스"
L["Totenkopf und Kreuz auf Todesstarrtentakel (Unterbrecher), Viereck und Mond auf Herrschertentakel."] = "해골과 가위표는 죽음의 시선 촉수 (차단), 네모와 달은 지배의 촉수."
L["Elerethe Renferal + Spinnlinge"] = "엘레레테 렌페랄 + 새끼 거미"
L["- Spinnenform - Nekrotisches Gift: Spieler hinterlassen Giftflächen -> am Rand ablegen."] = "- 거미 형상 - 괴저의 독: 플레이어가 독 장판을 남김 -> 가장자리에 내려놓기."
L["- Spinnenform - Netz des Schmerzes: zwei Spieler teilen Schaden -> Partner nicht trennen."] = "- 거미 형상 - 고통의 거미줄: 두 플레이어가 피해 분담 -> 짝과 떨어지지 말 것."
L["- Spinnenform - Wirbelnde Schatten: Einschläge -> ausweichen."] = "- 거미 형상 - 소용돌이치는 그림자: 충돌 -> 피하기."
L["- Rabenform - Rasierflügel: Linienangriff -> ausweichen."] = "- 까마귀 형상 - 면도날 날개: 직선 공격 -> 피하기."
L["- Rabenform - Sich sammelnde Wolken / Dunkler Sturm: Schaden durch Wolken -> im Auge des Sturms stehen."] = "- 까마귀 형상 - 모여드는 구름 / 어둠의 폭풍: 구름 피해 -> 폭풍의 눈 안에 서기."
L["- Spinnlinge (Adds): -> töten, Netzwege zur Plattform nutzen."] = "- 새끼 거미 (쫄): -> 처치, 거미줄 길로 단상 이동."
L["Taktik: Spinnenform: verteilt stehen, Gift am Rand. Rabenform: Linien ausweichen und gemeinsam im Sturm stehen."] = "공략: 거미 형상: 산개해서 서기, 독은 가장자리에. 까마귀 형상: 선 피하고 함께 폭풍 안에 서기."
L["RENFERAL: Gift am Rand ablegen, Rasierflügel ausweichen!"] = "렌페랄: 독은 가장자리에, 면도날 날개 피하기!"
L["Rabenphase: in den Dunklen Sturm stellen."] = "까마귀 단계: 어둠의 폭풍 안으로."
L["Ursoc"] = "우르속"
L["- Überwältigen / Fleisch zerfetzen: stapelnde Tank-Debuffs -> Tankwechsel."] = "- 압도 / 살점 찢기: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Fokussierter Blick: Ursoc stürmt zu markiertem Spieler -> Soak-Gruppe stellt sich in Linie zwischen Boss und Ziel."] = "- 집중된 시선: 우르속이 표시된 플레이어에게 돌진 -> 분담 그룹이 보스와 대상 사이에 일렬로 서기."
L["- Schwung: Soaker bekommen Debuff -> zwei Soak-Gruppen abwechseln."] = "- 탄력: 분담한 플레이어가 디버프를 받음 -> 분담 그룹 둘이 번갈아."
L["- Brüllende Kakophonie: Raidschaden + Albtraumbilder (Adds) -> Adds töten/kontrollieren."] = "- 포효하는 불협화음: 공격대 피해 + 악몽의 형상 (쫄) -> 쫄 처치/제어."
L["- Raserei (bei 30 %): mehr Schaden -> Heiler- und Tank-Cooldowns."] = "- 광폭 (30 %): 피해 증가 -> 힐러와 탱커 생존기."
L["Taktik: Zwei feste Soak-Gruppen für Fokussierten Blick einteilen, Raid hinter dem Ziel. Ab 30 % alles reinwerfen."] = "공략: 집중된 시선용 고정 분담 그룹 둘 배정, 공대는 대상 뒤. 30 %부터 모든 것 쏟아붓기."
L["URSOC: Fokussierter Blick soaken, Gruppen abwechseln!"] = "우르속: 집중된 시선 맞기, 그룹 번갈아!"
L["Tankwechsel nach Stapeln. Ab 30 % Raserei: Cooldowns."] = "중첩 후 탱 교대. 30 % 광폭: 생존기."
L["Ysondre + Emeriss + Lethon + Taerar (Drachen des Albtraums)"] = "이손드레 + 에메리스 + 레톤 + 타에라르 (악몽의 용)"
L["- Zwei bis drei Drachen gleichzeitig, Ysondre immer dabei -> Drachen getrennt tanken, Drachenmale verhindern Tankwechsel auf denselben Drachen."] = "- 동시에 용 둘에서 셋, 이손드레는 항상 등장 -> 용은 따로 탱킹, 용의 징표 때문에 같은 용으로 탱 교대 불가."
L["- Emeriss: Flüchtige Infektion -> verteilt stehen; Essenz der Verderbnis (Adds) -> unterbrechen/töten."] = "- 에메리스: 휘발성 감염 -> 산개해서 서기; 타락의 정수 (쫄) -> 차단/처치."
L["- Lethon: Geist absaugen -> Schattengeister erreichen den Drachen, schnell töten."] = "- 레톤: 영혼 흡수 -> 그림자 영혼이 용에게 도달, 빠르게 처치."
L["- Taerar: Schatten von Taerar (Adds) und Brüllendes Gebrüll (Furcht) -> Adds töten, Furcht-Schutz."] = "- 타에라르: 타에라르의 그림자 (쫄)와 포효 (공포) -> 쫄 처치, 공포 방지."
L["- Albtraumfelder / Atem: -> nicht vor die Drachen stellen, Felder meiden."] = "- 악몽의 장 / 숨결: -> 용 앞에 서지 말고 장 피하기."
L["Taktik: Drachen an verschiedenen Stellen tanken, Ysondre und den aktiven Zweitdrachen gleichmäßig senken. Adds je nach Drache priorisieren."] = "공략: 용은 서로 다른 곳에서 탱킹, 이손드레와 활성 두 번째 용의 생명력을 균등하게 깎기. 쫄은 용에 따라 우선순위."
L["DRACHEN: Getrennt tanken, Adds der Drachen sofort töten!"] = "악몽의 용: 따로 탱킹, 용의 쫄은 즉시 처치!"
L["Nicht vor die Köpfe, bei Emeriss verteilen."] = "머리 앞 금지, 에메리스 때 산개."
L["Drachen des Albtraums"] = "악몽의 용"
L["Ein Symbol pro aktivem Drachen (Totenkopf Ysondre), damit Tanks und Schadensverteilung klar sind."] = "활성 용마다 징표 하나 (해골 이손드레), 탱커와 딜 분배가 명확하도록."
L["Cenarius + Kräfte des Albtraums"] = "세나리우스 + 악몽의 세력"
L["- Kräfte des Albtraums: Adds (Irrwische, Drachen, Uralte, Verdrehte Schwestern) -> töten oder durch Heilung auf Gereinigtem Boden bekehren."] = "- 악몽의 세력: 쫄 (도깨비불, 용, 고대정령, 뒤틀린 자매) -> 처치하거나 정화된 땅에서 힐로 전향시키기."
L["- Kriechende Albträume: stapelnder Debuff -> auf gereinigten Boden gehen, um ihn zu senken."] = "- 기어오는 악몽: 중첩 디버프 -> 정화된 땅으로 가서 줄이기."
L["- Albtraumdornen: Ranken verfolgen einen Spieler -> Spieler zieht sie weg vom Raid."] = "- 악몽의 가시: 덩굴이 플레이어 한 명을 추적 -> 대상이 공대 밖으로 끌고 가기."
L["- Tank-Debuffs: -> Tankwechsel nach Stapeln."] = "- 탱커 디버프: -> 중첩 후 탱 교대."
L["- Späte Phase: mehr Adds und Raidschaden -> Heiler-Cooldowns, Fokus auf den Boss."] = "- 후반 단계: 쫄과 공격대 피해 증가 -> 힐러 생존기, 보스 집중."
L["Taktik: Gereinigte Adds helfen dem Raid, verdorbene Drachen und Uralte priorisieren. Debuffs auf gereinigtem Boden abbauen."] = "공략: 정화된 쫄은 공대를 도움, 타락한 용과 고대정령 우선. 디버프는 정화된 땅에서 해소."
L["CENARIUS: Adds kontrollieren, Stapel auf gereinigtem Boden abbauen!"] = "세나리우스: 쫄 관리, 중첩은 정화된 땅에서 해소!"
L["Ranken weg vom Raid ziehen. Tankwechsel nach Ansage."] = "덩굴은 공대 밖으로 끌기. 콜에 맞춰 탱 교대."
L["Xavius + Albtraumadds"] = "자비우스 + 악몽 쫄"
L["- Verderbnis-Leiste: steigt durch Mechaniken -> niedrig halten, bei 100 übernimmt Xavius den Spieler."] = "- 타락 게이지: 기믹으로 상승 -> 낮게 유지, 100이면 자비우스가 플레이어를 지배."
L["- Albtraumklingen: Klingen zwischen Spielern -> nicht in den Linien stehen."] = "- 악몽의 칼날: 플레이어 사이의 칼날 -> 선 위에 서지 말 것."
L["- Verdunkelnde Seele: Magie-Debuff, beim Bannen entsteht eine Fläche -> nur am Rand bannen."] = "- 어두워지는 영혼: 마법 디버프, 해제 시 장판 생성 -> 가장자리에서만 해제."
L["- Fesseln des Schreckens (Phase 2): zwei Spieler verbunden -> zusammenlaufen."] = "- 공포의 속박 (2단계): 두 플레이어 연결 -> 서로 모이기."
L["- Verderbnis-Schrecken (Add) -> von einem Tank übernehmen, Schaden darauf."] = "- 타락의 공포 (쫄) -> 탱커 하나가 잡기, 딜 집중."
L["- Traumsimulakrum: bei tödlichem Schaden fallen Spieler in den Traum -> zurückkehren, solange möglich."] = "- 꿈의 환영: 치명적 피해 시 플레이어가 꿈으로 떨어짐 -> 가능할 때 복귀."
L["Taktik: Verderbnis bewusst klein halten, Bannflächen am Rand. In Phase 3 Tentakel und Boss gleichzeitig kontrollieren."] = "공략: 타락은 의식적으로 낮게 유지, 해제 장판은 가장자리에. 3단계엔 촉수와 보스를 동시에 관리."
L["XAVIUS: Verderbnis niedrig halten, nur am Rand bannen!"] = "자비우스: 타락 낮게 유지, 해제는 가장자리에서만!"
L["Verbundene Spieler zusammen. Schrecken-Add vom Tank holen."] = "연결된 플레이어는 함께. 공포 쫄은 탱커가 잡기."
L["Die Nachtfestung"] = "밤의 요새"
L["Skorpyron + Kristall-, Säure- und Instabile Skorpide"] = "스코피론 + 수정, 산성, 불안정한 전갈"
L["- Arkanhieb: Tank-Kombo -> Tankwechsel nach jeder Kombo."] = "- 비전 강타: 탱커 연속기 -> 연속기마다 탱 교대."
L["- Schockwelle: tödlicher Raidschaden -> hinter einem abgefallenen blauen Kristallsplitter verstecken."] = "- 충격파: 치명적 공격대 피해 -> 떨어진 파란 수정 파편 뒤에 숨기."
L["- Kristallsplitter: fallen vom Boss -> nicht zerstören, solange sie als Deckung gebraucht werden."] = "- 수정 파편: 보스에게서 떨어짐 -> 엄폐물로 필요한 동안은 파괴 금지."
L["- Skorpid-Adds: kristallin, säurehaltig, instabil -> mit Flächenschaden töten, instabile Adds nicht im Raid platzen lassen."] = "- 전갈 쫄: 수정, 산성, 불안정 -> 광역으로 처치, 불안정한 쫄은 공대 안에서 터지지 않게."
L["Taktik: Raid hinter dem Boss, vor jeder Schockwelle zu den Splittern laufen. Adds zusammen ziehen und mit AoE töten."] = "공략: 공대는 보스 뒤, 충격파마다 파편 쪽으로 이동. 쫄은 모아서 광역으로 처치."
L["SKORPYRON: Bei Schockwelle hinter Kristallsplitter!"] = "스코피론: 충격파 시 수정 파편 뒤로!"
L["Tankwechsel nach Arkanhieb. Adds mit AoE töten."] = "비전 강타 후 탱 교대. 쫄은 광역으로 처치."
L["Chronomatische Anomalie + Zeitpartikel"] = "시간 변형체 + 시간 입자"
L["- Zeitgeschwindigkeit wechselt (normal, schnell, langsam) -> Fähigkeiten kommen je nach Phase schneller oder langsamer."] = "- 시간 속도 변화 (보통, 빠름, 느림) -> 단계에 따라 능력이 더 빠르거나 느리게 나옴."
L["- Zeitfreisetzung: Heilabsorption, die beim Ablauf explodiert -> vor dem Ablauf komplett wegheilen."] = "- 시간 방출: 만료 시 폭발하는 치유 흡수 -> 만료 전에 완전히 힐로 지우기."
L["- Zeitbombe: Spieler explodiert -> rechtzeitig aus dem Raid laufen."] = "- 시간 폭탄: 플레이어 폭발 -> 제때 공대 밖으로."
L["- Schwindendes Zeitpartikel (Add): explodiert bei Tod oder Ablauf -> kontrolliert töten, Heiler bereit."] = "- 사라지는 시간 입자 (쫄): 죽거나 만료되면 폭발 -> 계획적으로 처치, 힐러 대기."
L["- Kraft überwältigt: Tank-Stapel -> Tankwechsel."] = "- 압도하는 힘: 탱커 중첩 -> 탱 교대."
L["Taktik: Phasenablauf kennen und Cooldowns auf die schnellen Abschnitte legen. Heiler priorisieren Zeitfreisetzung."] = "공략: 단계 흐름을 숙지하고 빠른 구간에 생존기 배치. 힐러는 시간 방출 우선."
L["ANOMALIE: Zeitfreisetzung wegheilen, Zeitbomben raus!"] = "시간 변형체: 시간 방출 힐로 지우기, 시간 폭탄은 밖으로!"
L["Partikel kontrolliert töten. Tankwechsel nach Stapeln."] = "입자는 계획적으로 처치. 중첩 후 탱 교대."
L["Trilliax + Putzroboter"] = "트릴리악스 + 청소 로봇"
L["- Modi wechseln (Reiniger, Wahnsinniger, Hausmeister) -> Mechanik jedes Modus kennen."] = "- 모드 전환 (청소부, 광인, 관리인) -> 모드별 기믹 숙지."
L["- Wahnsinniger: Arkane Fesseln verbinden Spieler -> Verbundene stehen zusammen, Verbindungen nicht durch andere ziehen."] = "- 광인: 비전 족쇄가 플레이어를 연결 -> 연결된 플레이어끼리 함께 서기, 연결선을 다른 사람에게 지나가게 하지 말 것."
L["- Hausmeister: Kuchen/Giftige Stücke liegen herum -> nach Einteilung essen, giftige Stücke nicht zu oft."] = "- 관리인: 케이크/독성 조각이 널려 있음 -> 배정대로 먹기, 독성 조각은 너무 자주 먹지 말 것."
L["- Reiniger: Putzroboter erscheinen -> schnell töten."] = "- 청소부: 청소 로봇 등장 -> 빠르게 처치."
L["- Vernichtung: starker Raidschaden -> Cooldowns."] = "- 소멸: 강한 공격대 피해 -> 생존기."
L["Taktik: Boss in der Mitte, Raid verteilt. Kuchen-Esser und Add-Gruppe fest einteilen."] = "공략: 보스는 중앙, 공대는 산개. 케이크 먹는 담당과 쫄 그룹 고정 배정."
L["TRILLIAX: Verbundene zusammen, Kuchen nach Einteilung essen!"] = "트릴리악스: 연결된 플레이어는 함께, 케이크는 배정대로!"
L["Putzroboter schnell töten. Cooldowns für Vernichtung."] = "청소 로봇 빠르게 처치. 소멸에 생존기."
L["Aluriel die Zauberklinge + Verzauberungen (Adds)"] = "마법검사 알루리엘 + 마법부여 (쫄)"
L["- Vernichten: großer Tank-Treffer -> Tankwechsel nach jedem Vernichten."] = "- 소멸: 큰 탱커 공격 -> 소멸마다 탱 교대."
L["- Frostphase - Frostmal: Spieler springen ab und hinterlassen Flächen -> verteilt stehen, Flächen am Rand ablegen."] = "- 냉기 단계 - 서리 징표: 플레이어가 퍼지며 장판을 남김 -> 산개해서 서기, 장판은 가장자리에."
L["- Feuerphase - Sengendes Brandmal: markierte Spieler explodieren -> verteilt stehen, Feuerverzauberungs-Add töten."] = "- 화염 단계 - 이글거리는 낙인: 표시된 플레이어 폭발 -> 산개해서 서기, 화염 마법부여 쫄 처치."
L["- Arkanphase - Arkane Kugeln und Verzauberungen -> Adds schnell töten, Kugeln ausweichen."] = "- 비전 단계 - 비전 구슬과 마법부여 -> 쫄 빠르게 처치, 구슬 피하기."
L["- Verzauberungs-Adds nach jeder Phase -> unterbrechen und töten."] = "- 단계마다 마법부여 쫄 -> 차단하고 처치."
L["Taktik: Raid verteilt, Mechanik je nach Schule spielen. Adds haben Vorrang vor dem Boss."] = "공략: 공대는 산개, 계열에 따라 기믹 수행. 쫄이 보스보다 우선."
L["ALURIEL: Adds zuerst! Frostflächen am Rand, Brandmal verteilt!"] = "알루리엘: 쫄 먼저! 서리 장판은 가장자리, 낙인은 산개!"
L["Tankwechsel nach Vernichten."] = "소멸 후 탱 교대."
L["Aluriel (Adds)"] = "알루리엘 (쫄)"
L["Totenkopf, Kreuz und Viereck auf die Verzauberungs-Adds in Tötungsreihenfolge."] = "해골, 가위표, 네모는 처치 순서대로 마법부여 쫄."
L["Tichondrius + Fledermäuse"] = "티콘드리우스 + 박쥐"
L["- Aaspest: stapelnder Debuff auf Spielern -> Spieler mit Pest verteilt stehen."] = "- 썩은 역병: 플레이어에게 중첩 디버프 -> 역병 걸린 플레이어는 산개해서 서기."
L["- Sucherschwarm: trifft alle Spieler mit Aaspest in Linie -> nicht in der Linie zwischen Boss und Ziel stehen."] = "- 추적자 무리: 썩은 역병 걸린 모든 플레이어를 직선으로 타격 -> 보스와 대상 사이 선에 서지 말 것."
L["- Mal von Argus: markierte Spieler explodieren bei Nähe -> weit auseinander."] = "- 아르거스의 징표: 표시된 플레이어가 가까우면 폭발 -> 멀리 떨어지기."
L["- Echos der Leere: starker Schaden -> hinter Säulen/Deckung gehen."] = "- 공허의 메아리: 강한 피해 -> 기둥/엄폐물 뒤로."
L["- Illusionäre Nacht: Fledermäuse -> töten, Essenz der Nacht sammeln."] = "- 환영의 밤: 박쥐 -> 처치, 밤의 정수 수집."
L["Taktik: Raid verteilt um den Boss, Positionen für Mal von Argus festlegen. In Illusionärer Nacht Adds schnell weg."] = "공략: 공대는 보스 주위에 산개, 아르거스의 징표 위치 정하기. 환영의 밤엔 쫄 빠르게 정리."
L["TICHONDRIUS: Mal von Argus weit auseinander!"] = "티콘드리우스: 아르거스의 징표는 멀리 떨어지기!"
L["Bei Echos hinter Deckung. Fledermäuse töten."] = "메아리 때 엄폐물 뒤로. 박쥐 처치."
L["Krosus"] = "크로서스"
L["- Zerschmettern: Krosus zerstört Brückenteile -> Raid rechtzeitig auf intakte Teile laufen."] = "- 박살: 크로서스가 다리 부분을 파괴 -> 공대는 제때 멀쩡한 부분으로 이동."
L["- Brennendes Pech: Pfützen -> soaken bzw. ausweichen nach Ansage."] = "- 불타는 역청: 웅덩이 -> 콜에 맞춰 맞거나 피하기."
L["- Kugel der Zerstörung: markierter Spieler -> weit weg vom Raid laufen."] = "- 파괴의 구슬: 표시된 플레이어 -> 공대에서 멀리 떨어지기."
L["- Teufelsstrahl: Strahl über die Brücke -> ausweichen."] = "- 지옥 광선: 다리를 가로지르는 광선 -> 피하기."
L["- Brennende Glut (Adds) -> schnell töten."] = "- 불타는 잉걸불 (쫄) -> 빠르게 처치."
L["Taktik: Raid in der Brückenmitte, Kugel-Spieler an die Kanten. Plattform schrumpft, also Laufwege vorher absprechen."] = "공략: 공대는 다리 중앙, 구슬 대상은 가장자리로. 발판이 줄어드니 이동 경로는 미리 상의."
L["KROSUS: Kugel weg vom Raid, Strahl ausweichen!"] = "크로서스: 구슬은 공대에서 멀리, 광선 피하기!"
L["Auf die Brücke achten, Glut-Adds töten."] = "다리 주의, 잉걸불 쫄 처치."
L["Hochbotaniker Tel'arn (teilt sich in drei Formen)"] = "대식물학자 텔아른 (세 형상으로 분열)"
L["- Aufteilung: Tel'arn teilt sich in Naturalist, Arkanist und Solarist -> alle Formen gleichzeitig töten, sonst stehen sie wieder auf."] = "- 분열: 텔아른이 자연술사, 비전술사, 태양술사로 분열 -> 모든 형상을 동시에 처치, 아니면 다시 일어남."
L["- Zusammenbruch der Nacht: Soak-Zone -> mit mehreren Spielern soaken."] = "- 밤의 붕괴: 분담 구역 -> 여러 명이 맞기."
L["- Parasitäre Fessel: Debuff -> beim Bannen entstehen Adds, Bannen nach Plan."] = "- 기생 족쇄: 디버프 -> 해제 시 쫄 생성, 계획대로 해제."
L["- Kontrolliertes Chaos: Ringe -> Lücken nutzen."] = "- 통제된 혼돈: 고리 -> 틈 이용."
L["- Plasmasphären (Solarist): -> gleichzeitig töten."] = "- 플라스마 구체 (태양술사): -> 동시에 처치."
L["Taktik: Schaden gleichmäßig auf alle Formen verteilen. Soak-Gruppen und Banner fest einteilen."] = "공략: 모든 형상에 딜 균등 분배. 분담 그룹과 해제 담당 고정 배정."
L["TEL'ARN: Alle Formen gleichzeitig töten!"] = "텔아른: 모든 형상 동시 처치!"
L["Soaks nach Plan, Fessel kontrolliert bannen."] = "분담은 계획대로, 족쇄는 계획적으로 해제."
L["Tel'arn"] = "텔아른"
L["Ein Symbol pro Form (Naturalist, Arkanist, Solarist) für die Schadensverteilung."] = "형상마다 징표 하나 (자연술사, 비전술사, 태양술사), 딜 분배용."
L["Sterndeuter Etraeus"] = "점성술사 에트레우스"
L["- Große Konjunktion: Spieler bekommen Sternzeichen -> Spieler mit gleichem Zeichen stehen zusammen."] = "- 대합: 플레이어가 별자리를 받음 -> 같은 별자리끼리 모이기."
L["- Eis-, Teufels-, Leere-Phasen: wechselnde Debuffs -> Debuffs am Rand ablegen."] = "- 얼음, 지옥, 공허 단계: 바뀌는 디버프 -> 디버프는 가장자리에 내려놓기."
L["- Absoluter Nullpunkt: Spieler eingefroren -> Spieler soaken / Raid hilft."] = "- 절대 영도: 플레이어가 얼어붙음 -> 다른 플레이어가 맞기 / 공대가 돕기."
L["- Gravitationszug: Tank-Debuff -> Tankwechsel."] = "- 중력 당기기: 탱커 디버프 -> 탱 교대."
L["- Leere-Phase: Leerling-Adds -> schnell töten."] = "- 공허 단계: 공허 쫄 -> 빠르게 처치."
L["Taktik: Raid um den Boss verteilt, Konjunktionsgruppen schnell bilden. Phasenwechsel bei 90/60/30 % mit Cooldowns begleiten."] = "공략: 공대는 보스 주위에 산개, 대합 그룹은 빠르게 형성. 90/60/30 % 단계 전환에 생존기."
L["ETRAEUS: Gleiche Sternzeichen zusammen!"] = "에트레우스: 같은 별자리끼리 모이기!"
L["Debuffs am Rand ablegen. Tankwechsel nach Gravitation."] = "디버프는 가장자리에. 중력 후 탱 교대."
L["Großmagistrix Elisande + Rekursive und Zweckdienliche Elementare"] = "대마법학자 엘리산드 + 반복의 정령과 신속의 정령"
L["- Rekursives Elementar: erzeugt beim Tod eine Zone der verlangsamten Zeit -> für Ringe/Kugeln nutzen."] = "- 반복의 정령: 죽으면 시간 감속 구역 생성 -> 고리/구슬에 활용."
L["- Zweckdienliches Elementar: erzeugt beim Tod eine Zone der beschleunigten Zeit -> für Schaden nutzen, Zauber unterbrechen."] = "- 신속의 정령: 죽으면 시간 가속 구역 생성 -> 딜에 활용, 주문 차단."
L["- Arkanetischer Ring: Ring rollt auf den Raid zu -> durch eine Lücke gehen oder verlangsamt durchlaufen."] = "- 비전 고리: 고리가 공대 쪽으로 굴러옴 -> 틈으로 지나가거나 감속 상태로 통과."
L["- Epochenkugel: fällt herab -> soaken."] = "- 시대의 구슬: 떨어짐 -> 맞기."
L["- Zeitwiederholung: Elisande setzt die Zeit zurück -> Mechaniken wiederholen sich als Echos."] = "- 시간 반복: 엘리산드가 시간을 되돌림 -> 기믹이 메아리로 반복됨."
L["Taktik: Elementare an sinnvollen Stellen töten, um Zeitblasen zu nutzen. Kugeln soaken, Ringe sauber durchlaufen."] = "공략: 정령은 적절한 위치에서 처치해 시간 거품 활용. 구슬 맞고, 고리는 깔끔하게 통과."
L["ELISANDE: Ringe durch Lücken, Kugeln soaken!"] = "엘리산드: 고리는 틈으로, 구슬 맞기!"
L["Elementare gezielt töten, Zeitblasen nutzen."] = "정령은 계획적으로 처치, 시간 거품 활용."
L["Elisande (Elementare)"] = "엘리산드 (정령)"
L["Totenkopf auf Zweckdienliches, Kreuz auf Rekursives Elementar."] = "해골은 신속의 정령, 가위표는 반복의 정령."
L["Gul'dan + Inquisitor Vethriz, Teufelslord Kuraz, D'zorykx der Fallensteller"] = "굴단 + 심문관 베스리즈, 지옥 군주 쿠라즈, 덫사냥꾼 드조릭스"
L["- Phase 1: drei Dämonen-Adds unter Gul'dans Schild -> nacheinander töten, ihre Augen von Aman'Thul geben Buffs."] = "- 1단계: 굴단의 보호막 아래 악마 쫄 셋 -> 차례로 처치, 쫄이 남기는 아만툴의 눈이 버프 제공."
L["- Flüssiges Höllenfeuer: Einschläge -> ausweichen."] = "- 액체 지옥불: 충돌 -> 피하기."
L["- Teufelsfesseln (Phase 2): Spieler gekettet -> weg vom Raid."] = "- 지옥 속박 (2단계): 플레이어가 사슬에 묶임 -> 공대에서 멀어지기."
L["- Auge von Gul'dan: Augen-Adds -> töten, bevor sie sich teilen."] = "- 굴단의 눈: 눈 쫄 -> 분열 전에 처치."
L["- Phase 3 (Sturm des Zerstörers, Schwarze Ernte): Raidschaden und Flächen -> Cooldowns, Flächen ausweichen."] = "- 3단계 (파괴자의 폭풍, 검은 수확): 공격대 피해와 장판 -> 생존기, 장판 피하기."
L["Taktik: Phase 1 Adds nach Reihenfolge töten, danach Gul'dan mit Fokus auf Augen-Adds. Heiler-Cooldowns für Phase 3 planen."] = "공략: 1단계는 쫄을 순서대로 처치, 이후 굴단은 눈 쫄에 집중. 3단계용 힐러 생존기 계획."
L["Mythisch: zusätzliche Illidan-Phase."] = "신화: 추가 일리단 단계."
L["GUL'DAN: Adds nach Reihenfolge, Augen schnell töten!"] = "굴단: 쫄은 순서대로, 눈은 빠르게 처치!"
L["Feuer ausweichen. Gekettete Spieler weg vom Raid."] = "불 피하기. 사슬 묶인 플레이어는 공대에서 멀리."
L["Gul'dan"] = "굴단"
L["Totenkopf, Kreuz und Viereck auf die drei Dämonen in Phase 1 in Tötungsreihenfolge."] = "해골, 가위표, 네모는 처치 순서대로 1단계 악마 셋."
L["Grabmal des Sargeras"] = "살게라스의 무덤"
L["Goroth"] = "고로스"
L["- Brennende Rüstung: Tank-Debuff explodiert -> Tank läuft raus, Tankwechsel."] = "- 불타는 갑옷: 탱커 디버프 폭발 -> 탱커 나가기, 탱 교대."
L["- Höllische Stacheln: Stacheln erscheinen auf dem Boden -> als Deckung nutzen."] = "- 지옥 가시: 바닥에 가시 생성 -> 엄폐물로 사용."
L["- Höllisches Brennen: tödlicher Raidschaden -> hinter einem Stachel verstecken."] = "- 지옥의 불길: 치명적 공격대 피해 -> 가시 뒤에 숨기."
L["- Zerschmetternder Stern: markierter Spieler -> Linie so durch die Stacheln ziehen, dass sie zerstört werden."] = "- 박살내는 별: 표시된 플레이어 -> 선을 가시 쪽으로 끌어 가시를 파괴."
L["- Krachender Komet: Kometen auf Spielern -> verteilt stehen, Raid nicht treffen."] = "- 충돌하는 혜성: 플레이어에게 혜성 -> 산개해서 서기, 공대를 맞히지 말 것."
L["Taktik: Raid locker verteilt, vor Höllischem Brennen hinter Stacheln. Stacheln mit Zerschmetterndem Stern gezielt abbauen."] = "공략: 공대는 느슨하게 산개, 지옥의 불길 전에 가시 뒤로. 가시는 박살내는 별로 계획적으로 제거."
L["GOROTH: Bei Höllischem Brennen hinter Stachel!"] = "고로스: 지옥의 불길 시 가시 뒤로!"
L["Kometen verteilt. Tankwechsel nach Brennender Rüstung."] = "혜성은 산개. 불타는 갑옷 후 탱 교대."
L["Atrigan + Belac (Dämonische Inquisition)"] = "아트리간 + 벨락 (악마 심문)"
L["- Qual-Leiste: steigt ständig -> niedrig halten, bei hoher Qual Gequälte Seele/Seelenreich nutzen."] = "- 고통 게이지: 계속 상승 -> 낮게 유지, 고통이 높으면 고통받는 영혼/영혼 영역 이용."
L["- Knochensäge (Atrigan): wirbelnder Nahkampfschaden -> Nahkampf und Raid gehen auf Abstand."] = "- 뼈톱 (아트리간): 회전하는 근접 피해 -> 근딜과 공대는 거리 두기."
L["- Verkalkte Stacheln: Ziel-Spieler -> ausweichen."] = "- 석회화된 가시: 대상 플레이어 -> 피하기."
L["- Erstickende Dunkelheit / Teufelsbö (Belac): Flächen und Schaden -> ausweichen."] = "- 숨막히는 어둠 / 지옥 돌풍 (벨락): 장판과 피해 -> 피하기."
L["- Seelenreich: Spieler kehren zurück, indem sie Seelen töten/unterbrechen -> Schmerzen der Schuld unterbrechen."] = "- 영혼 영역: 영혼을 처치/차단해 복귀 -> 죄책감의 고통 차단."
L["Taktik: Beide Bosse gemeinsam tanken. Spieler mit hoher Qual gehen gezielt ins Seelenreich, um die Leiste zurückzusetzen."] = "공략: 두 보스를 함께 탱킹. 고통이 높은 플레이어는 계획적으로 영혼 영역에 들어가 게이지 초기화."
L["INQUISITION: Qual niedrig halten! Knochensäge weg!"] = "악마 심문: 고통 낮게 유지! 뼈톱 피하기!"
L["Im Seelenreich Schuld unterbrechen."] = "영혼 영역에서 죄책감 차단."
L["Harjatan + Klauenkiefer-Adds"] = "하자탄 + 갈퀴턱 쫄"
L["- Ungezügelte Wut: Kegel vor dem Boss -> mit möglichst vielen Spielern soaken."] = "- 억제되지 않는 분노: 보스 앞 부채꼴 -> 최대한 많은 인원이 맞기."
L["- Eisige Schläge: stapelnder Tank-Debuff -> Tankwechsel."] = "- 얼음 강타: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Gebieterisches Gebrüll: ruft Klauenkiefer-Adds -> Adds fixieren Spieler, schnell töten."] = "- 지휘의 포효: 갈퀴턱 쫄 소환 -> 쫄이 플레이어를 고정, 빠르게 처치."
L["- Durchnässt / Wasserflächen -> nicht in Flächen stehen."] = "- 흠뻑 젖음 / 물 장판 -> 장판에 서지 말 것."
L["- Heroisch: Eier schlüpfen -> Adds zusätzlich töten."] = "- 영웅: 알이 부화 -> 쫄 추가 처치."
L["Taktik: Raid sammelt sich vor dem Boss für die Wut, Adds sofort abfangen und töten."] = "공략: 분노 대비 공대는 보스 앞에 모이기, 쫄은 즉시 가로막아 처치."
L["HARJATAN: Ungezügelte Wut gemeinsam soaken!"] = "하자탄: 억제되지 않는 분노 함께 맞기!"
L["Adds schnell töten. Tankwechsel nach Stapeln."] = "쫄 빠르게 처치. 중첩 후 탱 교대."
L["Jägerin Kasparian + Hauptmann Yathae Mondsturm + Priesterin Lunaspyre"] = "사냥꾼 카스파리안 + 대장 야타에 문스트라이크 + 여사제 루나스파이어"
L["- Nur eine Schwester kämpft pro Phase -> Wechsel bei Gesundheitsschwellen."] = "- 단계마다 자매 하나만 전투 -> 생명력 기준점에서 교대."
L["- Mondgleve / Zwielichtgleve (Kasparian): Linien durch den Raid -> ausweichen bzw. nach Plan soaken."] = "- 달 글레이브 / 황혼 글레이브 (카스파리안): 공대를 가로지르는 선 -> 피하거나 계획대로 맞기."
L["- Astrales und Umbrales Licht: Raid in Licht- und Schattenseite -> Seite gezielt wechseln, um Stapel zu senken."] = "- 천상의 빛과 그림자의 빛: 공대가 빛과 그림자 쪽으로 나뉨 -> 중첩을 줄이려면 계획적으로 쪽 바꾸기."
L["- Mondbrand / Mondfeuer (Lunaspyre): Debuffs -> bannen nach Plan."] = "- 달빛 화상 / 달빛 섬광 (루나스파이어): 디버프 -> 계획대로 해제."
L["- Mondleuchtfeuer: Spieler mit Mondstrahl -> aus dem Raid laufen."] = "- 달빛 봉화: 달빛 광선을 받은 플레이어 -> 공대 밖으로."
L["Taktik: Raid auf Licht/Schatten verteilen, Tank holt die aktive Schwester. Debuffs auf Ansage bannen."] = "공략: 공대를 빛/그림자로 분배, 탱커가 활성 자매를 잡기. 디버프는 콜에 맞춰 해제."
L["SCHWESTERN: Gleven ausweichen, Licht/Schatten-Stapel managen!"] = "달의 자매: 글레이브 피하기, 빛/그림자 중첩 관리!"
L["Mondleuchtfeuer raus, Bannen auf Ansage."] = "달빛 봉화는 밖으로, 해제는 콜에 맞춰."
L["Herrin Sassz'ine + Abyssale Adds"] = "여군주 사스진 + 심연 쫄"
L["- Hydraschuss: Pfeile auf Spieler -> von zugewiesenen Spielern soaken lassen."] = "- 히드라 사격: 플레이어에게 화살 -> 배정된 플레이어가 맞기."
L["- Bürde der Schmerzen: Tank-Debuff -> Tankwechsel."] = "- 고통의 짐: 탱커 디버프 -> 탱 교대."
L["- Donnernder Schock (Aale): Linien -> ausweichen."] = "- 천둥 충격 (뱀장어): 선 -> 피하기."
L["- Phase 2/3 (Tinte, Schreckenshaie): -> Mechanik nach Ansage spielen, Haien ausweichen."] = "- 2/3단계 (먹물, 공포의 상어): -> 콜에 맞춰 기믹 수행, 상어 피하기."
L["- Schneidender Tornado: -> ausweichen."] = "- 베어내는 회오리: -> 피하기."
L["Taktik: Soak-Gruppen für Hydraschuss festlegen, Tanks wechseln regelmäßig. In späteren Phasen gemeinsam ausweichen."] = "공략: 히드라 사격 분담 그룹 정하기, 탱커는 주기적으로 교대. 후반 단계는 함께 피하기."
L["SASSZ'INE: Hydraschüsse soaken nach Plan!"] = "사스진: 히드라 사격은 계획대로 맞기!"
L["Aale und Tornados ausweichen. Tankwechsel nach Bürde."] = "뱀장어와 회오리 피하기. 짐 후 탱 교대."
L["Die trostlose Heerschar (Seelenkönigin Dejahna + Maschine der Seelen + Adds)"] = "황폐한 군대 (영혼 여왕 데자나 + 영혼의 기계 + 쫄)"
L["- Zwei Welten (Körperlich / Geisterwelt): Raid aufteilen -> jede Gruppe kümmert sich um ihre Adds."] = "- 두 세계 (육체 / 영혼 세계): 공대 분할 -> 각 그룹이 자기 쪽 쫄 처리."
L["- Seelenbindung: zwei Spieler verbunden -> zusammen bleiben oder Bindung nach Plan brechen."] = "- 영혼 결속: 두 플레이어 연결 -> 함께 있거나 계획대로 결속 끊기."
L["- Verdorrender Untergang / Untergang des Zerreißens: Soak-Zonen -> mit Spielern aus der richtigen Welt soaken."] = "- 시드는 파멸 / 찢어발기는 파멸: 분담 구역 -> 올바른 세계의 플레이어가 맞기."
L["- Gequälte Schreie: Raidschaden -> Cooldowns."] = "- 고통받는 비명: 공격대 피해 -> 생존기."
L["- Adds (Tempelritter, Knochenwächter, Gefallene Priesterin) -> schnell töten, Zauber unterbrechen."] = "- 쫄 (사원 기사, 뼈 수호자, 타락한 여사제) -> 빠르게 처치, 주문 차단."
L["Taktik: Teams für beide Welten einteilen, Adds priorisieren, Soaks sauber teilen. Phase 2 mit Raid-Cooldowns."] = "공략: 두 세계용 팀 배정, 쫄 우선, 분담은 깔끔하게. 2단계엔 공대 생존기."
L["HEERSCHAR: Welten nach Plan, Soaks richtig teilen!"] = "황폐한 군대: 세계는 계획대로, 분담 정확히!"
L["Adds töten, Seelenbindung nach Plan."] = "쫄 처치, 영혼 결속은 계획대로."
L["Wachsame Maid"] = "경계의 여신"
L["- Licht- und Teufelsinfusion: Raid in zwei Farben -> Spieler gleicher Farbe zusammen, Farbe nicht falsch mischen."] = "- 빛과 지옥 주입: 공대가 두 색으로 나뉨 -> 같은 색끼리 모이고, 색을 잘못 섞지 말 것."
L["- Hammer der Schöpfung / Auslöschung: Tank-Treffer -> Tankwechsel, Farbe beachten."] = "- 창조의 망치 / 소멸의 망치: 탱커 공격 -> 탱 교대, 색 주의."
L["- Fragmente: Kugeln in Licht/Teufel -> mit eigener Farbe fangen."] = "- 파편: 빛/지옥 구슬 -> 자기 색으로 받기."
L["- Instabile Seele: Debuff -> in das Loch in der Mitte springen."] = "- 불안정한 영혼: 디버프 -> 중앙 구멍으로 뛰어내리기."
L["- Zorn der Schöpfer: Schild auf der Maid -> mit Titanessenz brechen, Raidschaden."] = "- 창조주의 분노: 여신에게 보호막 -> 티탄 정수로 깨기, 공격대 피해."
L["Taktik: Raid in Licht- und Teufelshälfte, Kugeln mit passender Farbe fangen. Instabile Seele rechtzeitig ins Loch."] = "공략: 공대는 빛 절반과 지옥 절반으로, 구슬은 맞는 색으로 받기. 불안정한 영혼은 제때 구멍으로."
L["MAID: Licht und Teufel getrennt, Kugeln richtig fangen!"] = "경계의 여신: 빛과 지옥 분리, 구슬 정확히 받기!"
L["Instabile Seele ins Loch. Tankwechsel nach Hammer."] = "불안정한 영혼은 구멍으로. 망치 후 탱 교대."
L["Gefallener Avatar + Wachsame Maid"] = "타락한 화신 + 경계의 여신"
L["- Schwere Tank-Treffer: -> Tankwechsel nach Ansage."] = "- 강한 탱커 공격: -> 콜에 맞춰 탱 교대."
L["- Berührung des Sargeras: Soak-Zonen -> mit Spielern soaken."] = "- 살게라스의 손길: 분담 구역 -> 플레이어가 맞기."
L["- Realitäten zerreißen: Flächenschaden -> rauslaufen."] = "- 현실 찢기: 광역 피해 -> 빠져나오기."
L["- Verdorbene Matrix: Strahl -> in den Strahl stellen, damit die Maid nicht getroffen wird."] = "- 타락한 매트릭스: 광선 -> 여신이 맞지 않게 광선 안에 서기."
L["- Phase 2: Boden zerbricht, Dunkle Male -> verteilt stehen, Cooldowns."] = "- 2단계: 바닥 붕괴, 어둠의 징표 -> 산개해서 서기, 생존기."
L["Taktik: Matrix-Soaker einteilen, Raid hinter dem Boss. Phase 2 mit Raid-Cooldowns."] = "공략: 매트릭스 분담 담당 배정, 공대는 보스 뒤. 2단계엔 공대 생존기."
L["AVATAR: Matrix-Strahl soaken, Berührung soaken!"] = "타락한 화신: 매트릭스 광선 맞기, 손길 맞기!"
L["Phase 2: verteilt. Tankwechsel nach Ansage."] = "2단계: 산개. 콜에 맞춰 탱 교대."
L["- Teufelsklauen: Tank-Kombo -> Tankwechsel."] = "- 지옥 발톱: 탱커 연속기 -> 탱 교대."
L["- Zerreißende Singularität: Rückstoß -> Position so wählen, dass niemand von der Plattform fliegt."] = "- 찢어발기는 특이점: 넉백 -> 아무도 단상 밖으로 날아가지 않게 위치 선정."
L["- Armageddon: Meteore -> soaken."] = "- 아마겟돈: 유성 -> 맞기."
L["- Schattenspiegelung: Spieler erzeugen Adds -> Adds töten."] = "- 그림자 반영: 플레이어가 쫄 생성 -> 쫄 처치."
L["- Zwischenphase: Dunkelheit - Illidans Licht folgen."] = "- 중간 단계: 어둠 - 일리단의 빛 따라가기."
L["Taktik: Raid verteilt, Positionen gegen Rückstoß absichern. Zwischenphasen mit Illidan, Phase 3 Raid-Cooldowns."] = "공략: 공대는 산개, 넉백 대비 위치 확보. 중간 단계는 일리단과 함께, 3단계엔 공대 생존기."
L["KIL'JAEDEN: Singularität beachten, nicht runterfallen!"] = "킬제덴: 특이점 주의, 떨어지지 말 것!"
L["Armageddon soaken, Schatten-Adds töten. Tankwechsel."] = "아마겟돈 맞기, 그림자 쫄 처치. 탱 교대."
L["Prüfung der Tapferkeit"] = "용맹의 시험"
L["Odyn + Hymdall + Hyrja"] = "오딘 + 힘달 + 히르야"
L["- Phase 1: Hymdall und Hyrja -> beide gleichmäßig senken."] = "- 1단계: 힘달과 히르야 -> 둘 다 균등하게 깎기."
L["- Hyrja - Schild des Lichts: Strahl auf Spieler -> mit mehreren Spielern soaken."] = "- 히르야 - 빛의 방패: 플레이어에게 광선 -> 여러 명이 맞기."
L["- Hymdall - Tanzende Klinge: Wirbel -> ausweichen."] = "- 힘달 - 춤추는 칼날: 소용돌이 -> 피하기."
L["- Phase 2/3: Runenbrandmal -> Spieler mit Rune auf die passende Plattform."] = "- 2/3단계: 룬 낙인 -> 룬 받은 플레이어는 맞는 단상으로."
L["- Speer des Lichts / Gleißende Hiebe: -> ausweichen."] = "- 빛의 창 / 눈부신 베기: -> 피하기."
L["Taktik: Phase 1 beide Adds gleichzeitig senken. Runen-Spieler zügig auf ihre Plattform, Tanks wechseln."] = "공략: 1단계는 쫄 둘을 동시에 깎기. 룬 받은 플레이어는 빠르게 자기 단상으로, 탱커 교대."
L["ODYN: Runen-Spieler auf passende Plattform!"] = "오딘: 룬 받은 플레이어는 맞는 단상으로!"
L["Phase 1: Hymdall und Hyrja gleichmäßig senken."] = "1단계: 힘달과 히르야 균등하게 깎기."
L["Guarm"] = "가름"
L["- Atem (Feuer, Frost, Schatten): Kegel vor dem Boss -> mit passend markierten Spielern soaken."] = "- 숨결 (화염, 냉기, 암흑): 보스 앞 부채꼴 -> 맞게 표시된 플레이어가 맞기."
L["- Flüchtiger Schaum: Debuffs in drei Farben -> mit dem passenden Atem entfernen."] = "- 휘발성 거품: 세 가지 색의 디버프 -> 맞는 숨결로 제거."
L["- Lecken (Flamme, Frost, Schatten): Tank-Debuffs -> Tankwechsel."] = "- 핥기 (화염, 냉기, 암흑): 탱커 디버프 -> 탱 교대."
L["- Kopfloser Ansturm / Brüllender Sprung: Raid verteilt sich danach -> Positionen halten."] = "- 무모한 돌진 / 포효하는 도약: 이후 공대가 흩어짐 -> 위치 유지."
L["Taktik: Raid vor dem Boss für Atem-Soaks, Schaum-Farben genau zuweisen."] = "공략: 숨결 분담을 위해 공대는 보스 앞, 거품 색은 정확히 배정."
L["GUARM: Atem soaken, Schaum mit richtiger Farbe entfernen!"] = "가름: 숨결 맞기, 거품은 맞는 색으로 제거!"
L["Tankwechsel nach Lecken."] = "핥기 후 탱 교대."
L["Helya + Tentakel + Adds"] = "헬리아 + 촉수 + 쫄"
L["- Kugel der Verderbnis: markierte Spieler -> an den Rand laufen."] = "- 타락의 구슬: 표시된 플레이어 -> 가장자리로 이동."
L["- Makel des Meeres: Debuff -> am Rand bannen."] = "- 바다의 오염: 디버프 -> 가장자리에서 해제."
L["- Gallwasseratem: Tank-Kegel, Schleim-Adds -> Adds schnell töten."] = "- 담즙 숨결: 탱커 부채꼴, 점액 쫄 -> 쫄 빠르게 처치."
L["- Tentakelschlag: Soak-Zone -> soaken."] = "- 촉수 강타: 분담 구역 -> 맞기."
L["- Phase 2 (65 %): Adds (Matrosen, Schleimfürsten) -> töten/unterbrechen."] = "- 2단계 (65 %): 쫄 (선원, 점액 군주) -> 처치/차단."
L["Taktik: Kugeln und Debuffs am Rand ablegen, Tentakelschläge soaken. Phase 2 Adds priorisieren."] = "공략: 구슬과 디버프는 가장자리에, 촉수 강타 맞기. 2단계엔 쫄 우선."
L["HELYA: Kugeln an den Rand, Tentakel soaken!"] = "헬리아: 구슬은 가장자리로, 촉수 맞기!"
L["Phase 2: Adds schnell töten."] = "2단계: 쫄 빠르게 처치."
L["Aktueller Raid"] = "현재 공격대"
L["Boss-Infos"] = "보스 정보"
L["Erweiterung wählen."] = "확장팩 선택."
L["Für diesen Boss gibt es noch keine Taktik."] = "이 보스에 대한 전략이 아직 없습니다."
L["Für diesen Raid sind keine Bosse hinterlegt. Bosse werden beim ersten Kill automatisch erkannt."] = "이 공격대에 등록된 보스가 없습니다. 보스는 첫 처치 시 자동으로 인식됩니다."
L["Raid wählen. Im Raid wird er automatisch vorausgewählt."] = "공격대 선택. 공격대 안에서는 자동으로 미리 선택됩니다."
L["Springt zum Raid, in dem du gerade bist."] = "현재 있는 공격대로 이동합니다."
L["Vorlage beim Bosskampf automatisch wählen"] = "보스전 시 템플릿 자동 선택"
L["Classic"] = "오리지널"
L["The Burning Crusade"] = "불타는 성전"
L["Wrath of the Lich King"] = "리치 왕의 분노"
L["Cataclysm"] = "대격변"
L["Mists of Pandaria"] = "판다리아의 안개"
L["Warlords of Draenor"] = "드레노어의 전쟁군주"
L["Legion"] = "군단"
L["Battle for Azeroth"] = "격전의 아제로스"
L["Shadowlands"] = "어둠땅"
L["Dragonflight"] = "용군단"
L["The War Within"] = "내부 전쟁"
L["Midnight"] = "한밤"
L["Schlacht um Dazar'alor"] = "다자알로 전투"
L["Champion des Lichts + Adds (Allianz: Frida Eisenbalg / Horde: Ra'wani Kanae)"] = "빛의 용사 + 쫄 (얼라이언스: 프리다 아이언벨로우즈 / 호드: 라와니 카나에)"
L["- Adds (Priester/Paladine): heilen und stärken den Boss -> unterbrechen, Adds schnell töten."] = "- 쫄 (사제/성기사): 보스를 치유하고 강화 -> 차단, 쫄 빠르게 처치."
L["- Weihe-Flächen: Boss und Adds stehen darin verstärkt -> Boss und Adds aus den Flächen ziehen."] = "- 신성화 장판: 보스와 쫄이 안에 서면 강화됨 -> 보스와 쫄을 장판 밖으로 끌기."
L["- Blendender Glaube: grelles Licht vom Boss -> rechtzeitig vom Boss wegdrehen."] = "- 눈부신 신앙: 보스의 강렬한 빛 -> 제때 보스에게서 등 돌리기."
L["- Tankfähigkeit mit Stapel-Debuff -> Tankwechsel bei hohen Stapeln."] = "- 중첩 디버프가 있는 탱커 기술 -> 중첩이 높으면 탱 교대."
L["Taktik: Boss und Adds gemeinsam aus den Weihe-Flächen tanken, Kickrotation auf die Adds, Adds mit Priorität töten."] = "공략: 보스와 쫄을 함께 신성화 장판 밖에서 탱, 쫄에 차단 순서 배정, 쫄 우선 처치."
L["CHAMPION: Adds kicken und zuerst töten! Boss aus Weihe ziehen!"] = "빛의 용사: 쫄 차단하고 먼저 처치! 보스를 신성화 밖으로!"
L["Bei Blendendem Glauben wegdrehen. Tankwechsel bei Stapeln."] = "눈부신 신앙 시 등 돌리기. 중첩 시 탱 교대."
L["Champion des Lichts"] = "빛의 용사"
L["Totenkopf, Kreuz und Viereck auf die Adds, Kickgruppen je Symbol."] = "쫄에 해골, 가위표, 네모, 징표별 차단조."
L["Jadefeuermeister (zwei Mönche: Allianz-/Horde-Version je nach Fraktion)"] = "비취불꽃 달인 (수도사 둘: 진영에 따라 얼라이언스/호드 버전)"
L["- Vielseitiger Schlag: kegelförmiger Mehrfachangriff -> mehrere Spieler stellen sich zum Aufteilen vor den Boss."] = "- 다재다능한 일격: 원뿔형 다중 공격 -> 여러 명이 보스 앞에 서서 나눠 맞기."
L["- Feuer-Debuffs auf Spielern hinterlassen Flammen -> an den Rand laufen, Flammen nicht im Raid ablegen."] = "- 플레이어의 화염 디버프가 불길을 남김 -> 가장자리로 이동, 공격대 안에 불길 깔지 말 것."
L["- Magmafallen/Feuerflächen am Boden -> nicht hineinlaufen."] = "- 마그마 덫/바닥 화염 장판 -> 들어가지 말 것."
L["- Aufsteigende Flammen: stapelnder Feuerschaden auf Tanks -> Tankwechsel."] = "- 솟아오르는 불길: 탱커에게 중첩되는 화염 피해 -> 탱 교대."
L["- Chi-Welle und Energiefähigkeiten der Mönche -> Heiler-Cooldowns einteilen."] = "- 수도사의 기의 파도와 기력 기술 -> 힐러 생존기 배분."
L["Taktik: Beide Mönche getrennt tanken und gleichmäßig herunterschlagen, Soak-Gruppe für den Mehrfachangriff fest einteilen, Feuer an den Rand legen."] = "공략: 수도사 둘을 따로 탱하고 고르게 깎기, 다중 공격 나눠 맞을 조를 고정 배정, 불길은 가장자리에 깔기."
L["JADEFEUERMEISTER: Soaker vor den Boss! Feuer an den Rand legen!"] = "비취불꽃 달인: 나눠 맞을 인원 보스 앞으로! 불은 가장자리에!"
L["Nicht in Magmafallen laufen. Tankwechsel bei Aufsteigenden Flammen."] = "마그마 덫에 들어가지 마세요. 솟아오르는 불길 시 탱 교대."
L["Grong (Allianz: Grong der Wiedergänger / Horde: Grong der Dschungelherr)"] = "그롱 (얼라이언스: 망령 그롱 / 호드: 밀림의 군주 그롱)"
L["- Combo-Angriff auf den Tank: mehrere schwere Schläge mit Stapel-Debuff -> Tankwechsel nach jeder Combo."] = "- 탱커 연속 공격: 중첩 디버프가 붙는 강타 여러 번 -> 연속 공격마다 탱 교대."
L["- Energie-Fähigkeit (bei 100 Energie): Flächenschlag/Gebrüll auf den Raid -> Heiler-Cooldowns vorbereiten."] = "- 기력 기술 (기력 100): 공격대 광역 강타/포효 -> 힐러 생존기 준비."
L["- Geschleuderte Fässer/Kugeln: müssen von Spielern abgefangen bzw. getroffen werden -> eingeteilte Spieler fangen sie ab."] = "- 던져진 통/구슬: 플레이어가 받아내거나 맞아야 함 -> 배정된 인원이 받기."
L["- Frontaler Angriff des Bosses -> nie vor dem Boss stehen (außer Tank)."] = "- 보스 전방 공격 -> 절대 보스 앞에 서지 말 것 (탱커 제외)."
L["- Bodeneffekte nach Einschlägen -> sofort verlassen."] = "- 충돌 후 바닥 효과 -> 즉시 벗어나기."
L["Taktik: Boss in der Mitte tanken, Raid seitlich/hinten, Tankwechsel nach jeder Combo; Energie-Phasen mit Raid-Cooldowns abfangen."] = "공략: 보스는 중앙에서 탱, 공격대는 측면/뒤, 연속 공격마다 탱 교대; 기력 구간은 공대 생존기로 버티기."
L["GRONG: Tankwechsel nach jeder Combo! Nicht vor dem Boss stehen!"] = "그롱: 연속 공격마다 탱 교대! 보스 앞에 서지 마세요!"
L["Geworfene Objekte abfangen. Heiler-CDs bei 100 Energie."] = "던져진 물체 받기. 기력 100에 힐러 생존기."
L["Opulenz (Phase 1: zwei Schatzwächter, Phase 2: Opulenz)"] = "부귀 (1단계: 보물 수호자 둘, 2단계: 부귀)"
L["- Phase 1: Zwei Wächter in getrennten Räumen mit Fallen -> Raid teilt sich auf, beide Wächter möglichst gleichzeitig töten."] = "- 1단계: 함정이 있는 각기 다른 방의 수호자 둘 -> 공격대를 나눠 두 수호자를 최대한 동시에 처치."
L["- Juwelen (Rubin, Topas, Opal, Smaragd, Amethyst, Diamant): geben Trägern starke Effekte -> fest zugewiesene Spieler nehmen und weitergeben."] = "- 보석 (루비, 황옥, 오팔, 에메랄드, 자수정, 다이아몬드): 소지자에게 강력한 효과 -> 배정된 인원이 들고 넘기기."
L["- Münzregen: muss von Spielern abgefangen werden -> eingeteilte Soaker stellen sich darunter."] = "- 동전 비: 플레이어가 받아내야 함 -> 배정된 인원이 아래에 서기."
L["- Flüssiges Gold / Goldflächen am Boden -> nicht hineinlaufen, Debuff-Träger an den Rand."] = "- 액체 금 / 바닥 금 장판 -> 들어가지 말 것, 디버프 대상은 가장자리로."
L["- Tankfähigkeiten mit Stapel-Debuff -> Tankwechsel."] = "- 중첩 디버프가 있는 탱커 기술 -> 탱 교대."
L["Taktik: Phase 1 im Split mit gleichmäßigem Schaden, Phase 2 Juwelen fest einteilen und Soaks koordinieren, Raid-Cooldowns für die Schadensspitzen."] = "공략: 1단계는 나눠서 고르게 딜, 2단계는 보석 고정 배정하고 나눠 맞기 조율, 피해 급증 구간에 공대 생존기."
L["OPULENZ: Juwelen nur durch Eingeteilte! Münzregen soaken!"] = "부귀: 보석은 배정된 인원만! 동전 비 받아내기!"
L["Nicht im Gold stehen. Tankwechsel bei Stapeln."] = "금 위에 서지 마세요. 중첩 시 탱 교대."
L["Konklave der Auserwählten (Loa-Avatare: Pa'ku, Gonk, Kimbul, Akunda)"] = "선택받은 자들의 비밀회의 (로아 화신: 파쿠, 공크, 킴불, 아쿤다)"
L["- Pa'kus Zorn: Pa'ku fliegt ein -> alle laufen zu Pa'ku, sonst massiver Raidschaden."] = "- 파쿠의 분노: 파쿠가 날아옴 -> 전원 파쿠에게 달려가기, 아니면 막대한 공격대 피해."
L["- Gonks Raptoren: Adds tauchen auf -> schnell töten (Fernkampf), nicht auf Heiler laufen lassen."] = "- 공크의 랩터: 쫄 등장 -> 빠르게 처치 (원딜), 힐러에게 가지 않게."
L["- Kimbuls Zorn / Blutungen: springt auf Spieler -> Debuff-Träger heilen, Abstand halten."] = "- 킴불의 분노 / 출혈: 플레이어에게 도약 -> 디버프 대상 치유, 거리 유지."
L["- Akundas Zorn: Blitz-Debuff -> verteilen, Debuff-Träger aus dem Raid laufen."] = "- 아쿤다의 분노: 번개 디버프 -> 산개, 디버프 대상은 공격대 밖으로."
L["- Avatar des Loa: bei Erscheinen verstärkt er sich -> Avatare abwechselnd und gezielt töten."] = "- 로아의 화신: 등장 시 강화됨 -> 화신을 번갈아 집중 처치."
L["Taktik: Loa-Avatare nacheinander fokussieren (übliche Reihenfolge nach Gruppe absprechen), Raptoren sofort töten, bei Pa'ku sammeln."] = "공략: 로아 화신을 차례로 점사 (순서는 공대와 상의), 랩터 즉시 처치, 파쿠에서 집결."
L["KONKLAVE: Bei Pa'ku sofort hinlaufen! Raptoren sofort töten!"] = "비밀회의: 파쿠에게 즉시 달려가기! 랩터 즉시 처치!"
L["Akunda-Debuff aus dem Raid tragen. Fokusziel beachten."] = "아쿤다 디버프는 공격대 밖으로. 점사 대상 확인."
L["Totenkopf auf den aktuellen Fokus-Avatar, Kreuz auf den nächsten, Viereck/Mond auf Raptoren."] = "현재 점사 화신에 해골, 다음 화신에 가위표, 랩터에 네모/달."
L["König Rastakhan + Belagerungsbrecher Roka'mon / Prälat Za'lan, später Bwonsamdi"] = "라스타칸 왕 + 공성파괴자 로카몬 / 고위 성직자 잘란, 이후 본삼디"
L["- Krötenplage: Kröten laufen über den Boden -> ausweichen, Berührung explodiert."] = "- 두꺼비 역병: 두꺼비가 바닥을 기어다님 -> 피하기, 닿으면 폭발."
L["- Sengende Detonation: Debuff explodiert nach kurzer Zeit -> Träger läuft aus dem Raid."] = "- 이글거리는 폭발: 잠시 후 터지는 디버프 -> 대상은 공격대 밖으로."
L["- Meteorsprung (Roka'mon): Landeflächen müssen von mehreren Spielern geteilt werden -> soaken."] = "- 유성 도약 (로카몬): 착지 지점을 여러 명이 나눠 맞아야 함 -> 들어가서 맞기."
L["- Todesreich: Teil des Raids wird ins Reich des Todes geschickt -> dort Phantome töten und zurück."] = "- 죽음의 영역: 공격대 일부가 죽음의 세계로 보내짐 -> 그곳의 망령 처치 후 복귀."
L["- Phase 3: Bwonsamdi greift ein, Todesbereich und schwere Raidschläge -> Raid-Cooldowns, Abstände halten."] = "- 3단계: 본삼디 개입, 죽음의 영역과 강력한 공대 타격 -> 공대 생존기, 거리 유지."
L["Taktik: Phase 1 erst die Helfer töten, danach Rastakhan; Todesreich-Gruppe fest einteilen; Phase 3 Bwonsamdi aus dem Raid halten und Boss burnen."] = "공략: 1단계는 조력자 먼저, 이후 라스타칸; 죽음의 영역 조 고정 배정; 3단계는 본삼디를 공격대에서 떨어뜨리고 보스 폭딜."
L["RASTAKHAN: Kröten ausweichen! Meteorsprung soaken!"] = "라스타칸: 두꺼비 피하기! 유성 도약 나눠 맞기!"
L["Detonation aus dem Raid tragen. Todesreich-Gruppe bereit."] = "폭발 디버프는 공격대 밖으로. 죽음의 영역 조 대기."
L["Rastakhan"] = "라스타칸"
L["Totenkopf auf Roka'mon bzw. Za'lan, Kreuz auf das nächste Add."] = "로카몬 또는 잘란에 해골, 다음 쫄에 가위표."
L["Hochtüftler Mekkadrill + Funkenbots"] = "고위 땜장이 메카토크 + 불꽃로봇"
L["- Gigavoltladung: Bombe auf Spielern -> an den Rand laufen, nicht im Raid explodieren."] = "- 기가볼트 충전: 플레이어에게 폭탄 -> 가장자리로 이동, 공격대 안에서 터지지 않게."
L["- Durchbrecherkanone: frontaler Strahl -> nicht vor dem Boss stehen."] = "- 파괴자 대포: 전방 광선 -> 보스 앞에 서지 말 것."
L["- Schrumpfstrahl: geschrumpfte Spieler steigen in Gnomroboter und deaktivieren sie mit dem richtigen Code."] = "- 축소 광선: 작아진 플레이어가 노움 로봇에 올라 올바른 코드로 비활성화."
L["- Funkenbots: laufen durch den Raum -> betäuben/töten, nicht berühren."] = "- 불꽃로봇: 방 안을 돌아다님 -> 기절/처치, 닿지 말 것."
L["- Explosive Schafe / Wurmloch-Generator: schwere Flächen -> ausweichen und Kontrolle zurückgewinnen."] = "- 폭발하는 양 / 웜홀 생성기: 강한 장판 -> 피하고 다시 통제권 되찾기."
L["Taktik: Boss mittig tanken, Bombenträger fest an Randpositionen, Schrumpfspieler lösen die Roboter, Funkenbots kontrollieren."] = "공략: 보스는 중앙에서 탱, 폭탄 대상은 가장자리 고정 위치로, 작아진 인원이 로봇 해제, 불꽃로봇 제어."
L["MEKKADRILL: Bomben an den Rand! Nicht vor die Kanone!"] = "메카토크: 폭탄은 가장자리로! 대포 앞에 서지 마세요!"
L["Geschrumpfte: Roboter deaktivieren. Funkenbots stoppen."] = "작아진 인원: 로봇 비활성화. 불꽃로봇 저지."
L["Sturmwallblockade (Schwester Katherine, Bruder Joseph, später Laminaria)"] = "폭풍장벽 봉쇄선 (캐서린 수녀, 조셉 형제, 이후 라미나리아)"
L["- Zwei Geschwister auf getrennten Schiffen -> Raid teilt sich auf beide Boote auf."] = "- 각기 다른 배의 남매 둘 -> 공격대를 두 배로 나누기."
L["- Meeressturm / Wirbel auf dem Wasser -> Bewegung beachten, nicht ins Wasser gespült werden."] = "- 바다 폭풍 / 수면 위 소용돌이 -> 이동 주의, 물에 휩쓸리지 말 것."
L["- Spannungsblitz / Knisternde Blitze: Debuff springt über -> verteilt stehen."] = "- 전압 번개 / 지직거리는 번개: 튀는 디버프 -> 산개."
L["- Gezeitenhülle: Schild auf einem Boss -> wegschlagen oder unterbrechen."] = "- 해일의 장막: 보스 보호막 -> 깨거나 차단."
L["- Phase 2 Laminaria: Seetang-Stapel und Fluten -> Raid zusammen, Heiler-Cooldowns, Tankwechsel."] = "- 2단계 라미나리아: 해초 중첩과 범람 -> 공격대 뭉치기, 힐러 생존기, 탱 교대."
L["Taktik: Geschwister gleichmäßig herunterschlagen, damit sie nah beieinander sterben; danach Laminaria im zweiten Teil mit Raid-Cooldowns legen."] = "공략: 남매를 고르게 깎아 거의 동시에 죽이기; 이후 라미나리아는 공대 생존기로 처치."
L["STURMWALL: Raid auf beide Schiffe aufteilen! Verteilt stehen!"] = "폭풍장벽: 공격대를 두 배로 나누기! 산개!"
L["Schilde sofort wegmachen. P2: Heiler-CDs auf Laminaria."] = "보호막 즉시 깨기. 2단계: 라미나리아에 힐러 생존기."
L["Lady Jaina Prachtmeer + Kul Tiras-Marine"] = "제이나 프라우드무어 + 쿨 티라스 해군"
L["- Eiseskälte/Unterkühlung: stapelnde Kälte -> an Feuerflächen bzw. Wärmequellen aufwärmen."] = "- 혹한/저체온증: 중첩되는 냉기 -> 화염 장판이나 열원에서 몸 녹이기."
L["- Lawine: schwerer Tankangriff -> Tankwechsel."] = "- 눈사태: 강한 탱커 공격 -> 탱 교대."
L["- Eisring / Frostflächen: Spieler werden eingefroren -> rechtzeitig herauslaufen."] = "- 얼음 고리 / 서리 장판: 플레이어가 얼어붙음 -> 제때 밖으로 이동."
L["- Zwischenphasen: Jaina im Eisblock -> Kanonen/Feuer nutzen, Block brechen, Adds töten."] = "- 사잇단계: 얼음 덩어리 속 제이나 -> 대포/화염으로 덩어리 깨기, 쫄 처치."
L["- Phase 3: Breitseite und Eiswände -> Positionen absprechen, Wasserblitz-Salven unterbrechen."] = "- 3단계: 측면 포격과 얼음벽 -> 위치 사전 조율, 물의 화살 일제 사격 차단."
L["Taktik: Kälte-Stapel konsequent abbauen, Adds schnell töten, Zwischenphasen sauber spielen; Phase 3 mit allen Raid-Cooldowns."] = "공략: 냉기 중첩은 꾸준히 해소, 쫄 빠르게 처치, 사잇단계 깔끔하게; 3단계는 공대 생존기 총동원."
L["JAINA: Kälte-Stapel aufwärmen! Eisring sofort verlassen!"] = "제이나: 냉기 중첩 녹이기! 얼음 고리 즉시 벗어나기!"
L["Adds töten, Salven kicken. Tankwechsel bei Lawine."] = "쫄 처치, 일제 사격 차단. 눈사태 시 탱 교대."
L["Jaina"] = "제이나"
L["Totenkopf und Kreuz auf die Adds mit Zaubern (Kickziele)."] = "시전하는 쫄에 해골과 가위표 (차단 대상)."
L["Tiegel der Stürme"] = "폭풍의 용광로"
L["Die Rastlose Kabale (Zaxasj der Sprecher, Fa'thuul der Gefürchtete)"] = "쉼 없는 비밀결사 (대변자 자크사즈, 공포의 파툴)"
L["- Reliquien (Sturmrufer / Leerenstein): Spieler tragen sie und erhalten Fähigkeiten -> fest einteilen, rechtzeitig weitergeben."] = "- 유물 (폭풍소환사 / 공허석): 들고 있는 플레이어가 기술을 얻음 -> 고정 배정, 제때 넘기기."
L["- Verdunkelung/Wahnsinn: Spieler verlieren Kontrolle -> Ziele überwachen, kontrollierte Spieler nicht angreifen."] = "- 암흑/광기: 플레이어가 통제력 상실 -> 대상 감시, 정신 지배된 플레이어 공격 금지."
L["- Abyssalkollaps: großer Einschlag -> mit mehreren Spielern teilen."] = "- 심연 붕괴: 큰 충격 -> 여러 명이 나눠 맞기."
L["- Gesicht aus dem Jenseits: Add -> schnell töten."] = "- 저편의 얼굴: 쫄 -> 빠르게 처치."
L["Taktik: Beide Bosse getrennt tanken, Reliquienträger einteilen, Soaks und Adds koordinieren."] = "공략: 두 보스 따로 탱, 유물 소지자 배정, 나눠 맞기와 쫄 처리 조율."
L["KABALE: Reliquien nur durch Eingeteilte! Einschläge soaken!"] = "비밀결사: 유물은 배정된 인원만! 충격 나눠 맞기!"
L["Adds schnell töten. Tankwechsel bei Stapeln."] = "쫄 빠르게 처치. 중첩 시 탱 교대."
L["Kabale"] = "비밀결사"
L["Totenkopf und Kreuz auf die beschworenen Adds."] = "소환된 쫄에 해골과 가위표."
L["Uu'nat, Vorbote der Leere + Urtümliche Gedankenbeuger"] = "공허의 전령 우우나트 + 원시 정신조종자"
L["- Drei Reliquien (Sturmrufer, Ozeanrune, Leerenstein): Träger nutzen sie gegen Mechaniken -> fest einteilen."] = "- 유물 셋 (폭풍소환사, 대양의 룬, 공허석): 소지자가 기믹 대응에 사용 -> 고정 배정."
L["- Berührung des Endes: schwerer Tank-Debuff -> Tankwechsel."] = "- 종말의 손길: 강한 탱커 디버프 -> 탱 교대."
L["- Unergründlicher Schrecken: Furchteffekt -> rechtzeitig vom Boss wegdrehen."] = "- 헤아릴 수 없는 공포: 공포 효과 -> 제때 보스에게서 등 돌리기."
L["- Gedankenbeuger-Adds: zaubern -> unterbrechen und töten."] = "- 정신조종자 쫄: 시전 -> 차단 후 처치."
L["- Leerenrisse/Flächen -> nicht hineinlaufen."] = "- 공허 균열/장판 -> 들어가지 말 것."
L["Taktik: Reliquien rotieren lassen, Adds kicken und töten, bei Schrecken wegdrehen; Phase 3 mit Raid-Cooldowns."] = "공략: 유물 순환, 쫄 차단 후 처치, 공포 시 등 돌리기; 3단계는 공대 생존기."
L["UU'NAT: Reliquien-Träger bereit! Bei Schrecken wegdrehen!"] = "우우나트: 유물 소지자 대기! 공포 시 등 돌리기!"
L["Gedankenbeuger kicken und töten. Tankwechsel."] = "정신조종자 차단 후 처치. 탱 교대."
L["Uu'nat"] = "우우나트"
L["Je ein Symbol auf die Gedankenbeuger, Kickgruppen pro Symbol."] = "정신조종자마다 징표 하나, 징표별 차단조."
L["Der Ewige Palast"] = "영원한 궁전"
L["Abyssische Kommandantin Sivara"] = "심연의 사령관 시바라"
L["- Chimärische Male (Frost und Gift): Spieler erhalten eins von zwei Malen -> nach Mal-Farbe gruppiert stehen."] = "- 키메라의 징표 (냉기와 독): 플레이어가 두 징표 중 하나를 받음 -> 징표 색깔별로 모여 서기."
L["- Umkehrung: Male tauschen -> Gruppen neu sortieren."] = "- 반전: 징표가 바뀜 -> 조 재정렬."
L["- Frost-/Giftpfeile und Linien am Boden -> ausweichen."] = "- 냉기/독 화살과 바닥 줄 -> 피하기."
L["- Tankangriffe mit Frost-/Gift-Stapeln -> Tankwechsel."] = "- 냉기/독 중첩 탱커 공격 -> 탱 교대."
L["- Sturzflut/Überschwemmung -> Heiler-Cooldowns."] = "- 급류/범람 -> 힐러 생존기."
L["Taktik: Zwei feste Lager für Frost und Gift, beim Umkehren sauber wechseln; Tankwechsel nach Stapeln."] = "공략: 냉기와 독 진영 둘 고정, 반전 시 깔끔하게 교체; 중첩 후 탱 교대."
L["SIVARA: Nach Mal-Farbe aufstellen! Bei Umkehrung wechseln!"] = "시바라: 징표 색깔별로 서기! 반전 시 교체!"
L["Linien ausweichen. Tankwechsel bei Stapeln."] = "줄 피하기. 중첩 시 탱 교대."
L["Schwarzwasserbehemoth (Unterwasserkampf)"] = "검은바다 거수 (수중 전투)"
L["- Biolumineszenz: leuchtende Wolken einsammeln -> schützt vor Dunkelheit, Stapel halten."] = "- 생체발광: 빛나는 구름 수집 -> 어둠으로부터 보호, 중첩 유지."
L["- Fressrausch: stapelnder Tank-Debuff -> Tankwechsel."] = "- 먹이 광란: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Fischschwärme / Kavitation: große Flächen -> rechtzeitig ausweichen."] = "- 물고기 떼 / 공동 현상: 큰 장판 -> 제때 피하기."
L["- Abstieg in tiefere Ebenen: Kampf wandert nach unten -> zusammenbleiben."] = "- 더 깊은 층으로 하강: 전투가 아래로 이동 -> 함께 움직이기."
L["Taktik: Raid nah beim Boss, Biolumineszenz aktiv sammeln, Tankwechsel nach Stapeln, beim Abtauchen gemeinsam folgen."] = "공략: 공격대는 보스 가까이, 생체발광 적극 수집, 중첩 후 탱 교대, 잠수 시 함께 따라가기."
L["BEHEMOTH: Leuchtwolken sammeln! Schwärmen ausweichen!"] = "거수: 빛나는 구름 수집! 물고기 떼 피하기!"
L["Tankwechsel bei Fressrausch. Gemeinsam abtauchen."] = "먹이 광란 시 탱 교대. 함께 잠수."
L["Glanz von Azshara + Uralte Stürme"] = "아즈샤라의 광휘 + 고대의 폭풍"
L["- Arkanados / Sturmwirbel: wandernde Tornados -> ausweichen."] = "- 비전 회오리 / 폭풍 소용돌이: 움직이는 회오리 -> 피하기."
L["- Gezeitenfaust: schwerer Tankschlag -> Tankwechsel."] = "- 해일의 주먹: 강한 탱커 타격 -> 탱 교대."
L["- Arkane Bomben: Debuff-Träger -> an den Rand und auseinander."] = "- 비전 폭탄: 디버프 대상 -> 가장자리로 산개."
L["- Zwischenphase: Raid läuft die Rampen hoch, Uralte Stürme -> gemeinsam laufen, Schäden heilen."] = "- 사잇단계: 공격대가 경사로를 올라감, 고대의 폭풍 -> 함께 이동, 피해 치유."
L["Taktik: Boss mittig, Bomben nach außen, Tornados beachten; Zwischenphase zügig zusammen hochlaufen."] = "공략: 보스는 중앙, 폭탄은 바깥으로, 회오리 주의; 사잇단계는 빠르게 함께 올라가기."
L["GLANZ: Tornados ausweichen! Bomben nach außen!"] = "광휘: 회오리 피하기! 폭탄은 바깥으로!"
L["Tankwechsel nach Gezeitenfaust. Zwischenphase gemeinsam laufen."] = "해일의 주먹 후 탱 교대. 사잇단계 함께 이동."
L["Lady Ashvane"] = "레이디 애쉬베인"
L["- Schild auf Lady Ashvane: macht sie nahezu unverwundbar -> nach Raidplan über die Kampfmechanik brechen."] = "- 레이디 애쉬베인의 보호막: 거의 무적 상태 -> 공대 계획대로 전투 기믹으로 깨기."
L["- Muschelhieb: schwerer Tankangriff -> Tankwechsel."] = "- 껍질 강타: 강한 탱커 공격 -> 탱 교대."
L["- Bogen-Azerit: verbundene Spieler -> nach Anweisung positionieren, damit Linien keine anderen treffen."] = "- 아제라이트 궁: 연결된 플레이어 -> 지시대로 위치 잡아 줄이 다른 사람에게 닿지 않게."
L["- Salzblasen: Spieler eingeschlossen -> freischlagen/heilen."] = "- 소금 거품: 플레이어가 갇힘 -> 깨서 꺼내기/치유."
L["- Wachsende Korallen am Boden -> nicht im Weg stehen, Raum freihalten."] = "- 바닥에 자라나는 산호 -> 길을 막지 말고 공간 확보."
L["Taktik: Boss so bewegen, dass der Schild gebrochen wird, Azerit-Linien sauber legen, Tankwechsel."] = "공략: 보호막이 깨지도록 보스 이동, 아제라이트 줄 깔끔하게 정리, 탱 교대."
L["ASHVANE: Schild brechen! Azerit-Linien sauber legen!"] = "애쉬베인: 보호막 깨기! 아제라이트 줄 깔끔하게!"
L["Blasen freischlagen. Tankwechsel nach Muschelhieb."] = "거품 깨서 꺼내기. 껍질 강타 후 탱 교대."
L["Orgozoa + Brut"] = "오르고조아 + 새끼"
L["- Brut/Inkubationsadds: schlüpfen aus Eiern -> schnell töten, unterbrechen."] = "- 새끼/부화 쫄: 알에서 부화 -> 빠르게 처치, 차단."
L["- Betäubender Stachel: stapelnder Tank-Debuff -> Tankwechsel."] = "- 마비의 독침: 중첩되는 탱커 디버프 -> 탱 교대."
L["- Bogenstrom / Elektro-Effekte -> verteilt stehen."] = "- 전류 / 전기 효과 -> 산개."
L["- Inkubationsflüssigkeit: Debuff -> Abstand zu anderen Trägern."] = "- 부화액: 디버프 -> 다른 대상과 거리 두기."
L["Taktik: Adds mit Priorität töten, Kicks einteilen, Boss stationär; Phase 2 mit Raid-Cooldowns."] = "공략: 쫄 우선 처치, 차단 배정, 보스는 고정; 2단계는 공대 생존기."
L["ORGOZOA: Adds schnell töten! Kicks einteilen!"] = "오르고조아: 쫄 빠르게 처치! 차단 배정!"
L["Verteilt stehen. Tankwechsel bei Stachel-Stapeln."] = "산개. 독침 중첩 시 탱 교대."
L["Orgozoa"] = "오르고조아"
L["Symbole auf die zaubernden Adds, Kickgruppen pro Symbol."] = "시전하는 쫄에 징표, 징표별 차단조."
L["Der Hof der Königin (Silivaz die Eifrige, Pashmar die Fanatische)"] = "여왕의 궁정 (열성적인 실리바즈, 광신자 파쉬마르)"
L["- Erlasse der Königin: wechselnde Befehle (allein stehen, zusammen stehen, wiederholen, nicht bewegen) -> exakt befolgen."] = "- 여왕의 칙령: 바뀌는 명령 (혼자 서기, 함께 서기, 반복하기, 움직이지 않기) -> 정확히 따르기."
L["- Fanatisches Urteil: Flächen -> herauslaufen."] = "- 광신적 심판: 장판 -> 밖으로 이동."
L["- Mächtiger Funke: Adds -> töten, nicht zu nah an Bosse."] = "- 강력한 불꽃: 쫄 -> 처치, 보스에게 너무 가까이 두지 말 것."
L["- Beide Bosse verstärken sich gegenseitig -> abwechselnd schlagen, Bosse getrennt halten."] = "- 두 보스가 서로 강화 -> 번갈아 딜, 보스 떨어뜨리기."
L["Taktik: Erlasse des Hofes genau ansagen und befolgen, Bosse auseinander, Adds töten."] = "공략: 궁정의 칙령을 정확히 콜하고 따르기, 보스 분리, 쫄 처치."
L["HOF: Erlasse exakt befolgen! Bosse getrennt halten!"] = "여왕의 궁정: 칙령 정확히 따르기! 보스 떨어뜨리기!"
L["Adds töten, aus Flächen raus."] = "쫄 처치, 장판 밖으로."
L["Za'qul, Vorbote von Ny'alotha + Schreckensbeschwörer"] = "니알로타의 전령 자쿨 + 공포의 소환사"
L["- Wahnsinnsreich: Spieler werden ins Delirium versetzt -> dort Mechaniken lösen und zurückkehren."] = "- 광기의 영역: 플레이어가 섬망 상태에 빠짐 -> 그곳에서 기믹 해결 후 복귀."
L["- Dunkler Puls / Kugeln: schwere Effekte -> ausweichen oder nach Plan absorbieren."] = "- 어둠의 맥동 / 구슬: 강한 효과 -> 피하거나 계획대로 흡수."
L["- Gedankenverbindung: Tank-Mechanik -> Tankwechsel."] = "- 정신 연결: 탱커 기믹 -> 탱 교대."
L["- Zermalmender Griff: Tentakel-Einschläge -> ausweichen."] = "- 분쇄의 손아귀: 촉수 충격 -> 피하기."
L["- Adds (Schreckensbeschwörer) -> unterbrechen und schnell töten."] = "- 쫄 (공포의 소환사) -> 차단 후 빠르게 처치."
L["Taktik: Phasen bei 90/70/40 % vorbereiten, Delirium-Wechsel koordinieren, Adds zuerst."] = "공략: 90/70/40 % 단계 전환 대비, 섬망 교대 조율, 쫄 먼저."
L["ZA'QUL: Adds zuerst! Tentakeln ausweichen!"] = "자쿨: 쫄 먼저! 촉수 피하기!"
L["Delirium-Spieler zurückbringen. Tankwechsel beachten."] = "섬망 인원 복귀시키기. 탱 교대 주의."
L["Za'qul"] = "자쿨"
L["Totenkopf und Kreuz auf die Schreckensbeschwörer."] = "공포의 소환사에 해골과 가위표."
L["Königin Azshara + Aethanel / Wachen"] = "여왕 아즈샤라 + 아에타넬 / 경비병"
L["- Strafe/Arkane Bursts: schwere Flächen auf Spielern -> verteilen."] = "- 형벌/비전 폭발: 플레이어에게 강한 장판 -> 산개."
L["- Arkane Kugeln: fliegen durch den Raum -> nicht berühren."] = "- 비전 구슬: 방 안을 날아다님 -> 닿지 말 것."
L["- Konsole/Überladung: Spieler müssen Kristalle aufladen -> eingeteilte Gruppen."] = "- 제어반/과부하: 플레이어가 수정 충전 -> 배정된 조."
L["- Aethanel: Kälte-Tank-Fähigkeiten -> Tankwechsel."] = "- 아에타넬: 냉기 탱커 기술 -> 탱 교대."
L["- Endphasen: Azshara stellt Bedingungen -> genau ausführen, Raid-Cooldowns."] = "- 마지막 단계: 아즈샤라가 조건 제시 -> 정확히 수행, 공대 생존기."
L["Taktik: Boss und Adds getrennt tanken, Kugeln meiden, Phasen nach Plan; alle Cooldowns für die Endphase."] = "공략: 보스와 쫄 따로 탱, 구슬 피하기, 단계는 계획대로; 마지막 단계에 생존기 총동원."
L["AZSHARA: Kugeln meiden! Verteilen bei Bursts!"] = "아즈샤라: 구슬 피하기! 폭발 시 산개!"
L["Konsolen-Gruppen bereit. Tankwechsel beachten."] = "제어반 조 대기. 탱 교대 주의."
L["Ny'alotha, die Erwachende Stadt"] = "깨어난 도시 니알로타"
L["Wrathion, der Schwarze Kaiser + Schattenattentäter"] = "검은 황제 렉시온 + 그림자 암살자"
L["- Sengender Atem: Tank-Stapel -> Tankwechsel."] = "- 이글거리는 숨결: 탱커 중첩 -> 탱 교대."
